// Generated by build.js from data/*.json. Do not edit by hand.
window.DECKS=[{"name":"Common Words I","slug":"common-words-i","series":"Common Words","words":[{"w":"aberration","p":"n.","m":"A departure from what is normal or expected.","e":"Latin <i>aberrare</i>, “to wander away”: <i>ab-</i> (away) + <i>errare</i> (to wander, stray). The same <i>errare</i> gives French <i>errer</i> and English <i>err</i>, <i>error</i>.","f":"aberration","t":"Picture a knight-errant drifting off the road: ab + errer = wandering off the normal path. French already has the word with the same meaning.","h":["Sounds like “a bear ration”: a bear showing up in your ration line is a departure from the normal.","Ab (away) + errare (wander): one sheep that wanders off from the flock. A glitch in the data."],"s":["anomaly"]},{"w":"acrimony","p":"n.","m":"Bitter, sharp ill-feeling, especially in words or a dispute.","e":"Latin <i>acrimonia</i>, “sharpness, pungency”, from <i>acer</i> (sharp, sour). Same root as French <i>âcre</i>, <i>aigre</i> and <i>vinaigre</i> (vin + aigre).","f":"acrimonie, aigreur","t":"Acer → aigre → vinaigre. An acrimonious divorce is a marriage that has turned to vinegar.","h":["Acre = sharp. Acrid smoke, acrimonious words: both sting the throat.","Picture a Paris dinner where the cheese talk turns bitter: every sentence is vinaigrette, no oil."],"s":["asperity","contention","discord","invective","strife","vitriol"]},{"w":"amalgam","p":"n.","m":"A mixture or blend of different elements.","e":"Medieval Latin <i>amalgama</i>, the alchemists’ word for an alloy of mercury with another metal, probably via Arabic from Greek <i>malagma</i> (a softening paste). Dentists’ silver fillings are still called amalgam.","f":"amalgame (« faire l’amalgame »)","t":"Same word as « faire l’amalgame », lumping things together. Think of the dentist’s filling: several metals fused into one.","h":["Al-chemy gave us amal-gam: the mercury-and-silver mix in a dental filling. Any blend of unlike things.","Ama + gam: “a mass of gum” stuck together from different flavours."],"s":["hodgepodge"]},{"w":"ambiguous","p":"adj.","m":"Open to more than one interpretation; unclear.","e":"Latin <i>ambiguus</i>, “doubtful, shifting”, from <i>ambigere</i>, “to waver”: <i>ambi-</i> (both ways, around) + <i>agere</i> (to drive, lead).","f":"ambigu","t":"Ambi = both ways, as in ambidextrous. A sentence driving in two directions at once. Identical to French ambigu.","h":["Ambi (both) + agere (drive): a car steering both left and right at once.","Un panneau qui indique deux directions: you can’t tell which one is meant."],"s":["equivocal","evasive","indeterminate"]},{"w":"ambivalent","p":"adj.","m":"Having mixed or contradictory feelings about something.","e":"A modern coinage: the Swiss psychiatrist Eugen Bleuler built German <i>Ambivalenz</i> in 1910 from Latin <i>ambi-</i> (both) + <i>valentia</i> (strength, from <i>valere</i>, to be strong).","f":"ambivalent, partagé","t":"Ambi + valent = two feelings of equal strength pulling at once. Ambiguous describes a message; ambivalent describes how a person feels.","h":["Ambi (both) + valent (strength): two equally strong feelings. Hold two bags of equal weight: you can’t move.","“Ambi-valent” = bi-valent: you love it and hate it, like quitting a job you also need."],"s":[]},{"w":"amenable","p":"adj.","m":"Willing to cooperate or be persuaded; open to.","e":"Anglo-French <i>amenable</i>, “able to be led”, from <i>amener</i> (à + <i>mener</i>), from Late Latin <i>minare</i>, “to drive animals by shouting”. First a legal word: answerable to a court.","f":"accommodant, réceptif, disposé à","t":"French amener: an amenable person is easy to « amener » to your view. You can lead them where you want.","h":["“Amen-able”: someone who says Amen, easily agrees. A choir member who goes along with everything.","À mener: easy to lead, like a docile horse."],"s":["complaisant","compliant","docile","malleable","obliging","pliant","tractable"]},{"w":"amorphous","p":"adj.","m":"Without a clear shape, form or structure.","e":"Greek <i>amorphos</i>: <i>a-</i> (without) + <i>morphē</i> (shape, form). Same <i>morphē</i> as in metamorphosis and morphology.","f":"amorphe, informe","t":"A-morph = no shape, a metamorphosis that never finished. French « amorphe » often means listless; in English keep it about shape: an amorphous plan, an amorphous blob.","h":["A (without) + morph (shape): a blob. Think of a jellyfish on the sand.","Morphing in Photoshop stopped halfway: no defined outline, an amorphous cloud."],"s":[]},{"w":"anomalous","p":"adj.","m":"Deviating from what is standard or expected.","e":"Greek <i>anōmalos</i>, “uneven, irregular”: <i>an-</i> (not) + <i>homalos</i> (even, level), related to <i>homos</i> (same).","f":"anormal, anomal (une anomalie)","t":"An-homalos = not level, not the same as the rest. The anomaly is the data point that sticks out of the even line.","h":["An + homalos (even): a bump on a flat road. The anomaly is the odd one out.","A penguin in the Sahara: anomalous, it doesn’t belong to the pattern."],"s":["aberrant","discordant","incongruous"]},{"w":"artful","p":"adj.","m":"Cunning and sly (the usual GRE sense); also skilful.","e":"English <i>art</i> + <i>-ful</i>. <i>Art</i> came through Old French from Latin <i>ars, artis</i> (skill, craft), which also gave <i>artifice</i> and <i>artificial</i>. “Skilful” slid to “crafty” by the 1700s.","f":"rusé, astucieux, habile","t":"Think artifice, not art gallery. The Artful Dodger in Oliver Twist is a pickpocket full of tricks.","x":"2nd meaning","h":["Art-ful here = full of artifice: a magician’s sleight of hand, not a painter’s brush.","The Artful Dodger: a clever pickpocket in Oliver Twist. Smart and sly."],"s":["astute","canny","crafty","cunning","devious","disingenuous","duplicitous","ingenious","perspicacious","shrewd","wily"]},{"w":"auspicious","p":"adj.","m":"Showing signs of future success; favourable.","e":"Latin <i>auspicium</i>, “divination from birds”: <i>avis</i> (bird) + <i>specere</i> (to look). Roman augurs read the gods’ will in the flight of birds before any big decision.","f":"favorable, de bon augure (« sous de bons auspices »)","t":"« Sous de bons auspices »: picture the Roman priest watching the birds fly the right way. Auspicious = the birds say yes.","h":["Auspice: an omen. Sous de bons auspices = a good start, like a lucky sunrise on your first day.","Think “a spicy start”: a hot, promising beginning. Favourable signs."],"s":["propitious","providential"]},{"w":"belie","p":"v.","m":"To give a false impression of; or to show something to be false.","e":"Old English <i>belēogan</i>, “to deceive by lying”: <i>be-</i> + <i>lēogan</i> (to lie). Purely Germanic. The surface “lies about” what is underneath.","f":"démentir, masquer, contredire","t":"Be + lie: the surface tells a lie. “Her calm smile belied her panic” = the smile lied about it.","h":["Be + lie: your face lies. A huge smile that belies the fear inside.","To make a lie of: his calm manner belies his panic, the surface is hiding the truth."],"s":["cloak","debunk","discredit","gainsay","negate","refute"]},{"w":"betray","p":"v.","m":"To reveal unintentionally (the GRE sense); also to be disloyal.","e":"Germanic prefix <i>be-</i> + Middle English <i>trayen</i>, from Old French <i>trair</i> (now <i>trahir</i>), from Latin <i>tradere</i>, “to hand over”.","f":"trahir (« sa voix trahissait sa nervosité »)","t":"Exactly like French « trahir son émotion »: your face hands over (tradere) the secret without your permission.","x":"2nd meaning","h":["Trahir: the body betrays you. A blush betrays the lie you told.","Be + tray: you leave the tray, and the secret drops. Unintentional reveal."],"s":["divulge"]},{"w":"calumny","p":"n.","m":"A false statement made to damage someone’s reputation; slander.","e":"Latin <i>calumnia</i>, “trickery, false accusation”, from <i>calvi</i> (to deceive). Came into English through French <i>calomnie</i>.","f":"calomnie","t":"Same word as « calomnie », and the old saying: « Calomniez, calomniez, il en restera toujours quelque chose. »","h":["“Call-um-ny”: you call someone horrible names that aren’t true. A calomnie in the press.","Calomnie: the rumour that sticks. Calumny = a lie with a goal, to ruin a name."],"s":["aspersion","slander"]},{"w":"castigate","p":"v.","m":"To criticise or reprimand severely.","e":"Latin <i>castigare</i>, “to correct, punish”, literally “to make pure”: <i>castus</i> (pure, chaste) + <i>agere</i> (to drive). The same verb became Old French <i>chastier</i>, now <i>châtier</i>, which English borrowed again as chastise.","f":"fustiger, réprimander, châtier","t":"Castigate and chastise are twins, both from castigare → châtier. « Qui aime bien châtie bien. »","h":["Castigate = “cast a gate”: you slam the gate of criticism on someone.","Châtier: the strict headmaster who punishes with words as much as with the cane."],"s":["admonish","berate","censure","chastise","decry","denigrate","denounce","disparage","excoriate","lambast","lambaste","lampoon","objurgate","pillory","rebuke","reproach","stigmatize","upbraid","vilify","vituperate"]},{"w":"censure","p":"n. / v.","m":"Formal, severe disapproval; to criticise officially.","e":"Latin <i>censura</i>, the office of the Roman <i>censor</i> (from <i>censere</i>, to assess). Censors ran the census and also judged citizens’ morals, publicly marking the disgraced.","f":"blâme, censure (« motion de censure »)","t":"Think « motion de censure » at the Assemblée: an official vote of disapproval. Censure = formal blame. Cutting out content is censor.","h":["Censor + sure: a committee sure that you were wrong. Formal blame.","Un blâme officiel: the letter in your file after a vote of censure."],"s":["admonish","berate","castigate","decry","denigrate","denounce","disparage","excoriate","lambast","opprobrium","rebuke","reproach","stigma","stigmatize","upbraid","vilify"]},{"w":"chastise","p":"v.","m":"To scold or punish severely.","e":"Middle English <i>chastisen</i>, from <i>chasten</i>, from Old French <i>chastier</i> (modern <i>châtier</i>), from Latin <i>castigare</i>, “to make pure”.","f":"châtier, réprimander","t":"Chastise sounds like châtier because it is châtier. The twin of castigate.","h":["Chaste + rise: you tell off a child to “rise to chaste behaviour”. Scold.","Sounds like “chase-tise”: chasing someone with a scolding."],"s":["admonish","berate","castigate","lambaste","objurgate","rebuke","reproach","upbraid"]},{"w":"commensurate","p":"adj.","m":"In proportion to; corresponding in size or degree.","e":"Late Latin <i>commensuratus</i>: <i>com-</i> (together) + <i>mensurare</i> (to measure), from <i>mensura</i> (measure).","f":"proportionné à, à la mesure de","t":"Com + mesure = measured together. “Salary commensurate with experience” = à la mesure de votre expérience.","h":["Com + mensura (measure): same measuring tape for both. Pay measured against effort.","Commensurate = “common measure”: size of the reward matches the size of the work."],"s":["coterminous","tantamount"]},{"w":"demur","p":"v.","m":"To raise objections or show reluctance.","e":"Old French <i>demorer</i>, “to linger, delay” (modern <i>demeurer</i>), from Latin <i>demorari</i>, from <i>mora</i> (delay, as in moratorium). Lawyers turned “delay” into a formal objection, the demurrer.","f":"émettre des réserves, objecter, hésiter","t":"Demur = demeurer: you stay put instead of going along. Don’t confuse with demure (shy, modest).","x":"Look-alike","h":["Demurrer in French: to hesitate, linger. “De-murmur”: you murmur an objection instead of agreeing.","The pause before “yes”: you demur because you aren’t convinced."],"s":["balk","falter","flag","remonstrate","vacillate"]},{"w":"disinterested","p":"adj.","m":"Impartial, with no personal stake (not “uninterested”).","e":"<i>dis-</i> (not) + interested, from Latin <i>interesse</i>, “to be between, to matter”: <i>inter</i> + <i>esse</i>. Here “interest” means a stake, as in conflict of interest.","f":"désintéressé, impartial","t":"Same as French « désintéressé »: a referee with nothing to gain. A disinterested judge is good; an uninterested judge is asleep.","x":"2nd meaning","h":["Dis-interested = no stake: a referee who doesn’t care who wins. Opposite of biased.","Remember: dis-interest = impartial; un-interested = bored. A judge should be the first."],"s":["dispassionate","equitable","evenhanded","impartial"]},{"w":"egregious","p":"adj.","m":"Outstandingly bad; shocking.","e":"Latin <i>egregius</i>, “standing out from the flock”: <i>e/ex</i> (out of) + <i>grex, gregis</i> (flock). It first meant “distinguished”; ironic use in the 1500s made the bad sense win.","f":"flagrant, énorme, grossier (« une erreur grossière »)","t":"Ex grege: the sheep that stands out of the flock, for the wrong reason. Same grex as gregarious and grégaire.","h":["E + grex (flock): sticks out of the flock like a black sheep. A glaring error.","“Egg-regious”: a rotten egg in a basket of fresh ones, impossible not to notice."],"s":["blatant","brazen","flagrant"]},{"w":"enervate","p":"v.","m":"To weaken; drain of energy (not “to annoy” or “energise”).","e":"Latin <i>enervare</i>, “to remove the sinews”: <i>e-</i> (out) + <i>nervus</i> (sinew, tendon). Old French <i>énerver</i> meant the same before it shifted to “irritate”.","f":"affaiblir, épuiser, amollir (≠ énerver)","t":"Remember « les Énervés de Jumièges », the two princes of legend whose tendons were cut: énervés in the old sense, drained of strength. That is the English meaning.","x":"Faux ami","h":["E + nerve: you take the nerve out. A heat wave enervates you; you flop on the sofa.","False friend: énerver = annoy; enervate = drain. Think “energy gone”."],"s":["unnerve"]},{"w":"equivocal","p":"adj.","m":"Ambiguous, often deliberately; open to two readings.","e":"Late Latin <i>aequivocus</i>, “of identical sound”: <i>aequus</i> (equal) + <i>vox, vocis</i> (voice). Two meanings with an equal voice.","f":"équivoque","t":"Same as « équivoque »: two meanings speak equally loud, so you can’t tell which is meant. To equivocate = to dodge with double-meaning words.","h":["Equi + vocal: two voices of equal volume, saying different things.","Un oui qui veut dire non: an equivocal answer, impossible to pin down."],"s":["ambiguous","elusive","evasive","indeterminate"]},{"w":"extant","p":"adj.","m":"Still in existence; surviving.","e":"Latin <i>exstantem</i>, from <i>exstare</i>, “to stand out, be visible”: <i>ex</i> + <i>stare</i> (to stand).","f":"existant, qui subsiste, encore conservé","t":"Ex-stare = still standing. “The oldest extant manuscript” is the one still standing after the others were lost. Opposite: extinct.","h":["Ex + stare: still standing. Like the Parthenon, one of the few extant Greek temples.","The opposite of extinct. Extant = it didn’t die out."],"s":[]},{"w":"frugal","p":"adj.","m":"Sparing and economical with money or food.","e":"Latin <i>frugalis</i>, from <i>frugi</i> (useful, thrifty), from <i>frux, frugis</i> (fruit, produce). A frugal man made good use of his harvest.","f":"frugal, économe (« un repas frugal »)","t":"Identical to « un repas frugal ». Frux = fruit: living on what your own trees give you.","h":["Fruit: frugal = eats what the tree gives. A simple lunch of fruit and bread.","Un repas frugal: a grandmother who saves string and reuses teabags."],"s":["abstemious","ascetic","austere","canny","economical","miserly","parsimonious","penurious","provident","prudent","scant","spartan","stinting","thrifty"]},{"w":"galvanize","p":"v.","m":"To shock or excite someone into action.","e":"Named after Luigi Galvani (1737–1798), the Bologna physician whose dissected frog legs twitched when touched with metals: “animal electricity”. The zinc-coating sense came later, from galvanic cells.","f":"galvaniser","t":"Picture Galvani’s frog leg jumping when the current hits it. To galvanize a team = jolt it into motion. Same in French.","h":["Galvani’s frog twitched when electricity hit it: to galvanize is to give a jolt of life.","Think of a galvanised steel bucket: coated with zinc, ready to act, hard, protected. A speech that galvanises the crowd."],"s":["goad"]},{"w":"gregarious","p":"adj.","m":"Fond of company; sociable.","e":"Latin <i>gregarius</i>, “of the flock”, from <i>grex, gregis</i> (flock, herd).","f":"sociable, liant (« grégaire » is more pejorative)","t":"Grex = the flock: a gregarious person loves being in the herd. In English it’s a compliment, unlike « l’instinct grégaire ».","h":["Grex (flock): the sheep that must always be with the herd. The party guest who talks to everyone.","“Greg is gregarious”: Greg always goes out with friends, never alone."],"s":["convivial","genial","jovial"]},{"w":"harangue","p":"n. / v.","m":"A long, aggressive or pompous speech; to lecture forcefully.","e":"Middle French <i>harangue</i>, from Old Italian <i>aringa</i> (public speech), from <i>aringo</i> (public square), from a Germanic word for a ring of people at an assembly (compare English <i>ring</i>).","f":"harangue, haranguer","t":"Same as « haranguer la foule ». Picture a Germanic chief in the middle of a ring of warriors, shouting at them.","h":["Rang: the circle of listeners around the speaker. Harangue = a long loud speech, as at a rally.","Sounds like “hurry-gang”: the coach rushing his team with a loud, long pep-talk."],"s":["broadside","diatribe","polemic","screed","tirade"]},{"w":"iconoclast","p":"n.","m":"A person who attacks cherished beliefs or institutions.","e":"Greek <i>eikōn</i> (image) + <i>klastēs</i> (breaker), from <i>klan</i> (to break). First the Byzantine iconoclasts of the 8th–9th centuries, who smashed religious images.","f":"iconoclaste","t":"Icon-breaker: a monk smashing holy images. Today it’s someone smashing sacred ideas, like the founder who breaks every rule of an industry.","h":["Icon + clast (breaker): the one who smashes the holy pictures. Apple’s “Think different” rebel.","Think of a protester toppling a statue from its plinth: the iconoclast breaks what everyone else reveres."],"s":["apostate","heretic","maverick"]},{"w":"impertinent","p":"adj.","m":"Rude, disrespectful; also (older sense) not relevant.","e":"Latin <i>impertinentem</i>, “not belonging”: <i>in-</i> (not) + <i>pertinere</i> (to relate to). First “irrelevant”, then “meddling in what doesn’t concern you”, hence “rude”.","f":"impertinent, insolent; (ou) non pertinent","t":"Both meanings come from “not pertinent”: either irrelevant, or poking into things that are none of your business.","x":"2nd meaning","h":["Not pertinent: you jump into a conversation that isn’t yours. Rude kid answering back.","In-pertinent: a cheeky remark in a meeting, out of place and disrespectful."],"s":["audacious","brazen","extraneous","flippant","immaterial","impudent","insolent","irreverent","presumptuous","redundant","superfluous","tangential"]},{"w":"ingenuous","p":"adj.","m":"Innocent, naive, candid (not “ingenious”).","e":"Latin <i>ingenuus</i>, “native, freeborn”, hence “noble, frank”: <i>in-</i> + <i>gignere</i> (to beget). A freeborn person had nothing to hide.","f":"ingénu, candide, naïf","t":"Ingenuous = ingénu, like Voltaire’s L’Ingénu. Ingenious (with an i) is clever; disingenuous is fake-innocent.","x":"Look-alike","h":["In-genuous: born in (gen = born). Naive from birth, like a child. Voltaire’s L’Ingénu.","Genuine, with no tricks: an ingenuous question from a newcomer, innocent and open."],"s":["artless","candid","credulous","guileless","gullible","naive"]},{"w":"innocuous","p":"adj.","m":"Harmless; inoffensive.","e":"Latin <i>innocuus</i>: <i>in-</i> (not) + <i>nocuus</i> (harmful), from <i>nocere</i> (to harm). Same family as French <i>nuire</i>, <i>nocif</i> and <i>innocent</i>.","f":"inoffensif, anodin","t":"In + nocif = not nocif. An innocuous remark does no harm at all.","h":["In + nocere (to harm): no harm done. An innocuous joke, like a water pistol.","« Anodin »: a plain grey sweater, not a danger to anyone."],"s":["anodyne","benign"]},{"w":"intimate","p":"v.","m":"To hint or suggest indirectly (the GRE verb sense).","e":"Late Latin <i>intimare</i>, “to make known, announce”, from <i>intimus</i> (inmost): putting an idea into someone’s innermost thoughts.","f":"laisser entendre, insinuer, suggérer (≠ intimer)","t":"The verb, said “inti-MATE”, slips an idea into someone’s mind without saying it. Not French « intimer un ordre », which is the opposite of subtle.","x":"2nd meaning","h":["As a verb: you whisper (intimus, inner) a hint, you don’t say it out loud. “He intimated he would resign.”","Not “intime”: as a verb it means to drop a hint. “She intimated that she might quit”, said by lowering her voice."],"s":["allude"]},{"w":"involved","p":"adj.","m":"Complicated, intricate (the GRE sense).","e":"Latin <i>involvere</i>, “to roll into, wrap up”: <i>in-</i> + <i>volvere</i> (to roll). Something rolled in many layers is hard to unwrap.","f":"compliqué, alambiqué, complexe","t":"Picture a scroll rolled up on itself: an involved argument has to be unrolled layer by layer. Think « alambiqué ».","x":"2nd meaning","h":["Rolled up in itself (volvere, to roll): an involved plot with twists inside twists.","Un casse-tête: a long, tangled story with many subplots. Involved = complex."],"s":["byzantine","convoluted","embroiled","tortuous"]},{"w":"laconic","p":"adj.","m":"Using very few words; terse.","e":"Greek <i>Lakōnikos</i>, “of Laconia”, the region around Sparta. Spartans were famous for blunt brevity.","f":"laconique","t":"Philip II of Macedon warned Sparta: “If I invade Laconia, I will destroy you.” The Spartans replied with one word: “If.”","h":["Laconia = Sparta: the Spartans answered with one word. “If.” A laconic text message: “K.”","“Lacks conversation”: a laconic person says almost nothing."],"s":["pithy","reticent","sententious","succinct","taciturn","terse"]},{"w":"maintain","p":"v.","m":"To assert, claim firmly (the GRE sense).","e":"Old French <i>maintenir</i>, from Latin <i>manu tenere</i>, “to hold in the hand”.","f":"maintenir, affirmer, soutenir (« je maintiens que… »)","t":"Exactly French « je maintiens que c’est faux »: you hold your position in your hand and won’t let go.","x":"2nd meaning","h":["Main + tenir: hold with the hand. “I maintain that I was right”: you won’t let go of your claim.","Maintain = keep up. Here, keep up an argument against opposition."],"s":["aver","contend"]},{"w":"mercurial","p":"adj.","m":"Subject to sudden, unpredictable changes of mood.","e":"Latin <i>mercurialis</i>, “of Mercury”: the swift messenger god, the fast planet, and quicksilver, the liquid metal that never sits still. Astrologers said people born under Mercury were volatile.","f":"versatile, lunatique, d’humeur changeante","t":"Picture a drop of mercury (vif-argent) skittering across a table, impossible to pin down. A mercurial boss changes mood that fast.","h":["Mercury: god of speed and the metal that rolls around. A mercurial mood: Monday joy, Tuesday gloom.","Freddie Mercury: an unpredictable, changeable performer. A mercurial temper."],"s":["arbitrary","capricious","erratic","fickle","fitful","protean","volatile","wayward","whimsical"]},{"w":"parochial","p":"adj.","m":"Narrow in outlook; limited to local concerns.","e":"Late Latin <i>parochialis</i>, from <i>parochia</i> (parish), from Greek <i>paroikia</i>: <i>para</i> (beside) + <i>oikos</i> (house). Thinking that stops at the parish boundary.","f":"borné, provincial (« esprit de clocher »)","t":"Parochial = paroissial. « L’esprit de clocher »: someone who can’t see past their own village church tower.","h":["Parish: the small world of one church. A parochial mind never leaves the village.","Paroissial: the local fête as the centre of the universe. Narrow outlook."],"s":["blinkered","insular","provincial","rustic"]},{"w":"parsimonious","p":"adj.","m":"Extremely unwilling to spend money; stingy.","e":"Latin <i>parsimonia</i> (thrift), from <i>parcere</i>, “to spare, save”.","f":"parcimonieux, pingre, radin","t":"« Avec parcimonie »: coins handed out one by one. Stronger than frugal: frugal is a virtue, parsimonious is stingy.","h":["Pars-i-money: “parse your money”: you split each coin in two. Very stingy.","Parcimonie: Harpagon in L’Avare counting every candle. More extreme than frugal."],"s":["abstemious","avaricious","economical","frugal","miserly","penurious","provident","thrifty"]},{"w":"prevaricate","p":"v.","m":"To speak evasively; to dodge the truth.","e":"Latin <i>praevaricari</i>, “to walk crookedly, straddle”: <i>prae</i> + <i>varicare</i> (to straddle), from <i>varus</i> (bow-legged). In Roman law, a prosecutor secretly colluding with the defence.","f":"tergiverser, user de faux-fuyants (≠ prévariquer)","t":"Picture someone bow-legged, zig-zagging so they never walk straight to the truth. Tergiverser.","x":"Faux ami","h":["Pre + varicare (to straddle): standing with legs apart so you never choose a side. A politician who dodges the question.","Prevaricate ≈ “pre-vary-cate”: you vary your answers to avoid the truth. Tergiverser."],"s":["equivocate","evade","hedge","quibble"]},{"w":"prodigal","p":"adj. / n.","m":"Wastefully extravagant; someone who squanders.","e":"Latin <i>prodigus</i> (wasteful), from <i>prodigere</i>, “to drive away, squander”: <i>pro-</i> (forth) + <i>agere</i> (to drive).","f":"prodigue (« l’enfant prodigue »)","t":"The prodigal son of the parable, « l’enfant prodigue », who blew his inheritance. Not to be confused with prodigy (a genius).","x":"Look-alike","h":["The prodigal son spent everything. Prodigal = spends lavishly and carelessly.","Prodigue: the lottery winner who blows it all in a year."],"s":["extravagant","improvident","imprudent","lavish","profligate","spendthrift"]},{"w":"profligate","p":"adj.","m":"Recklessly wasteful; also dissolute, immoral.","e":"Latin <i>profligatus</i>, “ruined, dissolute”, from <i>profligare</i>, “to strike down”: <i>pro-</i> + <i>fligere</i> (to strike), as in inflict and conflict.","f":"dépensier, dissipateur, débauché","t":"Profligate = prodigal who also parties. Pro + fligere: knocking down your own fortune and morals blow by blow.","h":["Pro + fligere (strike down): you knock down your own fortune. Pure wastefulness.","“Profit-gone”: pro-fli-gate ≈ profits gone out the gate."],"s":["extravagant","improvident","imprudent","lavish","libertine","prodigal","reprobate","spendthrift"]},{"w":"qualify","p":"v.","m":"To limit or modify a statement; add reservations (GRE sense).","e":"Medieval Latin <i>qualificare</i>, “to give a quality to”: <i>qualis</i> (of what kind) + <i>facere</i> (to make).","f":"nuancer, apporter une réserve, tempérer","t":"Think « nuancer son propos ». A qualified endorsement is a yes with an asterisk.","x":"2nd meaning","h":["Add conditions: “I like it, but…”. A qualified yes is a yes with qualities (limits) attached.","In GRE contexts: to qualify a claim = to temper it. “Mostly true” instead of “true”."],"s":["mitigate","mollify","temper"]},{"w":"restive","p":"adj.","m":"Restless, impatient, resisting control.","e":"Old French <i>restif</i> (now <i>rétif</i>), “stationary, balky”, from <i>rester</i>, Latin <i>restare</i> (to stay). Used first of horses that refused to go forward; their stamping and fidgeting took over the meaning.","f":"agité, nerveux, rétif","t":"Picture « un cheval rétif », refusing to move while stamping and pulling at the reins. A restive crowd is losing patience.","h":["Rest-ive sounds restful but means the opposite: a horse that won’t stand still. A restless crowd.","Rétif: a donkey refusing to move. Restive = fidgety, hard to control."],"s":["fractious","peevish","petulant","refractory","skittish","timorous","unruly"]},{"w":"undermine","p":"v.","m":"To weaken gradually or secretly.","e":"Middle English <i>under</i> + <i>mine</i> (from Old French <i>miner</i>). Besiegers dug tunnels under castle walls, propped them with timber, then burned the props so the wall fell.","f":"saper, miner, ébranler","t":"Same image as French « saper le moral »: digging under the wall until it collapses.","h":["Under + mine: dig a tunnel under the wall. Weakens slowly, from below.","A boss who undermines you in meetings, piece by piece, until your authority crumbles."],"s":["compromise","debase","impair","jeopardize","subvert","undercut","vitiate"]},{"w":"upbraid","p":"v.","m":"To scold or reproach severely.","e":"Old English <i>upbregdan</i>, “to throw up against”: <i>up</i> + <i>bregdan</i> (to move quickly, weave; the source of braid). You throw someone’s faults back at them.","f":"réprimander, sermonner, faire des reproches","t":"Up + braid: you hurl the reproach up into their face. It sounds harsh because it is.","h":["Up + braid: you pull someone’s hair-braid up to tell them off. Scold.","Picture a teacher lifting a pupil’s braid to scold them: up + braid = a sharp telling-off."],"s":["admonish","berate","castigate","censure","chastise","excoriate","lambast","lambaste","objurgate","rebuke","reproach"]},{"w":"venality","p":"n.","m":"Openness to bribery; corruption.","e":"Latin <i>venalis</i>, “for sale”, from <i>venum</i> (sale), which also gave <i>vendere</i>, to sell (<i>venum dare</i>).","f":"vénalité, corruption","t":"Think « la vénalité des offices » under the Ancien Régime, when judges bought their posts. Venal = for sale. Venial is a small, forgivable sin.","x":"Look-alike","h":["Venal = vénal: for sale, like Venus’s favours bought with coins. A bribable official.","Vend-: venality = willing to vend your integrity. Corruption."],"s":["graft"]},{"w":"venerate","p":"v.","m":"To regard with deep respect; revere.","e":"Latin <i>venerari</i>, “to worship, revere”, related to <i>Venus</i> (love, desire).","f":"vénérer","t":"Identical to « vénérer ». Picture bowing before a statue of Venus.","h":["Venus was revered: to venerate = revere deeply, as a saint or an elder.","Vénérer: candles lit in front of a statue. Deep respect."],"s":["deify","exalt"]},{"w":"veracious","p":"adj.","m":"Truthful; accurate.","e":"Latin <i>verax, veracis</i> (truthful), from <i>verus</i> (true).","f":"véridique (« la véracité »)","t":"Véracité = truthfulness. Don’t confuse with voracious (hungry): veracious = vrai.","x":"Look-alike","h":["Ver = truth (verify, verdict). Véridique: tells the truth.","Veracious ≠ voracious. Think “very true”: very + ious = very truthful."],"s":["candid"]},{"w":"vindicate","p":"v.","m":"To clear of blame; to prove right.","e":"Latin <i>vindicare</i>, “to claim, avenge, set free”, from <i>vindex</i> (claimant, avenger). The same verb gave French <i>venger</i> and <i>revendiquer</i>.","f":"disculper, justifier, donner raison à","t":"Vindicate = venger: being proved right is your revenge. When the data vindicated her, she was avenged.","h":["Vindicate = venger: you’re proved right, which feels like revenge. The data vindicated her.","“Vin-dic-ate”: the judge says “not guilty”. Cleared of blame."],"s":["exculpate","exonerate"]},{"w":"wanting","p":"adj.","m":"Lacking; not good enough.","e":"Old Norse <i>vanta</i>, “to lack”, brought by Viking settlers. “Want” meant “lack” long before it meant “desire”.","f":"insuffisant, déficient, qui fait défaut","t":"From the Book of Daniel: “weighed in the balances, and found wanting” (« pesé dans la balance et trouvé léger »).","x":"2nd meaning","h":["Wanting = lacking something. “Found wanting”: weighed on the scale and not enough.","The adjective “wanting” is the verb’s lack: the soup is wanting salt."],"s":["bereft","scant"]}]},{"name":"Common Words II","slug":"common-words-ii","series":"Common Words","words":[{"w":"aesthete","p":"n.","m":"A person with a refined appreciation of art and beauty (sometimes excessive).","e":"Coined in 19th-century English from Greek <i>aisthētēs</i>, “one who perceives”, from <i>aisthanesthai</i> (to perceive, feel). Tied to Oscar Wilde’s Aesthetic movement and “art for art’s sake”.","f":"esthète","t":"Picture Oscar Wilde with a lily and a velvet jacket. Aesthete = the person; aesthetic = the quality.","h":["Aesthete sounds like “S-thete”: someone who is “thete” about beauty, standing for hours in front of a painting.","The friend who rearranges your flowers and sighs at an ugly font: lives for beauty."],"s":["connoisseur"]},{"w":"aesthetic","p":"adj. / n.","m":"Concerned with beauty or artistic taste.","e":"Greek <i>aisthētikos</i>, “of sense perception”, from <i>aisthanesthai</i> (to perceive). The German philosopher Baumgarten gave it the meaning “theory of taste” in the 1700s.","f":"esthétique","t":"Anesthetic = no feeling. Aesthetic = what your senses feel, especially beauty.","h":["Greek aisthesis = perception by the senses. Aesthetics is what looks, sounds and feels good.","An-aesthetic removes feeling; aesthetic is the feeling of beauty. Remove the “an”."],"s":[]},{"w":"apathetic","p":"adj.","m":"Showing no interest, enthusiasm or concern.","e":"Greek <i>apatheia</i>: <i>a-</i> (without) + <i>pathos</i> (feeling, suffering). For the Stoics apatheia was an ideal; in English it became indifference.","f":"apathique, indifférent","t":"A-pathos = no feeling, the opposite of sympathy and passion. Same as French apathique.","h":["A + pathos: no passion. The student who shrugs: “Whatever.”","Apathy sounds like “a path-y”: someone who won’t walk any path because they don’t care where it goes."],"s":["aloof","indifferent","languid","lethargic","nonchalant","sluggish","tepid"]},{"w":"audacious","p":"adj.","m":"Bold and daring; sometimes shamelessly so.","e":"Latin <i>audax, audacis</i> (bold), from <i>audere</i> (to dare).","f":"audacieux","t":"Danton in 1792: « De l’audace, encore de l’audace, toujours de l’audace ! » Audacious can praise or condemn.","h":["Aud: audio + dare (audere): speaks loudly and dares. An audacious plan: dare to try it.","Think of Danton’s « De l’audace ! »: boldness, for good or bad."],"s":["brazen","doughty","impertinent","impudent","insolent","intrepid"]},{"w":"banal","p":"adj.","m":"Lacking originality; trite.","e":"French <i>banal</i>, from the feudal <i>ban</i> (the lord’s jurisdiction; a Frankish word). The <i>four banal</i> and <i>moulin banal</i> were the lord’s oven and mill every villager had to use: “common to all” became “commonplace”.","f":"banal","t":"Picture the village four banal: everyone bakes in the same oven, so every loaf looks the same.","h":["Banal comes from feudal ban: things everyone in the village shared, so common to all. Hence ordinary.","Elevator music: heard so much it’s lost its flavour. Banal."],"s":["hackneyed","hoary","humdrum","mundane","pedestrian","prosaic","quotidian","tedious","trite"]},{"w":"bucolic","p":"adj.","m":"Relating to the pleasant side of country life; pastoral.","e":"Greek <i>boukolikos</i>, “of herdsmen”, from <i>boukolos</i> (cowherd): <i>bous</i> (ox) + <i>-kolos</i> (tending). Virgil’s <i>Bucolics</i> made it a literary genre.","f":"bucolique, champêtre","t":"Bous = ox. A cowherd lounging in a meadow, Virgil-style. Same as French bucolique.","h":["Bou- = cow (Greek bous). Bucolic scene: cows and a meadow, peaceful countryside.","Think “bucket-olic”: a milk bucket in the pasture. Idyllic rural life."],"s":["pastoral","provincial","rustic"]},{"w":"chortle","p":"v. / n.","m":"To laugh in a gleeful, breathy way.","e":"Coined by Lewis Carroll in <i>Through the Looking-Glass</i> (1871) as a blend of chuckle + snort.","f":"glousser, rire de contentement","t":"Chuckle + snort = chortle. The satisfied, slightly smug laugh after winning an argument.","h":["Lewis Carroll invented it: chuckle + snort. He wrote “he chortled in his joy” in Jabberwocky.","Chortle sounds like a throaty giggle: a snorting laugh after a clever pun."],"s":["guffaw"]},{"w":"concede","p":"v.","m":"To admit something is true, often reluctantly; to yield.","e":"Latin <i>concedere</i>, “to give way”: <i>com-</i> + <i>cedere</i> (to go, yield).","f":"concéder, admettre, céder","t":"Concéder: same word. You concede a point in an argument, or concede defeat in an election.","h":["Con + cedere (yield): hand over the point. Concede defeat after the election.","Cédez le passage: you give way to the other. To concede = to give way."],"s":["capitulate","cede","relent","relinquish","yield"]},{"w":"conspicuous","p":"adj.","m":"Clearly visible; attracting attention.","e":"Latin <i>conspicuus</i> (visible), from <i>conspicere</i>, “to look at closely”: <i>com-</i> + <i>specere</i> (to look), the root of spectacle and perspicace.","f":"voyant, manifeste, ostensible","t":"Veblen’s “conspicuous consumption” (1899): the logo-covered handbag bought to be seen. Conspicuous = made to be looked at.","h":["Con + specere (to look): easy to see from afar. A pink coat in a grey crowd.","Conspicuous = you can’t miss it. A neon sign in a dark street."],"s":["blatant","manifest","overt","patent"]},{"w":"cryptic","p":"adj.","m":"Mysterious; obscure in meaning.","e":"Late Latin <i>crypticus</i>, from Greek <i>kryptikos</i>, from <i>kryptos</i> (hidden). Same root as crypt and cryptography.","f":"énigmatique, sibyllin","t":"Kryptos = hidden, like a crypt under a church. A cryptic message keeps its meaning underground.","h":["Crypt = hidden chamber. A cryptic crossword clue hides its answer underground.","A text from your boss: “We need to talk.” Cryptic: no explanation."],"s":["abstruse","arcane","enigmatic","esoteric","impenetrable","inscrutable","obscure","recondite"]},{"w":"culminate","p":"v.","m":"To reach the highest point or climax.","e":"Late Latin <i>culminare</i> (to crown), from <i>culmen</i> (summit). Astronomers used it for a star reaching its highest point in the sky.","f":"culminer, aboutir","t":"« Le point culminant » = the summit. A career that culminates in the CEO role reaches its peak there.","h":["Culmen = summit. A mountain climb culminates at the peak.","Think “culminating” = reaching the culmination, the top of the staircase."],"s":[]},{"w":"culpability","p":"n.","m":"Responsibility for a fault or wrong; blameworthiness.","e":"Latin <i>culpabilis</i> (blameworthy), from <i>culpa</i> (fault, blame).","f":"culpabilité","t":"Mea culpa = my fault. Culpability = culpabilité.","h":["Culpa: mea culpa, “my fault”. Culpability = how much blame is yours.","Culprit and culpable share the root: the one guilty of the act."],"s":[]},{"w":"decorous","p":"adj.","m":"In keeping with good taste and propriety; polite.","e":"Latin <i>decorus</i> (becoming, proper), from <i>decor</i> (seemliness), from <i>decere</i> (to be fitting). Same root as decorum and décent.","f":"bienséant, convenable, digne","t":"Think « le décorum »: decorous behaviour respects decorum. Nothing to do with decorations.","h":["Decor-ous: acts in keeping with the decor of the occasion: a funeral calls for a quiet voice.","Décorum: dressing and behaving as the setting demands. Decorous = proper."],"s":["becoming","demure","genteel","staid"]},{"w":"deferential","p":"adj.","m":"Showing respect and humble submission.","e":"From deference, French <i>déférence</i>, from <i>déférer</i> (to yield to), Latin <i>deferre</i>: <i>de-</i> + <i>ferre</i> (to carry).","f":"déférent, respectueux","t":"Same as « par déférence ». A deferential junior defers to the partner’s judgment.","h":["De + ferre (carry): you carry your opinion down to let the other’s win. Bow to authority.","Par déférence: a junior who lets the senior speak first."],"s":["dutiful","obsequious","pious","reverent","subservient"]},{"w":"dictatorial","p":"adj.","m":"Domineering; imposing one’s will on others.","e":"Latin <i>dictator</i>, from <i>dictare</i> (to say repeatedly, prescribe). In Rome a dictator was a magistrate given absolute power for six months in an emergency.","f":"dictatorial, autoritaire, tyrannique","t":"The one who dictates. A dictatorial manager dictates and nobody else gets to speak.","h":["Dictate + oral: someone who orders everyone else around like a dictator.","In a dictatorial office, the boss decides everything and employees only take notes."],"s":["autocratic","despotic","doctrinaire","dogmatic","imperious","peremptory"]},{"w":"didactic","p":"adj.","m":"Intended to teach, often in a preachy or moralising way.","e":"Greek <i>didaktikos</i>, “apt at teaching”, from <i>didaskein</i> (to teach).","f":"didactique; moralisateur","t":"Same as « didactique ». On the GRE it often stings a little: a didactic novel lectures you.","h":["Didaskein = to teach. A didactic poem is a lecture in verse. A little preachy.","Didactic = “die-dactic”: the teacher who talks until the class dies of boredom."],"s":["aphoristic","pedantic","pithy","sanctimonious","sententious"]},{"w":"diffident","p":"adj.","m":"Shy; lacking self-confidence.","e":"Latin <i>diffidentem</i>, from <i>diffidere</i>, “to mistrust”: <i>dis-</i> (not) + <i>fidere</i> (to trust), as in fidèle and confiance. First it meant distrusting others; now, distrusting yourself.","f":"timide, qui manque d’assurance","t":"Dis + fidere = no trust. Défiance is mistrust of others; diffidence is mistrust of yourself. Opposite: confident (con + fidere).","h":["Dis + fidere (trust): lack of trust in oneself. A shy speaker who whispers.","Diffident ≈ « défiant » but turned inward: you don’t trust your own voice."],"s":["coy","demure","modest","reticent","retiring","self-effacing"]},{"w":"dogmatic","p":"adj.","m":"Asserting opinions as undeniably true; inflexible.","e":"Greek <i>dogmatikos</i>, from <i>dogma</i> (opinion, decree), from <i>dokein</i> (to seem, think).","f":"dogmatique","t":"Dogma = a decree that can’t be questioned. Same as French dogmatique.","h":["Dog + matic: a bulldog that won’t let go of its opinion. Rigid belief.","Dogma = official doctrine. A dogmatic debater cites it and refuses discussion."],"s":["dictatorial","doctrinaire","hidebound"]},{"w":"engender","p":"v.","m":"To cause or give rise to.","e":"Old French <i>engendrer</i>, from Latin <i>ingenerare</i>: <i>in-</i> + <i>generare</i> (to beget), from <i>genus</i> (birth, kind).","f":"engendrer","t":"Same as « engendrer ». A policy engenders resentment the way parents engender children.","h":["En + gender: to give birth to something, like a cause bringing about an effect. Engendrer.","“Engender” has gen = birth (generate, genesis). Hate engenders violence."],"s":["precipitate"]},{"w":"entrenched","p":"adj.","m":"Firmly established and hard to change.","e":"<i>en-</i> + trench, from Old French <i>trenche</i> (a cut, a ditch), from <i>trenchier</i> (now <i>trancher</i>), probably from Latin <i>truncare</i> (to cut off).","f":"ancré, enraciné, retranché","t":"Picture WWI soldiers dug into their tranchées for years. An entrenched belief is dug in and won’t move.","h":["Trench warfare: dug in and unlikely to move. An entrenched habit.","A tree with deep roots: entrenched, almost impossible to remove."],"s":["ingrained","inveterate"]},{"w":"eschew","p":"v.","m":"To deliberately avoid; abstain from.","e":"Old French <i>eschiver</i> (later <i>esquiver</i>), from Frankish <i>skiuhan</i> (to fear, shun). A cousin of English shy and German <i>scheuen</i>.","f":"éviter, esquiver, s’abstenir de","t":"Eschew = esquiver. Say it “es-CHOO” and picture dodging a sneeze. To eschew meat = to avoid it on principle.","h":["Say “es-chew”: you chew and spit out the thing you refuse. Avoid on purpose.","Esquiver: dodge. Eschew sugar = avoid it by choice."],"s":["abstain","avert","forgo"]},{"w":"exacerbate","p":"v.","m":"To make a problem worse.","e":"Latin <i>exacerbare</i> (to irritate, make harsh): <i>ex-</i> + <i>acerbus</i> (harsh, bitter).","f":"exacerber, aggraver","t":"Acerbus = acerbe. Pouring something bitter on a wound: same as « exacerber ».","h":["Ex + acerbus (bitter): make more bitter. Rubbing salt in a wound.","Acerbic = sharp. To exacerbate = to make the pain sharper."],"s":["compound","exasperate"]},{"w":"fortuitous","p":"adj.","m":"Happening by chance (not necessarily lucky).","e":"Latin <i>fortuitus</i> (happening by chance), from <i>fors</i> (chance), the root of Fortuna.","f":"fortuit (« une rencontre fortuite »)","t":"« Une rencontre fortuite » = a chance meeting. On the GRE, fortuitous means accidental, not fortunate.","x":"Look-alike","h":["Fortuit: by chance, not planned. It doesn’t mean fortunate: just a lucky or unlucky accident.","Fortuitous sounds like “fortune”, but think “random fortune”: a coin falling just so."],"s":["adventitious","incidental","providential","serendipitous"]},{"w":"frivolous","p":"adj.","m":"Not serious; silly, trivial.","e":"Latin <i>frivolus</i> (silly, empty, worthless), possibly from <i>friare</i> (to crumble).","f":"frivole","t":"Identical to frivole. Things that crumble into nothing: a frivolous lawsuit has no substance.","h":["Frivole: light as a feather, not serious. A frivolous lawsuit over a spilled coffee.","Frivolous = “free of weight”: it floats away because it has no substance."],"s":["cavalier","fatuous","flippant","glib","irreverent","puerile","trifling","trivial"]},{"w":"gainsay","p":"v.","m":"To deny or contradict.","e":"Middle English: <i>gain-</i>, “against” (Old English <i>gegn</i>, as in again and against) + say. Purely Germanic.","f":"contredire, nier","t":"Gain = against: to say against. “No one can gainsay her results” = no one can contradict them.","h":["Gain = against (as in again-st). Gainsay = say against: contradict.","“Who can gainsay the evidence?” No one can deny it."],"s":["assail","belie","debunk","impugn","negate","refute"]},{"w":"gall","p":"n.","m":"Bold, impudent behaviour; nerve. (Also bitterness, bile.)","e":"Old English <i>gealla</i> (bile), from an Indo-European root for yellow-green; related to Greek <i>cholē</i> (bile, as in cholera and mélancolie). Bitterness became audacity in 19th-century American slang.","f":"culot, toupet; fiel (la bile)","t":"The gall bladder holds bitter bile. Having the gall to ask = avoir le culot. To gall someone = to irritate them.","h":["Gall bladder = bile = bitterness. To have the gall = the bitter nerve to do something rude.","Avoir le culot: gall has the cheek of someone who asks for the boss’s job on day one."],"s":["audacity","effrontery","fester","irk","presumption","rankle","rile","temerity"]},{"w":"germane","p":"adj.","m":"Relevant to the subject at hand.","e":"A variant of <i>german</i>, “of the same parents”, from Latin <i>germanus</i> (full brother or sister). Closely related, hence relevant.","f":"pertinent, en rapport avec","t":"Cousin germain! A germane point is closely related to the topic, like a first cousin.","h":["Germane ≈ germain: cousins-german are close cousins. A germane remark is closely related.","Related like a sibling: germane points belong in the discussion."],"s":["apposite","apropos","apt","felicitous","pertinent"]},{"w":"glut","p":"n. / v.","m":"An excessive supply; to oversupply.","e":"Middle English <i>glotten</i> (to swallow greedily), from Old French <i>gloutir</i>, from Latin <i>gluttire</i> (to swallow). Same root as glouton and engloutir.","f":"surabondance, excédent, saturation","t":"Glouton + engloutir: a market so stuffed it can’t swallow any more. A glut of oil = prices collapse.","h":["Glutton: the market is so full that it can’t eat any more. Too much supply.","Un trop-plein: a glut of grapes means a price crash."],"s":["cornucopia","plethora","profusion","surfeit"]},{"w":"gossamer","p":"n. / adj.","m":"Extremely light, thin and delicate; fine spider silk.","e":"Middle English <i>gossomer</i>, probably “goose summer”: the warm spell in late autumn (St Martin’s summer) when geese were eaten and fine cobwebs floated over the fields.","f":"fils de la Vierge; arachnéen, vaporeux","t":"« Les fils de la Vierge »: threads of spider silk drifting over a field in an Indian summer. Gossamer = that light.","h":["Goose + summer: the thin silk that floats in the air on warm autumn days. Very light cloth.","Gossamer wings of a dragonfly: you see through them, they weigh nothing."],"s":["diaphanous","ethereal"]},{"w":"impudent","p":"adj.","m":"Not showing due respect; shamelessly bold.","e":"Latin <i>impudentem</i> (shameless): <i>in-</i> (not) + <i>pudens</i> (modest), from <i>pudere</i> (to feel shame).","f":"impudent, effronté, insolent","t":"In + pudeur = no shame. Same as French impudent, and close to gall and impertinent.","h":["Im + pudent (pudeur, shame): has no shame. A kid sticking out his tongue at the teacher.","Impudent = no pudeur: the child who walks into your meeting and tells the boss he’s wrong. Cheeky."],"s":["audacious","brazen","flippant","impertinent","insolent","irreverent","presumptuous"]},{"w":"incisive","p":"adj.","m":"Sharp and clear-thinking; going straight to the point.","e":"Medieval Latin <i>incisivus</i>, from <i>incidere</i>, “to cut into”: <i>in-</i> + <i>caedere</i> (to cut).","f":"incisif, tranchant, pénétrant","t":"Your incisives are the cutting teeth. An incisive question cuts straight to the core of the problem.","h":["Incisor: the tooth that cuts. An incisive comment slices to the point.","Scalpel analysis: the incisive analyst cuts away what isn’t relevant."],"s":["acerbic","astute","avid","cogent","compelling","keen","penetrating","perspicacious","shrewd","telling","trenchant"]},{"w":"inexorable","p":"adj.","m":"Impossible to stop or prevent; relentless.","e":"Latin <i>inexorabilis</i>: <i>in-</i> (not) + <i>exorabilis</i> (moved by pleading), from <i>exorare</i>: <i>ex-</i> + <i>orare</i> (to pray, plead; cf. oraison).","f":"inexorable, implacable","t":"In-ex-orare = can’t be moved by prayer. Like death or the tide: beg all you want.","h":["In + exorare (to persuade by prayer): you can’t beg it to stop. Like the tide.","An inexorable rise of sea level: nothing pleads it away."],"s":["implacable","ineluctable"]},{"w":"lambast","p":"v.","m":"To criticise harshly.","e":"1630s, probably <i>lam</i> (to beat, from Old Norse <i>lemja</i>) + <i>baste</i> (to thrash). Both halves mean hitting.","f":"éreinter, fustiger, descendre en flammes","t":"Lam + baste = beat + beat. A critic who lambasts a film gives it a double thrashing: « se faire éreinter par la critique ».","h":["Same as lambaste: lam (beat) + baste (beat). A blistering review.","Think of a lamb being basted… with criticism! Lambast the movie harshly."],"s":["berate","castigate","censure","excoriate","lambaste","rebuke","upbraid"]},{"w":"mawkish","p":"adj.","m":"Excessively, sickly sentimental.","e":"From <i>mawk</i> (maggot), Old Norse <i>maðkr</i>. In the 1660s it meant “sickly, nauseated”; by the 1700s, “sickly-sweet sentimental”.","f":"mièvre, à l’eau de rose, gnangnan","t":"Sentimentality so sweet it turns your stomach like maggots. A mawkish Christmas ad = mièvre.","h":["Maggot in origin (mawk): sentimentality so sweet it makes you sick. A soppy greeting card.","Mièvre: syrup on top of syrup. Mawkish = sickly sweet."],"s":["cloying","lachrymose","maudlin","sentimental"]},{"w":"meticulous","p":"adj.","m":"Showing great attention to detail; very careful.","e":"Latin <i>meticulosus</i> (fearful, timid), from <i>metus</i> (fear). In 19th-century French, <i>méticuleux</i> shifted to “afraid of making mistakes”, hence careful.","f":"méticuleux, minutieux","t":"Same as méticuleux. Metus = fear: a meticulous person is scared of making a single mistake.","h":["Metus = fear: afraid of errors, so careful. The accountant who checks every cell twice.","Meticulous = “meticulously” counting: details, details, details."],"s":["assiduous","captious","exacting","exhaustive","fastidious","finicky","painstaking","pedantic","punctilious","scrupulous","thorough"]},{"w":"mitigate","p":"v.","m":"To make less severe or painful.","e":"Latin <i>mitigare</i> (to soften): <i>mitis</i> (mild, gentle) + <i>agere</i> (to make).","f":"atténuer, adoucir, mitiger","t":"Mitigating circumstances = « circonstances atténuantes ». Mitis = soft: you soften the blow.","h":["Mitis = mild: to make milder. A lawyer’s mitigating factors soften the sentence.","Mitigate: like a mitten on a cold hand, it softens the sting."],"s":["alleviate","assuage","mollify","palliate","qualify","temper"]},{"w":"obscure","p":"adj. / v.","m":"Not well known, or unclear; to conceal.","e":"Latin <i>obscurus</i> (dark, dim, hidden).","f":"obscur; obscurcir","t":"Identical to obscur. Something in the dark is either unknown or hard to see clearly.","h":["Obscurus = dark. An obscure poet: you can’t see him because he’s in the dark.","Ob + scure: covered over. Obscure instructions hide their meaning."],"s":["abstruse","arcane","cryptic","eclipse","enigmatic","esoteric","impenetrable","inscrutable","obfuscate","opaque","recondite","turbid"]},{"w":"perfidy","p":"n.","m":"Deceitfulness; treachery.","e":"Latin <i>perfidia</i> (faithlessness): <i>per-</i> (away, to ruin) + <i>fides</i> (faith).","f":"perfidie","t":"« La perfide Albion »: the classic French jab at England’s supposed treachery. Per + fides = breaking faith.","h":["Per (through) + fides (faith): faith broken. La perfide Albion.","Perfidy = Judas’s kiss: a treacherous betrayal by one who seemed loyal."],"s":["duplicity","guile"]},{"w":"platitude","p":"n.","m":"A remark used too often to be interesting; a cliché.","e":"French <i>platitude</i> (17th century), “flatness”, from <i>plat</i> (flat), from Vulgar Latin <i>plattus</i>, from Greek <i>platys</i> (broad, flat).","f":"platitude, banalité, lieu commun","t":"Same as « platitude »: a flat, dull remark. “Let’s think outside the box” is a corporate platitude.","h":["Plat = flat: a flat remark with no depth. “Everything happens for a reason.”","Platitude: a cliché, said with a straight face: “Time heals all wounds.”"],"s":["banality","bromide"]},{"w":"preclude","p":"v.","m":"To prevent from happening; make impossible.","e":"Latin <i>praecludere</i> (to shut off in advance): <i>prae-</i> (before) + <i>claudere</i> (to close).","f":"empêcher, exclure, écarter","t":"Pre + close = closing the door in advance. Same root as exclude and clore.","h":["Pre + claudere (to close): close the door beforehand. A broken leg precludes running the marathon.","Preclude = exclude in advance. A fire precludes the use of the stairs."],"s":["avert","foil","forestall","frustrate","hinder","obviate","preempt","stymie","thwart"]},{"w":"predilection","p":"n.","m":"A preference or special liking.","e":"French <i>prédilection</i>, from Medieval Latin <i>praedilectio</i>: <i>prae-</i> (before) + <i>diligere</i> (to love, choose).","f":"prédilection","t":"Identical: « un sujet de prédilection ». A predilection for good coffee is a favourite habit.","h":["Pre + diligere (to love): a prior love. A predilection for chocolate.","Prédilection: your favourite, chosen before the others. A weakness for something."],"s":["penchant","proclivity","propensity"]},{"w":"prescience","p":"n.","m":"Knowledge of events before they happen; foresight.","e":"Latin <i>praescientia</i>: <i>prae-</i> (before) + <i>scire</i> (to know).","f":"prescience, clairvoyance","t":"Pre + science = knowing before. A prescient investor saw the crash coming.","h":["Pre + science: knowing in advance. The prescient trader sold before the crash.","Prescient sounds like “precious sight”: foreseeing the future."],"s":[]},{"w":"querulous","p":"adj.","m":"Complaining in a whining, petulant way.","e":"Latin <i>querulus</i>, from <i>queri</i> (to complain). Same root as querelle and quarrel.","f":"plaintif, geignard, ronchon","t":"Queri → querelle. A querulous person picks small complaints all day long.","h":["Querela = complaint (querelle). The querulous guest sends back the soup twice.","Sounds like “quarrel-ous”: always whining over small things."],"s":["carping","fractious","peevish","petulant","plaintive"]},{"w":"recondite","p":"adj.","m":"Little known; obscure; hard to understand.","e":"Latin <i>reconditus</i> (hidden, put away), from <i>recondere</i>: <i>re-</i> + <i>condere</i> (to put, store). Its cousin <i>abscondere</i> (to hide away) gave French <i>abscons</i>.","f":"abscons, ésotérique, obscur","t":"Recondite ≈ abscons: knowledge stored away where few can find it, like a footnote in a dusty archive.","h":["Re + condere (to hide): hidden away. A recondite theory only experts know.","Recondite = « abscons »: like a manuscript in a locked cellar."],"s":["abstruse","arcane","cryptic","esoteric","obscure"]},{"w":"reticent","p":"adj.","m":"Not revealing one’s thoughts readily; reserved.","e":"Latin <i>reticentem</i>, from <i>reticere</i> (to keep silent): <i>re-</i> + <i>tacere</i> (to be silent), as in taciturne.","f":"réservé, discret, taciturne (≠ réticent)","t":"Tacere = se taire: a reticent person holds back their words. Modern French réticent means reluctant; for the GRE, think taciturn.","x":"Faux ami","h":["Re + tacere (to be silent): holding back. A reticent witness says little.","Un homme réservé: reticent = unwilling to speak, not necessarily reluctant to act."],"s":["diffident","evasive","laconic","modest","retiring","self-effacing","taciturn","unforthcoming"]},{"w":"rustic","p":"adj.","m":"Of the countryside; simple, unsophisticated.","e":"Latin <i>rusticus</i>, from <i>rus</i> (countryside), as in rural.","f":"rustique, campagnard","t":"Same as rustique. Rus = countryside: a rustic table is rough wood from the farm.","h":["Rus = countryside. A rustic cabin: simple, wood, no frills.","Rustic charm: rough stone walls and a farm table. Rural simplicity."],"s":["bucolic","insular","parochial","pastoral","provincial"]},{"w":"superfluous","p":"adj.","m":"Unnecessary; more than enough.","e":"Latin <i>superfluus</i> (overflowing): <i>super</i> (over) + <i>fluere</i> (to flow).","f":"superflu","t":"Superflu: water overflowing the glass. The extra words on a slide are superfluous.","h":["Super + fluere (flow over): the water running over the rim is surplus. Unnecessary.","Superfluous adjectives: delete them; the sentence works without them."],"s":["extraneous","immaterial","impertinent","redundant","tangential"]},{"w":"torpor","p":"n.","m":"Physical or mental inactivity; lethargy.","e":"Latin <i>torpor</i> (numbness), from <i>torpere</i> (to be numb). The Latin <i>torpedo</i> was the electric ray, the fish that numbs its prey.","f":"torpeur, léthargie","t":"« La torpeur de l’après-midi ». Picture being zapped by a torpille fish: numb and sluggish.","h":["Torpedo fish (the electric ray) stuns you into numbness. Torpor = sluggish stillness.","Torpeur d’été: the heat makes you slow, like a lizard on a rock."],"s":["apathy","ennui","indifference","lassitude"]},{"w":"vociferous","p":"adj.","m":"Loud and forceful in expressing opinions.","e":"Latin <i>vociferari</i> (to shout): <i>vox, vocis</i> (voice) + <i>ferre</i> (to carry).","f":"véhément, bruyant, vociférant","t":"« Vociférer » = to yell. A vociferous critic carries their voice far and loud.","h":["Voc = voice + ferre (carry): carries a loud voice. A vociferous protest.","Vociferous: a crowd shouting complaints through megaphones."],"s":["boisterous","clamorous","obstreperous","vehement"]},{"w":"volubility","p":"n.","m":"Fluent, ready, continuous speech; talkativeness.","e":"Latin <i>volubilis</i> (that turns, rolls easily), from <i>volvere</i> (to roll).","f":"volubilité, loquacité","t":"Words that keep rolling out (volvere). Same as « volubilité ». Opposite of laconic and reticent.","h":["Volvere (roll): words keep rolling out. A voluble talker never stops.","Volubilité: a taxi driver who talks nonstop all the way from the airport."],"s":[]}]},{"name":"Common Words III","slug":"common-words-iii","series":"Common Words","words":[{"w":"abstain","p":"v.","m":"To deliberately refrain from doing or consuming something.","e":"Latin <i>abstinere</i>, “to hold oneself back”: <i>abs-</i> (away) + <i>tenere</i> (to hold). Came through Old French <i>abstenir</i>.","f":"s’abstenir","t":"Same as « s’abstenir » (and l’abstention in a vote). You hold yourself away from the thing.","h":["Abs + tenere: hold yourself away. Abstain from voting, from sugar, from the second slice.","Dry January: you abstain from wine. Keep your hands off it."],"s":["avert","eschew","forbear","forgo"]},{"w":"ameliorate","p":"v.","m":"To make something bad better; improve.","e":"From French <i>améliorer</i>, from Latin <i>ad-</i> + <i>melior</i> (better). The 18th-century English form added Latin-looking <i>-ate</i>.","f":"améliorer","t":"Ameliorate = améliorer, word for word. Melior = meilleur.","h":["Melior = better (meilleur). Ameliorate: make it meilleur.","The “A-MELIOrate” team arrives to improve the slum conditions."],"s":["amend","redress"]},{"w":"apathy","p":"n.","m":"Lack of interest, enthusiasm or concern.","e":"Greek <i>apatheia</i>: <i>a-</i> (without) + <i>pathos</i> (feeling, suffering). The Stoics prized it as freedom from passion.","f":"apathie, indifférence","t":"A-pathos = no feeling, the opposite of sympathy. Same as « apathie ».","h":["A + pathos: no feeling. Voter apathy: “Why bother?”","Apathy ≈ “a-path-y”: you don’t even walk down the path because you don’t care."],"s":["indifference","torpor"]},{"w":"ascetic","p":"adj. / n.","m":"Practising strict self-denial; a person who does so.","e":"Greek <i>askētikos</i>, from <i>askētēs</i> (monk, hermit), from <i>askein</i> (to exercise, train). First used of athletes in training, then of hermits training the soul.","f":"ascétique, ascète","t":"Picture a desert hermit training like an athlete, but for the soul: no food, no comfort. « Une vie ascétique ».","h":["Askesis = training. A monk who sleeps on a board and eats bread and water.","The ascetic’s room: a mat, a cup, nothing else. Self-denial for a higher goal."],"s":["abstemious","austere","frugal","spartan"]},{"w":"avaricious","p":"adj.","m":"Extremely greedy for wealth.","e":"Latin <i>avaritia</i> (greed), from <i>avarus</i> (greedy), from <i>avere</i> (to crave).","f":"avare, cupide","t":"Molière’s « L’Avare », Harpagon clutching his cash box. Avaricious = avare, and greedy for more.","h":["Harpagon hoarding gold: avarice = greed for money.","Avaricious sounds like “a very rich-ous” wish: always wanting even more."],"s":["acquisitive","mercenary","miserly","parsimonious","penurious","rapacious","ravenous","venal","voracious"]},{"w":"belligerent","p":"adj.","m":"Hostile and aggressive; eager to fight.","e":"Latin <i>belligerare</i>, “to wage war”: <i>bellum</i> (war) + <i>gerere</i> (to carry on).","f":"belliqueux, agressif (belligérant = at war)","t":"Bellum = war, as in « belliqueux ». A belligerent client is looking for a fight.","h":["Bellum (war): the drunk who picks a fight in the bar.","A belligerent tone: shouting the first insult before the conversation begins."],"s":["bellicose","contentious","martial","pugnacious","truculent"]},{"w":"circumvent","p":"v.","m":"To find a way around an obstacle or rule.","e":"Latin <i>circumvenire</i>, “to come around, surround”: <i>circum</i> (around) + <i>venire</i> (to come).","f":"contourner","t":"Circum + venir = to come around it. « Contourner la règle ».","h":["Circum + venire: go around the fence instead of through the gate.","The tax lawyer who circumvents the law finds the detour."],"s":["balk","check","elude","evade","foil","frustrate","skirt","stymie","thwart"]},{"w":"contrive","p":"v.","m":"To plan or bring about cleverly, often artificially.","e":"Old French <i>controver</i> (to invent, find), from Late Latin <i>contropare</i> (to compare). A contrived plot feels artificial.","f":"inventer, combiner, manigancer; contrived = artificiel","t":"Old French controuver = to invent. A contrived ending is invented too obviously: « forcé, artificiel ».","h":["Con + trouver: you “find” (make up) a plan. A contrived plot feels forced, built to order.","Contrived = contrivance, a made-up gadget. An artificial happy ending."],"s":["coin","fabricate","finagle","premeditate"]},{"w":"delineate","p":"v.","m":"To describe or outline precisely.","e":"Latin <i>delineare</i>, “to sketch out”: <i>de-</i> + <i>linea</i> (line).","f":"décrire, délimiter, tracer","t":"De + linea = drawing the lines of something. A good brief delineates the scope.","h":["De + linea: draw the lines. Delineate the border on the map.","A clear brief delineates who does what: every role outlined."],"s":[]},{"w":"denote","p":"v.","m":"To indicate; to be the literal meaning of.","e":"Latin <i>denotare</i>, “to mark out”: <i>de-</i> + <i>notare</i> (to mark), from <i>nota</i> (a mark).","f":"dénoter, désigner, signifier","t":"Same as « dénoter ». Denote = the dictionary meaning; connote = the feeling around it.","h":["De + nota: to mark. Red denotes danger; the dictionary meaning, not the feeling.","Denote = literal meaning (a rose denotes a flower); connote = associations (love)."],"s":[]},{"w":"derivative","p":"adj. / n.","m":"Imitative of another’s work; unoriginal. (Also something derived.)","e":"Late Latin <i>derivativus</i>, from <i>derivare</i>, “to draw off a stream”: <i>de-</i> + <i>rivus</i> (stream).","f":"dérivé; peu original","t":"Water drawn off someone else’s stream. On the GRE, a derivative novel copies others.","h":["Derive: flow from a river. A derivative film flows from other films with no fresh water.","In finance a derivative is derived from an underlying asset; in art a derivative work copies another."],"s":[]},{"w":"derive","p":"v.","m":"To obtain or trace from a source.","e":"Old French <i>deriver</i>, from Latin <i>derivare</i>: <i>de-</i> (from) + <i>rivus</i> (stream). Channelling water off a river.","f":"tirer de, dériver de","t":"Picture a channel drawing water from a river: you derive pleasure from a source.","h":["De + rivus (stream): to draw off from a stream. Derive meaning from the text.","Derive = tirer de: you draw a conclusion from the evidence."],"s":[]},{"w":"disaffected","p":"adj.","m":"Dissatisfied and no longer loyal, especially to authority.","e":"<i>dis-</i> (reverse) + <i>affect</i> (to love, from Latin <i>affectare</i>). Literally having lost one’s affection.","f":"désabusé, mécontent, en rupture","t":"Dis + affection: loyalty and love gone. Disaffected voters have given up on the party.","h":["Dis + affection: love and loyalty gone. The voter who no longer feels part of any party.","Disaffected youth: bored, resentful, cut off from the system."],"s":["divorced","estranged","jaundiced"]},{"w":"eclectic","p":"adj.","m":"Drawing on a wide variety of sources or styles.","e":"Greek <i>eklektikos</i>, “selective”, from <i>eklegein</i>: <i>ek</i> (out) + <i>legein</i> (to pick). Ancient philosophers who picked the best from every school.","f":"éclectique","t":"Ek + legein = picking out the best bits. « Des goûts éclectiques ».","h":["Ek + legein: pick out. An eclectic playlist: jazz, techno and opera.","Eclectic = a buffet where you pick from many cuisines."],"s":["catholic","universal"]},{"w":"elucidate","p":"v.","m":"To make clear; explain.","e":"Late Latin <i>elucidare</i>: <i>e-</i> (out) + <i>lucidus</i> (bright), from <i>lux</i> (light).","f":"élucider, éclaircir","t":"Same as « élucider ». Lux = light: you shine light on the mystery.","h":["E + lux (light): shed light on it. A good teacher elucidates the proof.","Lucid + ate: make lucid, make clear."],"s":["crystallize","elaborate","expatiate","expound"]},{"w":"eminent","p":"adj.","m":"Famous and respected; outstanding.","e":"Latin <i>eminentem</i>, from <i>eminere</i>, “to stand out”: <i>e-</i> + <i>minere</i> (to project). Related to Latin <i>mons</i> (mountain).","f":"éminent","t":"Une éminence = a hill that sticks out. An eminent scientist stands above the crowd. Not imminent (about to happen).","h":["E + minere (to jut out): stands above the crowd. An eminent professor.","Eminent ≠ imminent. Eminent = distinguished; imminent = about to happen. Same “e” for “excellent”."],"s":["august","illustrious"]},{"w":"ephemeral","p":"adj.","m":"Lasting a very short time.","e":"Greek <i>ephēmeros</i>, “lasting a day”: <i>epi</i> (on) + <i>hēmera</i> (day). The mayfly (<i>éphémère</i>) lives one day.","f":"éphémère","t":"Same as « éphémère »: the mayfly that lives a single day. Ephemeral fame, ephemeral trends.","h":["Epi + hemera (day): lasts one day. A mayfly, a soap bubble, a trend on TikTok.","The ephemeral beauty of cherry blossom: gone in a week."],"s":["evanescent","momentary","transient","transitory"]},{"w":"fallacious","p":"adj.","m":"Based on a mistaken belief; misleading.","e":"Latin <i>fallaciosus</i>, from <i>fallacia</i> (deceit), from <i>fallere</i> (to deceive). Same root as false and fail.","f":"fallacieux","t":"Identical to « fallacieux ». A fallacy is a trick of reasoning.","h":["Fallere: to deceive. A fallacious argument looks sound but fools you.","A fallacy is a false step in logic. Fallacious = based on one."],"s":["bogus","counterfeit","phony","sham","specious","spurious"]},{"w":"forlorn","p":"adj.","m":"Pitifully sad and abandoned.","e":"Old English <i>forloren</i>, past participle of <i>forlēosan</i> (to lose completely): <i>for-</i> + <i>lēosan</i> (to lose). Germanic, cousin of German <i>verloren</i>.","f":"abandonné, triste, délaissé","t":"For-lorn = for-lost, verloren. A forlorn puppy left at the roadside.","h":["For + lorn (lost): completely lost, abandoned. A forlorn teddy bear on the road.","Forlorn hope: a mission with almost no chance. Sad, helpless."],"s":["abject","bereft","crestfallen","glum"]},{"w":"frustrate","p":"v.","m":"To prevent a plan from succeeding; to annoy.","e":"Latin <i>frustrari</i> (to disappoint, deceive), from <i>frustra</i> (in vain).","f":"contrecarrer, déjouer; frustrer","t":"Frustra = in vain. On the GRE, “frustrate a plan” = déjouer: make it come to nothing.","h":["Frustra: in vain. To frustrate a plan: make it go for nothing.","Not just annoyed: bad weather frustrated our picnic = ruined it."],"s":["balk","check","circumvent","foil","hamper","hinder","impede","preclude","stymie","thwart"]},{"w":"guileless","p":"adj.","m":"Innocent and without deception.","e":"<i>guile</i> (Old French <i>guile</i>, deceit, probably from Frankish, related to wile) + <i>-less</i>.","f":"candide, sans malice","t":"Guile = ruse. Guileless = sans ruse. A guileless child tells the truth without thinking.","h":["Guile = trickery (guile in French: guile ~ ruse). Guileless: no tricks. A toddler’s honesty.","“Guile-less” = “trick-less”: wears every thought on his face."],"s":["artless","candid","ingenuous","naive"]},{"w":"haughty","p":"adj.","m":"Arrogantly superior and disdainful.","e":"From <i>haught</i>, Old French <i>haut</i> (high), from Latin <i>altus</i>. The <i>gh</i> was added by analogy with high.","f":"hautain","t":"Haughty = hautain, from haut. Someone looking down on you from high up.","h":["Haut = high: looks down his nose. The haughty maître d’.","Haughty ≈ « hautain »: chin up, nose in the air."],"s":["cavalier","flippant","glib","imperious","nonchalant","overweening","presumptuous","snide","supercilious"]},{"w":"heretic","p":"n.","m":"Someone who holds views contrary to accepted belief.","e":"Greek <i>hairetikos</i> (able to choose), from <i>hairesis</i> (a choosing, a sect).","f":"hérétique","t":"Hairesis = a choice. The heretic chose a different belief from the Church. Same as « hérétique ».","h":["Hairesis = choice: you chose your own belief. Galileo, a heretic for the Church.","A heretic sits in the wrong pew: believes something against accepted doctrine."],"s":["apostate","dissident","heterodox","iconoclast"]},{"w":"immutable","p":"adj.","m":"Unchanging; unable to be changed.","e":"Latin <i>immutabilis</i>: <i>in-</i> (not) + <i>mutare</i> (to change), as in mutation.","f":"immuable","t":"No mutation possible. « Les lois immuables de la physique ».","h":["In + mutare (change): can’t mutate. The laws of physics, immutable.","Immutable = set in stone: a statue never changes expression."],"s":["irrevocable"]},{"w":"incongruous","p":"adj.","m":"Out of place; not in harmony with the surroundings.","e":"Latin <i>incongruus</i>: <i>in-</i> (not) + <i>congruus</i> (agreeing), from <i>congruere</i> (to come together).","f":"incongru, déplacé","t":"Same as « incongru ». Flip-flops at a board meeting.","h":["In + congruere (agree): doesn’t match. A tuxedo at a barbecue.","Incongruous = a tuba in a string quartet: out of place."],"s":["anomalous","discordant"]},{"w":"insidious","p":"adj.","m":"Spreading gradually and harmfully, often unnoticed.","e":"Latin <i>insidiosus</i> (cunning), from <i>insidiae</i> (ambush), from <i>insidere</i> (to sit in, lie in wait).","f":"insidieux, sournois","t":"Insidiae = an ambush. An insidious disease lies in wait. Same as « insidieux ».","h":["Insidiae = ambush: creeps up on you. An insidious cough that slowly gets worse.","Insidious: a snake in the grass. Harmful, hidden, gradual."],"s":["deleterious","noxious","pernicious","subtle","treacherous"]},{"w":"itinerant","p":"adj.","m":"Travelling from place to place.","e":"Late Latin <i>itinerantem</i>, from <i>itinerari</i> (to travel), from <i>iter, itineris</i> (journey).","f":"itinérant, ambulant","t":"Iter = journey, as in itinéraire. Itinerant workers follow the harvest.","h":["Iter = journey: an itinerary on legs. An itinerant preacher goes village to village.","Itinérant: a circus on the road. No fixed address."],"s":["peripatetic"]},{"w":"jingoism","p":"n.","m":"Extreme, aggressive patriotism.","e":"From a British music-hall song of 1878 supporting war against Russia, with the oath “by Jingo” (a euphemism for Jesus). Supporters were mocked as jingoes.","f":"chauvinisme, nationalisme belliqueux","t":"Picture Victorian Londoners singing for war in a music hall. Same idea as French « chauvinisme ».","h":["From a music-hall song “by Jingo!” in 1878: cheering for war. Flag-waving to excess.","Jingo is a harmless oath, but jingoism is militant nationalism."],"s":["chauvinism"]},{"w":"jubilant","p":"adj.","m":"Feeling or expressing great joy.","e":"Latin <i>iubilare</i> (to shout with joy), originally a shepherd’s call; later linked to the Hebrew <i>yobel</i> (jubilee).","f":"jubilant, exultant","t":"« Jubiler » = to rejoice. A jubilant crowd after a final whistle.","h":["Jubilee: celebration. A jubilant crowd after the goal.","Jubilant ≈ « jubiler »: shouting for joy in the street."],"s":["elated","euphoric"]},{"w":"juxtapose","p":"v.","m":"To place side by side for contrast.","e":"French <i>juxtaposer</i>, from Latin <i>iuxta</i> (beside) + French <i>poser</i> (to place).","f":"juxtaposer","t":"Identical to « juxtaposer ». A before/after slide juxtaposes two images.","h":["Juxta = next to + pose: place side by side. Old and new buildings juxtaposed in Paris.","A comparison slide: two pictures juxtaposed so you see the difference."],"s":[]},{"w":"languid","p":"adj.","m":"Slow and relaxed; lacking energy.","e":"Latin <i>languidus</i> (faint, weak), from <i>languere</i> (to be weak). Same root as languish.","f":"langoureux, alangui, nonchalant","t":"Think « languir » and « langueur »: a languid afternoon in the heat.","h":["Languid ≈ langoureux: heat, a hammock, slow movement. A languid wave of the hand.","Languid = “languish”: sinking slowly into inactivity."],"s":["apathetic","dilatory","lethargic","sluggish"]},{"w":"magnanimous","p":"adj.","m":"Generous and forgiving, especially to a rival.","e":"Latin <i>magnanimus</i>: <i>magnus</i> (great) + <i>animus</i> (soul, spirit).","f":"magnanime","t":"Magna + anima = a great soul. Same as « magnanime ». The winner who praises the loser.","h":["Magna + anima: great soul. The winner who shakes the loser’s hand.","A magnanimous boss forgives the mistake and moves on."],"s":["benevolent","munificent","noble"]},{"w":"mollify","p":"v.","m":"To calm someone’s anger or anxiety.","e":"Latin <i>mollificare</i>: <i>mollis</i> (soft) + <i>facere</i> (to make).","f":"apaiser, amadouer","t":"Mollis = mou. To mollify an angry client = to soften them.","h":["Mollis (soft) + facere: make soft. A free dessert mollifies the angry diner.","Think of a mollusc: soft. To mollify = soften anger."],"s":["appease","assuage","conciliate","mitigate","pacify","placate","propitiate","qualify","reconcile","temper"]},{"w":"negligible","p":"adj.","m":"So small or unimportant it can be ignored.","e":"From French <i>négligeable</i>, from Latin <i>neglegere</i> (to disregard): <i>nec</i> (not) + <i>legere</i> (to pick up).","f":"négligeable","t":"Identical to « négligeable ». Something you can neglect.","h":["Neglect-able: you can neglect it. A negligible difference of 0.01%.","Negligible = peanuts: so small it doesn’t matter."],"s":["extraneous","immaterial","inconsequential","paltry","picayune","trifling","trivial"]},{"w":"panache","p":"n.","m":"Flamboyant confidence of style.","e":"French <i>panache</i>, the plume of feathers on a helmet, from Italian <i>pennacchio</i>, from Latin <i>penna</i> (feather).","f":"panache","t":"Cyrano de Bergerac’s last word: « mon panache »! The helmet plume worn with style.","h":["Panache = the plume on a helmet. Cyrano’s last word: « Mon panache ! ». Style with bravado.","Panache at the Oscars: the dress and the walk. Flair."],"s":["verve","vitality"]},{"w":"precocious","p":"adj.","m":"Having developed abilities unusually early.","e":"Latin <i>praecox</i>, “ripened early”: <i>prae</i> (before) + <i>coquere</i> (to cook, ripen).","f":"précoce","t":"Same as « précoce »: cooked before its time. A precocious child reads at three.","h":["Pre + coquere (cook): cooked early. A child prodigy at the piano.","Precocious apricots: ripe in April. Skilled or mature before their time."],"s":[]},{"w":"quotidian","p":"adj.","m":"Ordinary, everyday.","e":"Latin <i>quotidianus</i>, from <i>quotidie</i> (daily): <i>quot</i> (how many) + <i>dies</i> (day).","f":"quotidien","t":"Quotidian = « quotidien ». Le Quotidien, your daily paper: totally ordinary.","h":["Quotidian ≈ quotidien: your daily routine, nothing exciting.","The quotidian: the commute, the dishes, the emails."],"s":["banal","humdrum","mundane","pedestrian","prosaic"]},{"w":"refractory","p":"adj.","m":"Stubborn and unmanageable.","e":"Latin <i>refractarius</i> (obstinate), from <i>refringere</i> (to break back): <i>re-</i> + <i>frangere</i> (to break).","f":"réfractaire, rebelle","t":"Les « réfractaires » refused to submit (e.g. to the STO in WWII). Refractory = resists control.","h":["Re + frangere (break): resists, like a wave breaking back. A refractory mule won’t move.","Refractory = « réfractaire »: the pupil who refuses all instruction."],"s":["capricious","contumacious","fractious","headstrong","intractable","obdurate","obstinate","obstreperous","peevish","pertinacious","petulant","recalcitrant","restive","unruly","wayward","willful"]},{"w":"rudimentary","p":"adj.","m":"Basic, elementary; undeveloped.","e":"Latin <i>rudimentum</i> (first attempt), from <i>rudis</i> (rough, untrained).","f":"rudimentaire","t":"Identical to « rudimentaire ». Rudis = raw, rough.","h":["Rudis = raw: a rudimentary shelter of branches, basic and unrefined.","Rudimentary skills: you know the ABC but not the sentences."],"s":["elementary","embryonic","fledgling","inchoate","incipient","nascent","residual","vestigial"]},{"w":"spurious","p":"adj.","m":"False; not genuine or valid.","e":"Late Latin <i>spurius</i> (illegitimate, of unknown father).","f":"faux, fallacieux, apocryphe","t":"Spurius = illegitimate child: a spurious argument doesn’t come from a real source.","h":["Spurius = illegitimate: a spurious claim has no right parent. Fake logic.","Spurious correlation: ice-cream sales and drownings both rise in summer, but one doesn’t cause the other."],"s":["apocryphal","bogus","counterfeit","dubious","ersatz","fallacious","phony","plausible","sham","specious"]},{"w":"staunch","p":"adj.","m":"Very loyal and committed.","e":"Old French <i>estanche</i> (watertight), from <i>estanchier</i> (to stop a flow). Watertight → reliable → loyal.","f":"loyal, fervent, inébranlable","t":"Étanche = watertight! A staunch ally never leaks.","h":["Étanche: watertight. A staunch friend doesn’t leak your secrets.","Staunch supporter: stays loyal through every defeat."],"s":["adamant","check","dogged","resolute","robust","stalwart","stanch","steadfast","stem"]},{"w":"subsume","p":"v.","m":"To include within a larger group.","e":"Modern Latin <i>subsumere</i>: <i>sub</i> (under) + <i>sumere</i> (to take).","f":"englober, subsumer","t":"Take under: the smaller category is taken under the bigger one.","h":["Sub + sumere (take): take under a larger heading. Poodles are subsumed under dogs.","Subsume: absorb the small idea into the larger theory."],"s":["incorporate"]},{"w":"supplant","p":"v.","m":"To replace, often by force or scheming.","e":"Latin <i>supplantare</i>, “to trip up”: <i>sub</i> (under) + <i>planta</i> (sole of the foot).","f":"supplanter, évincer","t":"Same as « supplanter »: you trip someone up and take their place.","h":["Sub + planta (sole of the foot): to trip up. Supplant the CEO by intrigue.","Supplanter: a young rival who takes the old star’s place."],"s":["depose","oust","supersede"]},{"w":"tantamount","p":"adj.","m":"Equivalent in seriousness to.","e":"Anglo-French <i>tant amunter</i>, “to amount to as much”: <i>tant</i> (so much) + <i>amonter</i> (to go up, amount).","f":"équivalent à, qui revient à","t":"Tant + monter = amounts to as much. Silence is tantamount to consent.","h":["Tant + amount (monter): as much. A refusal tantamount to a no.","Tantamount = amounts to the same: silence is tantamount to a yes."],"s":["commensurate"]},{"w":"tenacious","p":"adj.","m":"Holding firmly; persistent.","e":"Latin <i>tenax, tenacis</i>, from <i>tenere</i> (to hold).","f":"tenace","t":"Same as « tenace »: a grip that won’t let go.","h":["Tenax: holding fast. A bulldog’s grip, a tenacious lawyer.","Tenir: you hold on. A tenacious stain won’t come out."],"s":["dogged","headstrong","obdurate","obstinate","pertinacious","resolute"]},{"w":"travesty","p":"n.","m":"A false, absurd or distorted version of something.","e":"French <i>travesti</i> (disguised), from Italian <i>travestire</i>: <i>tra-</i> (across) + <i>vestire</i> (to dress).","f":"parodie, simulacre","t":"« Travesti » = dressed up as something else. A travesty of justice is justice in disguise.","h":["Travesti = dressed as something else. A travesty of justice dresses up unfairness as a trial.","A travesty: the cheap parody that mocks the original. A sham."],"s":["caricature","lampoon","sham"]},{"w":"treacherous","p":"adj.","m":"Guilty of betrayal; also hazardous.","e":"Old French <i>trecherous</i>, from <i>trechier</i> (to cheat, trick).","f":"traître, perfide; dangereux","t":"Think « tricher »: a treacherous friend cheats you; a treacherous road tricks your tyres.","h":["Tricher: cheating friends, a treacherous betrayal; also an icy treacherous road.","Treacherous waters: calm on top, deadly below. Deceptive."],"s":["disingenuous","duplicitous","insidious","perfidious","pernicious","subtle"]},{"w":"unequivocal","p":"adj.","m":"Leaving no doubt; unambiguous.","e":"<i>un-</i> + equivocal, from Late Latin <i>aequivocus</i>: <i>aequus</i> (equal) + <i>vox</i> (voice).","f":"sans équivoque, catégorique","t":"Exactly « sans équivoque »: only one voice speaking.","h":["Un + equivocal: only one voice. An unequivocal yes.","« Sans équivoque »: no doubt at all, one meaning."],"s":["conclusive","explicit","irrefutable","overt"]},{"w":"vehement","p":"adj.","m":"Showing strong, forceful feeling.","e":"Latin <i>vehementem</i> (impetuous, violent), possibly from <i>vehere</i> (to carry) + <i>mens</i> (mind): carried away.","f":"véhément","t":"Same as « véhément »: a mind carried away by passion.","h":["Vehere (carry): carried away by passion. A vehement protest.","Vehement ≈ véhément: a voice shaking with force."],"s":["ardent","clamorous","fervent","vociferous"]},{"w":"vilify","p":"v.","m":"To speak or write about in an abusive, disparaging way.","e":"Late Latin <i>vilificare</i>: <i>vilis</i> (cheap, base) + <i>facere</i> (to make).","f":"diffamer, dénigrer, vilipender","t":"Make vile = « vilipender ». The tabloids vilified her.","h":["Vile + ify: make out to be vile. The press vilified the minister.","Vilipender: you throw mud on someone’s name until it sticks."],"s":["belittle","berate","besmirch","castigate","censure","decry","defame","denigrate","denounce","deprecate","disparage","excoriate","malign","slander","stigmatize","vituperate"]}]},{"name":"Common Words IV","slug":"common-words-iv","series":"Common Words","words":[{"w":"aberrant","p":"adj.","m":"Departing from what is normal or accepted.","e":"Latin <i>aberrantem</i>, from <i>aberrare</i>: <i>ab-</i> (away) + <i>errare</i> (to wander).","f":"aberrant","t":"Same root as aberration: wandering (errer) off the path. Identical to « aberrant ».","h":["Ab + errare: off the path. An aberrant result sticks out of the graph.","Aberrant behaviour: the polite cashier suddenly screaming. Abnormal."],"s":["anomalous"]},{"w":"abstruse","p":"adj.","m":"Difficult to understand; obscure.","e":"Latin <i>abstrusus</i> (hidden), from <i>abstrudere</i>: <i>abs-</i> (away) + <i>trudere</i> (to push). Pushed away out of sight.","f":"abstrus, abscons","t":"Same as « abstrus »: an idea pushed so far away you can’t reach it.","h":["Abs + trudere (push): pushed so far away it’s hard to reach. Abstruse legal jargon.","Abstruse = “abstract and obtuse”: a physics paper no one can follow."],"s":["arcane","cryptic","esoteric","obscure","profound","recondite"]},{"w":"acerbic","p":"adj.","m":"Sharp and forthright, especially in criticism.","e":"Latin <i>acerbus</i> (harsh, bitter, sour), related to <i>acer</i> (sharp).","f":"acerbe, caustique","t":"« Un ton acerbe ». Same acer as aigre and vinaigre.","h":["Acer = sharp. Acerbic humour: lemon juice in a joke.","Un ton acerbe: a critic whose tongue cuts like vinegar."],"s":["astringent","caustic","incisive","keen","mordant","penetrating","scathing","trenchant","virulent","vitriolic"]},{"w":"adamant","p":"adj.","m":"Refusing to change one’s mind; unshakable.","e":"Greek <i>adamas</i>, “unconquerable”: <i>a-</i> (not) + <i>daman</i> (to tame). A legendary unbreakable stone, later diamond.","f":"inflexible, intransigent","t":"Adamas = the unbreakable stone that gave « diamant ». An adamant person is diamond-hard.","h":["Adamas: diamond, unbreakable. Adamant = hard as a diamond; she won’t change her mind.","Adam + ant: Adam in the garden won’t eat the apple. Firmly refuses."],"s":["dogged","headstrong","intransigent","obdurate","obstinate","resolute","staunch","steadfast","uncompromising"]},{"w":"admonitory","p":"adj.","m":"Giving or conveying a warning or reprimand.","e":"Latin <i>admonere</i>, “to remind, warn”: <i>ad-</i> + <i>monere</i> (to warn), as in monitor.","f":"d’avertissement, réprobateur","t":"Ad + monere: a monitor warning you. Une admonestation = a reprimand.","h":["Admonish: a warning from a monitor. An admonitory finger wag.","Admonitory glance: your teacher’s look before the exam. A warning."],"s":[]},{"w":"apocryphal","p":"adj.","m":"Of doubtful authenticity, though widely repeated.","e":"Greek <i>apokryphos</i> (hidden): <i>apo</i> + <i>kryptein</i> (to hide). The Apocrypha were biblical books excluded as of uncertain origin.","f":"apocryphe","t":"Same as « apocryphe ». Like the famous quote nobody actually said.","h":["Apo + kryptein (hidden): originally hidden books. Doubtful authorship. The “Let them eat cake” line.","An apocryphal story: everyone repeats it, nobody can source it."],"s":["dubious","spurious"]},{"w":"blatant","p":"adj.","m":"Done openly and unashamedly; very obvious.","e":"Coined by Edmund Spenser in <i>The Faerie Queene</i> (1596) for the “Blatant Beast”, a noisy monster of slander; perhaps from Latin <i>blatire</i> (to babble).","f":"flagrant, criant","t":"Spenser’s loud Blatant Beast: blatant things shout at you. « Un mensonge flagrant ».","h":["Loud and obvious: a blatant lie, a neon sign.","Blatant = bleating: a sheep making noise. Impossible to miss."],"s":["brazen","conspicuous","egregious","flagrant","patent"]},{"w":"bumbling","p":"adj.","m":"Acting in a confused or clumsy way.","e":"From <i>bumble</i>, an imitative English word (like the buzz of a bumblebee), meaning to blunder or ramble.","f":"maladroit, empoté","t":"A bumblebee bumping into windows. Inspector Clouseau is a bumbling detective.","h":["Bumble + bee: knocks into everything. Mr. Bean, a bumbling fool.","Bumbling = fumbling and stumbling in a muddle."],"s":["gauche","inept","maladroit"]},{"w":"burgeon","p":"v.","m":"To grow or increase rapidly; flourish.","e":"Old French <i>borjoner</i> (to bud), from <i>borjon</i> (bud), modern <i>bourgeon</i>.","f":"bourgeonner, croître rapidement","t":"Burgeon = « bourgeonner »: buds bursting out in spring. A burgeoning start-up scene.","h":["Bourgeon = bud. In spring, buds burgeon, so too a booming business.","Burgeon: a rapid sprouting, like a field after rain."],"s":["proliferate"]},{"w":"confound","p":"v.","m":"To confuse; or to prove wrong.","e":"Old French <i>confondre</i>, from Latin <i>confundere</i>, “to pour together”: <i>com-</i> + <i>fundere</i> (to pour).","f":"confondre, déconcerter","t":"Same as « confondre »: everything poured together. Results that confound the experts prove them wrong.","h":["Con + fundere (pour together): everything mixed up. The results confounded the researchers.","“Confound it!”: old-fashioned curse for bewilderment. To confuse and to contradict."],"s":["discomfit","flummox","nonplussed"]},{"w":"construe","p":"v.","m":"To interpret a meaning.","e":"Latin <i>construere</i>, “to pile together, build”: <i>com-</i> + <i>struere</i> (to build). In grammar, to build up a sentence’s meaning.","f":"interpréter","t":"You construct a meaning. Misconstrue = to build the wrong one.","h":["Con + struere: build a meaning. You construe a text.","Misconstrue: you built the wrong meaning from his words."],"s":["decipher","unravel"]},{"w":"contingent","p":"adj. / n.","m":"Dependent on something uncertain. (n.: a group within a larger one.)","e":"Latin <i>contingentem</i>, from <i>contingere</i>, “to touch, befall”: <i>com-</i> + <i>tangere</i> (to touch).","f":"subordonné à, éventuel; contingent","t":"The offer is contingent on due diligence: it touches on it and depends on it. « Les contingences ».","h":["Con + tangere (touch): depends on touch with another. A contingent offer: only if the buyer gets a loan.","Contingent upon rain: the picnic depends on the weather."],"s":["provisional"]},{"w":"copious","p":"adj.","m":"Abundant, plentiful.","e":"Latin <i>copiosus</i>, from <i>copia</i> (abundance), as in cornucopia.","f":"copieux, abondant","t":"« Un repas copieux ». Copia = abundance.","h":["Copia = abundance (cornucopia). Copious notes fill pages.","Un repas copieux: more than enough. Copious food."],"s":["lavish","profuse"]},{"w":"decorum","p":"n.","m":"Behaviour in keeping with good taste and propriety.","e":"Latin <i>decorum</i> (that which is proper), from <i>decere</i> (to be fitting).","f":"décorum, bienséance","t":"Identical to « le décorum ». Same family as decorous.","h":["Décorum: the formal rules. At a funeral you maintain decorum.","Decorum = dress code of behaviour."],"s":["propriety"]},{"w":"denigrate","p":"v.","m":"To criticise unfairly; belittle.","e":"Latin <i>denigrare</i>, “to blacken”: <i>de-</i> + <i>nigrare</i>, from <i>niger</i> (black).","f":"dénigrer","t":"Same as « dénigrer »: blackening someone’s name.","h":["De + niger (black): blacken someone’s reputation.","Denigrate sounds like “de-nig-rate”: rate someone down, unfairly. Dénigrer."],"s":["belittle","besmirch","castigate","censure","decry","defame","demean","denounce","deprecate","disparage","excoriate","malign","slander","vilify","vituperate"]},{"w":"discrete","p":"adj.","m":"Separate and distinct.","e":"Latin <i>discretus</i> (separated), from <i>discernere</i>: <i>dis-</i> (apart) + <i>cernere</i> (to sift). Same origin as discreet, split in spelling later.","f":"distinct, séparé; discret (maths)","t":"Discrete = distinct units, like discrete maths. Discreet (ee) = « discret », tactful.","h":["Discrete = separate pieces, like beads on a string. Not continuous.","Discrete data vs continuous data: whole numbers only. Distinct and separate."],"s":[]},{"w":"eradicate","p":"v.","m":"To destroy completely; wipe out.","e":"Latin <i>eradicare</i>, “to pull up by the roots”: <i>e-</i> (out) + <i>radix</i> (root).","f":"éradiquer","t":"Radix = racine: pulling the weed out by its root. Same as « éradiquer ».","h":["E + radix (root): pull out by the root. Eradicate smallpox.","Eradicate: dig the weed out so it never returns."],"s":["expunge"]},{"w":"espouse","p":"v.","m":"To adopt or support a cause or belief.","e":"Old French <i>espouser</i> (to marry), from Latin <i>sponsare</i>, from <i>spondere</i> (to promise).","f":"épouser (une cause), embrasser","t":"Exactly « épouser une cause »: you marry the idea.","h":["Épouser: marry. You espouse a cause like a partner.","Espouse your ideas: you embrace them and take them home."],"s":["advocate","champion"]},{"w":"exacting","p":"adj.","m":"Making great demands; strict.","e":"From <i>exact</i> (to demand), Latin <i>exigere</i>, “to drive out, demand”: <i>ex-</i> + <i>agere</i>.","f":"exigeant","t":"Exacting = « exigeant », from the same exigere. An exacting partner.","h":["Exiger: demands accuracy. An exacting teacher marks every error.","Exacting = “exact-ing”: demanding exactness."],"s":["exigent","fastidious","imperative","meticulous","onerous","punctilious","scrupulous","stringent"]},{"w":"exalt","p":"v.","m":"To praise highly; raise in rank.","e":"Latin <i>exaltare</i>: <i>ex-</i> + <i>altus</i> (high).","f":"exalter, glorifier","t":"Ex + altus = lift up high. « Exalter ».","h":["Ex + altus (high): lift up. Exalt a hero on a pedestal.","Exalted rank: a high position."],"s":["acclaim","deify","extol","hail","laud","lionize","venerate"]},{"w":"exonerate","p":"v.","m":"To clear from blame.","e":"Latin <i>exonerare</i>, “to unload”: <i>ex-</i> + <i>onus, oneris</i> (burden).","f":"disculper, exonérer","t":"Onus = burden: lifting the burden of guilt off someone. « Exonérer » in French is mostly about taxes, but same image.","h":["Ex + onus (burden): lift the burden of blame. DNA evidence exonerated the prisoner.","Exonerate: the judge says “free to go”. No longer guilty."],"s":["exculpate","vindicate"]},{"w":"expound","p":"v.","m":"To explain in detail.","e":"Old French <i>espondre</i>, from Latin <i>exponere</i>, “to put forth”: <i>ex-</i> + <i>ponere</i> (to place).","f":"exposer, expliquer en détail","t":"Expound = « exposer » (same exponere). Expounding a theory at length.","h":["Ex + ponere (put out): lay out in detail. A professor expounds a theory for an hour.","Expound = déployer an idea, spread it out on the table."],"s":["elaborate","elucidate","embellish","expatiate","pontificate"]},{"w":"forthcoming","p":"adj.","m":"Willing to share information; also about to happen.","e":"English <i>forth</i> (forward) + <i>coming</i>. Germanic.","f":"ouvert, communicatif; à venir","t":"Coming forth with information. An unforthcoming witness says nothing.","h":["Comes forth: information freely given. A forthcoming witness answers fully.","Forthcoming also means upcoming: “the forthcoming album”."],"s":["candid","demonstrative","effusive","expansive","imminent","impending"]},{"w":"hackneyed","p":"adj.","m":"Overused, unoriginal; trite.","e":"From <i>hackney</i>, a horse for hire (perhaps from Hackney, the London village). A horse used by everyone became anything worn out.","f":"rebattu, éculé, banal","t":"Picture a tired hired horse ridden by everyone. A hackneyed phrase has been ridden to death.","h":["Hackney horses were hired out for everyone: worn out. A hackneyed plot has been ridden too often.","Hackneyed: the cliché you’ve heard a thousand times."],"s":["banal","hoary","trite"]},{"w":"iconoclastic","p":"adj.","m":"Attacking cherished beliefs or institutions.","e":"Greek <i>eikōn</i> (image) + <i>klastēs</i> (breaker). From the Byzantine image-smashers.","f":"iconoclaste","t":"The adjective of iconoclast: smashing sacred images, or sacred ideas.","h":["Adjective of iconoclast: smashing icons. An iconoclastic novel mocks every tradition.","Iconoclastic art: a painting that attacks the sacred cow."],"s":["subversive"]},{"w":"idiosyncrasy","p":"n.","m":"A peculiar habit or way of behaving.","e":"Greek <i>idiosynkrasia</i>: <i>idios</i> (one’s own) + <i>synkrasis</i> (mixture of temperaments).","f":"particularité, manie, idiosyncrasie","t":"Idios = one’s own (as in idiom): your own personal mix of quirks.","h":["Idios = own: your own personal quirk. Eating pizza with a fork and knife.","Idio-syn-crasy: a mix of your own. Peculiarities."],"s":["foible","frailty","peccadillo"]},{"w":"ignoble","p":"adj.","m":"Dishonourable; base.","e":"Latin <i>ignobilis</i>: <i>in-</i> (not) + <i>nobilis</i> (noble, well known).","f":"ignoble, vil","t":"Not noble. Same as « ignoble ».","h":["In + nobilis: not noble. An ignoble act of cowardice.","Ignoble = base, shameful, beneath someone of rank."],"s":["base","sordid"]},{"w":"implacable","p":"adj.","m":"Unable to be appeased; relentless.","e":"Latin <i>implacabilis</i>: <i>in-</i> (not) + <i>placare</i> (to calm, appease).","f":"implacable","t":"Same as « implacable »: impossible to placate.","h":["In + placare (to please): can’t be pleased or calmed. An implacable enemy.","Implacable: a storm that won’t be placated. Relentless."],"s":["inexorable"]},{"w":"implausible","p":"adj.","m":"Not seeming reasonable or likely.","e":"<i>in-</i> + Latin <i>plausibilis</i> (deserving applause), from <i>plaudere</i> (to clap).","f":"invraisemblable, peu plausible","t":"An excuse nobody would applaud. « Pas plausible ».","h":["Not worthy of applause (plaudere): an implausible alibi.","Implausible: a story that doesn’t pass the sniff test."],"s":["dubious"]},{"w":"incorrigible","p":"adj.","m":"Not able to be corrected or reformed.","e":"Latin <i>incorrigibilis</i>: <i>in-</i> + <i>corrigere</i> (to correct).","f":"incorrigible","t":"Identical to « incorrigible »: beyond correction.","h":["In + corriger: can’t be corrected. An incorrigible flirt.","Incorrigible: the kid who gets detention every week and keeps doing it."],"s":["intractable","inveterate"]},{"w":"indifference","p":"n.","m":"Lack of interest or concern. (Also mediocrity.)","e":"Latin <i>indifferentia</i>: <i>in-</i> + <i>differre</i> (to differ). It makes no difference to you.","f":"indifférence","t":"Same as « indifférence ». Careful: indifferent can also mean mediocre on the GRE.","h":["In + differ: no difference matters. I don’t care which one.","Indifferent can also mean “mediocre”: indifferent cooking is just OK."],"s":["apathy","insouciance","torpor"]},{"w":"ingratiate","p":"v.","m":"To bring oneself into favour, often by flattery.","e":"Italian <i>ingratiare</i>, from Latin <i>in gratiam</i> (into favour), <i>gratia</i> (grace).","f":"s’attirer les bonnes grâces de, s’insinuer","t":"Getting into someone’s good graces (gratia). « S’attirer les bonnes grâces ».","h":["In + gratia: get into someone’s good graces. The intern ingratiates himself with the boss.","Ingratiate: flattering to win favour. S’attirer les bonnes grâces."],"s":[]},{"w":"intransigent","p":"adj.","m":"Unwilling to compromise.","e":"Spanish <i>intransigente</i>, from Latin <i>in-</i> + <i>transigere</i> (to come to an agreement).","f":"intransigeant","t":"Same as « intransigeant »: no transaction possible.","h":["In + transigere (to settle): won’t make a deal. An intransigent negotiator.","Intransigent: no transaction possible; the other side won’t move an inch."],"s":["adamant","headstrong","obdurate","obstinate","uncompromising"]},{"w":"largess","p":"n.","m":"Generosity in giving gifts or money.","e":"Old French <i>largesse</i>, from <i>large</i> (generous), Latin <i>largus</i> (abundant).","f":"largesse, générosité","t":"Identical to « largesse ». A lord throwing coins from his carriage.","h":["Large = generous: large-hearted gift-giving. A rich patron’s largess.","Largesse: the lord throwing coins to the crowd."],"s":["largesse"]},{"w":"laudable","p":"adj.","m":"Deserving praise.","e":"Latin <i>laudabilis</i>, from <i>laudare</i> (to praise), <i>laus</i> (praise).","f":"louable","t":"Laud = louer (to praise). Laudable = louable.","h":["Laus = praise (applaud). A laudable effort deserves a laud.","Laudable ≈ louable: worth praising."],"s":["commendable","creditable","estimable","meritorious"]},{"w":"myopic","p":"adj.","m":"Short-sighted; lacking foresight.","e":"Greek <i>myōps</i>, “short-sighted”: <i>myein</i> (to shut) + <i>ōps</i> (eye). Squinting with half-closed eyes.","f":"myope; à courte vue","t":"Same as « myope ». A myopic strategy only sees this quarter.","h":["Myopia: short-sighted. A myopic CEO only sees next quarter.","Myopic = squinting at what’s right in front and missing the horizon."],"s":["improvident"]},{"w":"opaque","p":"adj.","m":"Not transparent; hard to understand.","e":"Latin <i>opacus</i> (shaded, dark).","f":"opaque, obscur","t":"Same as « opaque »: light can’t get through, and neither can meaning.","h":["Opaque: you can’t see through it. An opaque curtain; an opaque contract.","Opaque explanations leave you in the dark."],"s":["impenetrable","impervious","inscrutable","obscure","turbid"]},{"w":"ostentatious","p":"adj.","m":"Designed to impress; showy.","e":"Latin <i>ostentatio</i> (display), from <i>ostendere</i> (to show): <i>ob-</i> + <i>tendere</i> (to stretch).","f":"ostentatoire, tape-à-l’œil","t":"« Ostentatoire »: stretching it out for everyone to see.","h":["Ostendere: to show off. A gold watch flashed at dinner.","Ostentatious: peacock feathers in a pastel office. Flashy."],"s":["exorbitant","extravagant","flamboyant","florid","ornate","outlandish","pretentious"]},{"w":"pedantic","p":"adj.","m":"Overly concerned with minor details and rules.","e":"Italian <i>pedante</i> (schoolmaster), probably related to Greek <i>paideuein</i> (to teach).","f":"pédant, pointilleux","t":"Same as « pédant »: the schoolmaster correcting your commas.","h":["Pedagogue: the one who corrects every comma. A pedantic copy-editor.","Pedant: obsessed with the rules and minor details. A know-it-all."],"s":["captious","didactic","fastidious","finicky","meticulous","punctilious","sanctimonious","sententious"]},{"w":"petulant","p":"adj.","m":"Childishly sulky or bad-tempered.","e":"Latin <i>petulantem</i> (forward, insolent), from <i>petere</i> (to attack, seek).","f":"irritable, boudeur (≠ pétulant)","x":"Faux ami","t":"Careful: French « pétulant » means lively. English petulant = a sulking toddler.","h":["Petulant = sulky: the toddler who throws his toy. Not « pétulant » (lively).","A petulant pout when told no. Childish bad temper."],"s":["bilious","carping","choleric","fractious","irascible","peevish","plaintive","querulous","refractory","restive","splenetic","unruly"]},{"w":"pragmatic","p":"adj.","m":"Dealing with things practically, not theoretically.","e":"Greek <i>pragmatikos</i> (businesslike), from <i>pragma</i> (deed, affair), from <i>prassein</i> (to do).","f":"pragmatique","t":"Pragma = action. Same as « pragmatique ».","h":["Pragma = deed. A pragmatic solution works in the real world, not in theory.","Pragmatic: the engineer says “It works, ship it.”"],"s":["expedient","opportunistic","politic","utilitarian"]},{"w":"provincial","p":"adj.","m":"Unsophisticated, narrow-minded.","e":"Latin <i>provincialis</i>, from <i>provincia</i> (a territory outside Rome).","f":"provincial, borné","t":"Like parochial: thinking from far away from the capital. « Un esprit provincial ».","h":["Provincial: from the province, away from the capital. Narrow, unsophisticated views.","A provincial outlook: thinks the village is the world."],"s":["blinkered","bucolic","insular","parochial","pastoral","rustic"]},{"w":"pundit","p":"n.","m":"An expert who gives opinions publicly.","e":"Hindi <i>paṇḍit</i>, from Sanskrit <i>paṇḍita</i> (learned man).","f":"expert, commentateur","t":"A pandit was a learned Hindu scholar. Today’s pundits are TV experts.","h":["Pandit: learned scholar, now a TV expert. A political pundit has an opinion on everything.","Pundit: the “expert” paid to comment on the news."],"s":[]},{"w":"reconcile","p":"v.","m":"To restore friendly relations; make compatible.","e":"Latin <i>reconciliare</i>: <i>re-</i> + <i>conciliare</i> (to bring together).","f":"réconcilier, concilier","t":"Same as « réconcilier ». You also reconcile two sets of numbers in a model.","h":["Re + conciliare: bring together again. The two sisters reconcile.","Reconcile accounts: both ledgers must match."],"s":["appease","assuage","conciliate","mollify","pacify","placate","propitiate"]},{"w":"refute","p":"v.","m":"To prove wrong.","e":"Latin <i>refutare</i> (to drive back, disprove).","f":"réfuter","t":"Same as « réfuter ». Not just deny: prove false.","h":["Re + futare (beat back): prove wrong with evidence. Refute the accusation.","Refute: not just say “no”; show a proof that it’s false."],"s":["belie","debunk","discredit","gainsay","negate"]},{"w":"soporific","p":"adj.","m":"Causing sleep; very boring.","e":"Latin <i>sopor</i> (deep sleep) + <i>-ficus</i> (making).","f":"soporifique","t":"Identical to « soporifique ». A soporific lecture.","h":["Sopor = deep sleep. A soporific lecture is a sleeping pill.","Soporific = sleep-making: warm room, slow voice, closed eyes."],"s":["somnolent"]},{"w":"temperance","p":"n.","m":"Moderation, self-restraint (especially with alcohol).","e":"Latin <i>temperantia</i> (moderation), from <i>temperare</i> (to mix in due proportion).","f":"tempérance, modération","t":"One of the four cardinal virtues: « la tempérance ». Tempered = mixed in the right dose.","h":["Moderation, a cardinal virtue. Temperance movement: against alcohol.","Temper (mix) in measure: one glass, not the whole bottle."],"s":[]},{"w":"tortuous","p":"adj.","m":"Full of twists and turns; overly complex.","e":"Latin <i>tortuosus</i>, from <i>tortus</i> (twisted), from <i>torquere</i> (to twist).","f":"tortueux","t":"Same as « tortueux ». Not torturous (painful) — tortuous twists.","h":["Torquere: twisted road. Tortuous mountain road; a tortuous explanation.","Tortuous ≠ torturous (painful): this one winds like a serpent."],"s":["byzantine","convoluted","devious","involved","oblique","sinuous"]},{"w":"underscore","p":"v.","m":"To emphasise.","e":"English <i>under</i> + <i>score</i> (a line, from Old Norse <i>skor</i>, notch). Literally to underline.","f":"souligner","t":"Underline = « souligner ». The data underscores the risk.","h":["Underline a word: emphasise it. The report underscores the danger.","Underscore = highlight the key point."],"s":["accentuate"]},{"w":"unscrupulous","p":"adj.","m":"Having no moral principles; not honest.","e":"<i>un-</i> + scrupulous, from Latin <i>scrupulus</i> (a small sharp stone): the pebble in your sandal that bothers your conscience.","f":"sans scrupules","t":"Scrupulus = a little stone in your shoe. The unscrupulous feel no pebble at all. « Sans scrupules ».","h":["Scrupulus: a small sharp stone. The unscrupulous don’t feel the stone: no conscience.","Unscrupulous: a dealer who sells fake watches without any guilt."],"s":["exorbitant","expedient","exploitative","mercenary","opportunistic","unconscionable","venal"]}]},{"name":"Common Words V","slug":"common-words-v","series":"Common Words","words":[{"w":"accolade","p":"n.","m":"An award or expression of praise.","e":"French <i>accolade</i>, an embrace, from Latin <i>ad</i> + <i>collum</i> (neck). The knight’s ceremony included an embrace or a tap on the neck with the sword.","f":"distinction, éloge (accolade = hug)","t":"The king dubbing a knight with an embrace around the neck (collum). Today: an honour, a prize.","h":["Colle = neck: a hug or a tap on the shoulder from the king. Now: a prize, high praise.","Accolade: the award speech where the whole room applauds you."],"s":["approbation","encomium","eulogy","panegyric"]},{"w":"admonish","p":"v.","m":"To warn or reprimand firmly.","e":"Old French <i>amonester</i>, from Latin <i>admonere</i>: <i>ad-</i> + <i>monere</i> (to warn).","f":"admonester, réprimander","t":"Same as « admonester ». Monere = warn, like a monitor.","h":["Ad + monere: like a hall monitor who warns you. “Don’t run!”","Admonish gently: a firm but friendly reprimand."],"s":["berate","castigate","censure","chastise","enjoin","lambaste","objurgate","rebuke","reproach","upbraid"]},{"w":"antithetical","p":"adj.","m":"Directly opposed.","e":"Greek <i>antithesis</i>: <i>anti</i> (against) + <i>tithenai</i> (to place). Placed against.","f":"antithétique, opposé","t":"Thesis vs antithesis: placed against each other. « Aux antipodes ».","h":["Anti + thesis: the exact opposite of what you said. Fire is antithetical to ice.","Antithetical views: two debaters on opposite sides of the stage."],"s":[]},{"w":"arbitrary","p":"adj.","m":"Based on random choice or personal whim, not reason.","e":"Latin <i>arbitrarius</i>, from <i>arbiter</i> (judge). Left to the judge’s discretion.","f":"arbitraire","t":"Same as « arbitraire »: whatever the arbitre decides on a whim.","h":["Arbiter: a judge who picks on a whim. An arbitrary rule has no logic.","Arbitrary = picked by dice. “Why 3 pm? No reason.”"],"s":["capricious","erratic","fickle","mercurial","volatile","whimsical"]},{"w":"arcane","p":"adj.","m":"Understood by few; mysterious.","e":"Latin <i>arcanus</i> (secret), from <i>arca</i> (chest, box). Locked in a box.","f":"obscur, ésotérique; les arcanes","t":"« Les arcanes du pouvoir »: secrets locked in a chest (arca).","h":["Arca = chest: the secrets locked away. Arcane rituals only the initiated know.","Arcane knowledge: dusty manuscripts and spells."],"s":["abstruse","cryptic","enigmatic","esoteric","inscrutable","obscure","recondite"]},{"w":"audacity","p":"n.","m":"Willingness to take bold risks; rude boldness.","e":"Latin <i>audacia</i>, from <i>audax</i> (bold), <i>audere</i> (to dare).","f":"audace; culot","t":"« L’audace ». Can be praise (bold) or blame (the audacity to ask!).","h":["Audere: dare. Audacity can be brave or cheeky: “the audacity!”","Audacity: asking the CEO for a pay rise on day one."],"s":["effrontery","gall","presumption","temerity"]},{"w":"austere","p":"adj.","m":"Severe or strict; plain, without comfort.","e":"Greek <i>austēros</i> (harsh, bitter, making the tongue dry), via Latin <i>austerus</i>.","f":"austère","t":"Same as « austère ». A monk’s cell: bare walls, no comfort.","h":["Austère: bare walls, no decoration. An austere monk’s cell.","Austere = strict and plain: a Calvinist church."],"s":["abstemious","ascetic","dour","frugal","spartan","stern","unadorned"]},{"w":"brazen","p":"adj.","m":"Bold and shameless.","e":"Old English <i>bræsen</i> (made of brass). Brass = hard and loud, hence shameless.","f":"effronté, éhonté","t":"A face made of brass: no blush possible. A brazen lie.","h":["Brass face: you can’t blush through it. A brazen thief who steals in daylight.","Brazen = shameless: lying right to your face."],"s":["audacious","blatant","egregious","flagrant","impertinent","impudent","insolent","overweening","presumptuous"]},{"w":"circumscribe","p":"v.","m":"To restrict within limits.","e":"Latin <i>circumscribere</i>: <i>circum</i> (around) + <i>scribere</i> (to write, draw). Drawing a line around.","f":"circonscrire, limiter","t":"Same as « circonscrire »: drawing a circle around something (une circonscription).","h":["Circum + scribere: draw a circle around. The law circumscribes your powers.","Circumscribe: set limits, like a chalk circle around a child."],"s":[]},{"w":"constituent","p":"n. / adj.","m":"A component part; a voter in a district.","e":"Latin <i>constituentem</i>, from <i>constituere</i> (to set up): <i>com-</i> + <i>statuere</i> (to set).","f":"composant, constituant; électeur","t":"The parts that constitute something, or the voters who constitute a constituency.","h":["Constitute: a part that makes up the whole. An ingredient; a voter in your district.","Constituent = the person who constitutes your electorate."],"s":[]},{"w":"dilettante","p":"n.","m":"A person with superficial interest in an art or subject.","e":"Italian <i>dilettante</i> (lover of the arts), from <i>dilettare</i> (to delight), Latin <i>delectare</i>.","f":"dilettante, amateur","t":"Same as « dilettante »: dabbling for delight, never mastering.","h":["Diletto (Italian): delight. A dabbler who dips into painting, then pottery.","Dilettante: has fifteen hobbies and mastered none."],"s":["tyro"]},{"w":"foment","p":"v.","m":"To stir up trouble or rebellion.","e":"Latin <i>fomentare</i>, from <i>fomentum</i> (a warm poultice), from <i>fovere</i> (to warm).","f":"fomenter","t":"Same as « fomenter un complot »: keeping a revolt warm until it hatches.","h":["Fomentare (to warm): keep a rebellion warm until it hatches. Foment unrest.","A hot-water compress: foment = apply heat; now to stir up trouble."],"s":["agitate","goad","incite"]},{"w":"garrulous","p":"adj.","m":"Excessively talkative about trivial things.","e":"Latin <i>garrulus</i> (chattering), from <i>garrire</i> (to chatter).","f":"bavard, loquace","t":"Garrire = to chatter like a bird. A garrulous seatmate on a long flight.","h":["Garrulus: a chattering jay. A garrulous neighbour at the bus stop.","Garrulous = gargling words: talking too much about nothing."],"s":["effusive","glib","loquacious","prolix","tedious","verbose","voluble"]},{"w":"gauche","p":"adj.","m":"Socially awkward; tactless.","e":"French <i>gauche</i> (left; clumsy), probably from Frankish <i>welkan</i> (to wilt).","f":"gauche, maladroit","t":"Exactly French « gauche »: clumsy, like doing everything with the left hand.","h":["Gauche: left-handed, so clumsy. A gauche remark at dinner.","Gauche = awkward in company: you step on the host’s toes."],"s":["bumbling","gawky","indecorous","inept","maladroit","unseemly"]},{"w":"haphazard","p":"adj.","m":"Lacking order or plan; random.","e":"English <i>hap</i> (luck, from Old Norse <i>happ</i>) + <i>hazard</i> (chance, via French <i>hasard</i> from Arabic <i>az-zahr</i>, the die).","f":"au hasard, désordonné","t":"Hap + hasard = luck + luck. Nothing planned.","h":["Hap = chance, hazard: whatever happens. A haphazard pile of papers.","Haphazard: no plan, tossed anywhere."],"s":["desultory","discursive","fitful","indiscriminate","slapdash","sporadic"]},{"w":"hegemony","p":"n.","m":"Dominance of one group or state over others.","e":"Greek <i>hēgemonia</i> (leadership), from <i>hēgemōn</i> (leader), <i>hēgeisthai</i> (to lead).","f":"hégémonie","t":"Same as « hégémonie »: Athens leading the other Greek cities.","h":["Hegemon: leader. The hegemony of Rome over the Mediterranean.","Hegemony: one big power dominating the rest, like a school’s top clique."],"s":["ascendancy","primacy"]},{"w":"inimical","p":"adj.","m":"Hostile; harmful.","e":"Late Latin <i>inimicalis</i>, from <i>inimicus</i> (enemy): <i>in-</i> + <i>amicus</i> (friend).","f":"hostile, nuisible","t":"In-amicus = not a friend → « ennemi ». Conditions inimical to growth.","h":["In-amicus: not a friend. Inimical to peace: acts as its enemy.","Inimical = enemy-like: a climate inimical to crops."],"s":["adverse","deleterious","detrimental","noxious","pernicious","unpropitious","untoward"]},{"w":"inscrutable","p":"adj.","m":"Impossible to understand or interpret.","e":"Late Latin <i>inscrutabilis</i>: <i>in-</i> + <i>scrutari</i> (to search, examine).","f":"impénétrable, insondable","t":"Can’t be scrutinised. An inscrutable poker face.","h":["In + scrutari (search): can’t be searched out. The Sphinx’s face.","An inscrutable smile: you stare and learn nothing."],"s":["arcane","cryptic","enigmatic","impenetrable","impervious","obscure","opaque"]},{"w":"insolent","p":"adj.","m":"Rude and disrespectful.","e":"Latin <i>insolentem</i> (unusual, arrogant): <i>in-</i> + <i>solere</i> (to be accustomed).","f":"insolent","t":"Same as « insolent ».","h":["In + solere (be accustomed): not behaving as is customary. A cheeky pupil.","Insolent: talks back to the teacher."],"s":["audacious","brazen","impertinent","impudent","presumptuous"]},{"w":"intrepid","p":"adj.","m":"Fearless; adventurous.","e":"Latin <i>intrepidus</i>: <i>in-</i> (not) + <i>trepidus</i> (alarmed).","f":"intrépide","t":"Same as « intrépide »: no trépidation.","h":["In + trepidus (alarmed): no fear. An intrepid explorer.","Intrepid: wades into the jungle without a tremble."],"s":["audacious","doughty","plucky"]},{"w":"inveterate","p":"adj.","m":"Having a long-established habit unlikely to change.","e":"Latin <i>inveteratus</i> (grown old), from <i>vetus</i> (old), as in veteran.","f":"invétéré","t":"Same as « un fumeur invétéré ». A veteran habit.","h":["Vetus = old: old habit. An inveterate liar has lied for years.","Inveterate = a veteran of the habit: the chain smoker since age 14."],"s":["entrenched","incorrigible","ingrained","intractable"]},{"w":"irrevocable","p":"adj.","m":"Not able to be changed or reversed.","e":"Latin <i>irrevocabilis</i>: <i>in-</i> + <i>revocare</i> (to call back).","f":"irrévocable","t":"Same as « irrévocable »: can’t be called back.","h":["Ir + revocare: can’t call back. An irrevocable decision, no return.","Irrevocable: the arrow has left the bow."],"s":["immutable"]},{"w":"lionize","p":"v.","m":"To treat someone as a celebrity.","e":"From lion, in the 18th-century sense “a celebrity”: from the custom of taking visitors to see the lions at the Tower of London.","f":"porter aux nues, aduler","t":"Treat someone like the star attraction: the lion everyone queues to see.","h":["Treat someone like a lion: make a celebrity. The town lionized the hero.","Lionize: crowds mobbing the author at a book signing."],"s":["acclaim","exalt","extol","fete","hail","laud"]},{"w":"munificent","p":"adj.","m":"Very generous.","e":"Latin <i>munificus</i>: <i>munus</i> (gift, duty) + <i>facere</i> (to make).","f":"munificent, généreux","t":"A maker of gifts. Same as « munificent » (rare in French).","h":["Munus = gift: a munificent donor gives lavishly.","Munificent: opens his wallet like a fountain."],"s":["beneficent","extravagant","lavish","magnanimous","profuse","unstinting"]},{"w":"myriad","p":"n. / adj.","m":"Countless; a great number.","e":"Greek <i>myrias</i> (ten thousand), from <i>myrioi</i> (countless).","f":"myriade","t":"« Une myriade d’étoiles ». Literally 10,000.","h":["Myrias: 10,000. A myriad stars in the desert sky.","Myriad = countless: “myriad ways to fail”."],"s":["raft"]},{"w":"obsequious","p":"adj.","m":"Excessively eager to please or obey.","e":"Latin <i>obsequiosus</i>, from <i>obsequi</i> (to comply): <i>ob-</i> + <i>sequi</i> (to follow).","f":"obséquieux","t":"Same as « obséquieux »: following someone everywhere to please them.","h":["Ob + sequi (follow): follows you around nodding. An obsequious waiter bowing repeatedly.","Obsequious: sucking up. The intern laughing at all the boss’s jokes."],"s":["deferential","dutiful","reverent","subservient"]},{"w":"ostracize","p":"v.","m":"To exclude from a group.","e":"Greek <i>ostrakizein</i>, from <i>ostrakon</i> (pottery shard). Athenians voted to exile someone by writing his name on shards.","f":"ostraciser, exclure","t":"Picture Athenians scratching a name on a broken pot to banish him.","h":["Ostrakon: a pot-shard used to vote someone out of Athens. To shun.","Ostracize = send to Coventry: nobody talks to the outcast."],"s":["banish","disenfranchise","marginalize","oust","relegate","snub"]},{"w":"pedestrian","p":"adj.","m":"Dull, unimaginative.","e":"Latin <i>pedester</i> (on foot; prosaic), from <i>pes, pedis</i> (foot). Prose was “on foot”, poetry had wings.","f":"terne, prosaïque, banal","x":"2nd meaning","t":"Not the person crossing the road: a style that plods on foot instead of flying.","h":["Pedes = foot: walks instead of flies. A pedestrian speech: plodding, dull.","Pedestrian prose: a flat road with no view."],"s":["banal","humdrum","mundane","prosaic","quotidian","tedious"]},{"w":"pernicious","p":"adj.","m":"Having a harmful effect, especially gradually.","e":"Latin <i>perniciosus</i>, from <i>pernicies</i> (destruction): <i>per-</i> + <i>nex, necis</i> (death).","f":"pernicieux","t":"Same as « pernicieux ». Nex = death, slowly.","h":["Per + nex (death): deadly in the long run. A pernicious lie spreading in a community.","Pernicious: poison dripped slowly."],"s":["deleterious","detrimental","inimical","insidious","noxious","subtle","treacherous"]},{"w":"poignant","p":"adj.","m":"Evoking a keen sense of sadness.","e":"Old French <i>poignant</i> (pricking), from <i>poindre</i>, Latin <i>pungere</i> (to prick).","f":"poignant, émouvant","t":"Same as « poignant »: it pricks your heart (pungere, as in punctuation).","h":["Pungere (prick): a pang in the heart. A poignant farewell.","Poignant: an old couple holding hands at the grave."],"s":[]},{"w":"precipitous","p":"adj.","m":"Dangerously steep; also sudden.","e":"Latin <i>praeceps</i> (headlong): <i>prae</i> (before) + <i>caput</i> (head).","f":"abrupt, escarpé; précipité","t":"Head first over the précipice. A precipitous drop in sales.","h":["Precipice: a sheer cliff. A precipitous decline.","Precipitous slope: hold on or fall."],"s":[]},{"w":"prodigious","p":"adj.","m":"Remarkably great in size or degree.","e":"Latin <i>prodigiosus</i>, from <i>prodigium</i> (omen, marvel).","f":"prodigieux","t":"Same as « prodigieux »: like an omen, it amazes.","h":["Prodigy: amazing. A prodigious appetite or talent.","Prodigious: Mozart composing at five."],"s":["colossal"]},{"w":"prolific","p":"adj.","m":"Producing much; productive.","e":"French <i>prolifique</i>, from Latin <i>proles</i> (offspring) + <i>facere</i>.","f":"prolifique","t":"Same as « prolifique »: lots of offspring.","h":["Proles = offspring: lots of children, or lots of books. A prolific author.","Prolific: a rabbit’s family or a novelist’s output."],"s":["fecund","fruitful","lucrative"]},{"w":"propitious","p":"adj.","m":"Favourable; indicating a good chance of success.","e":"Latin <i>propitius</i> (favourable, gracious), perhaps from <i>pro</i> + <i>petere</i> (to seek).","f":"propice","t":"Propitious = « propice »: « un moment propice ».","h":["Propitius: kind, favourable. A propitious moment to ask for a raise.","Propitious: the stars align."],"s":["auspicious","providential"]},{"w":"ravenous","p":"adj.","m":"Extremely hungry.","e":"Old French <i>ravineus</i> (violent, rapacious), from <i>raviner</i> (to ravage), Latin <i>rapina</i> (plunder).","f":"affamé, vorace","t":"Hungry enough to plunder (rapina, as in « rapine »). Not from the bird raven.","h":["Ravine/rapere: seize. Eat like a wolf: ravenous.","Ravenous after a ten-mile hike: you could eat anything."],"s":["avaricious","rapacious","voracious"]},{"w":"repudiate","p":"v.","m":"To refuse to accept; reject.","e":"Latin <i>repudiare</i> (to divorce, reject), from <i>repudium</i> (divorce).","f":"répudier, rejeter","t":"« Répudier sa femme »: in Rome, a formal divorce. Repudiate a claim = cast it off.","h":["Repudium: Roman divorce. Repudiate = cast off a claim or a spouse.","Repudiate: publicly reject what was said in your name."],"s":["relinquish","renounce","spurn"]},{"w":"rescind","p":"v.","m":"To revoke or cancel.","e":"Latin <i>rescindere</i> (to cut off): <i>re-</i> + <i>scindere</i> (to split).","f":"annuler, révoquer, rescinder","t":"Scindere = scinder, to cut: rescinding a contract cuts it off.","h":["Re + scindere (cut): cut away the decision. The company rescinded the job offer.","Rescind = undo an order, as a law is repealed."],"s":["abrogate","countermand","nullify","quash","recant","retract","squelch","suppress"]},{"w":"resurgent","p":"adj.","m":"Increasing or reviving after a period of decline.","e":"Latin <i>resurgere</i> (to rise again): <i>re-</i> + <i>surgere</i> (to rise).","f":"renaissant, en plein renouveau","t":"Rising again, like resurrection. « Une résurgence ».","h":["Re + surgere: rise again. A resurgent economy after the crash.","Resurgent: the phoenix rising."],"s":[]},{"w":"reverent","p":"adj.","m":"Feeling or showing deep respect.","e":"Latin <i>reverentem</i>, from <i>revereri</i> (to stand in awe of).","f":"révérencieux, respectueux","t":"« Faire la révérence »: a deep, respectful bow.","h":["Revere: deep respect. Reverent silence in a cathedral.","Reverent: taking off your hat as the flag passes."],"s":["deferential","dutiful","obsequious","pious"]},{"w":"sanction","p":"n. / v.","m":"Official approval OR a penalty (contranym).","e":"Latin <i>sanctio</i> (decree, penalty), from <i>sancire</i> (to make sacred, decree).","f":"approbation; sanction","x":"2nd meaning","t":"A decree can approve or punish. On the GRE it often means approve: « entériner ».","h":["A contranym: to approve or to punish. Check the context: “sanctioned the plan” vs “sanctions on Russia”.","Sanction = “sanctify”: a stamp of authority. The council sanctioned the merger."],"s":["abide","brook","countenance","underwrite"]},{"w":"scrupulous","p":"adj.","m":"Very careful, honest and thorough.","e":"Latin <i>scrupulosus</i>, from <i>scrupulus</i> (small sharp stone; a pang of conscience).","f":"scrupuleux","t":"Same as « scrupuleux »: feeling every tiny pebble in your shoe.","h":["Scrupulus: a tiny sharp stone. A scrupulous person feels the stone and corrects it.","Scrupulous accounts: every cent checked."],"s":["assiduous","exacting","fastidious","meticulous","painstaking","punctilious","thorough"]},{"w":"sporadic","p":"adj.","m":"Occurring at irregular intervals.","e":"Greek <i>sporadikos</i> (scattered), from <i>speirein</i> (to sow).","f":"sporadique","t":"Seeds scattered when sowing (as in spore). « Sporadique ».","h":["Sporas = scattered (spores). Sporadic rain: a few drops here and there.","Sporadic gunfire: now and then, no pattern."],"s":["desultory","discursive","erratic","fitful","haphazard","intermittent"]},{"w":"subversive","p":"adj.","m":"Seeking to undermine an established system.","e":"Latin <i>subvertere</i>: <i>sub</i> (under) + <i>vertere</i> (to turn). Turning upside down from below.","f":"subversif","t":"Same as « subversif »: turning the system over from underneath.","h":["Sub + vertere: turn from below. A subversive pamphlet.","Subversive art: smuggling rebellion under the censor’s nose."],"s":["iconoclastic"]},{"w":"sycophant","p":"n.","m":"A servile flatterer.","e":"Greek <i>sykophantēs</i> (informer), literally “fig-shower”: <i>sykon</i> (fig) + <i>phainein</i> (to show). Origin of the image debated.","f":"flagorneur, lèche-bottes","t":"The fig-shower: picture a courtier offering figs to the king, nodding at every word.","h":["Sykophantes: “fig-shower”. Today the yes-man who flatters the king.","Sycophant: the aide who laughs at the boss’s weakest jokes."],"s":[]},{"w":"taciturn","p":"adj.","m":"Saying little; reserved.","e":"Latin <i>taciturnus</i>, from <i>tacitus</i> (silent), <i>tacere</i> (to be silent).","f":"taciturne","t":"Same as « taciturne ». Tacere = se taire.","h":["Tacere: be silent. A taciturn farmer: “Yup.”","Taciturn: speaks only when needed."],"s":["dour","glum","laconic","morose","reticent","retiring","saturnine","sullen"]},{"w":"tempered","p":"adj.","m":"Moderated or toned down.","e":"Latin <i>temperare</i> (to mix in proper proportion).","f":"tempéré, nuancé, modéré","t":"Like tempered steel or a « climat tempéré »: optimism tempered by realism.","h":["Tempered steel: heated and cooled to the right hardness; tempered opinions: softened.","Tempered = adjusted, moderated, like a chocolate."],"s":[]},{"w":"tractable","p":"adj.","m":"Easy to control or deal with.","e":"Latin <i>tractabilis</i>, from <i>tractare</i> (to handle), frequentative of <i>trahere</i> (to pull).","f":"docile, maniable","t":"Easy to pull, like a tractor pulling a docile cart. Opposite: intractable.","h":["Tractor-able: you can pull it along. A tractable horse.","Tractable: a student who does what he’s told."],"s":["amenable","complaisant","compliant","docile","malleable","obliging","plastic","pliant"]},{"w":"trite","p":"adj.","m":"Overused and unoriginal.","e":"Latin <i>tritus</i> (worn out), from <i>terere</i> (to rub).","f":"banal, rebattu","t":"Rubbed so much it’s worn out. A trite cliché.","h":["Tritus: worn out by rubbing. “All’s well that ends well”: trite.","Trite = over-polished: a cliché rubbed smooth."],"s":["banal","hackneyed","hoary"]},{"w":"vacillate","p":"v.","m":"To waver between opinions.","e":"Latin <i>vacillare</i> (to sway, totter).","f":"vaciller, hésiter","t":"Same as « vaciller »: a candle flame swaying back and forth.","h":["Vacillare: to sway. Candle flame back and forth; torn between two options.","Vacillate: can’t decide between pizza or pasta, for an hour."],"s":["demur","equivocate","falter","flag","oscillate"]},{"w":"winsome","p":"adj.","m":"Charming, engaging.","e":"Old English <i>wynsum</i>: <i>wynn</i> (joy) + <i>-sum</i> (-some). Germanic.","f":"charmant, avenant","t":"Win + some: a smile that wins you over. Old English wynn = joy.","h":["Win + some: you win people over. A winsome smile.","Winsome: a puppy’s charm."],"s":["debonair","urbane"]}]},{"name":"Common Words VI","slug":"common-words-vi","series":"Common Words","words":[{"w":"anomaly","p":"n.","m":"Something that deviates from what is expected.","e":"Greek <i>anōmalia</i>: <i>an-</i> (not) + <i>homalos</i> (even).","f":"anomalie","t":"Same as « anomalie »: the point off the even line.","h":["Anomalos: not level. The one red dot among blue ones.","Anomaly in the data: a spike on the chart that doesn’t fit the trend."],"s":["aberration","paradox"]},{"w":"antipathy","p":"n.","m":"A deep-seated dislike.","e":"Greek <i>antipatheia</i>: <i>anti</i> (against) + <i>pathos</i> (feeling).","f":"antipathie","t":"Feeling against: the opposite of sympathy. « Antipathie ».","h":["Anti + pathos: a feeling against. A natural antipathy toward liars.","Antipathy = the reverse of sympathy: you can’t stand each other."],"s":["animosity","animus","aversion","enmity"]},{"w":"appease","p":"v.","m":"To pacify by giving in to demands.","e":"Old French <i>apaisier</i>: <i>a</i> + <i>pais</i> (peace), Latin <i>pax</i>.","f":"apaiser","t":"Appease = « apaiser »: bringing peace. Munich 1938 = appeasement.","h":["Apaiser: bring peace by giving in. Munich 1938: appeasing Hitler.","Appease the toddler with a biscuit: calm him by conceding."],"s":["assuage","conciliate","mollify","pacify","placate","propitiate","reconcile"]},{"w":"arduous","p":"adj.","m":"Involving great effort; difficult.","e":"Latin <i>arduus</i> (steep, difficult).","f":"ardu, pénible","t":"Same as « ardu »: a steep climb.","h":["Arduus = steep. An arduous trek up a mountain.","Arduous: ardu: a task that is hard going."],"s":["cumbersome","laborious","onerous","plodding","ponderous","taxing"]},{"w":"askance","p":"adv.","m":"With suspicion or disapproval (to look askance).","e":"Origin uncertain, 1500s; perhaps from Italian <i>a scancio</i> (sideways).","f":"de travers, avec méfiance","t":"Looking at someone sideways: « regarder de travers ».","h":["Look askance = glance sideways in doubt. « De travers ».","Askance: your eyebrow rises as you peek at the strange menu."],"s":[]},{"w":"banality","p":"n.","m":"The quality of being trite or unoriginal.","e":"French <i>banalité</i>, from <i>banal</i>, from the feudal <i>ban</i> (Frankish): the lord’s oven used by all.","f":"banalité","t":"Same as « banalité ». The village four banal again.","h":["Banal + ity: the quality of being ordinary. The banality of small talk.","Banality: the clichés of a coffee-machine chat."],"s":["bromide","platitude"]},{"w":"bolster","p":"v.","m":"To support or strengthen.","e":"Old English <i>bolster</i> (a long pillow). Germanic. To prop up with a cushion.","f":"renforcer, étayer, soutenir","t":"A bolster is a long pillow propping you up. Data that bolsters your case.","h":["A bolster pillow props up your head. Bolster = prop up. Evidence bolsters the case.","Bolster morale: the coach’s pep talk strengthens the team."],"s":["buttress"]},{"w":"capricious","p":"adj.","m":"Given to sudden, unpredictable changes.","e":"French <i>capricieux</i>, from Italian <i>capriccio</i> (a sudden start, whim), perhaps from <i>capra</i> (goat) for its leaps.","f":"capricieux","t":"A goat leaping unpredictably: « capricieux ».","h":["Capra = goat: leaps without warning. A capricious monarch changes his mind daily.","Capricious weather: sun, then storm, then sun."],"s":["arbitrary","droll","erratic","fanciful","fickle","fitful","headstrong","impetuous","impulsive","mercurial","protean","quirky","rash","refractory","volatile","wayward","whimsical","willful"]},{"w":"contrition","p":"n.","m":"Sincere remorse.","e":"Latin <i>contritio</i> (grinding), from <i>conterere</i> (to grind, crush). A heart crushed by guilt.","f":"contrition, repentir","t":"Same as « contrition » in confession: a heart ground down by guilt.","h":["Con + terere (crush): a heart worn down by guilt. A contrite apology.","Contrition: sobbing at confession. Genuine remorse."],"s":[]},{"w":"craven","p":"adj.","m":"Contemptibly cowardly.","e":"Middle English <i>cravant</i> (defeated), probably from Old French <i>cravanté</i> (crushed).","f":"lâche, couard","t":"Defeated and crushed: a craven surrender.","h":["Craven = defeated, gives up. A craven coward who runs.","Craven sounds like “crave in”: crying for mercy at the first threat."],"s":["timorous"]},{"w":"deleterious","p":"adj.","m":"Causing harm.","e":"Greek <i>dēlētērios</i> (noxious), from <i>dēleisthai</i> (to hurt).","f":"délétère, nuisible","t":"Same as « délétère »: « une ambiance délétère ».","h":["Greek deleterios: harmful. Smoking has deleterious effects on health.","Délétère: gas leaking in a lab. Harmful."],"s":["detrimental","inimical","insidious","noxious","pernicious"]},{"w":"dilatory","p":"adj.","m":"Slow; tending to delay.","e":"Latin <i>dilatorius</i>, from <i>differre</i> (to delay), supine <i>dilatum</i>.","f":"dilatoire, lent","t":"« Des manœuvres dilatoires »: stalling tactics.","h":["Dilatare: to delay. A dilatory student postpones the essay all week.","Dilatory tactics: stalling in the meeting."],"s":["languid","lethargic","sluggish"]},{"w":"dispassionate","p":"adj.","m":"Not influenced by strong emotion; impartial.","e":"<i>dis-</i> + passionate, from Latin <i>passio</i> (suffering).","f":"impartial, objectif, posé","t":"Without passion: a dispassionate analysis.","h":["Dis + passion: no passion. A dispassionate judge analyses the facts.","Dispassionate: a scientist reading numbers, calm."],"s":["disinterested","equitable","evenhanded","impartial"]},{"w":"disseminate","p":"v.","m":"To spread widely.","e":"Latin <i>disseminare</i>: <i>dis-</i> (apart) + <i>seminare</i> (to sow), from <i>semen</i> (seed).","f":"disséminer, diffuser","t":"Sowing seeds everywhere: « disséminer ».","h":["Dis + seminare (sow): sow seeds widely. Disseminate information through the press.","Disseminate: spread the news like pollen."],"s":["diffuse","disperse","dissipate","promulgate","propagate"]},{"w":"duress","p":"n.","m":"Threats or pressure used to force someone.","e":"Old French <i>duresse</i> (hardness, harshness), from Latin <i>durus</i> (hard).","f":"contrainte","t":"From dur: signed under duress = sous la contrainte.","h":["Durus = hard: pressure. A signature under duress is not valid.","Duress: confessing with a knife at your back."],"s":["coercion","constraint"]},{"w":"economical","p":"adj.","m":"Using no more than necessary; thrifty (also: economical with the truth).","e":"Greek <i>oikonomia</i>: <i>oikos</i> (house) + <i>nomos</i> (management).","f":"économe, sobre","t":"House management. On the GRE: economical prose = no wasted words.","h":["Oikonomia: house management. An economical car uses little fuel; economical prose wastes no word.","Economical with the truth: says as little truth as possible. A polite way to say he lies."],"s":["abstemious","frugal","parsimonious","provident","prudent","scant","stinting","thrifty"]},{"w":"edifying","p":"adj.","m":"Morally or intellectually instructive.","e":"Latin <i>aedificare</i> (to build): <i>aedes</i> (building) + <i>facere</i>. Building up the soul.","f":"édifiant","t":"Same as « édifiant »: building (édifice) your character.","h":["Aedificare: build up. An edifying lecture builds your mind.","Edifying: a documentary that improves you morally or mentally."],"s":[]},{"w":"efficacious","p":"adj.","m":"Effective, producing the desired result.","e":"Latin <i>efficax</i>, from <i>efficere</i> (to accomplish).","f":"efficace","t":"Efficacious = « efficace ». Used of remedies.","h":["Efficax: works. An efficacious vaccine.","Efficacious sounds like effective: it does the job."],"s":["potent","puissant"]},{"w":"elicit","p":"v.","m":"To draw out a response or fact.","e":"Latin <i>elicere</i>: <i>e-</i> (out) + <i>lacere</i> (to lure).","f":"susciter, obtenir","t":"Lure out a reaction. Not illicit (illegal).","h":["E + lacere (lure): lure out. Elicit a smile.","Elicit information from a reluctant witness: draw it out gently."],"s":["evoke"]},{"w":"erudite","p":"adj.","m":"Very learned.","e":"Latin <i>eruditus</i>, from <i>erudire</i> (to instruct): <i>e-</i> + <i>rudis</i> (rough). Taking the roughness out.","f":"érudit","t":"Same as « érudit »: no longer rude/rough.","h":["E + rudis (rough): polished from rough. A professor so erudite that he quotes Latin.","Erudite: someone who has read the whole library."],"s":["polymath"]},{"w":"esoteric","p":"adj.","m":"Understood by only a small group.","e":"Greek <i>esōterikos</i> (inner), from <i>esō</i> (within). Teachings for inner disciples only.","f":"ésotérique","t":"Same as « ésotérique »: for the inner circle.","h":["Esoterikos: inner. Esoteric rituals understood only by insiders.","Esoteric knowledge: a secret society’s handbook."],"s":["abstruse","arcane","cryptic","obscure","rarefied","recondite","sublime"]},{"w":"fastidious","p":"adj.","m":"Very attentive to detail; hard to please.","e":"Latin <i>fastidiosus</i> (disdainful), from <i>fastidium</i> (loathing).","f":"méticuleux, pointilleux (≠ fastidieux)","x":"Faux ami","t":"Careful: « fastidieux » = tedious. Fastidious = maniaque, fussy.","h":["Fastidium: disgust. Fussy about every detail: not “fastidieux”.","A fastidious chef rejects a tomato for one blemish."],"s":["captious","exacting","finicky","meticulous","painstaking","pedantic","punctilious","scrupulous","thorough"]},{"w":"flux","p":"n.","m":"Continuous change.","e":"Latin <i>fluxus</i> (flow), from <i>fluere</i> (to flow).","f":"flux, mouvance","t":"Heraclitus: everything flows. A market in flux.","h":["Fluere: flow. Everything is in flux; the situation changes constantly.","Flux: a river never the same twice."],"s":[]},{"w":"furtive","p":"adj.","m":"Secretive; trying not to be noticed.","e":"Latin <i>furtivus</i>, from <i>furtum</i> (theft), <i>fur</i> (thief).","f":"furtif","t":"Same as « furtif »: moving like a thief.","h":["Fur = thief. A furtive glance, stolen quickly.","Furtive: slipping out of the room unseen."],"s":["clandestine","covert","surreptitious","ulterior"]},{"w":"harried","p":"adj.","m":"Harassed, stressed by demands.","e":"Old English <i>hergian</i> (to ravage, raid), related to <i>here</i> (army). Germanic.","f":"harcelé, débordé","t":"Raided by an army of emails. A harried consultant on a Sunday.","h":["Harry: raid. Harried by deadlines like an army attacking.","A harried mother of three: always rushed."],"s":[]},{"w":"ignominious","p":"adj.","m":"Deserving or causing public disgrace.","e":"Latin <i>ignominia</i>: <i>in-</i> (not) + <i>nomen</i> (name). Loss of one’s good name.","f":"ignominieux, honteux","t":"Same as « ignominieux »: losing your name.","h":["In + nomen (name): losing your good name. An ignominious defeat.","Ignominious: a king dethroned and paraded in shame."],"s":[]},{"w":"impartial","p":"adj.","m":"Treating all equally; fair.","e":"<i>in-</i> + partial, from Latin <i>pars</i> (part). Not taking a part.","f":"impartial","t":"Same as « impartial ».","h":["Im + partial: not taking a side. An impartial referee.","Impartial: scales balanced."],"s":["disinterested","dispassionate","equitable","evenhanded"]},{"w":"imprudent","p":"adj.","m":"Not showing care for the consequences.","e":"Latin <i>imprudens</i>: <i>in-</i> + <i>prudens</i> (foreseeing), contraction of <i>providens</i>.","f":"imprudent","t":"Same as « imprudent »: not foreseeing.","h":["In + prudens: lacking foresight. An imprudent investor puts everything on one bet.","Imprudent: crossing without looking."],"s":["foolhardy","impolitic","improvident","prodigal","profligate","rash","spendthrift"]},{"w":"indecorous","p":"adj.","m":"Improper; in bad taste.","e":"Latin <i>indecorus</i>: <i>in-</i> + <i>decorus</i> (fitting).","f":"inconvenant","t":"Breaking « le décorum ».","h":["In + decorous: improper. Indecorous laughter at a funeral.","Indecorous behaviour: breaking the rules of polite society."],"s":["gauche","unseemly","untoward"]},{"w":"jovial","p":"adj.","m":"Cheerful and friendly.","e":"Latin <i>Iovialis</i> (of Jupiter). Astrologers held those born under Jupiter to be happy.","f":"jovial","t":"Same as « jovial »: born under jolly Jupiter (Jove).","h":["Jove (Jupiter): cheerful. A jovial host with a loud laugh.","Jovial: Santa Claus type."],"s":["affable","amiable","congenial","convivial","cordial","droll","facetious","genial","gregarious","jocular","jocund"]},{"w":"maladroit","p":"adj.","m":"Clumsy, inept.","e":"French <i>maladroit</i>: <i>mal</i> (badly) + <i>adroit</i> (skilful, à droit).","f":"maladroit","t":"Straight from French « maladroit ».","h":["Mal + adroit: bad right hand. A maladroit remark that offends.","Maladroit: he spills the wine on the host."],"s":["bumbling","gauche","gawky","inept"]},{"w":"maverick","p":"n.","m":"An independent-minded nonconformist.","e":"From Samuel Maverick (1803–1870), a Texas rancher who refused to brand his cattle; unbranded calves were called mavericks.","f":"franc-tireur, non-conformiste","t":"The unbranded calf wandering free from the herd. Also Top Gun’s pilot.","h":["Samuel Maverick refused to brand his calves: an independent. Top Gun’s call sign.","A maverick scientist ignoring the consensus."],"s":["iconoclast"]},{"w":"mendacity","p":"n.","m":"Untruthfulness, lying.","e":"Latin <i>mendax</i> (lying), from <i>mendum</i> (fault).","f":"mensonge, fausseté","t":"Mendacity sounds like « mensonge », and that’s exactly what it is: a habit of lying.","h":["Mendax: liar. A mendacious politician.","Mendacity ≈ « mensonge »: habitual lying."],"s":[]},{"w":"misconstrue","p":"v.","m":"To interpret wrongly.","e":"<i>mis-</i> + construe, Latin <i>construere</i> (to build).","f":"mal interpréter","t":"Building the wrong meaning. Contrast with construe.","h":["Mis + construe: build the wrong meaning. She misconstrued his joke as an insult.","Misconstrue: reading the wrong message into a text."],"s":[]},{"w":"mundane","p":"adj.","m":"Ordinary, dull; earthly.","e":"Latin <i>mundanus</i>, from <i>mundus</i> (world).","f":"banal, terre-à-terre (≠ mondain)","x":"Faux ami","t":"Careful: « mondain » = society/high life. Mundane = ordinary everyday stuff.","h":["Mundus = world: everyday earthly things. Mundane tasks: laundry, emails.","Mundane: the commute: tedious and ordinary."],"s":["banal","humdrum","monotonous","pedestrian","prosaic","quotidian","tedious","temporal"]},{"w":"nonplussed","p":"adj.","m":"So surprised one doesn’t know how to react.","e":"Latin <i>non plus</i> (no more): a state where nothing more can be said.","f":"perplexe, décontenancé","t":"« Non plus »: you have nothing more to say. Means baffled, not calm.","h":["Non plus: no more to say. Totally baffled.","Nonplussed: you stare, speechless, at a surprising question."],"s":["befuddled","confound","flummox","flummoxed"]},{"w":"nuance","p":"n.","m":"A subtle difference in meaning or expression.","e":"French <i>nuance</i> (shade), from <i>nuer</i> (to shade), from <i>nue</i> (cloud).","f":"nuance","t":"Straight from French: shades like those of a cloud (nue).","h":["Nue = cloud: shades. A nuance of meaning: subtle.","Nuance: the difference between grey and gris perle."],"s":[]},{"w":"opulence","p":"n.","m":"Great wealth or luxury.","e":"Latin <i>opulentia</i>, from <i>opes</i> (wealth).","f":"opulence","t":"Same as « opulence ». Versailles’ Hall of Mirrors.","h":["Ops = wealth: lavish luxury. The opulence of Versailles.","Opulence: gold taps and chandeliers."],"s":[]},{"w":"pejorative","p":"adj.","m":"Expressing contempt or disapproval.","e":"Latin <i>peiorare</i> (to make worse), from <i>peior</i> (worse).","f":"péjoratif","t":"Same as « péjoratif »: making it sound worse.","h":["Pejor = worse. A pejorative term makes it sound bad.","Pejorative: calling a country “backward”: an insulting label."],"s":["derogative"]},{"w":"placate","p":"v.","m":"To calm or soothe someone angry.","e":"Latin <i>placare</i> (to calm).","f":"apaiser, calmer","t":"Placare: same root as implacable and plaire. Placate an angry client.","h":["Placare: to calm. Placate the customer with a refund.","Placate: give the baby a pacifier."],"s":["appease","assuage","conciliate","mollify","pacify","propitiate","reconcile"]},{"w":"polemic","p":"n.","m":"A strong verbal or written attack.","e":"Greek <i>polemikos</i> (warlike), from <i>polemos</i> (war).","f":"polémique","t":"Same as « polémique »: war (polemos) by words.","h":["Polemos = war: a war of words. A polemic against the government.","Polemic: a newspaper column that attacks."],"s":["broadside","diatribe","harangue","tirade"]},{"w":"posit","p":"v.","m":"To put forward as fact or a basis for argument.","e":"Latin <i>positus</i>, from <i>ponere</i> (to place).","f":"postuler, poser comme principe","t":"To posit = « poser » a hypothesis on the table.","h":["Ponere: to put. Posit a theory: put it forward.","Posit: “let’s assume X”: you set it down as a starting point."],"s":[]},{"w":"rebuke","p":"v. / n.","m":"To express sharp disapproval.","e":"Anglo-French <i>rebuker</i> (to beat back), from Old French <i>bukier</i> (to strike).","f":"réprimander, reproche","t":"Beat back verbally: a sharp rebuke from the partner.","h":["Re + buke: beat back. The teacher’s rebuke silenced the class.","Rebuke: a sharp scolding."],"s":["admonish","berate","castigate","censure","chastise","excoriate","lambast","lambaste","objurgate","objurgation","reproach","upbraid"]},{"w":"reproach","p":"v. / n.","m":"To express disappointment or disapproval.","e":"Old French <i>reprochier</i>, from Vulgar Latin <i>repropiare</i> (to bring back near).","f":"reprocher, reproche","t":"Same as « reprocher ». Beyond reproach = irréprochable.","h":["Re + prope: bring back to the near: you throw the fault back. Beyond reproach = spotless.","Reproach: the sad look from a disappointed parent."],"s":["admonish","berate","castigate","censure","chastise","excoriate","lambaste","objurgate","rebuke","upbraid"]},{"w":"specious","p":"adj.","m":"Superficially plausible but actually wrong.","e":"Latin <i>speciosus</i> (good-looking), from <i>species</i> (appearance).","f":"spécieux","t":"Same as « spécieux »: pretty on the surface, false inside.","h":["Species: appearance. A specious argument looks good but is wrong.","Specious = “spacious”: seems big but is hollow."],"s":["bogus","counterfeit","credible","fallacious","illusory","phony","plausible","sham","spurious"]},{"w":"stringent","p":"adj.","m":"Strict, precise and exacting.","e":"Latin <i>stringentem</i>, from <i>stringere</i> (to draw tight).","f":"rigoureux, strict","t":"Pulled tight (stringere, as in stricte). Stringent regulations.","h":["Stringere: tighten. Stringent rules: tight and strict.","Stringent controls: every box checked."],"s":["draconian","exacting","exigent","onerous"]},{"w":"sullen","p":"adj.","m":"Bad-tempered and sulky.","e":"Anglo-French <i>solein</i> (solitary), from Latin <i>solus</i> (alone).","f":"maussade, renfrogné","t":"Solus = alone: the sulky teen alone in his room.","h":["Solus: alone. A sullen teenager in a corner.","Sullen: grumpy silence at the table."],"s":["bilious","choleric","churlish","dour","glum","morose","saturnine","splenetic","surly","taciturn"]},{"w":"timorous","p":"adj.","m":"Showing fear; timid.","e":"Medieval Latin <i>timorosus</i>, from <i>timor</i> (fear).","f":"craintif, timoré","t":"Same as « timoré ». Timor = fear.","h":["Timor: fear. A timorous kitten under the sofa.","Timorous voice trembling when asked to speak."],"s":["craven","restive","skittish"]},{"w":"transient","p":"adj.","m":"Lasting only a short time.","e":"Latin <i>transire</i> (to go across): <i>trans</i> + <i>ire</i> (to go).","f":"transitoire, passager","t":"Passing through: « transitoire ».","h":["Trans + ire: passing through. Transient guests stay one night.","Transient: a cloud passing, gone soon."],"s":["ephemeral","evanescent","momentary","transitory"]},{"w":"truncate","p":"v.","m":"To shorten by cutting off.","e":"Latin <i>truncare</i> (to cut off), from <i>truncus</i> (trunk, maimed).","f":"tronquer","t":"Same as « tronquer »: cut down to the trunk.","h":["Truncus: trunk. Cut it short: a truncated report loses its ending.","Truncate: chop the end off, like a trimmed tree."],"s":["curb","curtail"]}]},{"name":"Common Words VII","slug":"common-words-vii","series":"Common Words","words":[{"w":"abate","p":"v.","m":"To become less intense; diminish.","e":"Old French <i>abatre</i> (to beat down), from Latin <i>ad</i> + <i>battuere</i> (to beat).","f":"diminuer, s’apaiser (abattre)","t":"« Abattre »: the storm is beaten down. The storm abated.","h":["A + battre: the wind is beaten down. The storm abated.","Abate = diminish: pain abates after the pill."],"s":["subside","wane"]},{"w":"acumen","p":"n.","m":"Keen insight; sharp judgment.","e":"Latin <i>acumen</i> (point, sharpness), from <i>acuere</i> (to sharpen).","f":"perspicacité, flair","t":"Acus = needle: a mind sharp as a point. Business acumen = le sens des affaires.","h":["Acus (needle): sharp thinking. Business acumen: spotting a good deal.","Acumen: a mind with a sharp point, like acute."],"s":[]},{"w":"adulterate","p":"v.","m":"To make impure by adding inferior substances.","e":"Latin <i>adulterare</i> (to corrupt), from <i>ad</i> + <i>alter</i> (other).","f":"frelater, altérer","t":"Adding something other (alter): watered-down wine is adulterated, « frelaté ».","h":["Ad + alter: make other. Adulterated milk is watered down.","Adulterate: cheap filler hidden in the product; not pure."],"s":["debase","degrade","demean","vitiate"]},{"w":"alleviate","p":"v.","m":"To make suffering less severe.","e":"Late Latin <i>alleviare</i>: <i>ad</i> + <i>levis</i> (light).","f":"soulager, alléger","t":"Levis = léger: alleviate = « alléger » the pain.","h":["Levis (light): lighten the pain. Aspirin alleviates a headache.","Alleviate: take weight off, like lifting a bag."],"s":["assuage","mitigate","palliate","temper"]},{"w":"approbation","p":"n.","m":"Approval or praise.","e":"Latin <i>approbatio</i>, from <i>approbare</i> (to approve): <i>ad</i> + <i>probare</i> (to test, find good).","f":"approbation","t":"Same as « approbation ». Opposite: opprobrium.","h":["Approve: nod of approval. Seek the boss’s approbation.","Approbation = a thumbs-up; the opposite of opprobrium."],"s":["accolade"]},{"w":"articulate","p":"adj. / v.","m":"Expressing oneself clearly; to express clearly.","e":"Latin <i>articulatus</i> (jointed), from <i>articulus</i> (small joint). Speech divided into distinct parts.","f":"qui s’exprime bien; articuler, formuler","t":"Joints (articulations) make movement clear; articulate speech is clearly jointed.","h":["Articulus: little joint. An articulate speaker joins ideas clearly.","Articulate as a verb: to say it clearly (“articulate your goals”)."],"s":["cogent","coherent","eloquent","intelligible","lucid"]},{"w":"aver","p":"v.","m":"To state or assert to be true.","e":"Old French <i>averer</i>, from Latin <i>ad</i> + <i>verus</i> (true).","f":"affirmer, avérer","t":"Aver = declare it « avéré », true (verus).","h":["Verus: true. Aver = say that it’s true: “I aver my innocence.”","Aver, avérer: to declare with certainty."],"s":["contend","maintain","opine"]},{"w":"bombastic","p":"adj.","m":"High-sounding but with little meaning; pompous.","e":"From <i>bombast</i>, cotton padding for clothes, from Medieval Latin <i>bombax</i> (cotton). Padded speech.","f":"grandiloquent, pompeux","t":"Bombast = cotton stuffing: speech padded with fluff.","h":["Bombast: cotton padding. A bombastic speech: padded, empty.","Bombastic = bomb + fantastic: loud and inflated, but a dud."],"s":["grandiloquent","pretentious","tumid","turgid"]},{"w":"chicanery","p":"n.","m":"Trickery to achieve a goal.","e":"French <i>chicanerie</i>, from <i>chicaner</i> (to quibble).","f":"chicane, manœuvres","t":"French « chicane »: legal tricks and quibbles.","h":["Chicane: legal tricks. A lawyer’s chicanery to dodge the point.","Chicanery: a salesman’s sleight of hand."],"s":["legerdemain","skullduggery","subterfuge"]},{"w":"circumspect","p":"adj.","m":"Cautious; unwilling to take risks.","e":"Latin <i>circumspectus</i>: <i>circum</i> (around) + <i>specere</i> (to look).","f":"circonspect, prudent","t":"Same as « circonspect »: looking all around before acting.","h":["Circum + specere: look around. A circumspect driver checks every direction.","Circumspect: thinks twice before speaking."],"s":["chary","discreet","judicious","leery","politic","prudent","vigilant","wary"]},{"w":"clamor","p":"n. / v.","m":"A loud, insistent demand or noise.","e":"Latin <i>clamor</i> (shout), from <i>clamare</i> (to cry out).","f":"clameur, réclamer à grands cris","t":"« Une clameur »: the crowd shouting for something.","h":["Clamare: shout. The clamor of the crowd for change.","Clamor for tickets: everyone demanding at once."],"s":["cacophony","clangor","discord","dissonance","tumult"]},{"w":"compliant","p":"adj.","m":"Inclined to obey; meeting rules.","e":"From comply, Italian <i>complire</i>, from Latin <i>complere</i> (to fill up, complete).","f":"docile, conforme","t":"Compliant with the rules = « conforme ». Compliance team.","h":["Comply: do as told. A compliant child tidies up when asked.","Compliant = conforming: your documents meet the rules."],"s":["amenable","complaisant","docile","malleable","obliging","pliant","supple","tractable"]},{"w":"connoisseur","p":"n.","m":"An expert judge in matters of taste.","e":"Old French <i>connoisseur</i> (modern <i>connaisseur</i>), from Latin <i>cognoscere</i> (to know).","f":"connaisseur","t":"Straight from French « connaisseur ».","h":["Connaître: to know. A wine connoisseur knows the vintage by smell.","Connoisseur: the friend you ask which cheese to buy."],"s":["aesthete"]},{"w":"covert","p":"adj.","m":"Not openly acknowledged; secret.","e":"Old French <i>covert</i> (covered), past participle of <i>covrir</i> (to cover).","f":"secret, caché, clandestin","t":"Covered = « couvert ». Covert ops. Opposite: overt (ouvert).","h":["Couvert: covered. A covert mission is hidden.","Covert ≠ overt: covered up vs open."],"s":["clandestine","furtive","surreptitious","ulterior"]},{"w":"desiccate","p":"v.","m":"To dry out completely.","e":"Latin <i>desiccare</i>: <i>de-</i> + <i>siccare</i> (to dry), from <i>siccus</i> (dry).","f":"dessécher","t":"Siccus = sec: « dessécher ».","h":["Siccus: dry. Desiccated coconut is dried out.","Desiccate: dry like a raisin in the sun."],"s":[]},{"w":"deterrent","p":"n.","m":"Something that discourages an action.","e":"Latin <i>deterrere</i>: <i>de-</i> (away) + <i>terrere</i> (to frighten).","f":"moyen de dissuasion","t":"Frighten away (terrere, as in terreur). Nuclear deterrent = « force de dissuasion ».","h":["Terrere (frighten): scares you off. A high fine as a deterrent.","Deterrent: the guard dog sign."],"s":["check","curb","impediment"]},{"w":"dissent","p":"n. / v.","m":"Disagreement with official opinion.","e":"Latin <i>dissentire</i>: <i>dis-</i> + <i>sentire</i> (to feel).","f":"dissidence, désaccord","t":"Feeling apart: a dissenting opinion. « Dissension ».","h":["Dis + sentire: feel apart. A dissenting judge writes a separate opinion.","Dissent: raising your hand to disagree."],"s":["variance"]},{"w":"divest","p":"v.","m":"To deprive or rid oneself of something.","e":"Medieval Latin <i>divestire</i>: <i>dis-</i> + <i>vestire</i> (to clothe). To undress.","f":"se défaire de, céder","t":"Un-dress: divesting a business unit = taking off a piece of clothing (vêtement).","h":["Vestire: clothe. Divest = take off clothes: sell off a stake.","Divest from fossil fuels: sell the shares."],"s":["relinquish"]},{"w":"efficacy","p":"n.","m":"The ability to produce the intended result.","e":"Latin <i>efficacia</i>, from <i>efficere</i> (to accomplish).","f":"efficacité","t":"« Efficacité » of a drug in a clinical trial.","h":["Efficax: effective. The efficacy of the vaccine: 95 %.","Efficacy = how well it works in a trial."],"s":[]},{"w":"eloquent","p":"adj.","m":"Fluent and persuasive in speech.","e":"Latin <i>eloquentem</i>, from <i>eloqui</i>: <i>e-</i> (out) + <i>loqui</i> (to speak).","f":"éloquent","t":"Same as « éloquent »: speaking out.","h":["E + loqui: speak out. An eloquent speech moves a crowd.","Eloquent: Martin Luther King on the steps."],"s":["articulate","cogent","telling"]},{"w":"epitome","p":"n.","m":"A perfect example of a type.","e":"Greek <i>epitomē</i> (abridgement), from <i>epitemnein</i> (to cut short).","f":"incarnation, quintessence","t":"Once a summary; now the essence condensed. Not « épitomé » (summary) in modern use.","h":["Epitemnein: to cut short. The epitome of elegance: the pure essence.","Epitome: the textbook example."],"s":["apotheosis","archetype","exemplar","paragon"]},{"w":"eulogy","p":"n.","m":"A speech praising someone, especially at a funeral.","e":"Greek <i>eulogia</i> (praise): <i>eu</i> (well) + <i>logos</i> (speaking).","f":"éloge funèbre","t":"Eu-logos = speaking well of someone. « Éloge ».","h":["Eu + logos: good words. A eulogy at the funeral.","Eulogy: reading a loving speech for a friend."],"s":["accolade","encomium","panegyric"]},{"w":"explicit","p":"adj.","m":"Stated clearly; leaving nothing implied.","e":"Latin <i>explicitus</i> (unfolded), from <i>explicare</i>: <i>ex-</i> + <i>plicare</i> (to fold).","f":"explicite","t":"Unfolded fully. Opposite: implicit (folded in).","h":["Explicare: unfold. Explicit instructions leave nothing unsaid.","Explicit: spelled out in plain words."],"s":["overt","unequivocal"]},{"w":"facilitate","p":"v.","m":"To make easier.","e":"French <i>faciliter</i>, from Latin <i>facilis</i> (easy).","f":"faciliter","t":"Same as « faciliter ».","h":["Facilis: easy. A good guide facilitates the discussion.","Facilitate: smoothing the path."],"s":["dispatch","expedite"]},{"w":"fervid","p":"adj.","m":"Intensely enthusiastic; passionate.","e":"Latin <i>fervidus</i>, from <i>fervere</i> (to boil).","f":"fervent, ardent","t":"Boiling: same root as « ferveur ».","h":["Fervere: boil. A fervid supporter chants all match.","Fervid: boiling with enthusiasm."],"s":["ardent","avid","fervent","keen","zealous"]},{"w":"guile","p":"n.","m":"Sly or cunning intelligence.","e":"Old French <i>guile</i> (deceit), probably Frankish; related to English <i>wile</i>.","f":"ruse, astuce","t":"Guile = wiles = ruse. Guileless = without it.","h":["Guile: wile, ruse. The fox’s guile.","Guile: a charm used to trick."],"s":["artifice","cunning","duplicity","perfidy"]},{"w":"gullible","p":"adj.","m":"Easily persuaded to believe something.","e":"From <i>gull</i> (to dupe), perhaps from the seagull, a bird that swallows anything.","f":"crédule, naïf","t":"A seagull swallows whatever is thrown. « Crédule ».","h":["Gull: a swallowable fool; a gull swallows anything. A gullible tourist believes the scam.","Gullible: believes the email from the “prince”."],"s":["artless","credulous","ingenuous","naive"]},{"w":"homogeneous","p":"adj.","m":"Of the same kind; uniform.","e":"Greek <i>homogenēs</i>: <i>homos</i> (same) + <i>genos</i> (kind).","f":"homogène","t":"Same as « homogène ».","h":["Homo (same) + genos (kind). Homogenised milk: uniform.","Homogeneous crowd: everyone dressed alike."],"s":[]},{"w":"implicit","p":"adj.","m":"Implied though not stated; absolute (implicit trust).","e":"Latin <i>implicitus</i> (entwined), from <i>implicare</i>: <i>in-</i> + <i>plicare</i> (to fold).","f":"implicite; absolu","t":"Folded inside. Opposite: explicit.","h":["Implicare: fold in. Implicit trust: no need to say it.","Implicit: understood but not said."],"s":["inherent","tacit"]},{"w":"inconsequential","p":"adj.","m":"Not important or significant.","e":"<i>in-</i> + Latin <i>consequentia</i>, from <i>consequi</i> (to follow).","f":"insignifiant, sans importance","t":"Nothing follows from it: no consequences.","h":["No consequences. An inconsequential remark: nobody remembers.","Inconsequential: a detail that changes nothing."],"s":["extraneous","immaterial","negligible","paltry","picayune","trifling","trivial"]},{"w":"indeterminate","p":"adj.","m":"Not exactly known or established.","e":"Latin <i>indeterminatus</i>: <i>in-</i> + <i>determinare</i> (to limit), from <i>terminus</i> (boundary).","f":"indéterminé","t":"No boundary drawn: « indéterminé ».","h":["Not determined. An indeterminate sentence: no fixed end.","Indeterminate: we don’t yet know the number."],"s":["ambiguous","equivocal","indefinite"]},{"w":"intractable","p":"adj.","m":"Hard to control or solve.","e":"Latin <i>intractabilis</i>: <i>in-</i> + <i>tractare</i> (to handle).","f":"insoluble, réfractaire","t":"Can’t be handled or pulled (tractor). An intractable problem.","h":["In + tractable: can’t be pulled along. An intractable conflict won’t be solved.","Intractable pain; intractable problem: nothing works."],"s":["contumacious","fractious","incorrigible","inveterate","obstinate","obstreperous","recalcitrant","refractory","unruly"]},{"w":"lavish","p":"adj. / v.","m":"Sumptuous; to give generously.","e":"Old French <i>lavasse</i> (downpour), from <i>laver</i> (to wash). A flood of something.","f":"somptueux, prodiguer","t":"A downpour (« lavasse ») of gifts. Lavish praise.","h":["Lavish: rich spending: a lavish party with champagne fountains.","Lavish praise: pouring it on thick."],"s":["copious","dissipate","extravagant","improvident","munificent","prodigal","profligate","profuse","spendthrift","squander","unstinting"]},{"w":"loquacious","p":"adj.","m":"Talkative.","e":"Latin <i>loquax</i>, from <i>loqui</i> (to speak).","f":"loquace","t":"Same as « loquace ».","h":["Loqui: speak. A loquacious guest talks all night.","Loquacious: the barber who never stops talking."],"s":["effusive","garrulous","glib","prolix","tedious","verbose","voluble"]},{"w":"nascent","p":"adj.","m":"Just beginning to develop.","e":"Latin <i>nascentem</i>, from <i>nasci</i> (to be born).","f":"naissant","t":"« Naissant »: just born. A nascent industry.","h":["Nasci: be born. A nascent industry: just born.","Nascent hope: a first sprout."],"s":["callow","embryonic","fledgling","inchoate","incipient","neophyte","rudimentary","tyro"]},{"w":"onerous","p":"adj.","m":"Burdensome; involving heavy effort.","e":"Latin <i>onerosus</i>, from <i>onus</i> (burden).","f":"lourd, pesant (onéreux = costly)","x":"Faux ami","t":"Onus = burden. French « onéreux » means expensive; English onerous means heavy work.","h":["Onus: burden. Onerous duties weigh you down. Not « onéreux ».","Onerous paperwork: a heavy load."],"s":["arduous","cumbersome","exacting","exigent","laborious","plodding","ponderous","stringent","taxing"]},{"w":"opprobrium","p":"n.","m":"Harsh public criticism; disgrace.","e":"Latin <i>opprobrium</i> (reproach): <i>ob</i> (against) + <i>probrum</i> (shameful act).","f":"opprobre","t":"Same as « jeter l’opprobre sur ». Opposite of approbation.","h":["Ob + probrum (reproach): public shame. The opprobrium of the press.","Opprobrium: scorn from the crowd."],"s":["censure","contempt","disdain","scorn","stigma"]},{"w":"overt","p":"adj.","m":"Done openly; not hidden.","e":"Old French <i>overt</i> (open), past participle of <i>ovrir</i> (to open), now <i>ouvrir</i>.","f":"manifeste, ouvert","t":"Overt = « ouvert ». Covert = « couvert ».","h":["Ouvert: open. Overt hostility; opposite of covert.","Overt: out in the open."],"s":["conspicuous","explicit","manifest","palpable","patent","unequivocal"]},{"w":"paradox","p":"n.","m":"A seemingly self-contradictory statement that may be true.","e":"Greek <i>paradoxos</i>: <i>para</i> (contrary to) + <i>doxa</i> (opinion).","f":"paradoxe","t":"Against common opinion (doxa). Same as « paradoxe ».","h":["Para + doxa: against opinion. “Less is more”: a paradox.","Paradox: a true statement that sounds false."],"s":["anomaly"]},{"w":"partisan","p":"adj. / n.","m":"Strongly biased towards a party or cause.","e":"French <i>partisan</i>, from Italian <i>partigiano</i>, from <i>parte</i> (part, faction).","f":"partisan","t":"Same as « partisan »: taking one party’s side.","h":["Parti: taking a side. A partisan crowd cheers only for its team.","Partisan: no middle ground."],"s":["contentious","factious","partial","tendentious"]},{"w":"plethora","p":"n.","m":"An excess; a large amount.","e":"Greek <i>plēthōrē</i> (fullness), from <i>plēthein</i> (to be full).","f":"pléthore","t":"« Pléthore de candidats »: an overflow.","h":["Plethore: fullness. A plethora of choices on the menu.","Plethora = too much: a flood."],"s":["cornucopia","glut","profusion","surfeit"]},{"w":"propriety","p":"n.","m":"Conformity to accepted standards of behaviour.","e":"Old French <i>propriete</i>, from Latin <i>proprietas</i> (appropriateness), from <i>proprius</i> (one’s own, proper).","f":"bienséance, convenance (≠ propriété)","x":"Faux ami","t":"Not property! Propriety = « les convenances », what is proper.","h":["Proper: acceptable behaviour. Observe the proprieties at the royal dinner.","Propriety: knowing which fork to use."],"s":["decorum"]},{"w":"tacit","p":"adj.","m":"Understood without being stated.","e":"Latin <i>tacitus</i> (silent), from <i>tacere</i>.","f":"tacite","t":"Same as « tacite »: « reconduction tacite ».","h":["Tacere: be silent. Tacit agreement: no words.","Tacit approval: a nod, no signature."],"s":["implicit","inherent"]},{"w":"tangential","p":"adj.","m":"Only slightly relevant; diverging.","e":"Latin <i>tangentem</i>, from <i>tangere</i> (to touch). A tangent only touches the circle at one point.","f":"accessoire, secondaire","t":"Going off on a tangent: barely touching the topic. « Partir dans une digression ».","h":["Tangent: touches a circle at one point. A tangential remark barely touches the subject.","Tangential: a digression that skims the topic."],"s":["concomitant","extraneous","immaterial","impertinent","incidental","peripheral","redundant","superfluous"]},{"w":"tenuous","p":"adj.","m":"Very weak or slight.","e":"Latin <i>tenuis</i> (thin).","f":"ténu, fragile","t":"Same as « ténu »: a thin thread of logic.","h":["Tenuis: thin. A tenuous link, thin as thread.","Tenuous argument: barely holding together."],"s":["slight"]},{"w":"veracity","p":"n.","m":"Truthfulness; accuracy.","e":"Medieval Latin <i>veracitas</i>, from <i>verax</i> (truthful), <i>verus</i> (true).","f":"véracité","t":"Same as « véracité ». Vrai.","h":["Verus: true. Doubt the veracity of the report.","Veracity: how true it is."],"s":[]},{"w":"verbose","p":"adj.","m":"Using more words than needed.","e":"Latin <i>verbosus</i>, from <i>verbum</i> (word).","f":"verbeux","t":"Same as « verbeux »: too many verbs/words.","h":["Verbum: word. Verbose email: too many words.","Verbose: the speech that went on for an hour."],"s":["diffuse","discursive","effusive","garrulous","loquacious","prolix","tedious","voluble"]},{"w":"volatile","p":"adj.","m":"Liable to change rapidly and unpredictably.","e":"Latin <i>volatilis</i> (flying), from <i>volare</i> (to fly).","f":"volatile, instable, explosif","t":"Flying away (voler): volatile markets, a volatile temper.","h":["Volare: fly. Volatile liquids evaporate; volatile markets jump.","Volatile mood: from calm to angry in a second."],"s":["arbitrary","capricious","erratic","fickle","mercurial","protean","tempestuous","turbulent","whimsical"]},{"w":"wary","p":"adj.","m":"Cautious about possible dangers.","e":"Old English <i>wær</i> (watchful). Germanic, related to aware and beware.","f":"méfiant, prudent","t":"Beware → wary. Méfiant.","h":["Ware: aware. Be wary of strangers.","Wary: one eye open, hand on the wallet."],"s":["chary","circumspect","discreet","judicious","leery","politic","prudent","vigilant"]},{"w":"zealous","p":"adj.","m":"Having great energy for a cause.","e":"Greek <i>zēlos</i> (ardour, jealousy), via Latin <i>zelus</i>.","f":"zélé","t":"Same as « zélé ». Zealots were fervent rebels in Judea.","h":["Zeal: fervour. A zealous volunteer.","Zealot: a fanatic for a cause; zealous = very eager."],"s":["ardent","avid","fervent","fervid","keen"]}]},{"name":"Basic I","slug":"basic-i","series":"Basic","words":[{"w":"acme","p":"n.","m":"The highest point of achievement or excellence.","e":"Greek <i>akmē</i> (point, peak, prime).","f":"apogée, summum","t":"Akmē = the peak. (Yes, the Acme company in the Road Runner cartoons claims to be the best.)","h":["Akmē: point. The acme of the career: the CEO’s office.","Acme sounds like “acne”: the pimple at its peak. (Crude but sticks.)"],"s":["apex","apogee","apotheosis","heyday","pinnacle","prime","summit","zenith"]},{"w":"affable","p":"adj.","m":"Friendly, easy to talk to.","e":"Latin <i>affabilis</i> (easy to speak to): <i>ad</i> + <i>fari</i> (to speak).","f":"affable","t":"Same as « affable »: easy to speak to.","h":["Ad + fari: easy to speak to. An affable receptionist.","Affable: the neighbour who chats over the fence."],"s":["amiable","amicable","congenial","convivial","cordial","genial","jovial"]},{"w":"affluent","p":"adj.","m":"Wealthy.","e":"Latin <i>affluentem</i>, from <i>affluere</i> (to flow towards): <i>ad</i> + <i>fluere</i>.","f":"aisé, riche (≠ affluent = tributary)","t":"Money flowing towards you. In French « un affluent » is a tributary river; same flow image.","h":["Ad + fluere: flowing to you: money flows in. An affluent suburb.","Affluent: swimming pool and two cars."],"s":["flush"]},{"w":"amiable","p":"adj.","m":"Friendly and pleasant.","e":"Old French <i>amiable</i>, from Late Latin <i>amicabilis</i> (friendly), from <i>amicus</i>.","f":"aimable, amical","t":"Ami → amiable. « À l’amiable » = settled in a friendly way.","h":["Ami: friend. An amiable stranger.","Amiable = à l’amiable: peaceable."],"s":["affable","amicable","congenial","convivial","cordial","genial","jovial"]},{"w":"bleak","p":"adj.","m":"Bare, cold, without hope.","e":"Old Norse <i>bleikr</i> (pale, shining), related to Old English <i>blāc</i> (pale). Germanic.","f":"morne, sombre, désolé","t":"Pale and colourless, like a bleak winter landscape or a bleak outlook.","h":["Bleak: pale, colourless. A bleak winter moor.","A bleak future: no hope in sight."],"s":[]},{"w":"candid","p":"adj.","m":"Truthful and straightforward; frank.","e":"Latin <i>candidus</i> (white, pure). Roman office-seekers wore white togas, hence candidate.","f":"franc, sincère (≠ candide = naive)","x":"Faux ami","t":"Pure white: nothing hidden. French « candide » means naive; English candid means frank.","h":["Candidus: shining white: pure honesty. A candid photo is unposed.","Candid feedback: no sugar-coating."],"s":["aboveboard","artless","expansive","forthcoming","forthright","frank","guileless","ingenuous","naive","unfeigned","veracious"]},{"w":"censor","p":"v. / n.","m":"To suppress unacceptable parts of a text or film.","e":"Latin <i>censor</i>, the Roman magistrate who took the census and policed morals, from <i>censere</i> (to assess).","f":"censurer; censeur","t":"Censor = cuts content. Censure (Common I) = formal blame.","h":["Censor: cuts content. The film was censored.","Censor’s red pen blackens the page."],"s":["bowdlerize","expurgate"]},{"w":"demean","p":"v.","m":"To lower the dignity of.","e":"<i>de-</i> + mean (low, inferior; Old English <i>gemǣne</i>, common). Germanic + Latin prefix.","f":"rabaisser, avilir","t":"Make someone mean (low). A demeaning task.","h":["De + mean: make low. A demeaning job: you’re treated as inferior.","Demean yourself: act beneath your dignity."],"s":["adulterate","belittle","debase","decry","degrade","denigrate","deprecate","disparage","vitiate"]},{"w":"demure","p":"adj.","m":"Reserved, modest and shy.","e":"Probably Anglo-French <i>demuré</i>, from <i>demorer</i> (to stay, be calm), Latin <i>demorari</i>.","f":"réservé, sage, pudique","t":"Demure = « sage comme une image ». Not demur (to object).","h":["Mûr: mature, grave. A demure girl lowers her eyes.","Demure: quiet and proper."],"s":["becoming","coy","decorous","diffident","genteel","modest","retiring","sober","staid"]},{"w":"diabolical","p":"adj.","m":"Characteristic of the devil; very bad.","e":"Greek <i>diabolos</i> (slanderer, devil), from <i>diaballein</i> (to throw across, slander).","f":"diabolique","t":"Same as « diabolique »: the devil (diable).","h":["Diable: devil. A diabolical plan.","Diabolical weather: terrible."],"s":[]},{"w":"dog","p":"v.","m":"To follow closely and persistently; to plague.","e":"Old English <i>docga</i>, a word of unknown origin. The verb (to track like a hound) dates from the 1500s.","f":"poursuivre, harceler, hanter","x":"2nd meaning","t":"A dog on your heels: dogged by scandal = « poursuivi par ».","h":["Dog: follow persistently. Dogged by bad luck.","A dog at your heels: you can’t shake off the scandal."],"s":["badger","hector","hound","importune"]},{"w":"dupe","p":"v. / n.","m":"To deceive; a person easily tricked.","e":"French <i>dupe</i>, perhaps from <i>huppe</i> (hoopoe), a bird reputed to be stupid.","f":"duper; dupe","t":"Same as French « duper ».","h":["Dupe: a fool: a dupe is tricked. Don’t be duped by the ad.","Dupe = huppe (hoopoe) bird, a silly bird in French lore."],"s":["beguile","hoodwink"]},{"w":"embroiled","p":"adj.","m":"Deeply involved in a conflict or difficult situation.","e":"French <i>embrouiller</i> (to confuse, tangle): <i>en</i> + <i>brouiller</i>.","f":"empêtré, mêlé à","t":"« Embrouillé »: tangled up in a scandal.","h":["Embrouiller: to muddle. Embroiled in a legal fight.","Embroiled = tangled like threads."],"s":["involved"]},{"w":"err","p":"v.","m":"To be mistaken.","e":"Latin <i>errare</i> (to wander, stray).","f":"se tromper, errer","t":"To err is human: « l’erreur est humaine ».","h":["Errare: wander. To err is human.","Err on the side of caution: make a mistake in the safer direction."],"s":[]},{"w":"erratic","p":"adj.","m":"Not even or regular; unpredictable.","e":"Latin <i>erraticus</i> (wandering), from <i>errare</i>.","f":"erratique, irrégulier","t":"Wandering all over: « erratique ».","h":["Errare: wander. An erratic driver swerves.","Erratic pulse: irregular beats."],"s":["arbitrary","capricious","fickle","fitful","intermittent","mercurial","protean","sporadic","volatile","wayward","whimsical"]},{"w":"hound","p":"v.","m":"To harass or pursue relentlessly.","e":"Old English <i>hund</i> (dog), Germanic (German <i>Hund</i>).","f":"traquer, harceler","x":"2nd meaning","t":"Hunted by hounds: the press hounded the minister.","h":["Hound dog chases the fox. Reporters hound the star.","Hounded by creditors: they follow you everywhere."],"s":["badger","dog","hector","importune"]},{"w":"indict","p":"v.","m":"To formally accuse of a crime.","e":"Anglo-French <i>enditer</i>, from Latin <i>indicere</i> (to proclaim): <i>in</i> + <i>dicere</i> (to say). Pronounced “in-DITE”.","f":"inculper, mettre en accusation","t":"Indicere = to declare against. Silent c: in-DITE.","h":["In + dicere: declare against: formally charge. Pronounced “in-DITE”.","Indict: the grand jury names you as accused."],"s":[]},{"w":"indigenous","p":"adj.","m":"Native to a particular place.","e":"Late Latin <i>indigenus</i>, from <i>indigena</i> (native): <i>indu</i> (within) + <i>gignere</i> (to beget).","f":"indigène, autochtone","t":"Born within: « autochtone ».","h":["Indu + genus: born within. Indigenous plants.","Indigenous people: first inhabitants."],"s":["endemic","rampant"]},{"w":"indignant","p":"adj.","m":"Angry at perceived unfairness.","e":"Latin <i>indignari</i> (to consider unworthy): <i>in-</i> + <i>dignus</i> (worthy).","f":"indigné","t":"Same as « indigné »: « Indignez-vous ! »","h":["In + dignus: affronted dignity. Indignant at the insult.","Indignant: “How dare you!”"],"s":[]},{"w":"inflammatory","p":"adj.","m":"Arousing angry or violent feelings.","e":"Latin <i>inflammare</i> (to set on fire), from <i>flamma</i>.","f":"incendiaire, provocateur","t":"Words that set the room on fire: « des propos incendiaires ».","h":["Flamma: flame. Inflammatory speech sets crowds ablaze.","Inflammatory tweet: pours petrol on a debate."],"s":["incendiary","provocative"]},{"w":"insolvent","p":"adj.","m":"Unable to pay debts.","e":"<i>in-</i> + Latin <i>solvere</i> (to loosen, pay).","f":"insolvable","t":"Not solvable: « insolvable ».","h":["In + solvere: can’t pay. An insolvent company goes bust.","Insolvent: the bank account hits zero."],"s":[]},{"w":"inundate","p":"v.","m":"To overwhelm, flood.","e":"Latin <i>inundare</i>: <i>in</i> + <i>unda</i> (wave).","f":"inonder, submerger","t":"Unda = onde: « inonder ». Inundated with emails.","h":["Unda: wave. Inundated with calls: a flood.","Inundate: a tsunami of emails."],"s":["besiege"]},{"w":"macabre","p":"adj.","m":"Disturbing because concerned with death.","e":"French <i>macabre</i>, from <i>Danse Macabre</i> (Dance of Death, 15th c.), perhaps after the Maccabees.","f":"macabre","t":"La Danse macabre: skeletons dancing. Same as French.","h":["Danse macabre: skeletons dancing. Gruesome.","Macabre humour: jokes about corpses."],"s":[]},{"w":"mesmerize","p":"v.","m":"To hold someone’s attention completely.","e":"From Franz Anton Mesmer (1734–1815), a German doctor whose “animal magnetism” sessions were the rage in Paris.","f":"hypnotiser, fasciner","t":"Picture Mesmer’s Parisian salons, patients entranced around his tub.","h":["Franz Mesmer, hypnotist in Paris, 1780s. The magician mesmerized the crowd.","Mesmerized by the flames of the fire: can’t look away."],"s":["beguile","enchant","enthrall","subjugate"]},{"w":"miser","p":"n.","m":"A person who hoards wealth and spends little.","e":"Latin <i>miser</i> (wretched, unhappy).","f":"avare, grippe-sou","t":"Latin miser = « misérable »: the wretched hoarder (Harpagon, Scrooge).","h":["Miser: wretched. A miser counts gold at night.","Scrooge: the miser who hates Christmas."],"s":[]},{"w":"peruse","p":"v.","m":"To read carefully (often misused as “skim”).","e":"Probably <i>per-</i> (thoroughly) + <i>use</i>: to use up completely.","f":"lire attentivement, examiner","t":"Per + use = use thoroughly. On the GRE: careful reading.","h":["Per + use: use thoroughly. Peruse the contract before signing.","Peruse: read slowly and carefully."],"s":[]},{"w":"pine","p":"v.","m":"To long for; to waste away from grief.","e":"Old English <i>pīnian</i> (to torment), from Latin <i>poena</i> (punishment).","f":"languir, se languir de","x":"2nd meaning","t":"Poena = peine: pining for a lost love.","h":["Pine: to ache for. Pining for a lost love.","Pine also a tree: but as a verb, to long for: “pining for the fjords”."],"s":["flag","languish"]},{"w":"pinnacle","p":"n.","m":"The highest point.","e":"Old French <i>pinacle</i>, from Late Latin <i>pinnaculum</i> (peak, turret), from <i>pinna</i> (feather, point).","f":"pinacle, sommet","t":"« Porter au pinacle »: the turret at the very top.","h":["Pinna: feather/wing: top turret. The pinnacle of success.","Pinnacle: a spire on a cathedral."],"s":["acme","apex","apogee","apotheosis","summit","zenith"]},{"w":"profuse","p":"adj.","m":"Plentiful, abundant.","e":"Latin <i>profusus</i>, from <i>profundere</i> (to pour out).","f":"abondant, profus","t":"Pouring forth: profuse apologies.","h":["Pro + fundere: pour forth. Profuse apologies.","Profuse sweating: gushing."],"s":["copious","demonstrative","effusive","expansive","extravagant","lavish","munificent"]},{"w":"remiss","p":"adj.","m":"Negligent in one’s duty.","e":"Latin <i>remissus</i> (slack), from <i>remittere</i> (to send back, relax).","f":"négligent","t":"Slackened off: it would be remiss of me not to thank…","h":["Re + mittere: let go. Remiss = careless about duty.","Remiss: you forgot to lock the door."],"s":["derelict","lax","negligent"]},{"w":"reprobate","p":"n.","m":"An unprincipled person.","e":"Late Latin <i>reprobatus</i> (rejected), from <i>reprobare</i> (to disapprove).","f":"dépravé, vaurien, réprouvé","t":"« Les réprouvés »: those rejected by God.","h":["Reprobare: reject. A drunken reprobate.","Reprobate: the family’s black sheep."],"s":["libertine","miscreant","profligate"]},{"w":"retiring","p":"adj.","m":"Shy, tending to avoid company.","e":"From retire, French <i>retirer</i> (to withdraw).","f":"réservé, effacé","x":"2nd meaning","t":"Someone who withdraws (« se retire ») from the crowd.","h":["Retire: withdraw. A retiring personality prefers the corner.","Retiring: shy, never speaks at parties."],"s":["coy","demure","diffident","modest","reticent","self-effacing","taciturn"]},{"w":"screed","p":"n.","m":"A long, tedious, usually angry piece of writing.","e":"Old English <i>scrēade</i> (a shred, strip). A long strip of parchment.","f":"diatribe, long pamphlet","t":"A long shred of paper full of ranting.","h":["Screed: long strip. A screed of angry email.","Screed: a rant that goes on for pages."],"s":["broadside","diatribe","harangue","tirade"]},{"w":"serendipity","p":"n.","m":"Finding good things by chance.","e":"Coined by Horace Walpole in 1754 from the Persian tale <i>The Three Princes of Serendip</i> (Sri Lanka), who kept making lucky discoveries.","f":"sérendipité, heureux hasard","t":"The princes of Serendip finding treasures by accident. Fleming’s penicillin.","h":["Walpole’s Serendip: lucky discoveries. Penicillin.","Serendipity: finding £20 in an old coat."],"s":[]},{"w":"slapdash","p":"adj.","m":"Done hurriedly and carelessly.","e":"English <i>slap</i> + <i>dash</i>, both suggesting quick, careless action.","f":"bâclé","t":"Slap it on, dash off: « travail bâclé ».","h":["Slap + dash: done quickly. A slapdash paint job.","Slapdash essay: written in ten minutes."],"s":["cursory","desultory","haphazard","indiscriminate","perfunctory","superficial"]},{"w":"spendthrift","p":"n.","m":"A person who spends money wastefully.","e":"<i>spend</i> + <i>thrift</i> (savings, prosperity, from Old Norse <i>þrift</i>). Someone who spends the savings.","f":"dépensier, panier percé","t":"Spends the thrift (the savings).","h":["Spends thrift (savings). A spendthrift blows his paycheque.","Spendthrift: shopping addict."],"s":["extravagant","improvident","imprudent","lavish","prodigal","profligate"]},{"w":"stipend","p":"n.","m":"A fixed regular allowance or salary.","e":"Latin <i>stipendium</i> (soldier’s pay): <i>stips</i> (coin) + <i>pendere</i> (to weigh out).","f":"allocation, traitement","t":"Coins weighed out for a soldier. PhD stipend.","h":["Stips + pendere: weigh coins. A grad stipend.","Stipend: a small regular payment."],"s":["remuneration"]},{"w":"summit","p":"n.","m":"The highest point; a meeting of leaders.","e":"Old French <i>somete</i>, diminutive of <i>som</i>, from Latin <i>summum</i> (highest).","f":"sommet","t":"« Sommet » and « sommet du G7 ».","h":["Summus: highest. The summit of Mont Blanc; G7 summit.","Summit = top of the mountain, or top-level meeting."],"s":["acme","apex","apogee","apotheosis","pinnacle","zenith"]},{"w":"telling","p":"adj.","m":"Revealing; having a striking effect.","e":"From <i>tell</i>, Old English <i>tellan</i> (to count, relate). Germanic.","f":"révélateur, significatif","x":"2nd meaning","t":"It tells you something. A telling silence.","h":["Telling: it tells you something. A telling detail.","Telling silence: says more than words."],"s":["cogent","compelling","eloquent","incisive","telltale","trenchant"]},{"w":"telltale","p":"adj.","m":"Revealing something hidden.","e":"<i>tell</i> + <i>tale</i>: originally a tattletale who tells tales.","f":"révélateur, qui trahit","t":"Telltale signs = « signes révélateurs ».","h":["Tell-tale: tells on you. Telltale crumbs on his shirt.","Telltale signs of lying: a twitch."],"s":["telling"]},{"w":"tender","p":"v. / n.","m":"To offer formally (tender a resignation); money offered.","e":"Old French <i>tendre</i> (to offer, stretch out), from Latin <i>tendere</i>.","f":"offrir, présenter; soumission","x":"2nd meaning","t":"« Tendre la main »: you stretch out an offer. Legal tender, a public tender (appel d’offres).","h":["Tendere: stretch out. Tender your resignation: hand it over.","Tender: a formal bid for a contract."],"s":[]},{"w":"thoroughgoing","p":"adj.","m":"Complete, thorough.","e":"<i>thorough</i> (Old English <i>þuruh</i>, through) + <i>going</i>. Going all the way through.","f":"complet, total, minutieux","t":"Going thoroughly through everything.","h":["Thorough + going: leaving nothing out. A thoroughgoing reform.","Thoroughgoing: from top to bottom."],"s":["all-ecompassing","arrant","exhaustive","thorough"]},{"w":"thrifty","p":"adj.","m":"Careful with money.","e":"From <i>thrift</i>, Old Norse <i>þrift</i> (prosperity), from <i>thrive</i>.","f":"économe","t":"Thrifty people thrive. A thrift shop sells cheap second-hand goods.","h":["Thrift: to thrive by saving. Thrifty shoppers.","Thrifty: coupons and second-hand shops."],"s":["abstemious","canny","economical","frugal","parsimonious","provident","prudent"]},{"w":"tirade","p":"n.","m":"A long angry speech of criticism.","e":"French <i>tirade</i>, from Italian <i>tirata</i> (a pull, volley), from <i>tirare</i> (to pull).","f":"tirade, diatribe","t":"Same as « tirade » (Cyrano’s famous nose tirade).","h":["Tirer: pull out lines. Cyrano’s tirade: a long speech.","Tirade: a coach yelling at the team."],"s":["broadside","diatribe","harangue","invective","polemic","screed","vitriol"]},{"w":"underwrite","p":"v.","m":"To guarantee financially; to support.","e":"<i>under</i> + <i>write</i>: insurers wrote their names under the risk on Lloyd’s policies.","f":"garantir, souscrire, financer","t":"Signing your name under a policy to cover it. Banks underwrite an IPO.","h":["Write your name under the risk: you guarantee it. Banks underwrite the share offering.","Underwrite: back a project with money."],"s":["sanction"]},{"w":"unnerve","p":"v.","m":"To make someone lose courage or confidence.","e":"<i>un-</i> + nerve (strength, courage), from Latin <i>nervus</i> (sinew).","f":"déstabiliser, démonter","t":"Remove the nerve (courage): his stare unnerved me.","h":["Un + nerve: remove courage. The long silence unnerved him.","Unnerve: stage fright."],"s":["enervate"]},{"w":"variance","p":"n.","m":"Disagreement; the amount of difference.","e":"Latin <i>variantia</i>, from <i>variare</i> (to change).","f":"désaccord, écart","t":"At variance with = « en désaccord avec ». Also statistical variance.","h":["Vary: difference. At variance with the facts.","Variance: how much the numbers differ."],"s":["discord","discrepancy","dissent"]},{"w":"vindictive","p":"adj.","m":"Having a strong desire for revenge.","e":"From Latin <i>vindicta</i> (vengeance), from <i>vindicare</i>.","f":"vindicatif, rancunier","t":"Same as « vindicatif ».","h":["Vindicta: revenge. A vindictive ex.","Vindictive: keeps score of every insult."],"s":["baleful","malevolent","malign"]},{"w":"voracious","p":"adj.","m":"Wanting great quantities; insatiable.","e":"Latin <i>vorax</i>, from <i>vorare</i> (to devour).","f":"vorace","t":"« Dévorer »: a voracious reader.","h":["Vorare: devour. A voracious reader devours novels.","Voracious appetite: eats everything."],"s":["avaricious","rapacious","ravenous"]},{"w":"zenith","p":"n.","m":"The highest point; peak.","e":"Arabic <i>samt ar-ra’s</i> (path over the head), misread by medieval scribes as <i>cenit</i>.","f":"zénith, apogée","t":"Same as « zénith »: the sun right over your head.","h":["Zenith: the point directly overhead. The sun at its zenith.","Zenith of her fame: peak."],"s":["acme","apex","apogee","apotheosis","heyday","pinnacle","prime","summit"]}]},{"name":"Basic II","slug":"basic-ii","series":"Basic","words":[{"w":"aboveboard","p":"adj.","m":"Legitimate, honest, open.","e":"Card players’ term: keeping your hands above the board (table) so you can’t cheat.","f":"régulier, honnête, transparent","t":"Hands above the card table: no cheating underneath.","h":["Above the board: hands visible over the table, no cheating. An aboveboard deal.","Aboveboard: nothing hidden under the table."],"s":["candid","forthright","frank"]},{"w":"amok","p":"adv.","m":"Behaving uncontrollably and disruptively (run amok).","e":"Malay <i>amuk</i> (attacking in a frenzy).","f":"en folie, de manière incontrôlée","t":"« Être pris d’amok »: a frenzied, uncontrolled rampage.","h":["Malay amuk: a frenzy. Run amok = rampage.","The bull ran amok in the shop."],"s":[]},{"w":"animosity","p":"n.","m":"Strong hostility.","e":"Latin <i>animositas</i> (boldness, spirit), from <i>animus</i> (spirit, passion).","f":"animosité","t":"Same as « animosité ».","h":["Animus: spirit/anger. Open animosity between two families.","Animosity: hostility that simmers."],"s":["animus","antipathy","enmity"]},{"w":"apex","p":"n.","m":"The top or highest point.","e":"Latin <i>apex</i> (summit, tip).","f":"sommet, apogée","t":"Apex predator = top of the food chain.","h":["Apex: the tip. Apex predator, apex of the triangle.","Apex = peak: at the top of the pyramid."],"s":["acme","apogee","apotheosis","pinnacle","summit","zenith"]},{"w":"avarice","p":"n.","m":"Extreme greed for wealth.","e":"Latin <i>avaritia</i>, from <i>avarus</i> (greedy).","f":"avarice, cupidité","t":"Same as « avarice »: L’Avare.","h":["Avidus: greedy. Avarice drives the miser.","Avarice: hoarding gold, never spending."],"s":["cupidity"]},{"w":"badger","p":"v.","m":"To pester repeatedly.","e":"From the animal; badger-baiting set dogs to harass a badger in its burrow.","f":"harceler, importuner","x":"2nd meaning","t":"Dogs pestering a badger in its hole: badgering your manager for an answer.","h":["Badger baiting: dogs pester it. Badger the boss for a raise.","Badger = nag, again and again."],"s":["beg","browbeat","dog","hector","hound","importune"]},{"w":"beatific","p":"adj.","m":"Blissfully happy.","e":"Latin <i>beatificus</i>: <i>beatus</i> (blessed) + <i>facere</i>.","f":"béat, radieux","t":"« Un sourire béat »: blessed (béatitude).","h":["Beatus: blessed. A beatific smile like a saint in glory.","Beatific: serene joy, halo above."],"s":["elated","euphoric"]},{"w":"becoming","p":"adj.","m":"Attractive or suitable; fitting.","e":"From <i>become</i> in the sense “to suit” (Old English <i>becuman</i>).","f":"seyant, convenable","x":"2nd meaning","t":"A dress that becomes you = « qui te va bien ».","h":["Becoming: it suits you. A becoming hat.","Becoming ≠ turning into: here it means flattering."],"s":["decorous","demure","genteel","staid"]},{"w":"bellicose","p":"adj.","m":"Eager to fight; warlike.","e":"Latin <i>bellicosus</i>, from <i>bellum</i> (war).","f":"belliqueux","t":"Bellum = war: « belliqueux ».","h":["Bellum: war. A bellicose speech calls for battle.","Bellicose dictator rattling his sabre."],"s":["belligerent","contentious","martial","pugnacious","truculent"]},{"w":"cadaverous","p":"adj.","m":"Very pale, thin or bony, like a corpse.","e":"Latin <i>cadaver</i> (corpse), from <i>cadere</i> (to fall).","f":"cadavérique","t":"Same as « cadavérique ».","h":["Cadaver: corpse. Cadaverous face: hollow and pale.","Cadaverous: skeleton thin."],"s":["pallid"]},{"w":"cardinal","p":"adj.","m":"Of the greatest importance; fundamental.","e":"Latin <i>cardinalis</i>, from <i>cardo</i> (hinge). The point on which everything turns.","f":"cardinal, capital","t":"The hinge everything turns on: cardinal sins, cardinal points.","h":["Cardo: hinge. Cardinal rules are the hinges.","Cardinal virtues: the main four."],"s":["prime"]},{"w":"catalyst","p":"n.","m":"Something that causes or speeds up a change.","e":"Greek <i>katalysis</i> (dissolution): <i>kata</i> (down) + <i>lyein</i> (to loosen).","f":"catalyseur","t":"Same as « catalyseur ».","h":["Catalysis: speeds up reactions. The scandal was a catalyst for reform.","Catalyst: the spark that makes it happen."],"s":[]},{"w":"chauvinist","p":"n.","m":"A person with excessive or prejudiced loyalty to their group.","e":"French <i>chauvin</i>, after Nicolas Chauvin, a probably legendary, fanatically loyal Napoleonic soldier.","f":"chauvin","t":"Nicolas Chauvin and his blind patriotism. Male chauvinist = « macho ».","h":["Chauvin: naïve veteran. A chauvinist thinks his group is the best.","Male chauvinist: sexist."],"s":["jingoist"]},{"w":"check","p":"v. / n.","m":"To restrain or stop; a restraint.","e":"Old French <i>eschec</i> (check in chess), from Persian <i>shāh</i> (king). The king is stopped.","f":"freiner, enrayer","x":"2nd meaning","t":"Échec au roi! Checks and balances = « contre-pouvoirs ».","h":["Check (chess): stop the king. Check inflation: restrain it.","Checks and balances: limits."],"s":["balk","bridle","circumvent","constraint","curb","curtail","deterrent","foil","frustrate","impediment","inhibit","stanch","staunch","stem","stymie","suppress","thwart"]},{"w":"checkered","p":"adj.","m":"Marked by changes of fortune, often including bad episodes.","e":"From the chessboard pattern (Old French <i>eschequier</i>, chessboard).","f":"mouvementé, en dents de scie","t":"A chessboard of black and white squares: a checkered past.","h":["Checkerboard: black and white squares. A checkered past: good and bad.","Checkered career: ups and downs."],"s":[]},{"w":"cogent","p":"adj.","m":"Clear, logical and convincing.","e":"Latin <i>cogentem</i>, from <i>cogere</i> (to compel, drive together).","f":"convaincant, irréfutable","t":"An argument that compels you (cogere). Une raison cogente is rare in French.","h":["Cogere: to drive together. A cogent argument forces agreement.","Cogent: compelling logic."],"s":["articulate","coherent","compelling","eloquent","incisive","intelligible","lucid","telling","trenchant"]},{"w":"contrite","p":"adj.","m":"Feeling remorse.","e":"Latin <i>contritus</i> (crushed), from <i>conterere</i> (to grind).","f":"contrit, repentant","t":"Same as « contrit ».","h":["Contritus: crushed. A contrite child says sorry.","Contrite: eyes down, sincere apology."],"s":[]},{"w":"corroborate","p":"v.","m":"To confirm or give support to.","e":"Latin <i>corroborare</i> (to strengthen): <i>com-</i> + <i>robur</i> (strength, oak).","f":"corroborer","t":"Same as « corroborer »: strong as oak.","h":["Cor + roborare: strengthen. Corroborate the story with evidence.","Corroborate: a second witness confirms."],"s":["substantiate"]},{"w":"desecrate","p":"v.","m":"To violate something sacred.","e":"<i>de-</i> + (con)secrate, Latin <i>sacrare</i> (to make holy).","f":"profaner","t":"Un-sacred: « profaner une tombe ».","h":["De + sacrare: unsacred. Desecrate a grave.","Desecrate: vandalise a church."],"s":[]},{"w":"disparate","p":"adj.","m":"Essentially different; not comparable.","e":"Latin <i>disparatus</i> (separated): <i>dis-</i> + <i>parare</i> (to prepare).","f":"disparate","t":"Same as « disparate ».","h":["Dis + par: not equal. Disparate groups with nothing in common.","Disparate = apples and oranges."],"s":["divergent","heterogeneous"]},{"w":"errant","p":"adj.","m":"Straying from the proper course; wandering.","e":"Old French <i>errant</i> (travelling), from <i>errer</i>; also Latin <i>errare</i>.","f":"errant, égaré","t":"A knight-errant wanders; an errant child strays.","h":["Errare: wander. A knight errant roams.","Errant husband: strays."],"s":["fallible"]},{"w":"exhort","p":"v.","m":"To strongly urge or encourage.","e":"Latin <i>exhortari</i>: <i>ex-</i> + <i>hortari</i> (to encourage).","f":"exhorter","t":"Same as « exhorter ».","h":["Ex + hortari: urge. The coach exhorted the team.","Exhort: a rousing speech to act."],"s":["goad","incite"]},{"w":"extenuating","p":"adj.","m":"Making a fault seem less serious.","e":"Latin <i>extenuare</i> (to make thin): <i>ex-</i> + <i>tenuis</i> (thin).","f":"atténuant","t":"Circonstances atténuantes = extenuating circumstances: thinning the guilt.","h":["Extenuare: make thin. Extenuating circumstances reduce blame.","Extenuating: the reasons that soften the verdict."],"s":[]},{"w":"ferret","p":"v.","m":"To search persistently (ferret out).","e":"From the animal, Old French <i>furet</i>, used to hunt rabbits out of burrows.","f":"dénicher, fureter","t":"« Fureter » like un furet: ferreting out the truth.","h":["Ferret hunts rabbits in burrows. Ferret out the truth.","Ferreting through files for the clue."],"s":[]},{"w":"fleece","p":"v.","m":"To swindle or overcharge.","e":"Old English <i>flēos</i> (sheep’s wool). To shear someone of their money.","f":"escroquer, plumer","x":"2nd meaning","t":"Shearing a sheep: « se faire plumer / tondre ».","h":["Fleece: sheep’s wool, sheared. Fleece the tourists: charge too much.","Fleece = to rob."],"s":["bilk","hoodwink","mulct","swindle"]},{"w":"flush","p":"adj.","m":"Having plenty of money; also level with.","e":"Of uncertain origin; “flush with money” from the idea of being full to overflowing.","f":"en fonds; à fleur de, de niveau","x":"2nd meaning","t":"A river in flood is flush: flush with cash.","h":["Flush with cash: wealthy; flush with the wall: level.","Flush: a cheque that just landed."],"s":["affluent"]},{"w":"heyday","p":"n.","m":"The period of greatest success.","e":"From an old exclamation of joy, <i>hey-day!</i> (16th c.).","f":"âge d’or, apogée","t":"Shouting « hey! » in your best years.","h":["Heyday: hey! the best days. The heyday of jazz.","Heyday: the golden age."],"s":["acme","prime","zenith"]},{"w":"hodgepodge","p":"n.","m":"A confused mixture.","e":"From <i>hotchpotch</i>, French <i>hochepot</i>, a stew of mixed ingredients.","f":"méli-mélo, fourre-tout","t":"Hochepot, a Flemish stew: everything thrown in.","h":["Hochepot: stew. A hodgepodge of styles.","Hodgepodge: a jumble in the attic."],"s":["amalgam","pastiche","welter"]},{"w":"immaterial","p":"adj.","m":"Unimportant, irrelevant.","e":"Late Latin <i>immaterialis</i>: <i>in-</i> + <i>materia</i> (matter).","f":"sans importance, négligeable","x":"2nd meaning","t":"It doesn’t matter: that’s immaterial.","h":["Im + material: doesn’t matter. Irrelevant to the case.","Immaterial: not important."],"s":["extraneous","impertinent","inconsequential","negligible","paltry","picayune","redundant","superfluous","tangential","trifling","trivial"]},{"w":"imponderable","p":"n. / adj.","m":"A factor difficult or impossible to assess.","e":"<i>in-</i> + Latin <i>ponderare</i> (to weigh), from <i>pondus</i> (weight).","f":"impondérable","t":"« Les impondérables »: what can’t be weighed.","h":["Can’t be pondered/weighed. The imponderables of the market.","Imponderable: unpredictable factors."],"s":[]},{"w":"junta","p":"n.","m":"A military group ruling after seizing power.","e":"Spanish <i>junta</i> (council), from Latin <i>iuncta</i> (joined).","f":"junte","t":"« La junte militaire ».","h":["Junta: junction. A military junta rules after the coup.","Junta: generals in sunglasses."],"s":[]},{"w":"lassitude","p":"n.","m":"Physical or mental weariness.","e":"Latin <i>lassitudo</i>, from <i>lassus</i> (weary).","f":"lassitude","t":"Same as « lassitude »: las.","h":["Lassus: tired. Lassitude after the exam.","Lassitude: no energy at all."],"s":["ennui","torpor"]},{"w":"melee","p":"n.","m":"A confused fight or crowd.","e":"French <i>mêlée</i> (mixed fight), from <i>mêler</i> (to mix).","f":"mêlée","t":"Straight from « mêlée », even in rugby.","h":["Mêlée: scrum. A melee at the sale.","Melee: confused brawl."],"s":[]},{"w":"misanthrope","p":"n.","m":"A person who dislikes humankind.","e":"Greek <i>misanthrōpos</i>: <i>misein</i> (to hate) + <i>anthrōpos</i> (man).","f":"misanthrope","t":"Molière’s « Le Misanthrope », Alceste.","h":["Misein + anthropos: hater of people. Molière’s Alceste.","Misanthrope: avoids parties."],"s":["curmudgeon"]},{"w":"moment","p":"n.","m":"Importance (of great moment).","e":"Latin <i>momentum</i> (movement, weight), from <i>movere</i>. A weight that tips the scale.","f":"importance","x":"2nd meaning","t":"Momentum tips the balance: a decision of great moment.","h":["Moment: importance. A matter of great moment.","Moment = weight, not time."],"s":[]},{"w":"paucity","p":"n.","m":"Scarcity; small quantity.","e":"Latin <i>paucitas</i>, from <i>paucus</i> (few).","f":"rareté, pénurie","t":"Paucus = few (peu).","h":["Paucus: few. A paucity of evidence.","Paucity: scarcely any."],"s":["dearth"]},{"w":"pittance","p":"n.","m":"A very small or inadequate amount of money.","e":"Old French <i>pitance</i> (a monk’s ration given out of piety), from <i>pitié</i>.","f":"pitance, misère","t":"« Une maigre pitance ».","h":["Pietas: pity: a charity dole. Paid a pittance.","Pittance: crumbs."],"s":[]},{"w":"preemptive","p":"adj.","m":"Taken to prevent an anticipated event.","e":"Latin <i>prae</i> (before) + <i>emere</i> (to buy). First “buying before others”.","f":"préventif","t":"A preemptive strike: acting before the other side does.","h":["Pre + emere: buy first. A preemptive strike.","Preemptive: act before the other does."],"s":[]},{"w":"pugnacious","p":"adj.","m":"Eager to argue or fight.","e":"Latin <i>pugnax</i>, from <i>pugnare</i> (to fight), <i>pugnus</i> (fist).","f":"pugnace, agressif","t":"Pugnus = poing: « pugnace ».","h":["Pugnus: fist. A pugnacious boxer.","Pugnacious: spoiling for a fight."],"s":["bellicose","belligerent","contentious","truculent"]},{"w":"raft","p":"n.","m":"A large number or amount.","e":"Probably from <i>raff</i> (heap, rubbish), influenced by raft (a floating mass of logs).","f":"tas, flopée","x":"2nd meaning","t":"A raft of logs floating together: a raft of new rules.","h":["Raft: a large collection. A raft of reforms.","Raft = lots, floating together."],"s":["myriad"]},{"w":"replete","p":"adj.","m":"Filled or well supplied.","e":"Latin <i>repletus</i>, from <i>replere</i> (to fill again).","f":"rempli, repu","t":"« Repu » after a feast: replete with.","h":["Re + plere: fill. Replete with detail.","Replete after a feast."],"s":["fraught"]},{"w":"sanctimonious","p":"adj.","m":"Making a show of moral superiority.","e":"Latin <i>sanctimonia</i> (holiness), from <i>sanctus</i>.","f":"moralisateur, bigot","t":"Fake saintliness: « des airs de sainte nitouche ».","h":["Sanctimonia: holiness. A sanctimonious preacher.","Sanctimonious: holier than thou."],"s":["didactic","pedantic","pious","sententious","smug"]},{"w":"sanguine","p":"adj.","m":"Optimistic, especially in a difficult situation.","e":"Latin <i>sanguineus</i> (bloody). In humour theory, blood made people cheerful.","f":"optimiste (≠ sanguinaire)","x":"Faux ami","t":"Ruddy-cheeked and cheerful: a sanguine temperament. Not bloodthirsty.","h":["Sanguis: blood: red-cheeked, optimistic.","Sanguine about the outcome: hopeful."],"s":["buoyant","ebullient"]},{"w":"scintillating","p":"adj.","m":"Brilliantly clever or lively.","e":"Latin <i>scintillare</i> (to sparkle), from <i>scintilla</i> (spark).","f":"brillant, pétillant","t":"« Scintillant »: sparkling conversation.","h":["Scintilla: spark. Scintillating wit.","Scintillating: sparkling conversation."],"s":["effervescent","vivacious"]},{"w":"start","p":"v.","m":"To jump in surprise.","e":"Old English <i>styrtan</i> (to leap up). The jump came before the begin sense.","f":"sursauter","x":"2nd meaning","t":"To wake with a start = « se réveiller en sursaut ».","h":["Start: jump. She started at the noise.","Start: a sudden jump."],"s":["commence"]},{"w":"stem","p":"v.","m":"To stop or restrict a flow.","e":"Old Norse <i>stemma</i> (to stop, dam).","f":"endiguer, enrayer","x":"2nd meaning","t":"Stem the bleeding, stem the tide: « endiguer ».","h":["Stem the flow: dam it. Stem the bleeding.","Stem: stop the tide."],"s":["check","curb","inhibit","stanch","staunch"]},{"w":"unconscionable","p":"adj.","m":"Not right or reasonable; shockingly unfair.","e":"<i>un-</i> + conscionable, from conscience.","f":"inadmissible, déraisonnable","t":"Something no conscience could accept.","h":["Un + conscience: shameless. Unconscionable prices.","Unconscionable: beyond what conscience allows."],"s":["exorbitant","unscrupulous"]},{"w":"vicarious","p":"adj.","m":"Experienced through another person.","e":"Latin <i>vicarius</i> (substitute), from <i>vicis</i> (change, turn), as in vicar and vice-president.","f":"par procuration","t":"Living through your kids = « vivre par procuration ».","h":["Vicarius: substitute. Vicarious thrill reading adventures.","Vicarious: enjoying through others."],"s":["surrogate"]},{"w":"virago","p":"n.","m":"A domineering, violent or bad-tempered woman.","e":"Latin <i>virago</i> (man-like woman, heroine), from <i>vir</i> (man).","f":"virago, mégère","t":"Same as « virago ».","h":["Vir: man: a mannish loud woman. A virago shouted at the waiter.","Virago: domineering and angry."],"s":[]},{"w":"wax","p":"v.","m":"To grow larger (wax and wane); to speak in a certain way.","e":"Old English <i>weaxan</i> (to grow), Germanic (German <i>wachsen</i>).","f":"croître; devenir","x":"2nd meaning","t":"The moon waxes and wanes: grows and shrinks. Wax lyrical = devenir lyrique.","h":["Wax: grow. The moon waxes. Wax lyrical.","Wax and wane: grow and shrink."],"s":[]}]},{"name":"Basic III","slug":"basic-iii","series":"Basic","words":[{"w":"advocate","p":"v. / n.","m":"To publicly support; a supporter.","e":"Latin <i>advocatus</i> (one called to help), from <i>ad</i> + <i>vocare</i> (to call).","f":"préconiser, défendre; avocat, partisan","t":"Called (vocare) to defend: like « un avocat ». To advocate = prôner.","h":["Ad + vocare: call to defend. An advocate speaks for the cause.","Advocate sounds like avocat: both speak for you."],"s":["apologist","champion","espouse","proponent"]},{"w":"appreciable","p":"adj.","m":"Large enough to be noticed.","e":"French <i>appréciable</i>, from Late Latin <i>appretiare</i> (to set a price on), <i>pretium</i> (price).","f":"appréciable, notable","t":"Same as « appréciable »: big enough to put a price on.","h":["Appreciate: measure the value. An appreciable gain: big enough to notice.","Appreciable: you can see the difference."],"s":["discernible"]},{"w":"apprehension","p":"n.","m":"Anxiety about the future; also understanding or arrest.","e":"Latin <i>apprehendere</i> (to seize): <i>ad</i> + <i>prehendere</i> (to grasp).","f":"appréhension","t":"Same as « appréhension »: fear seizes you.","h":["Apprehendre: to seize. Apprehension: fear grips you before the exam.","Apprehension also = arrest: seized by police."],"s":[]},{"w":"archaic","p":"adj.","m":"Very old or old-fashioned.","e":"Greek <i>arkhaikos</i>, from <i>arkhaios</i> (ancient), <i>arkhē</i> (beginning).","f":"archaïque","t":"Same as « archaïque »: archaeology.","h":["Arche: beginning. An archaic word is from the beginning of time.","Archaic: dusty, from the Stone Age."],"s":["anachronistic","antiquated","hoary","obsolete"]},{"w":"ascendancy","p":"n.","m":"Occupation of a position of dominant power.","e":"From ascendant, Latin <i>ascendere</i> (to climb up): <i>ad</i> + <i>scandere</i>.","f":"ascendant, suprématie","t":"« Avoir de l’ascendant sur »: having climbed above.","h":["Ascendere: climb. Rise to ascendancy: top position.","Ascendancy: having the upper hand."],"s":["hegemony","primacy"]},{"w":"autonomously","p":"adv.","m":"Independently; self-governing.","e":"Greek <i>autonomos</i>: <i>autos</i> (self) + <i>nomos</i> (law).","f":"de façon autonome","t":"Auto + nomos = making your own law.","h":["Auto + nomos: self-law. A robot working autonomously.","Autonomously: without anyone’s help."],"s":[]},{"w":"avid","p":"adj.","m":"Very eager, enthusiastic.","e":"Latin <i>avidus</i> (longing, greedy), from <i>avere</i> (to crave).","f":"avide, passionné","t":"« Avide »: an avid reader devours books.","h":["Avidus: eager. An avid reader.","Avid: hungry for more."],"s":["ardent","astute","fervent","fervid","incisive","keen","penetrating","shrewd","zealous"]},{"w":"boon","p":"n.","m":"A blessing; something helpful.","e":"Old Norse <i>bón</i> (prayer, request). A favour granted in answer to a prayer.","f":"aubaine, bienfait","t":"A prayer answered: remote work was a boon for her.","h":["Bon: good. A boon for the economy.","Boon: a lucky blessing."],"s":[]},{"w":"consummate","p":"adj. / v.","m":"Showing great skill; to complete perfectly.","e":"Latin <i>consummare</i> (to sum up, complete), from <i>summa</i> (total).","f":"accompli, parfait; consommer","t":"Summed up to perfection: a consummate professional.","h":["Consummare: complete. A consummate liar: perfect at it.","Consummate: the master at his craft."],"s":["virtuoso"]},{"w":"dearth","p":"n.","m":"A scarcity or lack.","e":"Middle English <i>derthe</i>, from <i>dear</i> (costly): when things are scarce, they are dear.","f":"pénurie, manque","t":"Dear + th: scarce things become dear.","h":["Dear = costly; dearth: scarcity raises prices. A dearth of talent.","Dearth: empty shelves."],"s":["paucity"]},{"w":"degrade","p":"v.","m":"To treat with disrespect; to break down.","e":"Late Latin <i>degradare</i> (to lower in rank): <i>de</i> + <i>gradus</i> (step).","f":"dégrader, avilir","t":"Same as « dégrader »: step down.","h":["De + gradus: step down. Plastic degrades slowly.","Degrade: lower in rank."],"s":["adulterate","belittle","debase","demean","vitiate"]},{"w":"deter","p":"v.","m":"To discourage from acting.","e":"Latin <i>deterrere</i>: <i>de</i> (away) + <i>terrere</i> (to frighten).","f":"dissuader","t":"Frighten away: terror.","h":["De + terrere: scare off. High fines deter speeding.","Deter: the scarecrow."],"s":["forestall","hinder","inhibit"]},{"w":"discriminate","p":"v.","m":"To distinguish; also to treat unfairly.","e":"Latin <i>discriminare</i> (to divide), from <i>discernere</i> (to separate).","f":"discriminer, distinguer","t":"On the GRE, discriminating often = discerning taste.","h":["Discernere: tell apart. A discriminating palate.","Discriminate: distinguish between."],"s":["differentiate","discern"]},{"w":"disenfranchise","p":"v.","m":"To deprive of a right, especially voting.","e":"<i>dis-</i> + enfranchise, from Old French <i>franc</i> (free).","f":"priver du droit de vote, marginaliser","t":"Franc = free: taking away a citizen’s franchise.","h":["Dis + franchise: strip the vote. Laws disenfranchised citizens.","Disenfranchise: taking away rights."],"s":["marginalize","ostracize","relegate"]},{"w":"disheartened","p":"adj.","m":"Having lost determination or confidence.","e":"<i>dis-</i> + <i>hearten</i>, from Old English <i>heorte</i> (heart).","f":"découragé","t":"The heart taken out: « découragé » (cœur).","h":["Dis + heart: lose heart. Disheartened by failure.","Disheartened: spirit drained."],"s":["crestfallen","glum"]},{"w":"elusive","p":"adj.","m":"Difficult to find, catch or remember.","e":"Latin <i>eludere</i> (to escape, mock): <i>e-</i> + <i>ludere</i> (to play).","f":"insaisissable","t":"It plays (ludere) its way out of your grasp: « éluder ».","h":["E + ludere: slip away in play. An elusive fugitive.","Elusive: hard to pin down, like a fish."],"s":["equivocal","evasive","subtle","understated"]},{"w":"endemic","p":"adj.","m":"Regularly found in a particular area.","e":"Greek <i>endēmos</i> (native): <i>en</i> (in) + <i>dēmos</i> (people).","f":"endémique","t":"Same as « endémique »: corruption endemic to the system.","h":["En + demos: in the people. Malaria is endemic to the region.","Endemic: always present locally."],"s":["indigenous","rampant"]},{"w":"entice","p":"v.","m":"To attract by offering advantage.","e":"Old French <i>enticier</i> (to set on fire, provoke), Vulgar Latin <i>intitiare</i>, from <i>titio</i> (firebrand).","f":"attirer, séduire","t":"Like « attiser »: stoking a fire to lure someone in.","h":["En + titio: firebrand. Entice with sweets.","Entice: lure with a treat."],"s":["beguile","cajole","inveigle","wheedle"]},{"w":"fete","p":"v. / n.","m":"To honour lavishly; a celebration.","e":"French <i>fête</i>, Latin <i>festa</i>.","f":"fêter, fête","t":"Straight from « fêter ».","h":["Fête: a party. To fête the winners.","Fete: lavish celebration in someone’s honour."],"s":["lionize"]},{"w":"fledgling","p":"adj. / n.","m":"New and inexperienced; a young bird.","e":"From <i>fledge</i> (to grow feathers), Old English <i>flycge</i> (able to fly).","f":"naissant, débutant; oisillon","t":"A baby bird just getting feathers: a fledgling start-up.","h":["Fledge: grow feathers. A fledgling company.","Fledgling: first flight."],"s":["callow","embryonic","inchoate","incipient","jejune","nascent","neophyte","rudimentary","tyro"]},{"w":"flounder","p":"v.","m":"To struggle clumsily; to be in confusion.","e":"Perhaps a blend of founder and blunder (16th c.).","f":"patauger, s’empêtrer","t":"Thrashing about in mud: « patauger ».","h":["Flounder fish thrashing on the sand. Flounder in an interview.","Flounder: floundering in a debate."],"s":[]},{"w":"guffaw","p":"n. / v.","m":"A loud, boisterous laugh.","e":"Scottish, imitative of the sound (18th c.).","f":"gros rire, s’esclaffer","t":"Say it out loud: guff-AW! « S’esclaffer ».","h":["Imitates the sound. A guffaw from the back row.","Guffaw: belly laugh."],"s":["chortle"]},{"w":"impede","p":"v.","m":"To delay or obstruct.","e":"Latin <i>impedire</i> (to shackle the feet): <i>in</i> + <i>pes, pedis</i> (foot).","f":"entraver, empêcher","t":"Feet tied: « empêcher » comes from the same word.","h":["In + pes: foot-shackle. Roadworks impede traffic.","Impede: block the path."],"s":["curb","encumber","frustrate","hamper","hinder","hobble","inhibit","stymie","thwart"]},{"w":"impermeable","p":"adj.","m":"Not allowing fluid (or influence) to pass through.","e":"Late Latin <i>impermeabilis</i>: <i>in-</i> + <i>permeare</i> (to pass through).","f":"imperméable","t":"Same as « imperméable », your raincoat.","h":["Im + permeare: can’t pass through. Impermeable raincoat.","Impermeable to criticism: it bounces off."],"s":["callous","impenetrable","impervious"]},{"w":"incessant","p":"adj.","m":"Continuing without pause.","e":"Late Latin <i>incessantem</i>: <i>in-</i> + <i>cessare</i> (to stop).","f":"incessant","t":"Never ceasing: « incessant ».","h":["In + cessare: no stop. Incessant rain.","Incessant chatter: no pause."],"s":["interminable"]},{"w":"inclement","p":"adj.","m":"Unpleasantly cold or wet (weather).","e":"Latin <i>inclemens</i>: <i>in-</i> + <i>clemens</i> (mild).","f":"rigoureux, peu clément","t":"Not clement: « un temps peu clément ».","h":["In + clemens: not mild. Inclement weather.","Inclement: snow, wind, rain."],"s":[]},{"w":"ingenuity","p":"n.","m":"Cleverness, inventiveness.","e":"Latin <i>ingenuitas</i> (originally frankness, confused with <i>ingenium</i>, talent).","f":"ingéniosité","t":"« Ingéniosité ». Funny twist: it comes from ingenuous (naive).","h":["Ingenium: talent. Ingenuity solves problems with little.","Ingenuity: MacGyver."],"s":[]},{"w":"jocular","p":"adj.","m":"Fond of joking; humorous.","e":"Latin <i>iocularis</i>, from <i>iocus</i> (joke), which gave French <i>jeu</i>.","f":"enjoué, facétieux","t":"Iocus = jeu, joke: jovial and jokey.","h":["Jocus: joke. A jocular uncle.","Jocular: tells puns at dinner."],"s":["droll","facetious","flippant","jocund","jovial"]},{"w":"malady","p":"n.","m":"A disease or ailment.","e":"Old French <i>maladie</i>, from <i>malade</i>, Latin <i>male habitus</i> (in bad condition).","f":"maladie, mal","t":"Straight from « maladie ».","h":["Mal habitus: poor condition. A mysterious malady.","Malady: an illness, a social ill."],"s":[]},{"w":"malleable","p":"adj.","m":"Easily shaped or influenced.","e":"Medieval Latin <i>malleabilis</i>, from <i>malleus</i> (hammer).","f":"malléable","t":"Metal you can shape with a hammer (malleus, maillet).","h":["Malleus: hammer. Gold is malleable.","Malleable minds: easily shaped."],"s":["amenable","compliant","docile","plastic","pliant","supple","tractable"]},{"w":"meander","p":"v.","m":"To wander aimlessly; follow a winding course.","e":"Greek <i>Maiandros</i>, a famously winding river in Asia Minor.","f":"serpenter, méandre","t":"« Les méandres » of the river Maeander.","h":["Maeander river: winding. A stream meanders.","Meander: a walk without a destination."],"s":["ramble"]},{"w":"moot","p":"adj.","m":"Debatable; or of no practical relevance.","e":"Old English <i>mōt</i> (assembly, meeting) where matters were debated.","f":"discutable; sans intérêt pratique","t":"A question debated at the moot (assembly). “A moot point” = « sans objet ».","h":["Moot: a meeting to debate. A moot point is arguable (UK) or pointless (US).","Moot: the question no longer matters."],"s":[]},{"w":"morose","p":"adj.","m":"Sullen and gloomy.","e":"Latin <i>morosus</i> (peevish), from <i>mos, moris</i> (custom, mood).","f":"morose","t":"Same as « morose ».","h":["Mos: mood. A morose patient says nothing.","Morose: gloomy and silent."],"s":["churlish","dour","glum","saturnine","sullen","surly","taciturn"]},{"w":"muted","p":"adj.","m":"Quiet, subdued, not intense.","e":"Latin <i>mutus</i> (silent).","f":"atténué, discret, feutré","t":"« Muet »: a muted response, muted colours.","h":["Mute: silent. Muted colours, muted applause.","Muted: the volume turned down."],"s":["subdued","subtle","understated"]},{"w":"obdurate","p":"adj.","m":"Stubbornly refusing to change.","e":"Latin <i>obduratus</i> (hardened): <i>ob</i> + <i>durare</i> (to harden), <i>durus</i>.","f":"obstiné, inflexible","t":"Hardened (dur) against persuasion.","h":["Ob + durus: hard. Obdurate refusal.","Obdurate: stone-faced."],"s":["adamant","contumacious","dogged","headstrong","intransigent","obstinate","pertinacious","recalcitrant","refractory","resolute","tenacious","uncompromising"]},{"w":"ornate","p":"adj.","m":"Elaborately decorated.","e":"Latin <i>ornatus</i>, from <i>ornare</i> (to adorn).","f":"orné, chargé","t":"« Orné »: ornate Baroque churches.","h":["Ornare: adorn. An ornate ceiling.","Ornate: too many decorations."],"s":["baroque","elaborate","flamboyant","florid","ostentatious"]},{"w":"patronize","p":"v.","m":"To treat condescendingly; also to be a customer of.","e":"From patron, Latin <i>patronus</i> (protector), from <i>pater</i> (father).","f":"traiter avec condescendance; fréquenter","t":"Acting like a father to an adult: condescending.","h":["Pater: father. Don’t patronize me: talk down.","Patronize: be a regular customer."],"s":[]},{"w":"pithy","p":"adj.","m":"Concise and full of meaning.","e":"From <i>pith</i>, Old English <i>pitha</i> (the essential core of a plant).","f":"concis, lapidaire","t":"All core, no fluff: a pithy remark.","h":["Pith: the core. A pithy slogan.","Pithy: short and sharp."],"s":["aphoristic","didactic","laconic","sententious","succinct","terse"]},{"w":"plodding","p":"adj.","m":"Slow and laborious; dull.","e":"Probably imitative of heavy footsteps (16th c.).","f":"laborieux, lent","t":"The sound of heavy boots: plod, plod.","h":["Plod: heavy steps. A plodding pace.","Plodding: slow and dull."],"s":["arduous","cumbersome","laborious","onerous","ponderous","tedious"]},{"w":"proponent","p":"n.","m":"A person who advocates a theory.","e":"Latin <i>proponentem</i>, from <i>proponere</i> (to put forward).","f":"partisan, défenseur","t":"Someone who proposes.","h":["Pro + ponere: put forward. A proponent of free trade.","Proponent: the champion of an idea."],"s":["advocate","apologist","champion"]},{"w":"quandary","p":"n.","m":"A state of uncertainty over what to do.","e":"Origin uncertain (16th c.); perhaps from Latin <i>quando</i> (when?).","f":"dilemme, embarras","t":"« Quand? » — not knowing what or when to do.","h":["Quandary: perplexity. In a quandary about two jobs.","Quandary: stuck at a fork."],"s":["conundrum","enigma","imbroglio","predicament"]},{"w":"raffish","p":"adj.","m":"Unconventional and slightly disreputable, but attractive.","e":"From <i>raff</i> (rubbish, riff-raff).","f":"canaille, un peu voyou","t":"Riff-raff with charm: « un air canaille ».","h":["Riff-raff with charm. A raffish grin.","Raffish: roguish, a bit dodgy."],"s":["debonair","rakish"]},{"w":"renege","p":"v.","m":"To go back on a promise.","e":"Medieval Latin <i>renegare</i> (to deny): <i>re-</i> + <i>negare</i>.","f":"revenir sur sa parole","t":"Like « renier »: you deny your own promise.","h":["Re + negare: deny. Renege on a deal.","Renege: break your word."],"s":[]},{"w":"resolve","p":"n.","m":"Firm determination.","e":"Latin <i>resolvere</i> (to loosen, settle).","f":"détermination, résolution","x":"2nd meaning","t":"Making a resolution = showing resolve.","h":["Resolve: firm purpose. Show resolve.","Resolve: sticks to the decision."],"s":["disentangle","perseverance","unravel"]},{"w":"respite","p":"n.","m":"A short period of rest or relief.","e":"Old French <i>respit</i>, from Latin <i>respectus</i> (regard, delay).","f":"répit","t":"Same as « répit ».","h":["Respectus: look back; a break. A brief respite.","Respite: a pause from the storm."],"s":["lull"]},{"w":"robust","p":"adj.","m":"Strong and healthy; sturdy.","e":"Latin <i>robustus</i> (oaken, strong), from <i>robur</i> (oak).","f":"robuste","t":"Strong as an oak: « robuste ».","h":["Robur: oak. A robust economy.","Robust: strong enough to withstand tests."],"s":["profound","resolute","sound","stalwart","staunch","steadfast"]},{"w":"snide","p":"adj.","m":"Mocking in an indirect, unkind way.","e":"19th-century slang, originally “counterfeit”; origin unknown.","f":"sarcastique, narquois","t":"A snide remark: a fake compliment with a sneer.","h":["Snide: sneering. A snide aside.","Snide: a dig with a smirk."],"s":["caustic","derisive","haughty","sardonic","supercilious"]},{"w":"stolid","p":"adj.","m":"Calm, dependable, showing little emotion.","e":"Latin <i>stolidus</i> (dull, stupid).","f":"impassible, flegmatique","t":"Not solid, but close: stolid = unmoving, impassive.","h":["Stolidus: dull. A stolid face shows no feeling.","Stolid: unflappable ox."],"s":["phlegmatic","placid","stoic","unflappable"]},{"w":"thwart","p":"v.","m":"To prevent someone from accomplishing something.","e":"Old Norse <i>þvert</i> (across). To put something across someone’s path.","f":"contrecarrer, déjouer","t":"Laying a log across the path: thwarted plans.","h":["Thwart: across. Rain thwarted the picnic.","Thwart: stand across the path."],"s":["balk","check","circumvent","encumber","foil","frustrate","hamper","hinder","impede","preclude","stymie"]},{"w":"transitory","p":"adj.","m":"Not permanent.","e":"Latin <i>transitorius</i>, from <i>transire</i> (to pass over).","f":"transitoire, passager","t":"Same as « transitoire ».","h":["Transire: pass. Transitory fame.","Transitory: here today, gone tomorrow."],"s":["ephemeral","evanescent","momentary","transient"]}]},{"name":"Basic IV","slug":"basic-iv","series":"Basic","words":[{"w":"altruism","p":"n.","m":"Selfless concern for others.","e":"French <i>altruisme</i>, coined by Auguste Comte (1830s) from Italian <i>altrui</i> (of others), Latin <i>alter</i>.","f":"altruisme","t":"Coined by a Frenchman, Comte: « autrui » = others.","h":["Alter: other. Altruism puts others first.","Altruism: donating a kidney to a stranger."],"s":[]},{"w":"assail","p":"v.","m":"To attack violently, physically or verbally.","e":"Old French <i>asaillir</i>, from Latin <i>ad</i> + <i>salire</i> (to leap).","f":"assaillir","t":"Same as « assaillir »: leaping at someone.","h":["Ad + salire: leap at. Assailed with questions.","Assail: the crowd attacking the speaker with insults."],"s":["gainsay","impugn"]},{"w":"assuage","p":"v.","m":"To make an unpleasant feeling less intense.","e":"Old French <i>assouagier</i>, from Latin <i>ad</i> + <i>suavis</i> (sweet).","f":"apaiser, soulager","t":"Sweeten (suave) the pain: assuage guilt.","h":["Suavis: sweet. Assuage hunger, assuage guilt.","Assuage: a soothing balm."],"s":["alleviate","appease","conciliate","mitigate","mollify","pacify","palliate","placate","propitiate","reconcile","slake","temper"]},{"w":"augment","p":"v.","m":"To make greater; increase.","e":"Latin <i>augmentare</i>, from <i>augere</i> (to increase).","f":"augmenter","t":"Same as « augmenter ».","h":["Augere: increase. Augment your income.","Augment: add on, as in augmented reality."],"s":["amplify","escalate"]},{"w":"banish","p":"v.","m":"To send away; exile.","e":"Old French <i>banir</i>, from Frankish <i>bannjan</i> (to proclaim). Germanic.","f":"bannir","t":"Same as « bannir »: proclaimed out.","h":["Ban: proclaim out. Banish the king.","Banish a thought from your mind."],"s":["exorcise","ostracize","oust","relegate","snub"]},{"w":"benign","p":"adj.","m":"Gentle and kind; not harmful.","e":"Latin <i>benignus</i> (kind): <i>bene</i> (well) + <i>gignere</i> (to be born).","f":"bénin, bienveillant","t":"« Une tumeur bénigne »: born well.","h":["Bene + genus: well born. A benign tumour is harmless.","Benign: kind smile."],"s":["anodyne","beneficent","benevolent","innocuous"]},{"w":"buck","p":"v.","m":"To resist or oppose (buck the trend).","e":"From the male deer or horse that kicks and resists its rider.","f":"résister à, aller à contre-courant","x":"2nd meaning","t":"A bucking horse throwing off its rider: bucking the trend.","h":["Buck: a horse jumping. Buck the trend: go against it.","Buck the system: refuse to comply."],"s":["withstand"]},{"w":"commendable","p":"adj.","m":"Deserving praise.","e":"Latin <i>commendare</i> (to entrust, recommend).","f":"louable","t":"Worth a recommendation.","h":["Commend: praise. A commendable effort.","Commendable: gets a pat on the back."],"s":["creditable","estimable","laudable","meritorious"]},{"w":"conducive","p":"adj.","m":"Making a certain outcome likely.","e":"Latin <i>conducere</i> (to lead together).","f":"propice à, favorable à","t":"Leading (conduire) towards a result: conducive to learning.","h":["Conducere: lead to. A quiet room is conducive to study.","Conducive: sets up the right outcome."],"s":[]},{"w":"contemptuous","p":"adj.","m":"Showing contempt; scornful.","e":"Latin <i>contemptus</i>, from <i>contemnere</i> (to despise).","f":"méprisant","t":"« Contempteur »: looking down on someone.","h":["Contemnere: scorn. A contemptuous sneer.","Contemptuous: looking down at the waiter."],"s":["derisive","sardonic","supercilious"]},{"w":"cornucopia","p":"n.","m":"An abundant supply.","e":"Latin <i>cornu copiae</i>, horn of plenty: the goat’s horn that fed baby Zeus.","f":"corne d’abondance, profusion","t":"The horn of plenty spilling fruit.","h":["Cornu + copia: horn of plenty. A cornucopia of fruit.","Cornucopia: the Thanksgiving basket overflowing."],"s":["glut","plethora","profusion"]},{"w":"credence","p":"n.","m":"Belief or acceptance as true.","e":"Medieval Latin <i>credentia</i>, from <i>credere</i> (to believe).","f":"crédit, foi","t":"Give credence = « accorder du crédit ».","h":["Credere: believe. Lend credence to a rumour.","Credence: how much you believe it."],"s":[]},{"w":"debase","p":"v.","m":"To reduce in quality or value.","e":"<i>de-</i> + base (low), from Late Latin <i>bassus</i>.","f":"avilir, dévaluer","t":"Bring down low (bas): debasing a currency.","h":["De + bas: lower. Debase the currency.","Debase: make cheap."],"s":["adulterate","belittle","degrade","demean","impair","undermine","vitiate"]},{"w":"derisive","p":"adj.","m":"Expressing contempt or ridicule.","e":"Latin <i>deridere</i> (to laugh at), <i>ridere</i>.","f":"moqueur, dérisoire","t":"« Dérision »: mocking laughter.","h":["Deridere: laugh at. Derisive laughter.","Derisive: sneering."],"s":["caustic","contemptuous","sardonic","snide","supercilious"]},{"w":"detrimental","p":"adj.","m":"Tending to cause harm.","e":"Latin <i>detrimentum</i> (loss), from <i>deterere</i> (to rub away).","f":"préjudiciable, nuisible","t":"« Au détriment de »: rubbing away your interests.","h":["Detritus: worn away. Detrimental to health.","Detrimental: harms."],"s":["deleterious","inimical","noxious","pernicious"]},{"w":"egotist","p":"n.","m":"A self-centred, conceited person.","e":"Latin <i>ego</i> (I).","f":"égotiste, égocentrique","t":"Ego + -ist: every conversation comes back to “I”. « Égotiste ».","h":["Ego: I. An egotist talks about himself.","Egotist: selfie addict."],"s":[]},{"w":"elaborate","p":"v. / adj.","m":"To add detail; intricate.","e":"Latin <i>elaborare</i> (to work out): <i>e-</i> + <i>labor</i> (work).","f":"développer, préciser; élaboré","t":"« Élaborer »: work it out further.","h":["E + laborare: work out. Elaborate on your point; an elaborate plan.","Elaborate: add details."],"s":["baroque","elucidate","embellish","expatiate","expound","florid","ornate"]},{"w":"empathetic","p":"adj.","m":"Showing understanding of others’ feelings.","e":"Greek <i>empatheia</i>: <i>en</i> (in) + <i>pathos</i> (feeling).","f":"empathique","t":"Feeling in someone else’s shoes.","h":["Em + pathos: feel in. An empathetic nurse.","Empathetic: “I feel your pain.”"],"s":[]},{"w":"euphoria","p":"n.","m":"Intense excitement and happiness.","e":"Greek <i>euphoria</i>: <i>eu</i> (well) + <i>pherein</i> (to bear).","f":"euphorie","t":"Same as « euphorie ».","h":["Eu + pherein: carry well. Euphoria after winning.","Euphoria: runner’s high."],"s":["panegyric","rhapsody"]},{"w":"facetious","p":"adj.","m":"Treating serious issues with inappropriate humour.","e":"French <i>facétieux</i>, from Latin <i>facetia</i> (jest).","f":"facétieux","t":"Same as « facétieux », but in English often a criticism.","h":["Facetiae: jests. A facetious remark at a funeral.","Facetious: joking when you shouldn’t."],"s":["droll","flippant","jocular","jocund","jovial"]},{"w":"fickle","p":"adj.","m":"Changing frequently, especially in loyalty.","e":"Old English <i>ficol</i> (deceitful). Germanic.","f":"inconstant, volage","t":"Fickle fans switch teams every season.","h":["Fickle: shifting. Fickle weather, fickle friends.","Fickle: can’t commit."],"s":["arbitrary","capricious","erratic","fitful","mercurial","protean","volatile","wayward","whimsical"]},{"w":"genial","p":"adj.","m":"Friendly and cheerful.","e":"Latin <i>genialis</i> (festive, pleasant), from <i>genius</i> (guardian spirit).","f":"cordial, aimable (≠ génial)","x":"Faux ami","t":"Not « génial »! A genial host is warm and friendly.","h":["Genialis: festive. A genial host.","Genial: warm, not ingenious."],"s":["affable","amiable","amicable","congenial","convivial","cordial","gregarious","jovial"]},{"w":"genteel","p":"adj.","m":"Polite, refined, respectable (sometimes affectedly so).","e":"French <i>gentil</i> (noble, well-born), Latin <i>gentilis</i> (of the same clan).","f":"distingué, raffiné","t":"Old French « gentil » = noble (gentilhomme).","h":["Gentil: noble. Genteel manners: refined, a bit snobbish.","Genteel: tea and crumpets."],"s":["becoming","cosmopolitan","decorous","demure","sophisticated","staid","urbane"]},{"w":"glib","p":"adj.","m":"Fluent but insincere and shallow.","e":"Perhaps Low German <i>glibberig</i> (slippery).","f":"désinvolte, facile, superficiel","t":"Slippery words: a glib answer slides off without thought.","h":["Glib: slippery. A glib salesman.","Glib: smooth words, no depth."],"s":["cavalier","cursory","facile","flippant","frivolous","garrulous","haughty","irreverent","loquacious","nonchalant","perfunctory","superficial","voluble"]},{"w":"grovel","p":"v.","m":"To act obsequiously to win favour.","e":"From Old Norse <i>á grúfu</i> (face down).","f":"ramper, s’aplatir","t":"Face down on the floor: « ramper ».","h":["Grovel: crawl. Grovel for forgiveness.","Grovel: bowing low."],"s":["fawn","kowtow"]},{"w":"hamstrung","p":"adj.","m":"Severely restricted; crippled.","e":"From <i>hamstring</i>: cutting the tendon behind the knee to disable.","f":"paralysé, entravé","t":"Tendons cut, like les Énervés de Jumièges: unable to act.","h":["Hamstring: cut tendon. Hamstrung by red tape.","Hamstrung: can’t move."],"s":[]},{"w":"illicit","p":"adj.","m":"Forbidden by law or custom.","e":"Latin <i>illicitus</i>: <i>in-</i> + <i>licitus</i> (allowed).","f":"illicite","t":"Same as « illicite ». Not elicit.","h":["In + licere: not allowed. Illicit trade.","Illicit affair: forbidden."],"s":[]},{"w":"impeccable","p":"adj.","m":"Flawless.","e":"Latin <i>impeccabilis</i>: <i>in-</i> + <i>peccare</i> (to sin).","f":"impeccable","t":"Without sin (péché).","h":["In + peccare: no sin. Impeccable manners.","Impeccable: spotless."],"s":["immaculate","pristine","unimpeachable"]},{"w":"inadvertent","p":"adj.","m":"Not intentional.","e":"<i>in-</i> + Latin <i>advertere</i> (to turn towards).","f":"involontaire, par inadvertance","t":"« Par inadvertance ».","h":["In + advertere: not paying attention. An inadvertent error.","Inadvertent: by accident."],"s":[]},{"w":"irresolute","p":"adj.","m":"Uncertain; hesitant.","e":"<i>in-</i> + Latin <i>resolutus</i> (resolved).","f":"irrésolu, indécis","t":"Same as « irrésolu ».","h":["Not resolute: can’t decide. An irresolute leader.","Irresolute: wobbling."],"s":["tentative"]},{"w":"jargon","p":"n.","m":"Specialist words hard for others to understand.","e":"Old French <i>jargon</i> (twittering of birds).","f":"jargon","t":"Birds chirping: consulting jargon like “synergies”.","h":["Jargon: chatter. Legal jargon.","Jargon: words only insiders understand."],"s":[]},{"w":"lucid","p":"adj.","m":"Clear, easy to understand.","e":"Latin <i>lucidus</i>, from <i>lux</i> (light).","f":"lucide, limpide","t":"Full of light: a lucid explanation.","h":["Lux: light. Lucid explanation; lucid dream.","Lucid: crystal clear."],"s":["articulate","cogent","coherent","intelligible","limpid","pellucid","rational","sound"]},{"w":"martial","p":"adj.","m":"Relating to war.","e":"Latin <i>martialis</i>, of Mars, god of war.","f":"martial","t":"Mars: martial arts, martial law.","h":["Mars: war. Martial arts.","Martial law: soldiers rule."],"s":["bellicose","belligerent"]},{"w":"perennial","p":"adj.","m":"Lasting a long time; recurring.","e":"Latin <i>perennis</i>: <i>per</i> + <i>annus</i> (year).","f":"pérenne, éternel; vivace","t":"Through the years: « pérenne ».","h":["Per + annus: through the years. Perennial plants return each spring.","Perennial: the same old problem."],"s":[]},{"w":"perpetuate","p":"v.","m":"To make something continue indefinitely.","e":"Latin <i>perpetuare</i>, from <i>perpetuus</i> (continuous).","f":"perpétuer","t":"Same as « perpétuer ».","h":["Perpetuus: continuous. Perpetuate a myth.","Perpetuate: keep it going."],"s":[]},{"w":"pertinent","p":"adj.","m":"Relevant.","e":"Latin <i>pertinentem</i>, from <i>pertinere</i> (to relate to).","f":"pertinent","t":"Same as « pertinent ».","h":["Pertinere: concern. A pertinent question.","Pertinent: on topic."],"s":["apposite","apropos","apt","felicitous","germane"]},{"w":"precedent","p":"n.","m":"An earlier event used as a guide.","e":"Latin <i>praecedere</i> (to go before).","f":"précédent","t":"« Créer un précédent ».","h":["Pre + cedere: gone before. Set a precedent.","Precedent: last time’s ruling."],"s":[]},{"w":"pristine","p":"adj.","m":"In original, perfect condition.","e":"Latin <i>pristinus</i> (former, original).","f":"immaculé, intact","t":"Like new, original state: pristine beaches.","h":["Pristinus: former. Pristine snow.","Pristine: untouched."],"s":["immaculate","impeccable","inviolate"]},{"w":"rankle","p":"v.","m":"To cause lasting irritation.","e":"Old French <i>draoncler</i> (to fester), from <i>draoncle</i> (ulcer), Latin <i>dracunculus</i> (little dragon).","f":"rester en travers de la gorge","t":"A little dragon festering inside you: the comment still rankles.","h":["Draconculus: little dragon, a festering sore. His comment still rankles.","Rankle: lingers and irritates."],"s":["fester","gall","irk"]},{"w":"sentimental","p":"adj.","m":"Driven by tender emotion, often excessively.","e":"From sentiment, Latin <i>sentire</i> (to feel).","f":"sentimental","t":"Same as « sentimental ».","h":["Sentire: feel. A sentimental song.","Sentimental: keeps every old ticket."],"s":["cloying","lachrymose","maudlin","mawkish"]},{"w":"smattering","p":"n.","m":"A slight knowledge; a small amount.","e":"From <i>smatter</i> (to talk ignorantly), perhaps Scandinavian.","f":"vague notion, quelques rudiments","t":"A smattering of Spanish: « quelques notions ».","h":["Smatter: splash. A smattering of French.","Smattering: just a little."],"s":["modicum"]},{"w":"spurn","p":"v.","m":"To reject with disdain.","e":"Old English <i>spurnan</i> (to kick). Germanic, related to spur.","f":"repousser, dédaigner","t":"Kicking away an offer.","h":["Spurn: kick away. Spurn an offer.","Spurn: turn up your nose."],"s":["contempt","disdain","renounce","repudiate","scorn","slight","snub"]},{"w":"surly","p":"adj.","m":"Bad-tempered and unfriendly.","e":"Earlier <i>sirly</i> (lordly, arrogant), from <i>sir</i>.","f":"bourru, revêche","t":"Acting like a haughty sir: a surly waiter.","h":["Sirly: lordly. A surly waiter.","Surly: grumpy and rude."],"s":["bilious","boorish","choleric","churlish","dour","glum","morose","saturnine","splenetic","sullen"]},{"w":"tawdry","p":"adj.","m":"Showy but cheap and of poor quality.","e":"From <i>St Audrey’s lace</i>: cheap lace sold at St Audrey’s fair in Ely.","f":"clinquant, de pacotille","t":"Cheap fair-ground lace: tawdry decor.","h":["St Audrey’s lace: cheap souvenirs. Tawdry jewellery.","Tawdry: gaudy tat."],"s":[]},{"w":"tumult","p":"n.","m":"Loud confused noise; uproar.","e":"Latin <i>tumultus</i>, from <i>tumere</i> (to swell).","f":"tumulte","t":"Same as « tumulte ».","h":["Tumultus: uproar. Tumult in the square.","Tumult: noisy chaos."],"s":["clamor"]},{"w":"uncompromising","p":"adj.","m":"Unwilling to make concessions.","e":"<i>un-</i> + compromise, Latin <i>compromittere</i> (to promise mutually).","f":"intransigeant","t":"No compromise at all: « intransigeant », like an uncompromising negotiator.","h":["Won’t compromise. An uncompromising stance.","Uncompromising: hard line."],"s":["adamant","intransigent","obdurate","obstinate"]},{"w":"unruly","p":"adj.","m":"Disorderly; hard to control.","e":"<i>un-</i> + <i>ruly</i> (orderly, from rule).","f":"indiscipliné, turbulent","t":"Not following the rules: an unruly class.","h":["Not ruly: disobeys. An unruly class.","Unruly hair: won’t behave."],"s":["boisterous","clamorous","contumacious","fractious","headstrong","intractable","obstinate","obstreperous","peevish","pertinacious","petulant","recalcitrant","refractory","restive","turbulent","willful"]},{"w":"urbane","p":"adj.","m":"Suave, courteous and refined.","e":"Latin <i>urbanus</i> (of the city), from <i>urbs</i>.","f":"courtois, raffiné","t":"City-polished manners (« urbanité »), as opposed to rustic.","h":["Urbs: city. An urbane diplomat.","Urbane: sophisticated."],"s":["cosmopolitan","debonair","genteel","sophisticated","universal","winsome"]},{"w":"vacuous","p":"adj.","m":"Showing lack of thought; empty.","e":"Latin <i>vacuus</i> (empty).","f":"vide, creux, niais","t":"Vacuum: a vacuous stare.","h":["Vacuus: empty. A vacuous smile.","Vacuous: nothing inside."],"s":["fatuous","puerile"]},{"w":"whimsical","p":"adj.","m":"Playfully quaint or fanciful.","e":"From <i>whim</i>, short for <i>whim-wham</i> (a trifle).","f":"fantasque, capricieux","t":"Following every whim: a whimsical illustration.","h":["Whim: sudden notion. A whimsical cartoon.","Whimsical: playful oddity."],"s":["arbitrary","capricious","droll","erratic","fanciful","fickle","mercurial","quirky","visionary","volatile"]}]},{"name":"Basic V","slug":"basic-v","series":"Basic","words":[{"w":"aphoristic","p":"adj.","m":"Expressed in short, wise sayings.","e":"Greek <i>aphorismos</i> (definition), from <i>aphorizein</i> (to mark off boundaries).","f":"aphoristique, sentencieux","t":"La Rochefoucauld’s maxims are aphoristic.","h":["Aphorizein: define. An aphoristic style: Wilde-like one-liners.","Aphoristic: a speech made of quotable sentences."],"s":["didactic","pithy","sententious","terse"]},{"w":"brusquely","p":"adv.","m":"In an abrupt, rude way.","e":"French <i>brusque</i>, from Italian <i>brusco</i> (sour, harsh).","f":"brusquement, sèchement","t":"Same as « brusquement ».","h":["Brusque: abrupt. He answered brusquely.","Brusquely: rude and short."],"s":[]},{"w":"candidness","p":"n.","m":"Frankness, openness.","e":"Latin <i>candidus</i> (white, pure).","f":"franchise","x":"Faux ami","t":"Candour = franchise, not French candeur (naivety).","h":["Candidus: white, honest. Candidness in feedback.","Candidness: telling it as it is."],"s":[]},{"w":"collusion","p":"n.","m":"Secret cooperation to cheat or deceive.","e":"Latin <i>colludere</i> (to play together): <i>com-</i> + <i>ludere</i>.","f":"collusion, connivence","t":"Playing together secretly: « collusion ».","h":["Col + ludere: play together. Collusion between rival firms.","Collusion: a secret deal to fix prices."],"s":["intrigue","machination"]},{"w":"complacent","p":"adj.","m":"Smugly self-satisfied, unaware of danger.","e":"Latin <i>complacere</i> (to please greatly).","f":"suffisant, trop sûr de soi (≠ complaisant)","x":"Faux ami","t":"French « complaisant » = obliging. Complacent = resting on your laurels.","h":["Complacere: please oneself. Complacent after the win.","Complacent: sleeping on the sofa as the house burns."],"s":["smug"]},{"w":"connive","p":"v.","m":"To secretly allow wrongdoing; to conspire.","e":"Latin <i>connivere</i> (to wink, shut the eyes).","f":"être de connivence, fermer les yeux","t":"Winking at a crime: « connivence ».","h":["Con + nivere: wink together. Connive in the fraud.","Connive: look the other way."],"s":["collude","conspire","intrigue","machinate"]},{"w":"convoluted","p":"adj.","m":"Extremely complex and hard to follow.","e":"Latin <i>convolutus</i> (rolled together): <i>com-</i> + <i>volvere</i>.","f":"alambiqué, compliqué","t":"Rolled up on itself, like involved.","h":["Con + volvere: roll up. A convoluted plot.","Convoluted: spaghetti logic."],"s":["byzantine","involved","sinuous","tortuous"]},{"w":"credulity","p":"n.","m":"Tendency to believe too readily.","e":"Latin <i>credulitas</i>, from <i>credere</i> (to believe).","f":"crédulité","t":"Same as « crédulité ».","h":["Credere: believe. Credulity of tourists.","Credulity: swallowing every claim."],"s":[]},{"w":"derogative","p":"adj.","m":"Showing a critical or disrespectful attitude.","e":"Latin <i>derogare</i> (to detract from): <i>de-</i> + <i>rogare</i> (to ask).","f":"péjoratif, désobligeant","t":"« Déroger »: taking away from someone’s worth.","h":["Derogare: reduce. Derogative remarks.","Derogative: belittling."],"s":["pejorative"]},{"w":"destitute","p":"adj.","m":"Extremely poor, lacking basic necessities.","e":"Latin <i>destitutus</i> (abandoned), from <i>destituere</i> (to forsake).","f":"démuni, dans le dénuement","t":"Abandoned with nothing: « dans le dénuement ».","h":["Destituere: abandon. A destitute family on the street.","Destitute: nothing left."],"s":["impecunious","indigent","miserly","penurious"]},{"w":"devolve","p":"v.","m":"To transfer power to a lower level.","e":"Latin <i>devolvere</i> (to roll down).","f":"déléguer, transférer","t":"Rolling power down: devolved Scottish government.","h":["De + volvere: roll down. Power devolves to the regions.","Devolve: hand down."],"s":["cede","delegate"]},{"w":"diligent","p":"adj.","m":"Showing care and effort.","e":"Latin <i>diligentem</i> (attentive), from <i>diligere</i> (to value).","f":"diligent, assidu","t":"Same as « diligent »: due diligence.","h":["Diligere: value. A diligent student.","Diligent: steady, careful work."],"s":["assiduous","indefatigable","industrious","painstaking","sedulous"]},{"w":"discord","p":"n.","m":"Disagreement; lack of harmony.","e":"Latin <i>discordia</i>: <i>dis-</i> + <i>cor, cordis</i> (heart). Hearts apart.","f":"discorde","t":"« La pomme de discorde ».","h":["Dis + cor: hearts apart. Discord in the family.","Discord: clashing notes."],"s":["acrimony","cacophony","clamor","contention","discrepancy","dissonance","strife","variance"]},{"w":"eke","p":"v.","m":"To make something last by careful use (eke out).","e":"Old English <i>īecan</i> (to increase). Germanic.","f":"faire durer; gagner péniblement","t":"Eke out a living = scraping by.","h":["Eke: add to. Eke out a living.","Eke: stretch resources."],"s":[]},{"w":"elude","p":"v.","m":"To evade or escape skilfully.","e":"Latin <i>eludere</i> (to escape by trickery).","f":"échapper à, éluder","t":"« Éluder une question ».","h":["E + ludere: dodge. The answer eludes me.","Elude: slip away."],"s":["circumvent","evade","skirt"]},{"w":"embellish","p":"v.","m":"To make more attractive; to exaggerate a story.","e":"Old French <i>embellir</i>, from <i>bel</i> (beautiful).","f":"embellir, enjoliver","t":"Same as « embellir ».","h":["Em + bel: beautify. Embellish the story.","Embellish: add flourishes."],"s":["aggrandize","elaborate","expatiate","expound"]},{"w":"enmity","p":"n.","m":"Hostility.","e":"Old French <i>enemistié</i>, from Latin <i>inimicus</i> (enemy).","f":"inimitié, hostilité","t":"Enemy → enmity.","h":["Inimicus: enemy. Deep enmity between two clans.","Enmity: long-standing hatred."],"s":["animosity","animus","antipathy"]},{"w":"exasperate","p":"v.","m":"To irritate intensely.","e":"Latin <i>exasperare</i> (to roughen): <i>ex-</i> + <i>asper</i> (rough).","f":"exaspérer","t":"Same as « exaspérer ».","h":["Ex + asper: rough. Exasperate the teacher.","Exasperate: drive up the wall."],"s":["compound","exacerbate","incense","irk","rile"]},{"w":"exemplify","p":"v.","m":"To be a typical example of.","e":"Medieval Latin <i>exemplificare</i>, from <i>exemplum</i>.","f":"illustrer, incarner","t":"Exemplify = be the exemplum, « illustrer »: she exemplifies the Bain work ethic.","h":["Exemplum: example. She exemplifies integrity.","Exemplify: be the model."],"s":[]},{"w":"foible","p":"n.","m":"A minor weakness in character.","e":"French <i>foible</i>, old form of <i>faible</i> (weak); in fencing, the weak part of the blade.","f":"faiblesse, petit travers","t":"« Faible »: everyone has their little foibles.","h":["Foible: weak. A harmless foible, like being late.","Foible: a little quirk."],"s":["frailty","idiosyncrasy","peccadillo"]},{"w":"goad","p":"v.","m":"To provoke or urge into action.","e":"Old English <i>gād</i> (a pointed stick for driving cattle).","f":"aiguillonner, pousser","t":"A pointed stick prodding oxen: goaded into a fight.","h":["Goad: a prodding stick. Goad him into action.","Goad: poke to anger."],"s":["exhort","foment","galvanize","incite"]},{"w":"impending","p":"adj.","m":"About to happen (usually something bad).","e":"Latin <i>impendere</i> (to hang over).","f":"imminent","t":"Hanging over your head: impending doom.","h":["In + pendere: hang over. Impending storm.","Impending: looming."],"s":["forthcoming","imminent"]},{"w":"impregnable","p":"adj.","m":"Unable to be captured or broken into.","e":"Old French <i>imprenable</i>: <i>in-</i> + <i>prendre</i> (to take).","f":"imprenable","t":"Same as « imprenable » (a fortress).","h":["In + prendre: can’t be taken. An impregnable fortress.","Impregnable: no way in."],"s":["impenetrable","inviolable","inviolate","irrefutable","sacrosanct","unassailable"]},{"w":"irk","p":"v.","m":"To irritate, annoy.","e":"Middle English <i>irken</i> (to grow weary), perhaps Old Norse.","f":"agacer","t":"Irk = « agacer »: small and sharp, like the sound of the word itself.","h":["Irk: annoy. It irks me when you’re late.","Irk: a minor irritation."],"s":["exasperate","fester","gall","incense","rankle","rile"]},{"w":"leery","p":"adj.","m":"Cautious or suspicious.","e":"From <i>leer</i> (a sideways look), Old English <i>hlēor</i> (cheek).","f":"méfiant","t":"Looking at it sideways: leery of strangers.","h":["Leer: sidelong look. Leery of strangers.","Leery: wary."],"s":["chary","circumspect","prudent","vigilant","wary"]},{"w":"malevolent","p":"adj.","m":"Wishing evil on others.","e":"Latin <i>malevolentem</i>: <i>male</i> (badly) + <i>velle</i> (to wish).","f":"malveillant","t":"Wishing ill: « malveillant ».","h":["Mal + velle: wish ill. A malevolent glare.","Malevolent: evil intent."],"s":["baleful","malign","vindictive"]},{"w":"maxim","p":"n.","m":"A short statement of a general truth or rule.","e":"Latin <i>maxima</i> (propositio), the greatest premise.","f":"maxime","t":"Same as « maxime ».","h":["Maxima: greatest rule. “Better late than never”.","Maxim: motto."],"s":["aphorism","apothegm","dictum","epigram"]},{"w":"obstinate","p":"adj.","m":"Stubbornly refusing to change.","e":"Latin <i>obstinatus</i>, from <i>obstinare</i> (to persist).","f":"obstiné","t":"Same as « obstiné ».","h":["Obstinare: persist. An obstinate mule.","Obstinate: won’t budge."],"s":["adamant","contumacious","deliberate","dogged","headstrong","intractable","intransigent","obdurate","pertinacious","recalcitrant","refractory","resolute","tenacious","uncompromising","unruly","willful"]},{"w":"pastoral","p":"adj.","m":"Relating to idealised country life.","e":"Latin <i>pastoralis</i>, from <i>pastor</i> (shepherd).","f":"pastoral, champêtre","t":"Shepherds (pasteurs) in green fields.","h":["Pastor: shepherd. A pastoral scene with sheep.","Pastoral: peaceful countryside."],"s":["bucolic","provincial","rustic"]},{"w":"peevish","p":"adj.","m":"Easily irritated, especially by trifles.","e":"Middle English <i>pevish</i> (perverse), origin unknown.","f":"grincheux, irritable","t":"Peeved over nothing.","h":["Peevish: cross. A peevish toddler.","Peevish: grumbling over nothing."],"s":["bilious","choleric","fractious","irascible","petulant","querulous","refractory","restive","splenetic","unruly"]},{"w":"perturb","p":"v.","m":"To make anxious or unsettled.","e":"Latin <i>perturbare</i>: <i>per-</i> + <i>turbare</i> (to disturb).","f":"perturber, troubler","t":"Same as « perturber ».","h":["Per + turbare: disturb. News that perturbed him.","Perturb: upset."],"s":["agitate"]},{"w":"placid","p":"adj.","m":"Calm; not easily upset.","e":"Latin <i>placidus</i>, from <i>placere</i> (to please).","f":"placide","t":"Same as « placide ».","h":["Placidus: peaceful. A placid lake.","Placid: calm as a cow."],"s":["halcyon","imperturbable","phlegmatic","serene","stoic","stolid","tranquil","unflappable"]},{"w":"ploy","p":"n.","m":"A cunning tactic.","e":"Perhaps from employ (17th c. Scottish).","f":"stratagème, manœuvre","t":"A marketing ploy.","h":["Ploy: a trick. A ploy to win attention.","Ploy: a smart manoeuvre."],"s":["artifice","gambit","intrigue","machination","stratagem"]},{"w":"presumption","p":"n.","m":"Arrogant overstepping of bounds; also an assumption.","e":"Latin <i>praesumere</i> (to take beforehand).","f":"présomption, arrogance","t":"Taking for granted: « présomptueux ».","h":["Praesumere: take beforehand. The presumption to speak for us.","Presumption: arrogance, or a working assumption."],"s":["audacity","effrontery","gall","temerity"]},{"w":"quip","p":"n.","m":"A witty remark.","e":"Perhaps from Latin <i>quippe</i> (indeed, forsooth, used ironically).","f":"bon mot, trait d’esprit","t":"A quick quip = « un bon mot ».","h":["Quip: a witty line. A quick quip lightens the meeting.","Quip: sharp one-liner."],"s":["aphorism","epigram"]},{"w":"rash","p":"adj.","m":"Acting without careful thought.","e":"Middle English <i>rasch</i> (quick), Germanic.","f":"irréfléchi, téméraire","t":"Rushing into it: a rash decision.","h":["Rash: hasty. A rash promise.","Rash: leaps first."],"s":["capricious","foolhardy","impetuous","imprudent","impulsive","precipitate"]},{"w":"reservation","p":"n.","m":"A doubt or qualification.","e":"Latin <i>reservare</i> (to keep back).","f":"réserve, réticence","x":"2nd meaning","t":"« Émettre des réserves »: holding something back.","h":["Reserve: hold back. I have reservations.","Reservation: doubt."],"s":["qualm"]},{"w":"retract","p":"v.","m":"To withdraw a statement.","e":"Latin <i>retrahere</i> (to draw back).","f":"rétracter, revenir sur","t":"« Se rétracter ».","h":["Re + trahere: draw back. Retract a statement.","Retract: take it back, like a cat’s claws."],"s":["abjure","recant","renounce","rescind"]},{"w":"savvy","p":"adj. / n.","m":"Shrewd and knowledgeable; practical know-how.","e":"Pidgin from Spanish/Portuguese <i>sabe</i> (he knows), Latin <i>sapere</i>.","f":"avisé, futé; savoir-faire","t":"« Savoir »: tech-savvy.","h":["Savoir: to know. Tech-savvy.","Savvy: street-smart."],"s":["astute","canny","sagacious","shrewd"]},{"w":"serene","p":"adj.","m":"Calm, peaceful.","e":"Latin <i>serenus</i> (clear, untroubled).","f":"serein","t":"Same as « serein ».","h":["Serenus: clear. A serene lake.","Serene: calm and untroubled."],"s":["halcyon","imperturbable","placid","tranquil","unflappable"]},{"w":"smug","p":"adj.","m":"Excessively pleased with oneself.","e":"Perhaps Low German <i>smuk</i> (neat, trim).","f":"suffisant, content de soi","t":"The smug grin of someone who told you so.","h":["Smug: self-satisfied. A smug grin.","Smug: “I told you so.”"],"s":["complacent","pious","sanctimonious"]},{"w":"squander","p":"v.","m":"To waste.","e":"Origin unknown (16th c.).","f":"gaspiller, dilapider","t":"Squander an opportunity: « gâcher ».","h":["Squander: scatter. Squander money.","Squander: waste a chance."],"s":["disperse","dissipate","lavish"]},{"w":"steadfast","p":"adj.","m":"Resolutely firm and unwavering.","e":"Old English <i>stedefæst</i>: <i>stede</i> (place) + <i>fæst</i> (firm). Fixed in place.","f":"inébranlable, constant","t":"Stuck fast to its place.","h":["Stead + fast: fixed in place. Steadfast loyalty.","Steadfast: unwavering."],"s":["adamant","dogged","resolute","robust","stalwart","staunch"]},{"w":"tact","p":"n.","m":"Sensitivity in dealing with others.","e":"French <i>tact</i>, Latin <i>tactus</i> (touch).","f":"tact","t":"Same as « tact »: the right touch.","h":["Tactus: touch. Tact: delicate handling.","Tact: knowing what not to say."],"s":["discretion"]},{"w":"tarnish","p":"v.","m":"To damage a reputation; to dull a metal.","e":"French <i>ternir</i>, from <i>terne</i> (dull).","f":"ternir","t":"Tarnish = « ternir ».","h":["Ternir: dull. Tarnish silver; tarnish a reputation.","Tarnish: lose the shine."],"s":["besmirch"]},{"w":"taxing","p":"adj.","m":"Physically or mentally demanding.","e":"Latin <i>taxare</i> (to assess, censure).","f":"éprouvant, épuisant","x":"2nd meaning","t":"It takes a tax on your energy.","h":["Tax: burden. A taxing climb.","Taxing: tiring work."],"s":["arduous","cumbersome","laborious","onerous","ponderous"]},{"w":"tout","p":"v.","m":"To promote insistently.","e":"Middle English <i>tuten</i> (to peep, look out). A tout looked out for customers.","f":"vanter, racoler","t":"Touted as the next big thing: « vanté ».","h":["Tout: solicit. Touted as the next big thing.","Tout: hype."],"s":[]},{"w":"travail","p":"n.","m":"Painful or laborious effort.","e":"Old French <i>travail</i> (suffering), from Latin <i>tripalium</i>, a three-pronged torture device.","f":"labeur, peine","t":"French « travail », in its old sense: hard toil. (Also labour pains.)","h":["Travail: toil. The travail of childbirth.","Travail: hard labour."],"s":[]},{"w":"unprecedented","p":"adj.","m":"Never done or known before.","e":"<i>un-</i> + precedent, Latin <i>praecedere</i>.","f":"sans précédent","t":"« Sans précédent ».","h":["Never before. Unprecedented growth.","Unprecedented: a first."],"s":[]},{"w":"unseemly","p":"adj.","m":"Not proper or appropriate.","e":"<i>un-</i> + seemly (fitting), Old Norse <i>sœmr</i>.","f":"inconvenant, malséant","t":"Not seemly: unseemly behaviour.","h":["Un + seemly: improper. Unseemly haste.","Unseemly: out of line."],"s":["adverse","gauche","indecorous","untoward"]}]},{"name":"Basic VI","slug":"basic-vi","series":"Basic","words":[{"w":"analogous","p":"adj.","m":"Comparable in certain respects.","e":"Greek <i>analogos</i> (proportionate): <i>ana</i> + <i>logos</i> (ratio).","f":"analogue","t":"Same as « analogue ».","h":["Ana + logos: according to the ratio. Analogous cases.","Analogous: like a map and a territory."],"s":[]},{"w":"antedate","p":"v.","m":"To come before in time.","e":"Latin <i>ante</i> (before) + date.","f":"précéder, antidater","t":"Ante = before (antérieur).","h":["Ante + date: earlier. This vase antedates Rome.","Antedate: put an earlier date."],"s":[]},{"w":"ascribe","p":"v.","m":"To attribute to a cause or source.","e":"Latin <i>ascribere</i>: <i>ad</i> + <i>scribere</i> (to write).","f":"attribuer, imputer","t":"Writing a name next to it: ascribe success to luck.","h":["Ad + scribere: write to. Ascribe the poem to Homer.","Ascribe: pin the cause on."],"s":["attribute","impute"]},{"w":"avert","p":"v.","m":"To prevent; to turn away (eyes).","e":"Latin <i>avertere</i>: <i>ab</i> + <i>vertere</i> (to turn).","f":"éviter, détourner","t":"Turn away disaster.","h":["A + vertere: turn away. Avert a crisis.","Avert your eyes."],"s":["abstain","deflect","eschew","forestall","forgo","obviate","preclude","preempt"]},{"w":"begrudge","p":"v.","m":"To resent someone having something; give reluctantly.","e":"<i>be-</i> + grudge, Old French <i>grouchier</i> (to grumble).","f":"envier, donner à contrecœur","t":"Grumbling (grouchy) about someone’s bonus.","h":["Be + grudge. Begrudge her success.","Begrudge: give with a scowl."],"s":["bridle","resent"]},{"w":"behoove","p":"v.","m":"To be necessary or proper for.","e":"Old English <i>behōfian</i> (to need). Germanic.","f":"incomber à, convenir à","t":"It behooves you to = « il vous incombe de ».","h":["Behoof: advantage. It behooves you to apologise.","Behoove: it is your duty."],"s":[]},{"w":"belittle","p":"v.","m":"To make seem unimportant.","e":"<i>be-</i> + little. Coined in America (Jefferson, 1780s).","f":"rabaisser, minimiser","t":"Be + little = make someone feel little: « rabaisser ».","h":["Be + little: make small. Don’t belittle my work.","Belittle: put someone down."],"s":["debase","decry","defame","degrade","demean","denigrate","deprecate","detract","disparage","malign","vilify"]},{"w":"besmirch","p":"v.","m":"To damage someone’s reputation.","e":"<i>be-</i> + <i>smirch</i> (to soil), perhaps from Old French <i>esmorcher</i> (to torment with heat).","f":"salir, ternir","t":"Smearing dirt on a name.","h":["Be + smirch: stain. Besmirch his name.","Besmirch: smear mud on."],"s":["debunk","defame","denigrate","discredit","malign","slander","tarnish","vilify"]},{"w":"buttress","p":"v. / n.","m":"To support or strengthen; a support.","e":"Old French <i>bouterez</i> (thrusting), from <i>bouter</i> (to push). A flying buttress pushes against a wall.","f":"étayer, renforcer; contrefort","t":"The flying buttresses (arcs-boutants) of Notre-Dame holding up the walls.","h":["Butt: push against. Flying buttresses hold up cathedrals.","Buttress an argument: add support."],"s":["bolster"]},{"w":"cavalier","p":"adj.","m":"Showing arrogant disregard.","e":"French <i>cavalier</i> (horseman), Latin <i>caballus</i> (horse).","f":"désinvolte, cavalier","t":"« Une attitude cavalière »: the haughty horseman.","h":["Cavalier: horseman. A cavalier attitude to safety.","Cavalier: dismissive of rules."],"s":["flippant","frivolous","glib","haughty","irreverent","nonchalant"]},{"w":"cerebral","p":"adj.","m":"Intellectual rather than emotional.","e":"Latin <i>cerebrum</i> (brain).","f":"cérébral","t":"Same as « cérébral ».","h":["Cerebrum: brain. A cerebral film: thoughtful, not emotional.","Cerebral: thinks, rarely feels."],"s":[]},{"w":"clemency","p":"n.","m":"Mercy, leniency.","e":"Latin <i>clementia</i>, from <i>clemens</i> (mild).","f":"clémence","t":"Same as « clémence ».","h":["Clemens: mild. Plead for clemency.","Clemency: a lighter sentence."],"s":[]},{"w":"coalesce","p":"v.","m":"To come together to form one whole.","e":"Latin <i>coalescere</i>: <i>com-</i> + <i>alescere</i> (to grow).","f":"fusionner, s’unir","t":"Growing together into one (coalition).","h":["Co + alescere: grow together. Clouds coalesce.","Coalesce: merge into one."],"s":["amalgamate","conflate"]},{"w":"cohesive","p":"adj.","m":"Forming a united whole.","e":"Latin <i>cohaerere</i> (to stick together).","f":"cohésif, uni","t":"Sticking together: « cohésion ».","h":["Co + haerere: stick together. A cohesive team.","Cohesive: hangs together."],"s":[]},{"w":"consecrate","p":"v.","m":"To make sacred.","e":"Latin <i>consecrare</i>, from <i>sacer</i> (sacred).","f":"consacrer","t":"« Consacrer ».","h":["Con + sacrare: make sacred. Consecrate the church.","Consecrate: dedicate to a high purpose."],"s":[]},{"w":"conundrum","p":"n.","m":"A difficult problem or puzzle.","e":"16th-century Oxford mock-Latin, origin unknown.","f":"énigme, casse-tête","t":"A conundrum = « un casse-tête ».","h":["Conundrum: a riddle. A tricky conundrum.","Conundrum: puzzle with no easy answer."],"s":["enigma","quandary"]},{"w":"delegate","p":"v. / n.","m":"To entrust a task to another.","e":"Latin <i>delegare</i>: <i>de</i> + <i>legare</i> (to send).","f":"déléguer; délégué","t":"Same as « déléguer ».","h":["De + legare: send. Delegate tasks.","Delegate: hand it off."],"s":["cede","devolve"]},{"w":"deride","p":"v.","m":"To mock, ridicule.","e":"Latin <i>deridere</i> (to laugh at).","f":"tourner en dérision","t":"« Dérision ».","h":["De + ridere: laugh down. Deride his ideas.","Deride: sneer."],"s":["caricature","lampoon","satirize"]},{"w":"docile","p":"adj.","m":"Ready to accept control; submissive.","e":"Latin <i>docilis</i> (teachable), from <i>docere</i> (to teach).","f":"docile","t":"Same as « docile ».","h":["Docere: teach. A docile pony.","Docile: easily taught and led."],"s":["amenable","complaisant","compliant","inert","malleable","obliging","passive","pliant","tractable"]},{"w":"eccentric","p":"adj.","m":"Unconventional, slightly strange.","e":"Greek <i>ekkentros</i>: <i>ek</i> (out of) + <i>kentron</i> (centre).","f":"excentrique","t":"Ex + kentron = off-centre: the eccentric aunt orbiting outside normal behaviour.","h":["Ek + kentron: off-centre. An eccentric millionaire.","Eccentric: odd and charming."],"s":["exotic","idiosyncratic","outlandish","peculiar","quirky"]},{"w":"emulate","p":"v.","m":"To imitate in order to equal or surpass.","e":"Latin <i>aemulari</i> (to rival).","f":"imiter, rivaliser avec","t":"« Émulation »: rivalry that pushes you.","h":["Aemulari: rival. Emulate your heroes.","Emulate: copy to equal."],"s":["mimic"]},{"w":"evenhanded","p":"adj.","m":"Fair and impartial.","e":"English <i>even</i> + <i>handed</i>.","f":"impartial, équitable","t":"Holding both hands level, like the scales of justice.","h":["Even + hand: fair. An evenhanded ruling.","Evenhanded: no favouritism."],"s":["disinterested","dispassionate","equitable","impartial"]},{"w":"fawn","p":"v.","m":"To flatter excessively.","e":"Old English <i>fagnian</i> (to rejoice, wag the tail).","f":"flagorner, faire des courbettes","t":"A dog wagging its tail to please: fawning on the boss.","h":["Fawn: cringe like a dog. Fawn over the boss.","Fawn: flatter."],"s":["grovel","kowtow"]},{"w":"finagle","p":"v.","m":"To obtain by trickery.","e":"American slang (1920s), perhaps from dialect <i>fainaigue</i> (to cheat).","f":"manigancer, obtenir par la ruse","t":"Finagling a deal = « magouiller ».","h":["Finagle: wangle. Finagle free tickets.","Finagle: use cunning."],"s":["contrive"]},{"w":"foolhardy","p":"adj.","m":"Recklessly bold.","e":"Old French <i>fol hardi</i> (foolishly bold).","f":"téméraire, imprudent","t":"Fol + hardi: foolishly daring.","h":["Fol + hardi. A foolhardy climb without ropes.","Foolhardy: brave without sense."],"s":["impetuous","imprudent","impulsive","precipitate","rash"]},{"w":"forthright","p":"adj.","m":"Direct and outspoken.","e":"Old English <i>forthriht</i> (straight forward).","f":"franc, direct","t":"Straight forward.","h":["Forth + right: straight ahead. A forthright answer.","Forthright: says it plainly."],"s":["aboveboard","candid","frank","unfeigned"]},{"w":"glean","p":"v.","m":"To gather information gradually.","e":"Old French <i>glener</i> (to gather leftover grain), Late Latin <i>glennare</i>.","f":"glaner","t":"« Glaner », like Millet’s Gleaners.","h":["Glaner: gather leftovers. Gleaned from the reports.","Glean: pick up bits of info."],"s":[]},{"w":"humdrum","p":"adj.","m":"Lacking excitement; monotonous.","e":"Reduplication of <i>hum</i> (16th c.).","f":"monotone, ennuyeux","t":"Humming the same drum beat every day.","h":["Hum + drum: monotony. A humdrum routine.","Humdrum: tedious."],"s":["banal","irksome","monotonous","mundane","pedestrian","prosaic","quotidian","tedious"]},{"w":"implicate","p":"v.","m":"To show to be involved in a crime.","e":"Latin <i>implicare</i> (to entwine).","f":"impliquer, mettre en cause","t":"Folded into the case.","h":["In + plicare: fold in. Implicated in the scandal.","Implicate: tie to a crime."],"s":[]},{"w":"incense","p":"v.","m":"To make very angry.","e":"Latin <i>incendere</i> (to set on fire).","f":"exaspérer, mettre en colère","x":"2nd meaning","t":"Set on fire (incendie): incensed by the decision. Stress on the second syllable.","h":["Incendere: set on fire. Incensed by the insult.","Incense: enrage."],"s":["exasperate","irk","rile"]},{"w":"incumbent","p":"adj. / n.","m":"Necessary as a duty; the current holder of an office.","e":"Latin <i>incumbere</i> (to lie upon).","f":"qui incombe; titulaire, sortant","t":"« Il vous incombe »: lying upon you. The incumbent president.","h":["In + cumbere: lie on. The incumbent mayor; it is incumbent on you.","Incumbent: current holder or duty."],"s":[]},{"w":"industrious","p":"adj.","m":"Diligent and hard-working.","e":"Latin <i>industria</i> (diligence).","f":"travailleur, assidu","t":"Not industrial: hard-working like a bee.","h":["Industria: diligence. Industrious as an ant.","Industrious: always busy."],"s":["assiduous","diligent","indefatigable","painstaking","sedulous"]},{"w":"insipid","p":"adj.","m":"Lacking flavour or interest.","e":"Latin <i>insipidus</i>: <i>in-</i> + <i>sapidus</i> (tasty).","f":"insipide, fade","t":"Same as « insipide ».","h":["In + sapidus: no taste. Insipid soup.","Insipid: bland."],"s":["anodyne","jejune","naive","puerile","vapid"]},{"w":"intermittent","p":"adj.","m":"Occurring at irregular intervals.","e":"Latin <i>intermittere</i> (to leave off for a while).","f":"intermittent","t":"« Les intermittents du spectacle ».","h":["Inter + mittere: send between. Intermittent rain.","Intermittent: on and off."],"s":["erratic","fitful","sporadic"]},{"w":"irascible","p":"adj.","m":"Easily made angry.","e":"Latin <i>irascibilis</i>, from <i>ira</i> (anger).","f":"irascible, colérique","t":"Same as « irascible ».","h":["Ira: anger. An irascible old man.","Irascible: short fuse."],"s":["bilious","choleric","peevish","petulant","splenetic"]},{"w":"lethargic","p":"adj.","m":"Sluggish and apathetic.","e":"Greek <i>lēthargos</i> (forgetful), from <i>lēthē</i> (forgetfulness).","f":"léthargique","t":"The river Lethe of forgetfulness.","h":["Lethe: forgetfulness. Lethargic in the heat.","Lethargic: sluggish."],"s":["apathetic","dilatory","indolent","inert","languid","passive","sluggish"]},{"w":"melancholy","p":"n. / adj.","m":"Deep, lasting sadness.","e":"Greek <i>melankholia</i>: <i>melas</i> (black) + <i>kholē</i> (bile).","f":"mélancolie, mélancolique","t":"Black bile: same as « mélancolie ».","h":["Melas + khole: black bile. Melancholy autumn.","Melancholy: gentle sadness."],"s":["doleful","lugubrious","pensive","plaintive","wistful","woeful"]},{"w":"piquant","p":"adj.","m":"Pleasantly sharp; stimulating.","e":"French <i>piquant</i> (stinging), from <i>piquer</i>.","f":"piquant","t":"Straight from « piquant ».","h":["Piquer: sting. Piquant sauce.","Piquant: spicy."],"s":[]},{"w":"precarious","p":"adj.","m":"Dangerously unstable.","e":"Latin <i>precarius</i> (obtained by prayer, dependent on others), from <i>prex</i> (prayer).","f":"précaire","t":"Same as « précaire »: dependent on someone’s goodwill.","h":["Precarius: by prayer. A precarious ledge.","Precarious: could collapse."],"s":["perilous"]},{"w":"preempt","p":"v.","m":"To act in advance to prevent something.","e":"Back-formation from pre-emption, Latin <i>prae</i> + <i>emere</i> (to buy).","f":"devancer, anticiper","t":"Pre-empt = buy before others (prae + emere): acting first so the rival can’t.","h":["Pre + emere: buy first. Preempt the rival.","Preempt: strike first."],"s":["avert","forestall","obviate","preclude","supersede"]},{"w":"presumptuous","p":"adj.","m":"Overstepping limits; overconfident.","e":"Latin <i>praesumptuosus</i>, from <i>praesumere</i>.","f":"présomptueux","t":"Same as « présomptueux ».","h":["Presume: take for granted. A presumptuous question.","Presumptuous: arrogant."],"s":["brazen","haughty","impertinent","impudent","insolent","overweening"]},{"w":"prevail","p":"v.","m":"To prove more powerful; to be widespread.","e":"Latin <i>praevalere</i>: <i>prae</i> + <i>valere</i> (to be strong).","f":"prévaloir, l’emporter","t":"« Prévaloir ».","h":["Prae + valere: be stronger. Reason prevails.","Prevail: win out."],"s":["obtain"]},{"w":"profusion","p":"n.","m":"An abundance.","e":"Latin <i>profusio</i> (pouring out).","f":"profusion","t":"« À profusion ».","h":["Pro + fundere: pour. A profusion of flowers.","Profusion: overflowing."],"s":["cornucopia","glut","plethora","surfeit"]},{"w":"rakish","p":"adj.","m":"Dashing, jaunty; slightly disreputable.","e":"From <i>rake</i> (a dissolute man), short for <i>rakehell</i>.","f":"désinvolte, canaille","t":"A hat at a rakish angle: the charming rake.","h":["Rake: a libertine. A rakish hat.","Rakish: jaunty."],"s":["debonair","raffish"]},{"w":"redress","p":"v. / n.","m":"To remedy a wrong; remedy.","e":"Old French <i>redrecier</i> (to set straight again).","f":"réparer, redresser","t":"« Redresser un tort ».","h":["Re + dress: put right. Redress a grievance.","Redress: make amends."],"s":["ameliorate","amend"]},{"w":"rile","p":"v.","m":"To annoy or irritate.","e":"Variant of <i>roil</i> (to stir up mud), perhaps French <i>rouiller</i>.","f":"agacer, énerver","t":"Stirring up muddy water: don’t rile him.","h":["Rile: stir up. Rile the crowd.","Rile: annoy."],"s":["exasperate","gall","incense","irk"]},{"w":"tribulation","p":"n.","m":"A cause of great trouble or suffering.","e":"Latin <i>tribulare</i> (to press, oppress), from <i>tribulum</i> (threshing sledge).","f":"tribulation, épreuve","t":"Same as « tribulations »: crushed like grain.","h":["Tribulum: threshing sledge. Trials and tribulations.","Tribulation: hardship."],"s":[]},{"w":"uncanny","p":"adj.","m":"Strange or mysterious in an unsettling way.","e":"Scots <i>un-</i> + <i>canny</i> (knowing, safe), from <i>can</i> (to know).","f":"troublant, étrange","t":"Beyond what can be known: an uncanny resemblance.","h":["Un + canny: eerie. An uncanny resemblance.","Uncanny: spooky."],"s":[]},{"w":"veneer","p":"n.","m":"A superficial appearance covering reality.","e":"German <i>furnieren</i>, from French <i>fournir</i> (to furnish). A thin layer of fine wood.","f":"vernis, façade","t":"A thin layer of fine wood on cheap furniture: a veneer of respectability.","h":["Fournir: furnish. A veneer of politeness.","Veneer: thin outer layer."],"s":["facade","semblance"]},{"w":"wanton","p":"adj.","m":"Deliberate and unprovoked; also immoral.","e":"Middle English <i>wantowen</i>: <i>wan-</i> (lacking) + <i>togen</i> (trained, disciplined).","f":"gratuit, délibéré; dévergondé","t":"Lacking discipline: wanton destruction.","h":["Wan + togen: undisciplined. Wanton cruelty.","Wanton: senseless."],"s":["gratuitous","wayward","willful"]}]},{"name":"Basic VII","slug":"basic-vii","series":"Basic","words":[{"w":"abysmal","p":"adj.","m":"Extremely bad; also very deep.","e":"Old French <i>abisme</i> (abyss), from Greek <i>abyssos</i> (bottomless).","f":"exécrable, abyssal","t":"Bottomless: « abîme ».","h":["Abyss: bottomless. An abysmal performance: as bad as it gets.","Abysmal: the pit of a score."],"s":["abject","execrable","odious","woeful"]},{"w":"amply","p":"adv.","m":"Sufficiently or more than enough.","e":"Latin <i>amplus</i> (large).","f":"amplement","t":"« Amplement ».","h":["Ample: large. Amply rewarded.","Amply: more than enough."],"s":[]},{"w":"antiquated","p":"adj.","m":"Old-fashioned, outdated.","e":"Latin <i>antiquare</i>, from <i>antiquus</i> (old).","f":"désuet, vieillot","t":"Antique and out of date.","h":["Antique + ated: out of date. An antiquated system.","Antiquated: belongs in a museum."],"s":["anachronistic","archaic","hoary","obsolete"]},{"w":"aphorism","p":"n.","m":"A concise statement of a general truth.","e":"Greek <i>aphorismos</i> (definition).","f":"aphorisme, maxime","t":"Same as « aphorisme ».","h":["Aphorizein: define. “Less is more” is an aphorism.","Aphorism: a wise short saying."],"s":["apothegm","dictum","epigram","maxim","quip"]},{"w":"balk","p":"v.","m":"To hesitate or refuse to proceed.","e":"Old English <i>balca</i> (ridge between furrows); a horse balks at a ridge.","f":"rechigner, renâcler","t":"A horse refusing a jump: « renâcler ».","h":["Balk: a ridge. The horse balked at the fence.","Balk: pull back."],"s":["check","circumvent","demur","foil","frustrate","stymie","thwart"]},{"w":"besiege","p":"v.","m":"To surround with armed forces; to overwhelm.","e":"<i>be-</i> + siege, Old French <i>sege</i> (seat).","f":"assiéger, assaillir","t":"« Assiéger »: besieged by journalists.","h":["Be + siege: surround. Journalists besieged her.","Besiege: encircle."],"s":["inundate"]},{"w":"boorish","p":"adj.","m":"Rough and bad-mannered.","e":"From <i>boor</i>, Dutch <i>boer</i> (farmer, peasant).","f":"rustre, grossier","t":"Boer = peasant: « rustre ».","h":["Boor: peasant. Boorish table manners.","Boorish: loud and rude."],"s":["churlish","surly"]},{"w":"carping","p":"adj.","m":"Constantly finding fault.","e":"Old Norse <i>karpa</i> (to boast), influenced by Latin <i>carpere</i> (to pluck, slander).","f":"chicanier, critique","t":"Carping critics pluck at every detail.","h":["Carp: complain. Carping about nothing.","Carping: nitpicking."],"s":["captious","finicky","petulant","plaintive","querulous"]},{"w":"champion","p":"v.","m":"To support or defend a cause.","e":"Old French <i>champion</i> (combatant), Late Latin <i>campio</i>, from <i>campus</i> (field of battle).","f":"défendre, se faire le champion de","x":"2nd meaning","t":"« Se faire le champion de »: fighting for a cause.","h":["Champion: fighter. Champion the poor.","Champion: speak up for."],"s":["advocate","apologist","espouse","proponent"]},{"w":"chivalrous","p":"adj.","m":"Courteous and gallant, especially towards women.","e":"Old French <i>chevalerie</i>, from <i>cheval</i>.","f":"chevaleresque","t":"The horseman’s code: « chevaleresque ».","h":["Chevalier: knight. Chivalrous gestures.","Chivalrous: opens the door."],"s":[]},{"w":"colossal","p":"adj.","m":"Extremely large.","e":"Greek <i>kolossos</i>, the giant statue (Colossus of Rhodes).","f":"colossal","t":"The Colossus of Rhodes.","h":["Colossus: huge statue. A colossal mistake.","Colossal: giant."],"s":["prodigious"]},{"w":"complementary","p":"adj.","m":"Combining to complete each other.","e":"Latin <i>complementum</i> (that which fills up), from <i>complere</i>.","f":"complémentaire","t":"Not complimentary (praise): pieces that complete each other.","h":["Complete: fit together. Complementary skills.","Complementary: pieces of a puzzle."],"s":[]},{"w":"compound","p":"v.","m":"To make worse; to combine.","e":"Old French <i>compondre</i>, Latin <i>componere</i> (to put together).","f":"aggraver; composer","x":"2nd meaning","t":"Compound interest grows on itself: compound a problem = aggravate it.","h":["Compound: combine; worsen. Compound interest; compound the error.","Compound: add to."],"s":["exacerbate","exasperate"]},{"w":"constraint","p":"n.","m":"A limitation or restriction.","e":"Old French <i>constreinte</i>, from Latin <i>constringere</i> (to bind tightly).","f":"contrainte","t":"Same as « contrainte ».","h":["Con + stringere: bind. A budget constraint.","Constraint: limit."],"s":["check","coercion","curb","duress"]},{"w":"convivial","p":"adj.","m":"Friendly, lively and enjoyable.","e":"Latin <i>convivium</i> (feast): <i>com-</i> + <i>vivere</i> (to live).","f":"convivial","t":"Same as « convivial ».","h":["Con + vivere: live together. A convivial dinner.","Convivial: lively and warm."],"s":["affable","amiable","congenial","cordial","genial","gregarious","jocund","jovial"]},{"w":"cosmopolitan","p":"adj.","m":"Familiar with many cultures; including people from many countries.","e":"Greek <i>kosmopolitēs</i> (citizen of the world): <i>kosmos</i> + <i>politēs</i>.","f":"cosmopolite","t":"Citizen of the world.","h":["Cosmos + polis: world city. A cosmopolitan city.","Cosmopolitan: global."],"s":["debonair","genteel","sophisticated","universal","urbane"]},{"w":"creditable","p":"adj.","m":"Deserving praise, though not outstanding.","e":"From credit, Latin <i>credere</i> (to believe).","f":"honorable, estimable","t":"It does you credit.","h":["Credit: you earn it. A creditable result.","Creditable: respectable."],"s":["commendable","estimable","laudable","meritorious"]},{"w":"cumbersome","p":"adj.","m":"Large, heavy and awkward.","e":"From <i>cumber</i> (to hinder), Old French <i>encombrer</i>.","f":"encombrant, lourd","t":"« Encombrant ».","h":["Cumber: hinder. A cumbersome suitcase.","Cumbersome: clumsy to carry."],"s":["arduous","onerous","plodding","ponderous","taxing"]},{"w":"debunk","p":"v.","m":"To expose a myth as false.","e":"<i>de-</i> + bunk (nonsense, from <i>bunkum</i>, Buncombe County, whose congressman made a pointless speech in 1820).","f":"démystifier, démentir","t":"Removing the bunk (nonsense).","h":["De + bunk (nonsense). Debunk a myth.","Debunk: show it’s false."],"s":["belie","besmirch","defame","discredit","gainsay","negate","refute"]},{"w":"decimation","p":"n.","m":"Killing or destruction of a large part.","e":"Latin <i>decimare</i>: Roman punishment killing one soldier in ten (<i>decimus</i>).","f":"décimation, destruction","t":"One in ten killed: « décimer ».","h":["Decimus: tenth. Roman punishment. The plague decimated the town.","Decimation: massive loss."],"s":["ravage"]},{"w":"deliberate","p":"v. / adj.","m":"To think carefully; intentional.","e":"Latin <i>deliberare</i> (to weigh well), from <i>libra</i> (scales).","f":"délibérer; délibéré","t":"Weighing on scales (libra).","h":["De + librare: weigh. Deliberate over the verdict; a deliberate act.","Deliberate: planned."],"s":["cogitate","contemplate","headstrong","obstinate","reflect","ruminate","willful"]},{"w":"differentiate","p":"v.","m":"To recognise or show the difference.","e":"Medieval Latin <i>differentiare</i>.","f":"différencier","t":"Same as « différencier ».","h":["Differ: tell apart. Differentiate cat from dog.","Differentiate: set apart."],"s":["discern","discriminate"]},{"w":"dilapidated","p":"adj.","m":"In a state of disrepair.","e":"Latin <i>dilapidare</i> (to scatter stones), from <i>lapis</i> (stone).","f":"délabré","t":"Stones falling apart (lapis).","h":["De + lapis: stones come apart. A dilapidated house.","Dilapidated: falling to pieces."],"s":["derelict"]},{"w":"discreet","p":"adj.","m":"Careful to avoid causing offence or revealing secrets.","e":"Old French <i>discret</i>, Latin <i>discretus</i> (separated, discerning).","f":"discret","t":"Discreet = « discret ». Discrete = separate.","h":["Discretus: separate/judicious. A discreet cough.","Discreet: quiet and careful."],"s":["astute","canny","circumspect","expedient","judicious","politic","prudent","sagacious","shrewd","wary"]},{"w":"dispatch","p":"v. / n.","m":"To send off; to deal with quickly; speed.","e":"Italian <i>dispacciare</i> or Spanish <i>despachar</i> (to expedite).","f":"expédier; célérité","x":"2nd meaning","t":"« Dépêcher »: with dispatch = promptly.","h":["Dépêcher: hasten. Dispatch a messenger.","Dispatch: speed."],"s":["alacrity","celerity","expedite","facilitate"]},{"w":"enumerate","p":"v.","m":"To list one by one.","e":"Latin <i>enumerare</i>, from <i>numerus</i>.","f":"énumérer","t":"Same as « énumérer ».","h":["E + numerare: count out. Enumerate the reasons.","Enumerate: list them."],"s":[]},{"w":"evasive","p":"adj.","m":"Tending to avoid commitment or answers.","e":"Latin <i>evadere</i> (to escape).","f":"évasif","t":"Same as « évasif ».","h":["E + vadere: slip away. An evasive answer.","Evasive: dodges."],"s":["ambiguous","elusive","equivocal","reticent","subtle","unforthcoming"]},{"w":"excruciating","p":"adj.","m":"Intensely painful.","e":"Latin <i>excruciare</i>, from <i>crux</i> (cross): tormented as on a cross.","f":"atroce, insoutenable","t":"Crux = croix: crucifying pain.","h":["Ex + crux: from the cross. Excruciating pain.","Excruciating: agony."],"s":["harrowing"]},{"w":"futile","p":"adj.","m":"Pointless, ineffective.","e":"Latin <i>futilis</i> (leaky, worthless).","f":"vain, inutile (futile = frivolous)","t":"A leaky vessel: futile efforts. French « futile » leans to frivolous.","h":["Futilis: leaky. Futile attempt.","Futile: useless."],"s":["inefficacious"]},{"w":"hamper","p":"v.","m":"To hinder.","e":"Middle English <i>hamperen</i>, perhaps related to German <i>hemmen</i> (to restrain).","f":"entraver, gêner","t":"Hamper progress = « entraver ».","h":["Hamper: impede. Hamper progress.","Hamper: hold back."],"s":["curb","encumber","frustrate","hinder","hobble","impede","inhibit","quash","squelch","stultify","stymie","suppress","thwart"]},{"w":"inarticulate","p":"adj.","m":"Unable to express ideas clearly.","e":"<i>in-</i> + Latin <i>articulatus</i>.","f":"incapable de s’exprimer, inarticulé","t":"Speech without joints.","h":["In + articulate: can’t express. Inarticulate with rage.","Inarticulate: tongue-tied."],"s":[]},{"w":"inkling","p":"n.","m":"A slight suspicion or hint.","e":"Middle English <i>inclen</i> (to hint), origin uncertain.","f":"soupçon, vague idée","t":"Not the faintest inkling = « pas la moindre idée ».","h":["Inkling: slight hint. No inkling of the danger.","Inkling: faint idea."],"s":["intimation"]},{"w":"laborious","p":"adj.","m":"Requiring much effort.","e":"Latin <i>laboriosus</i>, from <i>labor</i>.","f":"laborieux","t":"Same as « laborieux ».","h":["Labor: toil. A laborious task.","Laborious: long and hard."],"s":["arduous","onerous","plodding","taxing","tedious"]},{"w":"malodorous","p":"adj.","m":"Smelling very unpleasant.","e":"Latin <i>male</i> (badly) + <i>odor</i>.","f":"malodorant","t":"Same as « malodorant ».","h":["Mal + odor: bad smell. A malodorous drain.","Malodorous: stinks."],"s":["noisome","noxious"]},{"w":"miscreant","p":"n.","m":"A wrongdoer.","e":"Old French <i>mescreant</i> (unbeliever): <i>mes-</i> + <i>croire</i>.","f":"scélérat, malfaiteur","t":"« Mécréant » = unbeliever → villain.","h":["Mécréant: unbeliever. A miscreant boy.","Miscreant: villain."],"s":["reprobate"]},{"w":"misogynist","p":"n.","m":"A person who dislikes women.","e":"Greek <i>misogynēs</i>: <i>misein</i> (to hate) + <i>gynē</i> (woman).","f":"misogyne","t":"Same as « misogyne ».","h":["Miso + gyne: woman-hater. A misogynist remark.","Misogynist: sexist."],"s":[]},{"w":"morph","p":"v.","m":"To change gradually into something else.","e":"Short for metamorphose, Greek <i>morphē</i> (shape).","f":"se transformer","t":"Metamorphosis shortened.","h":["Metamorphosis: change. The caterpillar morphs into a butterfly.","Morph: transform."],"s":["transmute"]},{"w":"obliging","p":"adj.","m":"Willing to help.","e":"Latin <i>obligare</i> (to bind).","f":"serviable, obligeant","t":"« Obligeant ».","h":["Obliger: oblige. An obliging neighbour.","Obliging: helpful."],"s":["amenable","complaisant","compliant","docile","pliant","tractable"]},{"w":"paradoxical","p":"adj.","m":"Seemingly absurd or contradictory.","e":"Greek <i>paradoxos</i>.","f":"paradoxal","t":"Same as « paradoxal ».","h":["Paradox: contradiction. A paradoxical result.","Paradoxical: strange but possibly true."],"s":[]},{"w":"perquisite","p":"n.","m":"A benefit in addition to salary (a perk).","e":"Medieval Latin <i>perquisitum</i> (thing acquired), from <i>perquirere</i> (to seek diligently).","f":"avantage, à-côté","t":"Perk is short for perquisite.","h":["Perk. A company car is a perquisite.","Perquisite: extra benefit."],"s":[]},{"w":"provisional","p":"adj.","m":"Arranged for the present, likely to change.","e":"Latin <i>provisio</i> (foresight).","f":"provisoire","t":"« Provisoire ».","h":["Provision: for now. A provisional licence.","Provisional: temporary."],"s":["contingent","tentative"]},{"w":"qualm","p":"n.","m":"An uneasy feeling of doubt or guilt.","e":"Origin uncertain; Old English <i>cwealm</i> (death, pain) or Dutch <i>kwalm</i> (nausea).","f":"scrupule, remords","t":"No qualms = « aucun scrupule ».","h":["Qualm: doubt. No qualms about lying.","Qualm: conscience pang."],"s":["reservation"]},{"w":"relegate","p":"v.","m":"To assign to a lower rank.","e":"Latin <i>relegare</i> (to send away, banish).","f":"reléguer","t":"Same as « reléguer ».","h":["Re + legare: send away. Relegated to the minor league.","Relegate: demote."],"s":["banish","disenfranchise","marginalize","ostracize"]},{"w":"resignation","p":"n.","m":"Acceptance of something undesirable but inevitable.","e":"Latin <i>resignare</i> (to unseal, give up).","f":"résignation","x":"2nd meaning","t":"« Résignation ».","h":["Resign: give up. Resignation at the news.","Resignation: acceptance."],"s":[]},{"w":"snub","p":"v. / n.","m":"To rebuff or ignore disdainfully.","e":"Old Norse <i>snubba</i> (to rebuke).","f":"snober, rabrouer","t":"Snub = to ignore someone pointedly: the colleague who looks right through you at the coffee machine.","h":["Snub: rebuff. Snubbed the invitation.","Snub: cold shoulder."],"s":["affront","banish","disdain","ostracize","scorn","slight","spurn"]},{"w":"sordid","p":"adj.","m":"Morally vile; dirty.","e":"Latin <i>sordidus</i> (dirty), from <i>sordes</i> (dirt).","f":"sordide","t":"Same as « sordide ».","h":["Sordidus: dirty. A sordid affair.","Sordid: squalid."],"s":["base","ignoble"]},{"w":"staid","p":"adj.","m":"Sedate, respectable and unadventurous.","e":"Old past participle of <i>stay</i>: settled, steady.","f":"guindé, rangé","t":"Stayed in place: a staid banker.","h":["Stay: stable. A staid banker.","Staid: sober and dull."],"s":["becoming","decorous","demure","genteel","sober"]},{"w":"stymie","p":"v.","m":"To prevent or hinder progress.","e":"Golf term: a ball blocking another’s path to the hole.","f":"entraver, bloquer","t":"A golf ball in your way.","h":["Stymie: block (golf). Stymied by red tape.","Stymie: stop progress."],"s":["balk","check","circumvent","encumber","foil","frustrate","hamper","hinder","hobble","impede","inhibit","preclude","thwart"]},{"w":"vanquish","p":"v.","m":"To defeat thoroughly.","e":"Old French <i>vencus</i>, from Latin <i>vincere</i> (to conquer).","f":"vaincre","t":"Vincere = « vaincre ».","h":["Vincere: conquer. Vanquish the enemy.","Vanquish: beat decisively."],"s":["subjugate","surmount"]},{"w":"vie","p":"v.","m":"To compete eagerly.","e":"Short for <i>envy</i> in the old sense “to challenge”, from Old French <i>envier</i> (to invite, challenge).","f":"rivaliser","t":"Vying for the top spot = « rivaliser ».","h":["Vie: compete. Vying for the prize.","Vie: race for it."],"s":["contend"]}]},{"name":"Basic VIII","slug":"basic-viii","series":"Basic","words":[{"w":"cacophony","p":"n.","m":"A harsh, discordant mixture of sounds.","e":"Greek <i>kakophōnia</i>: <i>kakos</i> (bad) + <i>phōnē</i> (sound).","f":"cacophonie","t":"Same as « cacophonie ».","h":["Kakos + phone: bad sound. A cacophony of car horns.","Cacophony: an orchestra tuning."],"s":["clamor","discord","dissonance"]},{"w":"cathartic","p":"adj.","m":"Providing emotional release.","e":"Greek <i>katharsis</i> (purging), from <i>katharos</i> (pure).","f":"cathartique, libérateur","t":"Aristotle’s catharsis: tragedy purging emotions.","h":["Katharsis: cleansing. Crying at the film felt cathartic.","Cathartic: a release."],"s":[]},{"w":"caustic","p":"adj.","m":"Sarcastic in a scathing way; corrosive.","e":"Greek <i>kaustikos</i> (burning), from <i>kaiein</i> (to burn).","f":"caustique, mordant","t":"Burning like acid: caustic humour.","h":["Kaustikos: burning. Caustic soda; caustic wit.","Caustic: acid tongue."],"s":["acerbic","astringent","derisive","mordant","sardonic","scathing","snide","trenchant","virulent","vitriolic"]},{"w":"cloying","p":"adj.","m":"Sickeningly sweet or sentimental.","e":"From <i>cloy</i>, Old French <i>encloer</i> (to nail, block up).","f":"écœurant, mièvre","t":"So sweet it clogs you up: cloying.","h":["Cloy: clog with sweetness. Cloying perfume.","Cloying: too much syrup."],"s":["maudlin","mawkish","sentimental"]},{"w":"debacle","p":"n.","m":"A sudden and ignominious failure.","e":"French <i>débâcle</i> (breaking up of ice on a river), from <i>débâcler</i> (to unbar).","f":"débâcle, fiasco","t":"Same as « débâcle ».","h":["Débâcle: breakup of river ice. A total debacle.","Debacle: a fiasco."],"s":[]},{"w":"discern","p":"v.","m":"To perceive or recognise.","e":"Latin <i>discernere</i> (to separate, distinguish).","f":"discerner","t":"Same as « discerner ».","h":["Dis + cernere: sift apart. Discern the truth.","Discern: spot the difference."],"s":["descry","differentiate","discriminate"]},{"w":"discordant","p":"adj.","m":"Disagreeing; harsh-sounding.","e":"Latin <i>discordare</i> (to disagree), <i>cor</i> (heart).","f":"discordant","t":"Same as « discordant ».","h":["Dis + cor: hearts apart. A discordant note.","Discordant: clashing."],"s":["anomalous","cacophonous","incongruous"]},{"w":"discredit","p":"v.","m":"To harm the reputation of; to cause to be doubted.","e":"<i>dis-</i> + credit, Latin <i>credere</i>.","f":"discréditer","t":"Same as « discréditer ».","h":["Dis + credit: undo trust. Discredit the witness.","Discredit: make doubtful."],"s":["belie","besmirch","debunk","defame","refute"]},{"w":"discrepancy","p":"n.","m":"A lack of compatibility between facts.","e":"Latin <i>discrepare</i> (to sound differently): <i>dis-</i> + <i>crepare</i> (to rattle).","f":"divergence, écart","t":"Two numbers that don’t sound the same in a model.","h":["Dis + crepare: sound different. A discrepancy in the accounts.","Discrepancy: figures don’t match."],"s":["discord","variance"]},{"w":"disparage","p":"v.","m":"To belittle.","e":"Old French <i>desparagier</i> (to marry beneath one’s rank), from <i>parage</i> (rank).","f":"dénigrer, déprécier","t":"Lowering someone’s rank (« parage »).","h":["Dis + parage (rank): lower. Disparage a rival.","Disparage: run down."],"s":["belittle","castigate","censure","decry","defame","demean","denigrate","denounce","deprecate","excoriate","malign","slander","vilify"]},{"w":"divulge","p":"v.","m":"To reveal (secret information).","e":"Latin <i>divulgare</i> (to publish), from <i>vulgus</i> (common people).","f":"divulguer","t":"Same as « divulguer ».","h":["Di + vulgus: tell the crowd. Divulge a secret.","Divulge: spill."],"s":["betray"]},{"w":"dubious","p":"adj.","m":"Doubtful; suspect.","e":"Latin <i>dubiosus</i>, from <i>dubium</i> (doubt).","f":"douteux","t":"Doubt: « douteux ».","h":["Dubius: doubting. A dubious claim.","Dubious: suspicious."],"s":["apocryphal","implausible","incredulous","spurious","suspect"]},{"w":"euphemism","p":"n.","m":"A mild word substituted for a harsh one.","e":"Greek <i>euphēmismos</i>: <i>eu</i> (well) + <i>phēmē</i> (speaking).","f":"euphémisme","t":"Same as « euphémisme ».","h":["Eu + phemi: speak well. “Passed away” is a euphemism.","Euphemism: soften it."],"s":[]},{"w":"florid","p":"adj.","m":"Overly elaborate; also red-faced.","e":"Latin <i>floridus</i> (flowery), from <i>flos</i> (flower).","f":"fleuri, ampoulé; rougeaud","t":"Flos = fleur: florid prose is over-flowered; a florid face is flushed red.","h":["Flos: flower. A florid style; a florid complexion.","Florid: flowery."],"s":["baroque","elaborate","flamboyant","ornate","ostentatious"]},{"w":"flout","p":"v.","m":"To openly disregard a rule.","e":"Perhaps from Middle Dutch <i>fluyten</i> (to play the flute, to jeer).","f":"bafouer, braver","t":"Not flaunt (show off). Flout the rules.","h":["Flout: scoff at. Flout the law.","Flout: break openly."],"s":["contravene","scorn"]},{"w":"heterogeneous","p":"adj.","m":"Diverse in character.","e":"Greek <i>heterogenēs</i>: <i>heteros</i> (other) + <i>genos</i>.","f":"hétérogène","t":"Same as « hétérogène ».","h":["Heteros + genos: other kinds. A heterogeneous crowd.","Heterogeneous: mixed."],"s":["disparate","divergent"]},{"w":"hierarchy","p":"n.","m":"A system of ranked levels.","e":"Greek <i>hierarkhia</i> (rule of a high priest): <i>hieros</i> (sacred) + <i>arkhein</i> (to rule).","f":"hiérarchie","t":"Same as « hiérarchie ».","h":["Hieros + arkhe: sacred rule. Corporate hierarchy.","Hierarchy: ladder of ranks."],"s":[]},{"w":"hyperbole","p":"n.","m":"Deliberate exaggeration.","e":"Greek <i>hyperbolē</i> (excess): <i>hyper</i> (beyond) + <i>ballein</i> (to throw).","f":"hyperbole, exagération","t":"Throwing beyond: « hyperbole ».","h":["Hyper + ballein: throw beyond. “Million times” is hyperbole.","Hyperbole: overstatement."],"s":[]},{"w":"incorporate","p":"v.","m":"To include as part of a whole.","e":"Latin <i>incorporare</i>, from <i>corpus</i> (body).","f":"incorporer, intégrer","t":"In + corpus = into the body: incorporating feedback into the final deck.","h":["In + corpus: into a body. Incorporate comments.","Incorporate: blend in."],"s":["subsume"]},{"w":"indelible","p":"adj.","m":"Impossible to remove or forget.","e":"Latin <i>indelebilis</i>: <i>in-</i> + <i>delere</i> (to erase).","f":"indélébile","t":"Same as « indélébile ».","h":["In + delere: can’t erase. An indelible mark.","Indelible: permanent ink."],"s":["ingrained"]},{"w":"indifferent","p":"adj.","m":"Uninterested; also mediocre.","e":"Latin <i>indifferens</i> (not differing).","f":"indifférent; médiocre","x":"2nd meaning","t":"GRE trap: an indifferent cook = a mediocre one.","h":["Not different enough: also so-so. An indifferent meal.","Indifferent: unconcerned or mediocre."],"s":["aloof","apathetic","nonchalant"]},{"w":"indolent","p":"adj.","m":"Lazy.","e":"Late Latin <i>indolentem</i> (insensitive to pain): <i>in-</i> + <i>dolere</i> (to suffer).","f":"indolent, paresseux","t":"« Indolent »: too comfortable to move.","h":["In + dolere: no pain, no effort. An indolent afternoon.","Indolent: lazy."],"s":["lethargic","sluggish"]},{"w":"lament","p":"v. / n.","m":"To mourn; express regret.","e":"Latin <i>lamentari</i>.","f":"se lamenter, déplorer","t":"Same as « lamentation ».","h":["Lamentum: wail. Lament the loss.","Lament: sad song."],"s":["bemoan","dirge","elegy"]},{"w":"laud","p":"v.","m":"To praise highly.","e":"Latin <i>laudare</i>.","f":"louer, encenser","t":"Laud = « louer ».","h":["Laus: praise. Laud the winner.","Laud: applaud."],"s":["acclaim","exalt","extol","hail","lionize"]},{"w":"negate","p":"v.","m":"To nullify; to deny.","e":"Latin <i>negare</i> (to deny).","f":"annuler, nier","t":"Negate = « nier », cancel out: one bad quarter can negate a year of growth.","h":["Negare: deny. Negate the effect.","Negate: cancel."],"s":["belie","countermand","debunk","gainsay","neutralize","nullify","quash","refute"]},{"w":"neophyte","p":"n.","m":"A beginner.","e":"Greek <i>neophytos</i> (newly planted): <i>neos</i> + <i>phyein</i>.","f":"néophyte, novice","t":"Same as « néophyte ».","h":["Neo + phyton: new plant. A neophyte skier.","Neophyte: beginner."],"s":["callow","fledgling","nascent","tyro"]},{"w":"orthodox","p":"adj.","m":"Conforming to established beliefs.","e":"Greek <i>orthodoxos</i>: <i>orthos</i> (right) + <i>doxa</i> (opinion).","f":"orthodoxe","t":"Ortho (right, as in orthographe) + doxa (opinion): the correct, approved opinion.","h":["Ortho + doxa: right opinion. Orthodox views.","Orthodox: conventional."],"s":["conventional"]},{"w":"permeate","p":"v.","m":"To spread throughout.","e":"Latin <i>permeare</i> (to pass through).","f":"imprégner, pénétrer","t":"Permeable: seeping through everything.","h":["Per + meare: pass through. Smoke permeated the room.","Permeate: seep through."],"s":[]},{"w":"pervasive","p":"adj.","m":"Spreading widely throughout.","e":"Latin <i>pervadere</i> (to go through).","f":"omniprésent, envahissant","t":"Pervading everything.","h":["Per + vadere: go through. Pervasive corruption.","Pervasive: everywhere."],"s":["invasive","omnipresent","rampant","ubiquitous","universal"]},{"w":"precursor","p":"n.","m":"Something that comes before and leads to another.","e":"Latin <i>praecursor</i> (forerunner): <i>prae</i> + <i>currere</i> (to run).","f":"précurseur","t":"Same as « précurseur ».","h":["Pre + currere: runs before. A precursor of the internet.","Precursor: forerunner."],"s":["harbinger"]},{"w":"proliferate","p":"v.","m":"To increase rapidly.","e":"French <i>prolifère</i>, Latin <i>proles</i> (offspring).","f":"proliférer","t":"Same as « proliférer ».","h":["Proles + ferre: bear offspring. Rumours proliferate.","Proliferate: multiply."],"s":["abound","burgeon"]},{"w":"propensity","p":"n.","m":"A natural tendency.","e":"Latin <i>propensus</i> (inclined), from <i>propendere</i> (to hang forward).","f":"propension","t":"Same as « propension ».","h":["Pro + pendere: lean forward. A propensity to worry.","Propensity: tendency."],"s":["penchant","predilection","proclivity"]},{"w":"rarefy","p":"v.","m":"To make thinner or more refined.","e":"Latin <i>rarefacere</i>: <i>rarus</i> (thin) + <i>facere</i>.","f":"raréfier","t":"« L’air raréfié » at altitude.","h":["Rarus: thin. Rarefied air.","Rarefy: make thinner."],"s":["attenuate","refine"]},{"w":"recant","p":"v.","m":"To formally withdraw a belief.","e":"Latin <i>recantare</i> (to sing back, revoke).","f":"se rétracter, abjurer","t":"Galileo forced to recant.","h":["Re + cantare: sing again, take back. Recant testimony.","Recant: withdraw."],"s":["abjure","renounce","rescind","retract"]},{"w":"satirize","p":"v.","m":"To mock with humour or irony.","e":"Latin <i>satira</i> (a mixed dish, medley).","f":"satiriser, tourner en dérision","t":"« Satire ».","h":["Satura: medley. Satirize politicians.","Satirize: mock."],"s":["caricature","deride","lampoon"]},{"w":"scant","p":"adj.","m":"Barely sufficient.","e":"Old Norse <i>skamt</i> (short).","f":"insuffisant, maigre","t":"Scant evidence = « peu de preuves ».","h":["Scant: barely enough. Scant praise.","Scant: meagre."],"s":["economical","frugal","paltry","sparse","stinting","wanting"]},{"w":"stigma","p":"n.","m":"A mark of disgrace.","e":"Greek <i>stigma</i> (mark made by a pointed tool, brand).","f":"stigmate, opprobre","t":"Branded: « stigmatiser ».","h":["Stigma: brand mark. The stigma of illness.","Stigma: shame."],"s":["censure","opprobrium"]},{"w":"subjugate","p":"v.","m":"To bring under domination.","e":"Latin <i>subiugare</i> (to put under the yoke, <i>iugum</i>).","f":"subjuguer, asservir","t":"Under the yoke (joug).","h":["Sub + jugum: under the yoke. Subjugate a people.","Subjugate: conquer."],"s":["enchant","enthrall","mesmerize","vanquish"]},{"w":"sublime","p":"adj.","m":"Of great beauty or excellence.","e":"Latin <i>sublimis</i> (lofty).","f":"sublime","t":"Same as « sublime ».","h":["Sublimis: lofty. A sublime view.","Sublime: breathtaking."],"s":["esoteric","rarefied"]},{"w":"subside","p":"v.","m":"To become less intense.","e":"Latin <i>subsidere</i> (to settle down).","f":"s’apaiser, se calmer","t":"The storm subsides, settles down.","h":["Sub + sidere: settle down. The flood subsided.","Subside: calm down."],"s":["abate","wane"]},{"w":"succinct","p":"adj.","m":"Brief and clearly expressed.","e":"Latin <i>succinctus</i> (girded up, tucked in).","f":"succinct","t":"Same as « succinct ».","h":["Succinctus: girded up. A succinct summary.","Succinct: brief."],"s":["laconic","pithy","sententious","terse"]},{"w":"supersede","p":"v.","m":"To replace something older.","e":"Latin <i>supersedere</i> (to sit above).","f":"remplacer, supplanter","t":"Sitting above the old one.","h":["Super + sedere: sit above. Supersede the old rules.","Supersede: replace."],"s":["forestall","oust","preempt","supplant"]},{"w":"surmise","p":"v.","m":"To suppose without evidence.","e":"Old French <i>surmettre</i> (to accuse).","f":"conjecturer, supposer","t":"A guess put on top.","h":["Sur + mettre: put on. I surmise he left.","Surmise: guess."],"s":["speculate"]},{"w":"table","p":"v.","m":"To postpone consideration (US); to propose (UK).","e":"Latin <i>tabula</i> (board).","f":"ajourner; mettre sur la table","x":"2nd meaning","t":"US: tabling = putting aside. UK: putting on the table.","h":["Table: US postpone, UK propose. Table the motion.","Table: a trap word."],"s":[]},{"w":"utilitarian","p":"adj.","m":"Designed to be useful rather than attractive.","e":"From utility, Latin <i>utilis</i>.","f":"utilitaire, fonctionnel","t":"« Utilitaire ».","h":["Utile: useful. A utilitarian design.","Utilitarian: practical."],"s":["pragmatic"]},{"w":"virtuoso","p":"n.","m":"A highly skilled person, especially in music.","e":"Italian <i>virtuoso</i> (skilled), Latin <i>virtus</i>.","f":"virtuose","t":"Same as « virtuose ».","h":["Virtus: skill. A violin virtuoso.","Virtuoso: master."],"s":["adept","consummate"]},{"w":"virulent","p":"adj.","m":"Extremely severe or hostile.","e":"Latin <i>virulentus</i>, from <i>virus</i> (poison).","f":"virulent","t":"Same as « virulent ».","h":["Virus: poison. Virulent criticism.","Virulent: harsh and harmful."],"s":["acerbic","acrimonious","caustic","scathing","vitriolic"]},{"w":"viscous","p":"adj.","m":"Thick and sticky.","e":"Latin <i>viscosus</i>, from <i>viscum</i> (birdlime, mistletoe).","f":"visqueux","t":"Same as « visqueux ».","h":["Viscum: mistletoe glue. Viscous oil.","Viscous: sticky."],"s":[]},{"w":"watershed","p":"n.","m":"A turning point.","e":"German <i>Wasserscheide</i> (water-parting): the ridge dividing river basins.","f":"tournant, moment décisif","t":"The ridge where water flows one way or the other.","h":["Water + shed: divide. A watershed election.","Watershed: turning point."],"s":[]},{"w":"winnow","p":"v.","m":"To reduce a group by removing the least desirable.","e":"Old English <i>windwian</i> (to fan), from <i>wind</i>: blowing chaff from grain.","f":"trier, faire le tri","t":"Wind blowing chaff away: winnowing the shortlist.","h":["Winnow: fan the grain. Winnow the list.","Winnow: sort out."],"s":[]}]},{"name":"Basic IX","slug":"basic-ix","series":"Basic","words":[{"w":"abhor","p":"v.","m":"To regard with disgust.","e":"Latin <i>abhorrere</i> (to shrink back in horror): <i>ab</i> + <i>horrere</i> (to bristle).","f":"abhorrer, avoir en horreur","t":"« Avoir en horreur »: your hair bristles.","h":["Ab + horrere: bristle in horror. I abhor spiders.","Abhor: shudder."],"s":["execrate","loathe"]},{"w":"abscond","p":"v.","m":"To leave secretly, often with stolen goods.","e":"Latin <i>abscondere</i> (to hide away).","f":"s’enfuir, décamper","t":"Same root as « abscons »: hiding away with the money.","h":["Abs + condere: hide away. The cashier absconded with the cash.","Abscond: run off with it."],"s":[]},{"w":"adhere","p":"v.","m":"To stick to; to follow a rule.","e":"Latin <i>adhaerere</i> (to stick to).","f":"adhérer, respecter","t":"Same as « adhérer ».","h":["Ad + haerere: stick to. Adhere to the rules.","Adhere: glue."],"s":["abide","acquiesce","comply"]},{"w":"aggregate","p":"n. / adj.","m":"A whole formed by combining elements; total.","e":"Latin <i>aggregare</i> (to add to a flock): <i>ad</i> + <i>grex</i>.","f":"ensemble, total, agrégat","t":"Adding to the flock (grex).","h":["Ad + grex: to the flock. Aggregate data.","Aggregate: sum total."],"s":[]},{"w":"autonomous","p":"adj.","m":"Self-governing; independent.","e":"Greek <i>autonomos</i>.","f":"autonome","t":"Same as « autonome ».","h":["Auto + nomos: self-rule. Autonomous region.","Autonomous: independent."],"s":[]},{"w":"bastion","p":"n.","m":"A stronghold of a belief or quality.","e":"French <i>bastion</i>, Italian <i>bastione</i>, from <i>bastire</i> (to build).","f":"bastion","t":"Same as « bastion ».","h":["Bastir: build. A bastion of freedom.","Bastion: stronghold."],"s":[]},{"w":"conciliatory","p":"adj.","m":"Intended to placate.","e":"Latin <i>conciliare</i> (to bring together).","f":"conciliant","t":"« Conciliant ».","h":["Concilier: bring together. A conciliatory gesture.","Conciliatory: peace-making."],"s":[]},{"w":"contention","p":"n.","m":"Heated disagreement; an assertion.","e":"Latin <i>contentio</i> (strife), from <i>contendere</i>.","f":"différend; affirmation","t":"Bone of contention = « pomme de discorde ».","h":["Contendere: strive. A bone of contention.","Contention: argument."],"s":["acrimony","discord","strife"]},{"w":"credulous","p":"adj.","m":"Too ready to believe.","e":"Latin <i>credulus</i>.","f":"crédule","t":"Same as « crédule ».","h":["Credere: believe. Credulous fools.","Credulous: gullible."],"s":["artless","gullible","ingenuous","naive"]},{"w":"deference","p":"n.","m":"Humble respect.","e":"French <i>déférence</i>.","f":"déférence","t":"Same as « déférence ».","h":["De + ferre: bring down. Defer to elders.","Deference: courteous respect."],"s":["obeisance"]},{"w":"discretion","p":"n.","m":"Freedom to decide; also tact.","e":"Latin <i>discretio</i> (separation, discernment).","f":"discrétion; libre appréciation","t":"« À votre discrétion ».","h":["Discretus: judgment. Use your discretion.","Discretion: tact."],"s":["latitude","tact"]},{"w":"diverge","p":"v.","m":"To separate and go in different directions.","e":"Medieval Latin <i>divergere</i> (to incline apart).","f":"diverger","t":"Same as « diverger ».","h":["Di + vergere: bend apart. Paths diverge.","Diverge: split."],"s":["deviate"]},{"w":"dogma","p":"n.","m":"Principles laid down as undeniably true.","e":"Greek <i>dogma</i> (opinion, decree).","f":"dogme","t":"Same as « dogme ».","h":["Dogma: opinion. Religious dogma.","Dogma: unquestioned belief."],"s":[]},{"w":"dour","p":"adj.","m":"Stern and gloomy.","e":"Scots, probably from Latin <i>durus</i> (hard).","f":"austère, sévère, renfrogné","t":"Hard (dur) and gloomy.","h":["Dur: hard. A dour Scot.","Dour: gloomy."],"s":["austere","glum","morose","saturnine","stern","sullen","surly","taciturn"]},{"w":"egalitarian","p":"adj.","m":"Believing in equality.","e":"French <i>égalitaire</i>, from <i>égal</i>.","f":"égalitaire","t":"Liberté, égalité…","h":["Égalité. An egalitarian society.","Egalitarian: all equal."],"s":[]},{"w":"enigma","p":"n.","m":"A mysterious person or thing.","e":"Greek <i>ainigma</i> (riddle).","f":"énigme","t":"Same as « énigme ».","h":["Ainigma: riddle. The Enigma machine.","Enigma: puzzle."],"s":["conundrum","quandary"]},{"w":"facade","p":"n.","m":"A deceptive outward appearance.","e":"French <i>façade</i>, from Italian <i>facciata</i>, <i>faccia</i> (face).","f":"façade","t":"Same as « façade ».","h":["Façade: face. A facade of calm.","Facade: front."],"s":["semblance","veneer"]},{"w":"implore","p":"v.","m":"To beg urgently.","e":"Latin <i>implorare</i>: <i>in</i> + <i>plorare</i> (to weep).","f":"implorer","t":"Weeping (pleurer) while begging.","h":["Im + plorare: weep to. Implore forgiveness.","Implore: beg."],"s":["beg","entreat","importune","supplicate"]},{"w":"inert","p":"adj.","m":"Lacking ability or will to move.","e":"Latin <i>iners</i> (unskilled, idle): <i>in-</i> + <i>ars</i>.","f":"inerte","t":"Same as « inerte ».","h":["In + ars: no skill/activity. An inert gas.","Inert: motionless."],"s":["docile","dormant","lethargic","passive","quiescent","sluggish"]},{"w":"inherent","p":"adj.","m":"Existing as a permanent, essential attribute.","e":"Latin <i>inhaerere</i> (to stick in).","f":"inhérent","t":"Same as « inhérent ».","h":["In + haerere: stick in. Inherent risk.","Inherent: built in."],"s":["implicit","inborn","intrinsic","tacit"]},{"w":"insular","p":"adj.","m":"Narrow-minded; isolated.","e":"Latin <i>insula</i> (island).","f":"insulaire, fermé","t":"Island mentality.","h":["Insula: island. Insular attitudes.","Insular: cut off."],"s":["blinkered","chauvinistic","parochial","provincial","rustic","xenophobic"]},{"w":"judicious","p":"adj.","m":"Having good judgment.","e":"French <i>judicieux</i>, Latin <i>iudicium</i>.","f":"judicieux","t":"Same as « judicieux ».","h":["Judicium: judgment. A judicious choice.","Judicious: wise."],"s":["astute","canny","circumspect","discreet","expedient","perspicacious","politic","prudent","sagacious","shrewd","wary"]},{"w":"levity","p":"n.","m":"Humour or lack of seriousness.","e":"Latin <i>levitas</i> (lightness), <i>levis</i>.","f":"légèreté","t":"Lightness: « légèreté ».","h":["Levis: light. Levity at a funeral.","Levity: jokiness."],"s":[]},{"w":"luminous","p":"adj.","m":"Full of light; very clear.","e":"Latin <i>luminosus</i>, from <i>lumen</i>.","f":"lumineux","t":"Same as « lumineux ».","h":["Lumen: light. A luminous smile.","Luminous: glowing."],"s":[]},{"w":"naive","p":"adj.","m":"Lacking experience or judgment.","e":"French <i>naïve</i>, Latin <i>nativus</i> (native, natural).","f":"naïf","t":"Same as « naïf ».","h":["Nativus: native. Naive trust.","Naive: unworldly."],"s":["artless","candid","credulous","guileless","gullible","ingenuous","insipid","jejune","puerile","vapid"]},{"w":"notoriety","p":"n.","m":"Fame for something bad.","e":"Medieval Latin <i>notorietas</i>, from <i>notus</i> (known).","f":"mauvaise réputation","x":"Faux ami","t":"French « notoriété » is neutral; English notoriety is bad fame.","h":["Notus: known. Notoriety for scandal.","Notoriety: infamous."],"s":[]},{"w":"opine","p":"v.","m":"To state an opinion.","e":"Latin <i>opinari</i>.","f":"opiner, déclarer","t":"« Opiner ».","h":["Opinari: think. Opine on politics.","Opine: voice a view."],"s":["aver"]},{"w":"oscillate","p":"v.","m":"To swing back and forth; to waver.","e":"Latin <i>oscillare</i> (to swing).","f":"osciller","t":"Same as « osciller ».","h":["Oscillum: swing. Oscillate between moods.","Oscillate: swing."],"s":["equivocate","vacillate"]},{"w":"painstaking","p":"adj.","m":"Done with great care.","e":"English <i>pains</i> + <i>taking</i>: taking pains.","f":"minutieux","t":"Taking pains over every detail.","h":["Pains + taking. Painstaking research.","Painstaking: meticulous."],"s":["assiduous","diligent","exhaustive","fastidious","industrious","meticulous","punctilious","scrupulous","sedulous","thorough"]},{"w":"penchant","p":"n.","m":"A strong liking.","e":"French <i>penchant</i>, from <i>pencher</i> (to lean).","f":"penchant","t":"Same as « penchant ».","h":["Pencher: lean. A penchant for jazz.","Penchant: leaning."],"s":["predilection","proclivity","propensity"]},{"w":"pious","p":"adj.","m":"Devoutly religious; sometimes hypocritically virtuous.","e":"Latin <i>pius</i> (dutiful).","f":"pieux","t":"« Pieux ».","h":["Pius: devout. A pious family.","Pious: devout."],"s":["deferential","reverent","sanctimonious","smug"]},{"w":"plastic","p":"adj.","m":"Easily shaped; adaptable.","e":"Greek <i>plastikos</i> (fit for moulding), from <i>plassein</i>.","f":"malléable, plastique","x":"2nd meaning","t":"Neuroplasticity: the brain reshaping.","h":["Plassein: mould. Plastic arts; plastic mind.","Plastic: shapeable."],"s":["malleable","pliant","tractable"]},{"w":"plummet","p":"v.","m":"To fall straight down rapidly.","e":"Old French <i>plommet</i> (plumb line weight), from <i>plomb</i> (lead).","f":"chuter, s’effondrer","t":"Falling like lead (plomb).","h":["Plomb: lead. Prices plummeted.","Plummet: plunge."],"s":[]},{"w":"prudent","p":"adj.","m":"Acting with care for the future.","e":"Latin <i>prudens</i> (foreseeing).","f":"prudent","t":"Same as « prudent ».","h":["Providens: foreseeing. A prudent saver.","Prudent: careful."],"s":["astute","canny","chary","circumspect","discreet","economical","expedient","frugal","judicious","leery","perspicacious","politic","provident","sagacious","shrewd","thrifty","wary"]},{"w":"rhetoric","p":"n.","m":"Persuasive language, often insincere.","e":"Greek <i>rhētorikē</i>, art of the orator (<i>rhētōr</i>).","f":"rhétorique","t":"Same as « rhétorique ».","h":["Rhetor: orator. Empty rhetoric.","Rhetoric: speech craft."],"s":["pomposity"]},{"w":"savor","p":"v.","m":"To enjoy fully.","e":"Old French <i>savourer</i>, Latin <i>sapor</i> (taste).","f":"savourer","t":"Same as « savourer ».","h":["Savourer: taste. Savor the moment.","Savor: relish."],"s":["relish"]},{"w":"secrete","p":"v.","m":"To produce and discharge; also to hide.","e":"Latin <i>secernere</i> (to separate).","f":"sécréter; cacher","x":"2nd meaning","t":"Hide like a secret.","h":["Secernere: separate. Glands secrete hormones.","Secrete: produce or hide."],"s":[]},{"w":"sentient","p":"adj.","m":"Able to perceive or feel.","e":"Latin <i>sentiens</i>, from <i>sentire</i>.","f":"sensible, doué de sensibilité","t":"Feeling (sentir).","h":["Sentire: feel. Sentient beings.","Sentient: conscious."],"s":[]},{"w":"shard","p":"n.","m":"A broken piece of pottery or glass.","e":"Old English <i>sceard</i> (cleft). Germanic.","f":"éclat, tesson","t":"A shard is a sharp broken piece, « un tesson » of glass or pottery.","h":["Sceard: notch. A shard of glass.","Shard: sharp piece."],"s":[]},{"w":"skeptic","p":"n.","m":"A person inclined to doubt.","e":"Greek <i>skeptikos</i> (inquiring).","f":"sceptique","t":"Same as « sceptique ».","h":["Skeptikos: inquirer. A skeptic doubts.","Skeptic: doubter."],"s":[]},{"w":"slight","p":"v. / n.","m":"To insult by ignoring; an insult.","e":"Old Norse <i>sléttr</i> (smooth, level).","f":"offenser, snober; affront","x":"2nd meaning","t":"To treat as slight (unimportant).","h":["Slight: small; to snub. A slight to his pride.","Slight: insult."],"s":["affront","remote","snub","spurn","tenuous"]},{"w":"stint","p":"n. / v.","m":"A period of work; to be sparing.","e":"Old English <i>styntan</i> (to blunt, dull).","f":"période, passage; lésiner","t":"A stint at Bain; don’t stint on effort.","h":["Stint: limit. A two-year stint.","Stint: short period."],"s":[]},{"w":"striated","p":"adj.","m":"Marked with lines or grooves.","e":"Latin <i>striatus</i>, from <i>stria</i> (furrow).","f":"strié","t":"Same as « strié ».","h":["Stria: furrow. Striated muscle.","Striated: grooved."],"s":[]},{"w":"substantiate","p":"v.","m":"To provide evidence for.","e":"Latin <i>substantia</i> (substance).","f":"étayer, prouver","t":"Give substance to a claim: « étayer » it with evidence.","h":["Substantia: substance. Substantiate a claim.","Substantiate: back up."],"s":["corroborate"]},{"w":"terse","p":"adj.","m":"Brief to the point of rudeness.","e":"Latin <i>tersus</i> (wiped clean, neat).","f":"laconique, sec","t":"Wiped clean of extra words.","h":["Tersus: wiped. A terse reply.","Terse: curt."],"s":["aphoristic","laconic","pithy","sententious","succinct"]},{"w":"ubiquitous","p":"adj.","m":"Present everywhere.","e":"Latin <i>ubique</i> (everywhere).","f":"omniprésent, ubiquitaire","t":"« Ubiquité ».","h":["Ubique: everywhere. Ubiquitous smartphones.","Ubiquitous: omnipresent."],"s":["omnipresent","pervasive","rampant","universal"]},{"w":"unfettered","p":"adj.","m":"Free, unrestricted.","e":"<i>un-</i> + fetter (chain), Old English <i>feter</i>.","f":"sans entraves","t":"Fetters = chains on the feet. Unfettered = chains off: unfettered capitalism.","h":["Fetter: chain. Unfettered access.","Unfettered: free."],"s":["untrammeled"]},{"w":"viable","p":"adj.","m":"Capable of working successfully.","e":"French <i>viable</i>, from <i>vie</i>.","f":"viable","t":"Same as « viable ».","h":["Vita: life. A viable plan.","Viable: can work."],"s":["feasible","plausible","sound","tenable"]},{"w":"yoke","p":"n. / v.","m":"A bond or burden; to join together.","e":"Old English <i>geoc</i>, cousin of Latin <i>iugum</i>.","f":"joug","t":"« Le joug ».","h":["Yoke: oxen’s collar. The yoke of tyranny.","Yoke: burden."],"s":[]},{"w":"zeal","p":"n.","m":"Great energy for a cause.","e":"Greek <i>zēlos</i>.","f":"zèle","t":"Same as « zèle ».","h":["Zelos: ardour. Missionary zeal.","Zeal: passion."],"s":["fervor"]}]},{"name":"Advanced I","slug":"advanced-i","series":"Advanced","words":[{"w":"alacrity","p":"n.","m":"Brisk and cheerful readiness.","e":"Latin <i>alacritas</i>, from <i>alacer</i> (lively, eager), which gave French <i>allègre</i>.","f":"empressement, entrain","t":"Alacer → « allègre »: accepting with alacrity = « avec empressement ».","h":["Alacer: brisk. She accepted with alacrity.","Alacrity: bounces up to say yes."],"s":["celerity","dispatch"]},{"w":"anathema","p":"n.","m":"Something or someone vehemently disliked.","e":"Greek <i>anathema</i> (thing devoted to evil, accursed). The Church’s formal curse and excommunication.","f":"anathème, bête noire","t":"« Jeter l’anathème »: cursed by the Church. Lying is anathema to her.","h":["Anathema: cursed. Lying is anathema to him.","Anathema: the thing you can’t stand."],"s":["malediction"]},{"w":"apogee","p":"n.","m":"The highest point; climax.","e":"Greek <i>apogaion</i> (away from the earth): <i>apo</i> + <i>gē</i>. A moon’s farthest point from Earth.","f":"apogée","t":"Same as « apogée ».","h":["Apo + gaia: away from earth. The apogee of his career.","Apogee: the top of the orbit."],"s":["acme","apex","apotheosis","pinnacle","summit","zenith"]},{"w":"apostate","p":"n.","m":"A person who renounces a belief or party.","e":"Greek <i>apostatēs</i> (deserter): <i>apo</i> (away) + <i>histanai</i> (to stand).","f":"apostat, renégat","t":"Standing away from the faith: « apostat ».","h":["Apo + stasis: standing away. An apostate leaves the faith.","Apostate: turncoat."],"s":["dissident","heretic","heterodox","iconoclast"]},{"w":"arrant","p":"adj.","m":"Complete, utter (arrant nonsense).","e":"Variant of <i>errant</i> (wandering): an “arrant thief” was a roving outlaw; then just “notorious, utter”.","f":"fieffé, pur, total","t":"Arrant nonsense = « une pure absurdité ». « Un fieffé menteur ».","h":["Arrant = errant, thorough. An arrant fool.","Arrant: complete, utter."],"s":["exhaustive","thoroughgoing"]},{"w":"artless","p":"adj.","m":"Without guile; natural and simple.","e":"<i>art</i> (skill, artifice) + <i>-less</i>.","f":"naturel, ingénu","t":"No artifice: opposite of artful (Common I).","h":["Without art or trickery. An artless smile.","Artless: simple."],"s":["candid","credulous","guileless","gullible","ingenuous","naive"]},{"w":"attenuate","p":"v.","m":"To reduce the force or effect of.","e":"Latin <i>attenuare</i> (to make thin): <i>ad</i> + <i>tenuis</i>.","f":"atténuer","t":"Same as « atténuer ».","h":["Ad + tenuis: thin. Attenuate the sound.","Attenuate: weaken."],"s":["rarefy"]},{"w":"base","p":"adj.","m":"Without moral principles; ignoble.","e":"Late Latin <i>bassus</i> (low).","f":"bas, vil, ignoble","x":"2nd meaning","t":"Low (« bas »): base motives. Base metals vs noble ones.","h":["Bas: low. Base motives.","Base: low-minded."],"s":["ignoble","sordid"]},{"w":"beg","p":"v.","m":"To evade (beg the question = assume what is to be proved).","e":"Middle English <i>beggen</i>; “beg the question” translates Latin <i>petitio principii</i>.","f":"éluder; pétition de principe","x":"2nd meaning","t":"Begging the question = « une pétition de principe »: circular logic.","h":["To beg the question: dodge it by circular logic.","Beg the question: assume what you must prove."],"s":["badger","cadge","entreat","implore","importune","supplicate"]},{"w":"byzantine","p":"adj.","m":"Excessively complicated; devious.","e":"From Byzantium, whose imperial court was famous for complex intrigue and bureaucracy.","f":"byzantin, alambiqué","t":"« Des querelles byzantines »: the labyrinthine Byzantine court.","h":["Byzantium’s court: intrigue. A byzantine bureaucracy.","Byzantine: tangled."],"s":["convoluted","involved","sinuous","tortuous"]},{"w":"catholic","p":"adj.","m":"Wide-ranging; universal (lower-case c).","e":"Greek <i>katholikos</i> (universal): <i>kata</i> + <i>holos</i> (whole).","f":"éclectique, universel","x":"2nd meaning","t":"Catholic tastes = eclectic, covering the whole (holos).","h":["Katholikos: universal. Catholic tastes.","Catholic: wide-ranging."],"s":["eclectic","universal"]},{"w":"chary","p":"adj.","m":"Cautiously reluctant.","e":"Old English <i>cearig</i> (sorrowful, careful), from <i>caru</i> (care).","f":"méfiant, réticent, prudent","t":"Chary = full of care, cautious: chary of giving out his number.","h":["Chary = care. Chary of strangers.","Chary: wary."],"s":["circumspect","leery","loath","prudent","vigilant","wary"]},{"w":"choleric","p":"adj.","m":"Bad-tempered, irritable.","e":"Greek <i>kholērikos</i>, from <i>kholē</i> (yellow bile), the humour of anger.","f":"colérique","t":"Yellow bile → « colère ».","h":["Khole: bile. A choleric colonel.","Choleric: angry."],"s":["bilious","irascible","peevish","petulant","splenetic","sullen","surly"]},{"w":"churlish","p":"adj.","m":"Rude and mean-spirited.","e":"Old English <i>ceorl</i> (peasant, low-born man).","f":"grossier, mal élevé","t":"Behaving like a churl (lowly peasant): churlish to refuse.","h":["Churl: boor. A churlish reply.","Churlish: rude."],"s":["boorish","morose","sullen","surly"]},{"w":"conciliate","p":"v.","m":"To placate; to win over.","e":"Latin <i>conciliare</i> (to bring together).","f":"concilier, apaiser","t":"Same as « concilier ».","h":["Conciliare: unite. Conciliate the parties.","Conciliate: win over."],"s":["appease","assuage","mollify","pacify","placate","propitiate","reconcile"]},{"w":"contentious","p":"adj.","m":"Causing or likely to cause argument.","e":"Latin <i>contentiosus</i>, from <i>contentio</i> (strife).","f":"controversé, litigieux","t":"« Contentieux »: a dispute.","h":["Contend: argue. A contentious issue.","Contentious: provokes argument."],"s":["bellicose","belligerent","factious","partisan","polemical","pugnacious","truculent"]},{"w":"cow","p":"v.","m":"To intimidate into submission.","e":"Probably Old Norse <i>kúga</i> (to oppress).","f":"intimider, terroriser","x":"2nd meaning","t":"Cowed into silence: made meek as a cow.","h":["Cow: scare. Cowed by the bully.","Cow: browbeat."],"s":["browbeat","hector"]},{"w":"defray","p":"v.","m":"To pay costs.","e":"French <i>défrayer</i>: <i>de</i> + <i>frai</i> (expense).","f":"défrayer","t":"Same as « défrayer »: travel costs defrayed.","h":["De + frais: pay costs. Defray expenses.","Defray: foot the bill."],"s":[]},{"w":"diatribe","p":"n.","m":"A bitter verbal attack.","e":"Greek <i>diatribē</i> (pastime, discourse), from <i>diatribein</i> (to wear away).","f":"diatribe","t":"Same as « diatribe ».","h":["Dia + tribein: wear away. A diatribe against taxes.","Diatribe: rant."],"s":["broadside","harangue","invective","polemic","screed","tirade","vitriol"]},{"w":"equivocate","p":"v.","m":"To use ambiguous language to conceal the truth.","e":"Late Latin <i>aequivocare</i> (to call by the same name).","f":"tergiverser, user d’équivoques","t":"Speaking with two equal voices.","h":["Equi + vocare: equal voices. Don’t equivocate!","Equivocate: dodge."],"s":["evade","hedge","oscillate","prevaricate","quibble","vacillate"]},{"w":"exegesis","p":"n.","m":"Critical explanation of a text.","e":"Greek <i>exēgēsis</i> (explanation): <i>ex</i> + <i>hēgeisthai</i> (to lead).","f":"exégèse","t":"Same as « exégèse ».","h":["Ex + hegeisthai: lead out. Biblical exegesis.","Exegesis: close reading."],"s":[]},{"w":"expansive","p":"adj.","m":"Open and communicative; extensive.","e":"Latin <i>expandere</i> (to spread out).","f":"expansif, communicatif","t":"Same as « expansif ».","h":["Expand: spread out. An expansive mood.","Expansive: talkative."],"s":["candid","demonstrative","effusive","forthcoming","profuse"]},{"w":"expunge","p":"v.","m":"To erase completely.","e":"Latin <i>expungere</i> (to prick out). Scribes marked deletions with dots.","f":"effacer, supprimer","t":"Dots pricked under deleted words.","h":["Ex + pungere: prick out. Expunge the record.","Expunge: wipe."],"s":["eradicate"]},{"w":"factious","p":"adj.","m":"Inclined to dissension.","e":"Latin <i>factiosus</i>, from <i>factio</i> (party, faction).","f":"factieux","t":"Same as « factieux ». Not factitious (artificial).","h":["Facere: do. Factious parties split.","Factious: splintering."],"s":["contentious","partisan"]},{"w":"feckless","p":"adj.","m":"Lacking initiative; irresponsible.","e":"Scots <i>feck</i> (effect, value), short for effect + <i>-less</i>.","f":"incapable, irresponsable","t":"Feck = effect. Feckless = without effect: the feckless flatmate who never pays his share.","h":["Feck (effect) + less. A feckless youth.","Feckless: useless and irresponsible."],"s":["improvident","inept"]},{"w":"fractious","p":"adj.","m":"Irritable and quarrelsome; hard to control.","e":"From fraction in the old sense “discord”, Latin <i>frangere</i> (to break).","f":"rétif, querelleur","t":"Breaking into factions: a fractious coalition.","h":["Frangere: break. A fractious child.","Fractious: grumpy and unruly."],"s":["intractable","obstreperous","peevish","petulant","querulous","recalcitrant","refractory","restive","skittish","unruly"]},{"w":"hector","p":"v.","m":"To bully, talk to in an intimidating way.","e":"From Hector of Troy; in 17th-c. London, “Hectors” were swaggering street bullies.","f":"rudoyer, malmener","t":"Hector of Troy: in 17th-century London, “hectors” were swaggering street bullies.","h":["Hector: Trojan hero turned bully. Hector the staff.","Hector: intimidate."],"s":["badger","browbeat","cow","dog","hound","importune"]},{"w":"imbibe","p":"v.","m":"To drink; to absorb ideas.","e":"Latin <i>imbibere</i>: <i>in</i> + <i>bibere</i> (to drink).","f":"boire; s’imprégner de","t":"« Imbiber », « biberon ».","h":["In + bibere: drink in. Imbibe wine; imbibe ideas.","Imbibe: absorb."],"s":[]},{"w":"indigent","p":"adj.","m":"Poor, needy.","e":"Latin <i>indigentem</i> (in need).","f":"indigent","t":"Same as « indigent ».","h":["Indigere: need. An indigent family.","Indigent: needy."],"s":["destitute","impecunious","miserly","penurious"]},{"w":"insufferable","p":"adj.","m":"Too extreme to bear.","e":"<i>in-</i> + Latin <i>sufferre</i> (to endure).","f":"insupportable","t":"In + suffer: someone you cannot suffer (endure): « insupportable ».","h":["In + suffer: unbearable. An insufferable show-off.","Insufferable: can’t stand."],"s":[]},{"w":"jingoist","p":"n.","m":"An aggressive nationalist.","e":"From the 1878 music-hall song “by Jingo”.","f":"chauvin, nationaliste belliqueux","t":"The Victorian music-hall crowd singing for war.","h":["Jingo song. A jingoist yells “Our country first!”.","Jingoist: war-hungry patriot."],"s":["chauvinist"]},{"w":"kowtow","p":"v.","m":"To act in an excessively subservient way.","e":"Chinese <i>kòutóu</i> (knock head): touching the forehead to the ground before the emperor.","f":"se prosterner, courber l’échine","t":"Forehead on the floor before the emperor.","h":["Chinese ketou: knock the head. Kowtow to the boss.","Kowtow: grovel."],"s":["fawn","grovel"]},{"w":"lascivious","p":"adj.","m":"Feeling or showing overt sexual desire.","e":"Latin <i>lascivia</i> (playfulness, wantonness).","f":"lascif","t":"Same as « lascif ».","h":["Lascivus: wanton. A lascivious stare.","Lascivious: lustful."],"s":["bawdy","prurient","salacious"]},{"w":"malfeasance","p":"n.","m":"Wrongdoing, especially by a public official.","e":"Anglo-French <i>malfaisance</i>: <i>mal</i> + <i>faire</i>.","f":"malversation, prévarication","t":"« Malfaisance »: doing evil.","h":["Mal + faire: wrongdoing. Corporate malfeasance.","Malfeasance: official crime."],"s":[]},{"w":"nadir","p":"n.","m":"The lowest point.","e":"Arabic <i>naẓīr</i> (opposite), i.e. the point opposite the zenith.","f":"nadir, point le plus bas","t":"Nadir = the point right under your feet, opposite the zenith above your head.","h":["Arabic: opposite. The nadir of his career.","Nadir: rock bottom."],"s":[]},{"w":"overweening","p":"adj.","m":"Showing excessive confidence or pride.","e":"<i>over</i> + <i>ween</i> (to think, Old English <i>wēnan</i>). Thinking too much of oneself.","f":"outrecuidant, démesuré","t":"Over-thinking of yourself: overweening ambition.","h":["Over + ween (think): arrogant. Overweening pride.","Overweening: too proud."],"s":["brazen","haughty","hubris","presumptuous"]},{"w":"pariah","p":"n.","m":"An outcast.","e":"Tamil <i>paraiyar</i>, drummers at festivals, a caste treated as outcasts in colonial India.","f":"paria","t":"Same as « paria ».","h":["Tamil paraiyar: drummer caste. A social pariah.","Pariah: outcast."],"s":[]},{"w":"penurious","p":"adj.","m":"Extremely poor; also stingy.","e":"Latin <i>penuria</i> (want, scarcity).","f":"misérable; avare","t":"« Pénurie ».","h":["Penuria: want. Penurious students.","Penurious: broke or stingy."],"s":["avaricious","destitute","frugal","impecunious","indigent","miserly","parsimonious"]},{"w":"perfunctory","p":"adj.","m":"Done with minimum effort.","e":"Late Latin <i>perfunctorius</i> (careless), from <i>perfungi</i> (to get through, discharge).","f":"de pure forme, superficiel","t":"Just getting it done: a perfunctory nod.","h":["Per + fungi: get through. A perfunctory glance.","Perfunctory: going through the motions."],"s":["cursory","desultory","facile","glib","nominal","slapdash","superficial","token"]},{"w":"ponderous","p":"adj.","m":"Slow and clumsy because heavy; dull.","e":"Latin <i>ponderosus</i>, from <i>pondus</i> (weight).","f":"lourd, pesant","t":"Weighty (pondéré): ponderous prose.","h":["Pondus: weight. Ponderous speech.","Ponderous: heavy and slow."],"s":["arduous","cumbersome","onerous","plodding","taxing"]},{"w":"precipitate","p":"v. / adj.","m":"To cause to happen suddenly; hasty.","e":"Latin <i>praecipitare</i> (to throw headlong).","f":"précipiter; précipité","t":"Same as « précipiter ».","h":["Prae + caput: head first. A precipitate decision.","Precipitate: hasty."],"s":["engender","foolhardy","impetuous","impulsive","rash"]},{"w":"prosaic","p":"adj.","m":"Lacking imagination; ordinary.","e":"Late Latin <i>prosaicus</i>, from <i>prosa</i> (prose).","f":"prosaïque","t":"Same as « prosaïque ».","h":["Prosa: plain speech. A prosaic life.","Prosaic: unpoetic."],"s":["banal","humdrum","monotonous","mundane","pedestrian","quotidian","tedious"]},{"w":"saturnine","p":"adj.","m":"Gloomy, slow and serious.","e":"From Saturn, the planet said by astrologers to make people gloomy.","f":"sombre, taciturne","t":"Opposite of jovial (Jupiter).","h":["Saturn: gloomy. A saturnine face.","Saturnine: sullen."],"s":["dour","glum","morose","sullen","surly","taciturn"]},{"w":"sedulous","p":"adj.","m":"Showing dedication and diligence.","e":"Latin <i>sedulus</i> (zealous), perhaps <i>se dolo</i> (without guile).","f":"assidu, appliqué","t":"Sedulous ≈ assiduous: steady, careful, persevering work.","h":["Sedulus: persistent. A sedulous clerk.","Sedulous: diligent."],"s":["assiduous","diligent","indefatigable","industrious","painstaking"]},{"w":"supercilious","p":"adj.","m":"Behaving as if superior; haughty.","e":"Latin <i>supercilium</i> (eyebrow): raising the eyebrow in disdain.","f":"hautain, dédaigneux","t":"Raised eyebrows (sourcils).","h":["Super + cilium: raised eyebrow. A supercilious sneer.","Supercilious: looks down."],"s":["contemptuous","derisive","haughty","imperious","sardonic","snide"]},{"w":"truculent","p":"adj.","m":"Eager to argue or fight.","e":"Latin <i>truculentus</i> (fierce), from <i>trux</i> (savage).","f":"agressif, belliqueux (≠ truculent)","x":"Faux ami","t":"French « truculent » = colourful. English = aggressive.","h":["Trux: fierce. A truculent drunk.","Truculent: belligerent."],"s":["bellicose","belligerent","contentious","pugnacious"]},{"w":"turpitude","p":"n.","m":"Depravity, wickedness.","e":"Latin <i>turpitudo</i>, from <i>turpis</i> (base, shameful).","f":"turpitude","t":"Same as « turpitude ».","h":["Turpis: ugly. Moral turpitude.","Turpitude: baseness."],"s":["depravity"]},{"w":"untoward","p":"adj.","m":"Unexpected and inappropriate.","e":"<i>un-</i> + toward (promising, docile).","f":"fâcheux, malencontreux","t":"Nothing untoward = « rien d’anormal ».","h":["Not toward: improper. Nothing untoward happened.","Untoward: unexpected, unwelcome."],"s":["adverse","indecorous","inimical","unpropitious","unseemly"]},{"w":"vicissitude","p":"n.","m":"A change of circumstances, usually unwelcome.","e":"Latin <i>vicissitudo</i>, from <i>vicis</i> (change).","f":"vicissitude","t":"« Les vicissitudes de la vie ».","h":["Vicis: change. Vicissitudes of fortune.","Vicissitude: ups and downs."],"s":[]},{"w":"zeitgeist","p":"n.","m":"The spirit of the time.","e":"German <i>Zeitgeist</i>: <i>Zeit</i> (time) + <i>Geist</i> (spirit).","f":"air du temps","t":"« L’air du temps ».","h":["German: time-spirit. The zeitgeist of the 60s.","Zeitgeist: mood of an era."],"s":[]}]},{"name":"Advanced II","slug":"advanced-ii","series":"Advanced","words":[{"w":"apotheosis","p":"n.","m":"The highest point; perfect example; deification.","e":"Greek <i>apotheōsis</i>: <i>apo</i> + <i>theos</i> (god). Making someone a god.","f":"apothéose","t":"Same as « apothéose ».","h":["Apo + theos: becoming god. The apotheosis of the empire.","Apotheosis: the glorious peak."],"s":["acme","apex","apogee","epitome","paragon","pinnacle","summit","zenith"]},{"w":"arch","p":"adj.","m":"Deliberately playful or teasing; also chief.","e":"Greek <i>arkhi-</i> (chief), from <i>arkhein</i> (to rule). From “arch-rogue” it came to mean mischievous.","f":"malicieux, espiègle; principal","x":"2nd meaning","t":"An arch smile = « un sourire malicieux ».","h":["Arch: playful. An arch smile.","Arch: knowing, teasing."],"s":[]},{"w":"arriviste","p":"n.","m":"An ambitious, self-seeking newcomer.","e":"French <i>arriviste</i>, from <i>arriver</i>.","f":"arriviste","t":"Straight from French.","h":["Arriver: arrived. An arriviste networking.","Arriviste: social climber."],"s":["parvenu"]},{"w":"benighted","p":"adj.","m":"Ignorant, unenlightened.","e":"<i>be-</i> + night: overtaken by darkness.","f":"ignorant, obscurantiste","t":"Be + night: overtaken by the night of ignorance. « Obscurantiste ».","h":["Be + night: in darkness. Benighted peasants.","Benighted: ignorant."],"s":[]},{"w":"bilious","p":"adj.","m":"Bad-tempered; nauseous.","e":"Latin <i>biliosus</i>, from <i>bilis</i> (bile).","f":"bilieux, irritable","t":"« Se faire de la bile ».","h":["Bile: gall. A bilious critic.","Bilious: peevish."],"s":["choleric","irascible","peevish","petulant","splenetic","sullen","surly"]},{"w":"blinkered","p":"adj.","m":"Having a narrow outlook.","e":"From blinkers, eye shields on a horse’s bridle.","f":"borné, qui a des œillères","t":"« Avoir des œillères ».","h":["Blinkers on a horse. A blinkered view.","Blinkered: can’t see sides."],"s":["hidebound","insular","parochial","provincial"]},{"w":"cupidity","p":"n.","m":"Greed for money.","e":"Latin <i>cupiditas</i> (desire), from <i>cupere</i>; Cupid.","f":"cupidité","t":"Same as « cupidité ».","h":["Cupid: desire. Cupidity for gold.","Cupidity: greed."],"s":["avarice"]},{"w":"curmudgeon","p":"n.","m":"A bad-tempered, surly person.","e":"Origin unknown (16th c.).","f":"grincheux, vieux ronchon","t":"Sounds grumpy: the curmudgeonly neighbour.","h":["Curmudgeon: crusty old person. A curmudgeon complains.","Curmudgeon: grouch."],"s":["misanthrope"]},{"w":"disabuse","p":"v.","m":"To free someone from a mistaken idea.","e":"<i>dis-</i> + abuse (deceive), after French <i>désabuser</i>.","f":"détromper","t":"« Désabuser ».","h":["Dis + abuse: free from error. Disabuse him of that idea.","Disabuse: set straight."],"s":[]},{"w":"excoriate","p":"v.","m":"To criticise severely.","e":"Latin <i>excoriare</i> (to strip the skin): <i>ex</i> + <i>corium</i> (hide).","f":"fustiger, éreinter","t":"Stripping the skin off: « écorcher ».","h":["Ex + corium: skin off. Excoriate the critics.","Excoriate: flay."],"s":["berate","castigate","censure","decry","denigrate","denounce","disparage","lambast","lambaste","rebuke","reproach","stigmatize","upbraid","vilify"]},{"w":"execrate","p":"v.","m":"To feel or express great loathing.","e":"Latin <i>exsecrari</i> (to curse): <i>ex</i> + <i>sacer</i>.","f":"exécrer","t":"Same as « exécrer ».","h":["Ex + sacrare: curse. Execrate the tyrant.","Execrate: loathe."],"s":["abhor","loathe"]},{"w":"expurgate","p":"v.","m":"To remove objectionable parts of a text.","e":"Latin <i>expurgare</i> (to purge).","f":"expurger","t":"Same as « expurger ».","h":["Ex + purgare: clean out. Expurgate the novel.","Expurgate: censor."],"s":["bowdlerize","censor"]},{"w":"factitious","p":"adj.","m":"Artificial, contrived.","e":"Latin <i>facticius</i> (made by art), from <i>facere</i>.","f":"factice","t":"« Factice ». Not factious.","h":["Factus: made. A factitious demand.","Factitious: artificial."],"s":["ersatz"]},{"w":"fell","p":"adj. / v.","m":"Fierce, deadly; to cut down.","e":"Old French <i>fel</i> (wicked), from which French <i>félon</i>.","f":"cruel, funeste; abattre","x":"2nd meaning","t":"In one fell swoop: « d’un seul coup funeste ».","h":["Fell: cruel. One fell swoop.","Fell: deadly."],"s":["baleful"]},{"w":"gerrymander","p":"v.","m":"To manipulate electoral boundaries.","e":"Governor Elbridge Gerry + salamander: an 1812 Massachusetts district shaped like a salamander.","f":"charcutage électoral","t":"Gerry + salamander: a voting district drawn in a ridiculous shape to win.","h":["Gerry + salamander. Gerrymander districts.","Gerrymander: rig the map."],"s":[]},{"w":"hedge","p":"v.","m":"To avoid committing oneself; to limit risk.","e":"Old English <i>hecg</i> (fence).","f":"rester évasif; se couvrir","x":"2nd meaning","t":"Fence yourself in: hedge your bets.","h":["Hedge: fence. Hedge your bets.","Hedge: don’t commit."],"s":["equivocate","evade","prevaricate","quibble"]},{"w":"histrionic","p":"adj.","m":"Overly theatrical or melodramatic.","e":"Latin <i>histrio</i> (actor).","f":"théâtral, cabotin","t":"Histrio = actor: « histrionique ».","h":["Histrio: actor. Histrionic tantrum.","Histrionic: overacting."],"s":[]},{"w":"imbroglio","p":"n.","m":"A complicated, embarrassing situation.","e":"Italian <i>imbroglio</i>, from <i>imbrogliare</i> (to tangle).","f":"imbroglio","t":"Same as « imbroglio ».","h":["Italian: tangle. A diplomatic imbroglio.","Imbroglio: mess."],"s":["predicament","quandary"]},{"w":"impecunious","p":"adj.","m":"Having little or no money.","e":"<i>in-</i> + Latin <i>pecunia</i> (money), from <i>pecus</i> (cattle).","f":"impécunieux, sans le sou","t":"In + pecunia (pécuniaire): no money at all.","h":["In + pecunia: no money. An impecunious student.","Impecunious: broke."],"s":["destitute","indigent","miserly","penurious"]},{"w":"invective","p":"n.","m":"Insulting, abusive language.","e":"Latin <i>invehi</i> (to attack with words).","f":"invective","t":"Same as « invectives ».","h":["Invehi: attack. A stream of invective.","Invective: abuse."],"s":["acrimony","diatribe","tirade","vitriol"]},{"w":"jaundiced","p":"adj.","m":"Bitter or resentful; cynical.","e":"Old French <i>jaunisse</i>, from <i>jaune</i>: yellow-skinned illness thought to make you see everything yellow.","f":"aigri, désabusé","t":"Seeing everything yellow (jaune).","h":["Jaundice: yellow. A jaundiced view.","Jaundiced: bitter."],"s":["disaffected","estranged"]},{"w":"jejune","p":"adj.","m":"Naive and simplistic; dull.","e":"Latin <i>ieiunus</i> (fasting, barren), which gave French <i>jeûne</i>.","f":"naïf, puéril; insipide","t":"Fasting (jeûne): empty, unnourishing ideas. Not « jeune », but you may think childish.","h":["Jejunus: fasting. Jejune argument.","Jejune: thin and childish."],"s":["callow","fledgling","insipid","naive","puerile","vapid"]},{"w":"juggernaut","p":"n.","m":"A huge, unstoppable force.","e":"Hindi <i>Jagannāth</i> (lord of the world), whose huge temple chariot was said to crush devotees.","f":"rouleau compresseur","t":"Jagannath’s giant temple chariot that nothing could stop.","h":["Jagannath cart. A juggernaut of change.","Juggernaut: unstoppable force."],"s":[]},{"w":"limpid","p":"adj.","m":"Clear, transparent.","e":"Latin <i>limpidus</i>.","f":"limpide","t":"Same as « limpide ».","h":["Limpidus: clear. A limpid stream.","Limpid: transparent."],"s":["coherent","intelligible","lucid","pellucid"]},{"w":"malapropism","p":"n.","m":"The mistaken use of a similar-sounding word.","e":"From Mrs Malaprop in Sheridan’s <i>The Rivals</i> (1775), from French <i>mal à propos</i>.","f":"lapsus, impropriété","t":"« Mal à propos ».","h":["Mrs Malaprop in a play: wrong words. “Illiterate” for “alliterate”.","Malapropism: a comic misused word."],"s":["gaffe","infelicity","solecism"]},{"w":"martinet","p":"n.","m":"A strict disciplinarian.","e":"From Jean Martinet, a 17th-century French drillmaster under Louis XIV.","f":"tyran, adjudant","t":"Colonel Martinet drilling soldiers (and the whip, « martinet »).","h":["General Martinet. A martinet for rules.","Martinet: strict."],"s":[]},{"w":"maudlin","p":"adj.","m":"Self-pityingly or tearfully sentimental.","e":"From Mary Magdalene (Maudlin), painted weeping.","f":"larmoyant, sentimental","t":"Maudlin comes from Mary Magdalene, always painted weeping: tearful and self-pitying.","h":["Magdalen: weeping. Maudlin drunk.","Maudlin: tearful."],"s":["cloying","lachrymose","mawkish","sentimental"]},{"w":"mellifluous","p":"adj.","m":"Sweet and smooth-sounding.","e":"Latin <i>mel</i> (honey) + <i>fluere</i> (to flow).","f":"mélodieux, suave","t":"Mel (miel) + fluere: words flowing like honey.","h":["Mel + fluere: honey flowing. A mellifluous voice.","Mellifluous: smooth."],"s":[]},{"w":"mettlesome","p":"adj.","m":"Spirited, courageous.","e":"From <i>mettle</i>, variant of metal.","f":"fougueux, courageux","t":"Mettle (metal): showing what you’re made of. Spirited, brave.","h":["Mettle: courage. A mettlesome horse.","Mettlesome: spirited."],"s":["plucky"]},{"w":"mulct","p":"v.","m":"To extract money by fine or deception.","e":"Latin <i>mulcta</i> (a fine).","f":"escroquer, mettre à l’amende","t":"« Une amende »: mulcted of savings.","h":["Mulcta: fine. Mulct the tourist.","Mulct: swindle."],"s":["bilk","fleece","hoodwink","swindle"]},{"w":"palimpsest","p":"n.","m":"Something reused but with traces of its earlier form.","e":"Greek <i>palimpsēstos</i> (scraped again): manuscripts scraped and rewritten.","f":"palimpseste","t":"Same as « palimpseste ».","h":["Palin + psao: scraped again. A palimpsest manuscript.","Palimpsest: layers beneath."],"s":[]},{"w":"parvenu","p":"n.","m":"A newly rich person seen as lacking refinement.","e":"French <i>parvenu</i> (arrived).","f":"parvenu","t":"Straight from French.","h":["Parvenir: arrive. A parvenu flaunting wealth.","Parvenu: new money."],"s":["arriviste"]},{"w":"peremptory","p":"adj.","m":"Insisting on immediate obedience; brusque.","e":"Latin <i>peremptorius</i> (decisive, destructive), from <i>perimere</i> (to destroy).","f":"péremptoire","t":"Same as « péremptoire ».","h":["Per + emere: cut off. A peremptory order.","Peremptory: no argument."],"s":["dictatorial","imperious"]},{"w":"phantasmagorical","p":"adj.","m":"Dreamlike; bizarrely changing.","e":"French <i>fantasmagorie</i> (1802), a magic-lantern ghost show; Greek <i>phantasma</i>.","f":"fantasmagorique","t":"The magic-lantern ghost shows in Paris.","h":["Phantasma: illusion. Phantasmagorical visions.","Phantasmagorical: dreamlike."],"s":[]},{"w":"picayune","p":"adj.","m":"Petty; of little value.","e":"Louisiana French <i>picaillon</i> (small coin).","f":"insignifiant, mesquin","t":"A picayune was a tiny Louisiana coin: picayune details are worth almost nothing.","h":["Picaillon: small coin. Picayune quibbles.","Picayune: trivial."],"s":["immaterial","inconsequential","negligible","paltry","trifling","trivial"]},{"w":"Pollyannaish","p":"adj.","m":"Unreasonably or illogically optimistic.","e":"From Pollyanna, heroine of Eleanor H. Porter’s 1913 novel who always finds something to be glad about.","f":"d’un optimisme béat","t":"Pollyanna’s “glad game”: always looking on the bright side.","h":["Pollyanna: glad game. Pollyannaish forecasts.","Pollyannaish: rose-tinted."],"s":[]},{"w":"propitiate","p":"v.","m":"To win the favour of; appease.","e":"Latin <i>propitiare</i>, from <i>propitius</i> (favourable).","f":"apaiser, se concilier","t":"Making the gods « propices ».","h":["Propitius: favourable. Propitiate the gods.","Propitiate: appease."],"s":["appease","assuage","conciliate","mollify","pacify","placate","reconcile"]},{"w":"protean","p":"adj.","m":"Able to change frequently; versatile.","e":"From Proteus, the Greek sea god who could change shape.","f":"protéiforme","t":"Proteus, the sea god who changed shape to escape capture: endlessly versatile.","h":["Proteus: shape-shifter. A protean talent.","Protean: changeable."],"s":["capricious","erratic","fickle","mercurial","multifaceted","resourceful","versatile","volatile"]},{"w":"pyrrhic","p":"adj.","m":"(Of a victory) won at too great a cost.","e":"After King Pyrrhus of Epirus, who beat Rome in 279 BC but lost most of his army.","f":"à la Pyrrhus","t":"« Une victoire à la Pyrrhus ».","h":["Pyrrhus: costly win. A pyrrhic victory.","Pyrrhic: not worth it."],"s":[]},{"w":"quisling","p":"n.","m":"A traitor who collaborates with an occupier.","e":"Vidkun Quisling, who led Norway’s Nazi-collaborating government.","f":"collabo, traître","t":"Vidkun Quisling, who governed Norway for the Nazis: the archetype of the traitor.","h":["Quisling: Norwegian traitor. A quisling collaborator.","Quisling: traitor."],"s":[]},{"w":"quixotic","p":"adj.","m":"Idealistic and impractical.","e":"From Don Quixote, Cervantes’ knight tilting at windmills.","f":"chimérique, donquichottesque","t":"Don Quixote attacking windmills: noble but hopelessly impractical.","h":["Don Quixote: windmills. A quixotic plan.","Quixotic: idealistic."],"s":["visionary"]},{"w":"remonstrate","p":"v.","m":"To protest.","e":"Medieval Latin <i>remonstrare</i> (to demonstrate).","f":"protester, faire des remontrances","t":"« Faire des remontrances ».","h":["Re + monstrare: show again. Remonstrate with the manager.","Remonstrate: protest."],"s":["demur"]},{"w":"sangfroid","p":"n.","m":"Composure under pressure.","e":"French <i>sang-froid</i> (cold blood).","f":"sang-froid","t":"Straight from French.","h":["Sang + froid: cold blood. Keep sangfroid.","Sangfroid: cool head."],"s":["aplomb","equanimity","poise"]},{"w":"sartorial","p":"adj.","m":"Relating to clothing or tailoring.","e":"Latin <i>sartor</i> (tailor), from <i>sarcire</i> (to patch).","f":"vestimentaire","t":"Sartor = tailor: sartorial elegance = how well you dress.","h":["Sartor: tailor. Sartorial elegance.","Sartorial: clothing."],"s":[]},{"w":"schadenfreude","p":"n.","m":"Pleasure at another’s misfortune.","e":"German <i>Schaden</i> (harm) + <i>Freude</i> (joy).","f":"joie malsaine","t":"Schaden (harm) + Freude (joy): the private smile when a rival’s deal falls through.","h":["Schaden + Freude: harm-joy. Schadenfreude at a rival’s failure.","Schadenfreude: secret glee."],"s":[]},{"w":"sententious","p":"adj.","m":"Given to pompous moralising.","e":"Latin <i>sententiosus</i> (full of meaning), from <i>sententia</i> (opinion, maxim).","f":"sentencieux","t":"Same as « sentencieux ».","h":["Sententia: opinion. A sententious preacher.","Sententious: moralising."],"s":["aphoristic","didactic","laconic","pedantic","pithy","sanctimonious","succinct","terse"]},{"w":"sybarite","p":"n.","m":"A person devoted to luxury.","e":"From Sybaris, a Greek city in southern Italy famous for luxury.","f":"sybarite","t":"Same as « sybarite ».","h":["Sybaris: luxury city. A sybarite loves silk.","Sybarite: pleasure lover."],"s":[]},{"w":"tendentious","p":"adj.","m":"Promoting a particular cause; biased.","e":"German <i>tendenziös</i>, from Latin <i>tendere</i>.","f":"tendancieux","t":"Same as « tendancieux ».","h":["Tend: lean. A tendentious article.","Tendentious: biased."],"s":["partisan"]},{"w":"venial","p":"adj.","m":"(Of a sin) forgivable.","e":"Latin <i>venialis</i>, from <i>venia</i> (forgiveness).","f":"véniel","t":"« Péché véniel ».","h":["Venia: pardon. A venial sin.","Venial: forgivable."],"s":["trivial"]},{"w":"vituperate","p":"v.","m":"To blame or insult abusively.","e":"Latin <i>vituperare</i> (to censure).","f":"vitupérer","t":"Same as « vitupérer ».","h":["Vitium: fault. Vituperate the referee.","Vituperate: berate."],"s":["berate","castigate","defame","denigrate","malign","slander","vilify"]}]},{"name":"Advanced III","slug":"advanced-iii","series":"Advanced","words":[{"w":"anemic","p":"adj.","m":"Lacking energy or vigour; weak.","e":"Greek <i>anaimia</i>: <i>an-</i> + <i>haima</i> (blood).","f":"anémique, faible","t":"An + haima = no blood: anemic growth is pale and weak.","h":["Anémie: no blood. An anemic recovery.","Anemic: pale and weak."],"s":["feeble"]},{"w":"anodyne","p":"adj.","m":"Inoffensive, bland; (n.) a painkiller.","e":"Greek <i>anōdynos</i> (painless): <i>an-</i> + <i>odynē</i> (pain).","f":"anodin, fade","t":"Same as « anodin »: harmless and bland.","h":["An + odyne: no pain. An anodyne speech.","Anodyne: bland, harmless."],"s":["benign","innocuous","insipid","vapid"]},{"w":"approbatory","p":"adj.","m":"Expressing approval.","e":"Latin <i>approbare</i> (to approve).","f":"approbateur","t":"« Approbation ».","h":["Approve: nod. An approbatory smile.","Approbatory: thumbs-up."],"s":[]},{"w":"artlessness","p":"n.","m":"Simplicity; lack of guile.","e":"<i>art</i> (artifice) + <i>-less</i> + <i>-ness</i>.","f":"naturel, ingénuité","t":"No artifice at all: childlike, natural simplicity.","h":["Art + less: simplicity. The artlessness of a child.","Artlessness: sincere, no tricks."],"s":[]},{"w":"bowdlerize","p":"v.","m":"To remove indecent parts from a text.","e":"From Thomas Bowdler, who published a censored “Family Shakespeare” in 1818.","f":"expurger","t":"Bowdler’s prudish Shakespeare.","h":["Dr Bowdler cleaned Shakespeare. Bowdlerize a book.","Bowdlerize: sanitise."],"s":["censor","expurgate"]},{"w":"cede","p":"v.","m":"To give up power or territory.","e":"Latin <i>cedere</i> (to yield).","f":"céder","t":"Same as « céder ».","h":["Cedere: yield. Cede territory.","Cede: hand over."],"s":["capitulate","concede","delegate","devolve","forgo","relent","relinquish","renounce","yield"]},{"w":"charlatan","p":"n.","m":"A person falsely claiming expertise.","e":"Italian <i>ciarlatano</i> (quack), from <i>ciarlare</i> (to chatter).","f":"charlatan","t":"Same as « charlatan ».","h":["Ciarlatano: babbler. A charlatan doctor.","Charlatan: fraud."],"s":["hypocrite","phony","sham"]},{"w":"derelict","p":"adj.","m":"Abandoned and dilapidated; negligent.","e":"Latin <i>derelictus</i> (abandoned).","f":"à l’abandon; négligent","t":"Abandoned (déréliction). Derelict in duty = négligent.","h":["De + relinquere: left behind. A derelict building.","Derelict: abandoned or negligent."],"s":["dilapidated","lax","negligent","remiss"]},{"w":"duplicity","p":"n.","m":"Deceitfulness, double-dealing.","e":"Latin <i>duplicitas</i> (doubleness).","f":"duplicité","t":"Same as « duplicité »: double face.","h":["Duplex: double. Duplicity in the contract.","Duplicity: two-faced."],"s":["guile","perfidy"]},{"w":"effrontery","p":"n.","m":"Insolent boldness.","e":"French <i>effronterie</i>, from <i>effronté</i> (without a forehead to blush).","f":"effronterie, culot","t":"« Effronterie ».","h":["Effronté: shameless. Effrontery to demand more.","Effrontery: cheek."],"s":["audacity","gall","presumption","temerity"]},{"w":"enjoin","p":"v.","m":"To instruct or urge; to prohibit (legal).","e":"Old French <i>enjoindre</i>, Latin <i>iniungere</i>.","f":"enjoindre","t":"Same as « enjoindre ».","h":["Enjoindre: order. The court enjoined the sale.","Enjoin: command."],"s":["admonish"]},{"w":"enthrall","p":"v.","m":"To captivate.","e":"<i>en-</i> + thrall (slave, Old Norse <i>þræll</i>).","f":"captiver, subjuguer","t":"Make a slave of: totally captivated.","h":["Thrall: slave. Enthralled by the story.","Enthrall: hold spellbound."],"s":["beguile","enchant","mesmerize","subjugate"]},{"w":"epiphany","p":"n.","m":"A sudden realisation.","e":"Greek <i>epiphaneia</i> (manifestation). Also the Christian feast (Épiphanie).","f":"révélation, illumination","t":"La galette des rois: Épiphanie. A sudden revelation.","h":["Epiphaneia: appearing. An epiphany in the shower.","Epiphany: lightbulb."],"s":[]},{"w":"flummox","p":"v.","m":"To bewilder completely.","e":"19th-century English dialect, origin unknown.","f":"déconcerter, laisser perplexe","t":"A funny word for a funny feeling.","h":["Slang: confuse. Flummoxed by the puzzle.","Flummox: baffle."],"s":["confound","discomfit","nonplussed"]},{"w":"gaffe","p":"n.","m":"An embarrassing blunder.","e":"French <i>gaffe</i> (boat hook; blunder).","f":"gaffe","t":"Straight from French.","h":["Gaffe: a blunder. A diplomatic gaffe.","Gaffe: foot in mouth."],"s":["infelicity","malapropism","solecism"]},{"w":"grandiloquent","p":"adj.","m":"Pompous or extravagant in language.","e":"Latin <i>grandiloquus</i>: <i>grandis</i> + <i>loqui</i>.","f":"grandiloquent","t":"Same as « grandiloquent ».","h":["Grandis + loqui: grand speech. A grandiloquent speech.","Grandiloquent: pompous."],"s":["bombastic","pretentious","tumid","turgid"]},{"w":"hagiographic","p":"adj.","m":"Excessively flattering in describing someone.","e":"Greek <i>hagios</i> (holy) + <i>graphein</i>: writing saints’ lives.","f":"hagiographique","t":"Writing about someone as if they were a saint.","h":["Hagios + graphein: saints’ lives. A hagiographic biography.","Hagiographic: worshipful."],"s":[]},{"w":"hail","p":"v.","m":"To acclaim enthusiastically; to come from.","e":"Old Norse <i>heill</i> (healthy): a greeting.","f":"acclamer, saluer; être originaire de","x":"2nd meaning","t":"Hailed as a genius; she hails from Paris.","h":["Hail: greet. Hailed as a hero.","Hail from: come from."],"s":["acclaim","exalt","extol","laud","lionize"]},{"w":"illustrious","p":"adj.","m":"Famous and admired.","e":"Latin <i>illustris</i> (bright, distinguished).","f":"illustre","t":"Same as « illustre ».","h":["Illustris: bright. An illustrious career.","Illustrious: renowned."],"s":["august","eminent"]},{"w":"importune","p":"v.","m":"To harass with persistent requests.","e":"Latin <i>importunus</i> (unfit, troublesome).","f":"importuner","t":"Same as « importuner ».","h":["Importunus: troublesome. Importune the minister.","Importune: pester."],"s":["badger","beg","dog","entreat","hector","hound","implore","supplicate"]},{"w":"impute","p":"v.","m":"To attribute (a fault) to someone.","e":"Latin <i>imputare</i> (to reckon in).","f":"imputer","t":"Same as « imputer ».","h":["Imputare: charge. Impute blame.","Impute: attribute."],"s":["ascribe","attribute"]},{"w":"insouciance","p":"n.","m":"Casual lack of concern.","e":"French <i>insouciance</i>.","f":"insouciance","t":"Straight from French.","h":["In + souci: no care. A French insouciance.","Insouciance: carefree."],"s":["indifference"]},{"w":"lampoon","p":"v. / n.","m":"To ridicule publicly; a satire.","e":"French <i>lampon</i>, from <i>lampons</i> (let’s drink), a refrain in drinking songs.","f":"tourner en dérision; satire","t":"Mocking drinking songs: « lampons! »","h":["Lampons! Let’s drink. A lampoon in the press.","Lampoon: satire."],"s":["caricature","castigate","deride","pillory","satirize","stigmatize","travesty"]},{"w":"litany","p":"n.","m":"A tedious recital or long list.","e":"Greek <i>litaneia</i> (prayer).","f":"litanie","t":"« Une litanie de plaintes ».","h":["Litaneia: prayer. A litany of complaints.","Litany: long list."],"s":[]},{"w":"lugubrious","p":"adj.","m":"Looking or sounding sad and dismal.","e":"Latin <i>lugubris</i>, from <i>lugere</i> (to mourn).","f":"lugubre","t":"Same as « lugubre ».","h":["Lugere: mourn. Lugubrious music.","Lugubrious: gloomy."],"s":["doleful","dolorous","lachrymose","melancholy","plaintive","woeful"]},{"w":"maunder","p":"v.","m":"To talk or wander in a rambling way.","e":"Perhaps from obsolete <i>maund</i> (to beg).","f":"divaguer, radoter","t":"Meander + wander while talking.","h":["Maunder: ramble. He maundered on.","Maunder: mumble on."],"s":["prattle","ramble"]},{"w":"mordant","p":"adj.","m":"Sharply sarcastic.","e":"French <i>mordant</i> (biting), from <i>mordre</i>.","f":"mordant","t":"Same as « mordant ».","h":["Mordere: bite. Mordant wit.","Mordant: biting."],"s":["acerbic","astringent","caustic","scathing","trenchant","vitriolic"]},{"w":"moribund","p":"adj.","m":"At the point of death; in decline.","e":"Latin <i>moribundus</i>, from <i>mori</i> (to die).","f":"moribond","t":"Same as « moribond ».","h":["Mori: die. A moribund industry.","Moribund: dying."],"s":[]},{"w":"pecuniary","p":"adj.","m":"Relating to money.","e":"Latin <i>pecuniarius</i>, from <i>pecunia</i>.","f":"pécuniaire","t":"Same as « pécuniaire ».","h":["Pecus: cattle (wealth). Pecuniary penalty.","Pecuniary: financial."],"s":[]},{"w":"perspicacious","p":"adj.","m":"Having keen insight.","e":"Latin <i>perspicax</i> (sharp-sighted), from <i>perspicere</i> (to see through).","f":"perspicace","t":"Same as « perspicace ».","h":["Per + specere: see through. A perspicacious judge.","Perspicacious: sharp."],"s":["artful","astute","canny","incisive","judicious","keen","penetrating","percipient","prudent","sagacious","shrewd","trenchant"]},{"w":"plucky","p":"adj.","m":"Brave and determined.","e":"From <i>pluck</i> (courage), originally the heart and lungs of an animal.","f":"courageux, qui a du cran","t":"Pluck = courage: the plucky underdog who keeps fighting. « Qui a du cran ».","h":["Pluck: courage. A plucky underdog.","Plucky: spunky."],"s":["doughty","intrepid","mettlesome","stalwart"]},{"w":"portentous","p":"adj.","m":"Ominous; also pompously solemn.","e":"Latin <i>portentum</i> (omen).","f":"de mauvais augure; pompeux","t":"A portent is an omen: portentous clouds before a storm; also pompously solemn.","h":["Portentum: omen. Portentous clouds.","Portentous: ominous."],"s":["baleful","ominous","prescient","prophetic","unpropitious"]},{"w":"primacy","p":"n.","m":"The state of being most important.","e":"Medieval Latin <i>primatia</i>, from <i>primus</i>.","f":"primauté","t":"« Primauté ».","h":["Primus: first. The primacy of health.","Primacy: top rank."],"s":["ascendancy","hegemony"]},{"w":"probity","p":"n.","m":"Strong moral principles; honesty.","e":"Latin <i>probitas</i>, from <i>probus</i> (upright).","f":"probité","t":"Same as « probité ».","h":["Probus: honest. Judicial probity.","Probity: integrity."],"s":[]},{"w":"prognostication","p":"n.","m":"A prediction.","e":"Greek <i>prognōsis</i> (foreknowledge).","f":"pronostic, prédiction","t":"« Pronostic ».","h":["Pro + gnosis: foreknowledge. Gloomy prognostications.","Prognostication: forecast."],"s":[]},{"w":"prolixity","p":"n.","m":"Tedious wordiness.","e":"Latin <i>prolixus</i> (extended, long).","f":"prolixité","t":"Same as « prolixe ».","h":["Prolix: long-winded. Prolixity in the report.","Prolixity: wordiness."],"s":[]},{"w":"provident","p":"adj.","m":"Making provision for the future.","e":"Latin <i>providens</i> (foreseeing).","f":"prévoyant","t":"« Prévoyant », not providential.","h":["Pro + videre: see ahead. A provident saver.","Provident: thrifty."],"s":["abstemious","canny","economical","frugal","parsimonious","prudent","thrifty"]},{"w":"punctilio","p":"n.","m":"A fine point of etiquette.","e":"Italian <i>puntiglio</i>, Spanish <i>puntillo</i> (small point), from Latin <i>punctum</i>.","f":"point d’étiquette","t":"A tiny point of protocol.","h":["Puntiglio: fine point. Court punctilio.","Punctilio: etiquette detail."],"s":[]},{"w":"punctilious","p":"adj.","m":"Very attentive to correct behaviour and detail.","e":"From punctilio.","f":"pointilleux, scrupuleux","t":"Obsessed with tiny points.","h":["Punctum: point. A punctilious clerk.","Punctilious: precise."],"s":["captious","exacting","fastidious","finicky","meticulous","painstaking","pedantic","scrupulous","thorough"]},{"w":"quail","p":"v.","m":"To feel or show fear.","e":"Middle English <i>quailen</i> (to fail, give way), perhaps from Latin <i>coagulare</i>.","f":"trembler, flancher","x":"2nd meaning","t":"Not the bird: quailing at the sight of the boss.","h":["Quail: cower. Quail before the dragon.","Quail: shrink."],"s":[]},{"w":"raconteur","p":"n.","m":"A skilled storyteller.","e":"French <i>raconteur</i>.","f":"conteur","t":"Straight from « raconter ».","h":["Raconter: tell. A raconteur at dinner.","Raconteur: storyteller."],"s":[]},{"w":"recapitulation","p":"n.","m":"A summary.","e":"Latin <i>recapitulare</i> (to go over the headings, <i>capitulum</i>).","f":"récapitulation","t":"Same as « récapitulation ».","h":["Re + caput: head again. Recapitulation of the facts.","Recapitulation: summary."],"s":[]},{"w":"redoubtable","p":"adj.","m":"Formidable; worthy of respect.","e":"Old French <i>redoutable</i>, from <i>redouter</i>.","f":"redoutable","t":"Same as « redoutable ».","h":["Redouter: dread. A redoubtable foe.","Redoubtable: formidable."],"s":[]},{"w":"sagacious","p":"adj.","m":"Wise; showing good judgment.","e":"Latin <i>sagax</i> (keen-scented, shrewd).","f":"sagace","t":"Same as « sagace ».","h":["Sagax: keen. A sagacious advisor.","Sagacious: wise."],"s":["astute","canny","discreet","judicious","penetrating","percipient","perspicacious","politic","prudent","savvy","shrewd"]},{"w":"semblance","p":"n.","m":"Outward appearance, often deceptive.","e":"Old French <i>semblance</i>, from <i>sembler</i>.","f":"semblant, apparence","t":"« Un semblant d’ordre ».","h":["Sembler: seem. A semblance of order.","Semblance: look."],"s":["effigy","facade","simulacrum","veneer","verisimilitude"]},{"w":"sinecure","p":"n.","m":"A paid position requiring little work.","e":"Latin <i>sine cura</i> (without care).","f":"sinécure","t":"Same as « sinécure ».","h":["Sine + cura: no care. A sinecure on the board.","Sinecure: cushy job."],"s":[]},{"w":"solecism","p":"n.","m":"A grammatical mistake; a breach of etiquette.","e":"Greek <i>soloikismos</i>, from Soloi, a colony whose dialect Athenians mocked.","f":"solécisme","t":"Same as « solécisme ».","h":["Soloi: faulty Greek. A solecism of grammar.","Solecism: blunder."],"s":["gaffe","infelicity","malapropism"]},{"w":"temerity","p":"n.","m":"Excessive boldness; audacity.","e":"Latin <i>temeritas</i> (rashness).","f":"témérité, culot","t":"« Témérité ».","h":["Temeritas: rashness. The temerity to ask.","Temerity: nerve."],"s":["audacity","effrontery","gall","presumption"]},{"w":"umbrage","p":"n.","m":"Offence or annoyance.","e":"Latin <i>umbra</i> (shadow): something that overshadows you.","f":"ombrage","t":"« Prendre ombrage ».","h":["Umbra: shadow. Take umbrage at a remark.","Umbrage: offence."],"s":[]},{"w":"unforthcoming","p":"adj.","m":"Not willing to give information.","e":"<i>un-</i> + forthcoming.","f":"peu loquace, réticent","t":"Not forthcoming with information: a tight-lipped witness.","h":["Not forthcoming: reluctant to share. An unforthcoming witness.","Unforthcoming: tight-lipped."],"s":["evasive","reticent"]},{"w":"vitriolic","p":"adj.","m":"Filled with bitter criticism.","e":"Medieval Latin <i>vitriolum</i> (sulphuric acid), from <i>vitrum</i> (glass).","f":"au vitriol, virulent","t":"« Une critique au vitriol ».","h":["Vitriol: acid. A vitriolic attack.","Vitriolic: acidic."],"s":["acerbic","acrimonious","astringent","caustic","mordant","scathing","virulent"]}]},{"name":"Advanced IV","slug":"advanced-iv","series":"Advanced","words":[{"w":"apposite","p":"adj.","m":"Apt; highly appropriate.","e":"Latin <i>appositus</i> (placed near), from <i>apponere</i>.","f":"à propos, pertinent","t":"Placed right next to the point: an apposite remark is « à propos ».","h":["Ad + ponere: placed near. An apposite quotation.","Apposite: fits perfectly."],"s":["apropos","apt","felicitous","germane","pertinent"]},{"w":"asperity","p":"n.","m":"Harshness of tone or manner.","e":"Latin <i>asperitas</i>, from <i>asper</i> (rough).","f":"aspérité, rudesse","t":"Rough surface: « aspérité ».","h":["Asper: rough. The asperity of his tone.","Asperity: sharpness."],"s":["acrimony","vitriol"]},{"w":"celerity","p":"n.","m":"Swiftness.","e":"Latin <i>celeritas</i>, from <i>celer</i> (swift).","f":"célérité","t":"Same as « célérité ».","h":["Celer: swift. Celerity of response.","Celerity: speed."],"s":["alacrity","dispatch"]},{"w":"corollary","p":"n.","m":"A proposition that follows from one already proved; a consequence.","e":"Latin <i>corollarium</i> (gift of a garland, gratuity), from <i>corolla</i> (little crown).","f":"corollaire","t":"Same as « corollaire ».","h":["Corolla: little garland: a bonus. A corollary of the theorem.","Corollary: natural consequence."],"s":["ramification"]},{"w":"cosset","p":"v.","m":"To pamper.","e":"From <i>cosset</i>, a pet lamb raised by hand.","f":"dorloter, choyer","t":"A cosset was a lamb raised by hand: to cosset = « dorloter ».","h":["Cosset: pet lamb. Cosset the child.","Cosset: pamper."],"s":["coddle"]},{"w":"crestfallen","p":"adj.","m":"Sad and disappointed.","e":"<i>crest</i> + <i>fallen</i>: a fighting cock with a drooping crest.","f":"dépité, abattu","t":"A fighting cock’s crest falls when he loses: « dépité ».","h":["Crest fallen: a rooster loses. Crestfallen after rejection.","Crestfallen: deflated."],"s":["disheartened","forlorn","glum"]},{"w":"crystallize","p":"v.","m":"To make or become definite and clear.","e":"Greek <i>krystallos</i> (ice, crystal).","f":"se cristalliser, se préciser","t":"Ideas taking solid, clear form, like crystals forming.","h":["Crystal: clear form. Ideas crystallized.","Crystallize: take definite shape."],"s":["elucidate"]},{"w":"decry","p":"v.","m":"To publicly denounce.","e":"French <i>décrier</i>.","f":"décrier, dénoncer","t":"Same as « décrier ».","h":["De + crier: cry down. Decry the policy.","Decry: condemn openly."],"s":["belittle","castigate","censure","demean","denigrate","denounce","deprecate","disparage","excoriate","stigmatize","vilify"]},{"w":"denouement","p":"n.","m":"The final resolution of a plot.","e":"French <i>dénouement</i> (untying), from <i>dénouer</i>.","f":"dénouement","t":"Straight from French.","h":["Dénouer: untie a knot. The denouement of the play.","Denouement: where it all resolves."],"s":[]},{"w":"dispensation","p":"n.","m":"Exemption from a rule; a system of order.","e":"Latin <i>dispensatio</i> (management, distribution).","f":"dispense; régime","t":"« Dispense ».","h":["Dispensare: weigh out. Special dispensation.","Dispensation: exemption."],"s":[]},{"w":"dovetail","p":"v.","m":"To fit together harmoniously.","e":"From the dovetail joint in carpentry, shaped like a dove’s tail.","f":"concorder, s’emboîter","t":"Interlocking wood joints: « queue d’aronde ».","h":["Dovetail joint: interlocking. Plans dovetail.","Dovetail: fit snug."],"s":["accord"]},{"w":"encumber","p":"v.","m":"To burden or impede.","e":"Old French <i>encombrer</i>.","f":"encombrer, entraver","t":"Same as « encombrer ».","h":["En + combrer: burden. Encumbered by debt.","Encumber: weigh down."],"s":["hamper","hinder","hobble","impede","inhibit","stymie","thwart"]},{"w":"equitable","p":"adj.","m":"Fair and impartial.","e":"French <i>équitable</i>, Latin <i>aequitas</i>.","f":"équitable","t":"Same as « équitable ».","h":["Aequus: fair. An equitable split.","Equitable: just."],"s":["disinterested","dispassionate","evenhanded","impartial"]},{"w":"firebrand","p":"n.","m":"A person who passionately stirs up trouble.","e":"<i>fire</i> + <i>brand</i> (burning piece of wood).","f":"agitateur, boutefeu","t":"A brand is a burning stick: the firebrand activist sets crowds alight.","h":["Fire + brand: burning torch. A firebrand orator.","Firebrand: agitator."],"s":["incendiary"]},{"w":"flippant","p":"adj.","m":"Not showing proper seriousness.","e":"From <i>flip</i> (to flick).","f":"désinvolte, cavalier","t":"Flip = flick away: treating a serious subject too lightly. « Désinvolte ».","h":["Flip: flick. A flippant remark.","Flippant: disrespectful."],"s":["cavalier","facetious","frivolous","glib","haughty","impertinent","impudent","irreverent","jocular","nonchalant","trifling","trivial"]},{"w":"hobble","p":"v.","m":"To walk awkwardly; to hamper.","e":"Middle English <i>hobelen</i>, probably Low German.","f":"entraver; boitiller","t":"A hobble ties a horse’s legs so it can’t run: hobbled by debt = « entravé ».","h":["Hobble: tie legs. Hobbled by injury.","Hobble: limp."],"s":["encumber","hamper","hinder","impede","inhibit","stymie"]},{"w":"hubris","p":"n.","m":"Excessive pride.","e":"Greek <i>hybris</i> (outrage, arrogance punished by the gods).","f":"démesure, orgueil","t":"Hybris in Greek tragedy: the pride the gods punish, like Icarus flying too close to the sun.","h":["Hybris: insolence. Hubris led to his fall.","Hubris: overweening pride."],"s":["overweening"]},{"w":"immure","p":"v.","m":"To confine or imprison.","e":"Medieval Latin <i>immurare</i>, from <i>murus</i> (wall).","f":"emmurer","t":"« Emmurer ».","h":["In + murus: wall in. Immured in a cell.","Immure: shut in."],"s":[]},{"w":"imperious","p":"adj.","m":"Arrogant and domineering.","e":"Latin <i>imperiosus</i>, from <i>imperium</i> (command).","f":"impérieux","t":"Same as « impérieux ».","h":["Imperium: command. An imperious tone.","Imperious: bossy."],"s":["autocratic","despotic","dictatorial","haughty","magisterial","peremptory","supercilious"]},{"w":"impetuous","p":"adj.","m":"Acting without thought.","e":"Latin <i>impetuosus</i>, from <i>impetus</i> (attack).","f":"impétueux","t":"Same as « impétueux ».","h":["Impetere: rush at. An impetuous youth.","Impetuous: reckless."],"s":["capricious","foolhardy","impulsive","precipitate","rash"]},{"w":"improvident","p":"adj.","m":"Not providing for the future.","e":"<i>in-</i> + provident (foreseeing).","f":"imprévoyant","t":"« Imprévoyant ».","h":["In + providere: no foresight. Improvident spending.","Improvident: wasteful."],"s":["extravagant","feckless","imprudent","inept","lavish","myopic","prodigal","profligate","spendthrift"]},{"w":"incontrovertible","p":"adj.","m":"Not able to be denied.","e":"<i>in-</i> + controvert, Latin <i>contra</i> + <i>vertere</i>.","f":"incontestable, irréfutable","t":"Can’t be controverted (turned against): « incontestable ».","h":["In + contra + vertere. Incontrovertible proof.","Incontrovertible: undeniable."],"s":["axiomatic","irrefutable","unassailable"]},{"w":"inimitable","p":"adj.","m":"So good as to be impossible to copy.","e":"Latin <i>inimitabilis</i>.","f":"inimitable","t":"Same as « inimitable ».","h":["Not imitable. Her inimitable style.","Inimitable: one of a kind."],"s":[]},{"w":"intimation","p":"n.","m":"An indication or hint.","e":"Late Latin <i>intimare</i> (to make known).","f":"indice, allusion","t":"From intimate (to hint): an intimation is a hint, « un signe avant-coureur ».","h":["Intimare: hint. An intimation of trouble.","Intimation: a hint."],"s":["inkling"]},{"w":"inure","p":"v.","m":"To accustom to something unpleasant.","e":"Anglo-French <i>en ure</i> (in use, in practice).","f":"endurcir, aguerrir","t":"Inured to criticism = « aguerri ».","h":["In + ure: use. Inured to cold.","Inure: toughen."],"s":[]},{"w":"invidious","p":"adj.","m":"Likely to arouse resentment; unfair.","e":"Latin <i>invidiosus</i>, from <i>invidia</i> (envy).","f":"injuste, odieux","t":"Envie: an invidious comparison.","h":["Invidia: envy. An invidious comparison.","Invidious: unfairly hurtful."],"s":["odious"]},{"w":"inviolate","p":"adj.","m":"Free from injury or violation.","e":"Latin <i>inviolatus</i>.","f":"inviolé, intact","t":"In + violate: never violated, still intact. « Inviolé ».","h":["In + violate. Inviolate rights.","Inviolate: untouched."],"s":["immaculate","impregnable","inviolable","pristine","sacrosanct","unassailable"]},{"w":"irrefutable","p":"adj.","m":"Impossible to deny.","e":"Late Latin <i>irrefutabilis</i>.","f":"irréfutable","t":"Same as « irréfutable ».","h":["Not refutable. Irrefutable proof.","Irrefutable: can’t be disproved."],"s":["axiomatic","conclusive","impregnable","incontrovertible","inviolable","unassailable","unequivocal"]},{"w":"lacerate","p":"v.","m":"To tear; to wound deeply.","e":"Latin <i>lacerare</i> (to tear).","f":"lacérer","t":"Same as « lacérer ».","h":["Lacer: torn. Lacerate the skin.","Lacerate: slash."],"s":[]},{"w":"machinate","p":"v.","m":"To plot.","e":"Latin <i>machinari</i> (to devise).","f":"machiner, comploter","t":"« Machination ».","h":["Machina: device. Machinate a plot.","Machinate: scheme."],"s":["collude","connive","conspire","intrigue"]},{"w":"magisterial","p":"adj.","m":"Having authority; masterful; domineering.","e":"Latin <i>magister</i> (master).","f":"magistral","t":"« Magistral ».","h":["Magister: master. A magisterial tone.","Magisterial: authoritative."],"s":["imperious"]},{"w":"nonchalant","p":"adj.","m":"Calm and casual.","e":"French <i>nonchalant</i>: <i>non</i> + <i>chaloir</i> (to matter).","f":"nonchalant","t":"Straight from French.","h":["Non + chaloir: not caring. Nonchalant shrug.","Nonchalant: cool."],"s":["aloof","apathetic","blithe","cavalier","flippant","glib","haughty","indifferent","insouciant"]},{"w":"obstreperous","p":"adj.","m":"Noisy and difficult to control.","e":"Latin <i>obstreperus</i>, from <i>obstrepere</i> (to make a noise against).","f":"tapageur, turbulent","t":"Ob + strepere (to make a noise): the noisy, unruly child at the restaurant.","h":["Ob + strepere: noisy. Obstreperous crowd.","Obstreperous: rowdy."],"s":["boisterous","clamorous","fractious","intractable","recalcitrant","refractory","turbulent","unruly","vociferous"]},{"w":"ossify","p":"v.","m":"To become rigid and unchanging.","e":"Latin <i>os, ossis</i> (bone).","f":"se scléroser, s’ossifier","t":"Os = bone: an ossified institution has turned rigid like bone.","h":["Os: bone. Ossified habits.","Ossify: harden."],"s":[]},{"w":"patent","p":"adj.","m":"Obvious.","e":"Latin <i>patentem</i> (lying open), from <i>patere</i>.","f":"patent, manifeste","x":"2nd meaning","t":"« Patent »: a patent lie.","h":["Patere: lie open. A patent lie.","Patent: obvious."],"s":["blatant","conspicuous","manifest","overt","palpable"]},{"w":"peripatetic","p":"adj.","m":"Travelling from place to place.","e":"Greek <i>peripatētikos</i>; Aristotle taught while walking.","f":"itinérant","t":"Aristotle taught while walking around (peripatein): a peripatetic consultant always travelling.","h":["Peri + patein: walk around. A peripatetic teacher.","Peripatetic: roaming."],"s":["itinerant"]},{"w":"presentiment","p":"n.","m":"A feeling that something will happen.","e":"French <i>pressentiment</i>.","f":"pressentiment","t":"Straight from French.","h":["Pre + sentire: feel before. A presentiment of doom.","Presentiment: foreboding."],"s":[]},{"w":"puerile","p":"adj.","m":"Childishly silly.","e":"Latin <i>puerilis</i>, from <i>puer</i> (boy).","f":"puéril","t":"Same as « puéril ».","h":["Puer: boy. Puerile jokes.","Puerile: childish."],"s":["fatuous","frivolous","insipid","jejune","naive","vacuous","vapid"]},{"w":"puissant","p":"adj.","m":"Powerful.","e":"French <i>puissant</i>.","f":"puissant","t":"Straight from French.","h":["Puissant: powerful. A puissant ruler.","Puissant: mighty."],"s":["efficacious","potent"]},{"w":"rarefied","p":"adj.","m":"Esoteric; distant from ordinary life.","e":"Latin <i>rarefacere</i>.","f":"raffiné, élitiste; raréfié","t":"Thin air at the top: the rarefied world of haute couture.","h":["Rarus: thin. The rarefied air of academia.","Rarefied: elite."],"s":["elitist","esoteric","sublime"]},{"w":"recrimination","p":"n.","m":"An accusation in response to one.","e":"Medieval Latin <i>recriminari</i>.","f":"récrimination","t":"Same as « récriminations ».","h":["Re + criminari: accuse back. Mutual recriminations.","Recrimination: counter-accusation."],"s":[]},{"w":"ribald","p":"adj.","m":"Referring to sex in an amusingly rude way.","e":"Old French <i>ribaut</i> (rascal, debauchee).","f":"paillard, grivois","t":"« Chansons paillardes ».","h":["Ribaud: rogue. Ribald songs.","Ribald: bawdy."],"s":["bawdy","salacious"]},{"w":"spartan","p":"adj.","m":"Showing austerity; lacking comfort.","e":"From Sparta.","f":"spartiate","t":"« Spartiate ».","h":["Sparta: austere. A spartan room.","Spartan: plain."],"s":["abstemious","ascetic","austere","frugal"]},{"w":"stalwart","p":"adj. / n.","m":"Loyal, reliable, hard-working; a loyal supporter.","e":"Old English <i>stǣlwierthe</i> (serviceable).","f":"fidèle, inébranlable","t":"Stalwart = solid and loyal: the party stalwart who has voted the same way for 40 years.","h":["Stal + worth: sturdy. A stalwart supporter.","Stalwart: dependable."],"s":["doughty","plucky","resolute","robust","staunch","steadfast"]},{"w":"subterfuge","p":"n.","m":"Deceit used to achieve a goal.","e":"Latin <i>subterfugere</i> (to escape secretly).","f":"subterfuge","t":"Same as « subterfuge ».","h":["Subter + fugere: flee secretly. By subterfuge.","Subterfuge: trick."],"s":["artifice","chicanery","legerdemain","skullduggery"]},{"w":"surreptitious","p":"adj.","m":"Kept secret because it would not be approved.","e":"Latin <i>surrepticius</i> (stolen, secret).","f":"subreptice","t":"« Subreptice ».","h":["Sub + rapere: take secretly. A surreptitious glance.","Surreptitious: stealthy."],"s":["clandestine","covert","furtive","ulterior"]},{"w":"tempestuous","p":"adj.","m":"Characterised by strong, turbulent emotion.","e":"Latin <i>tempestas</i> (storm).","f":"tumultueux, orageux","t":"« Tempête ».","h":["Tempestas: storm. A tempestuous romance.","Tempestuous: stormy."],"s":["turbulent","volatile"]},{"w":"unflappable","p":"adj.","m":"Calm in a crisis.","e":"<i>un-</i> + flap (state of agitation).","f":"imperturbable","t":"Never in a flap (panic): the unflappable pilot.","h":["Not flap: no panic. An unflappable nurse.","Unflappable: calm."],"s":["imperturbable","phlegmatic","placid","serene","stoic","stolid"]},{"w":"unpropitious","p":"adj.","m":"Not favourable.","e":"<i>un-</i> + propitious.","f":"peu propice, défavorable","t":"« Peu propice ».","h":["Not propitious. An unpropitious start.","Unpropitious: ominous."],"s":["adverse","inimical","ominous","portentous","untoward"]},{"w":"untenable","p":"adj.","m":"Not able to be defended.","e":"<i>un-</i> + French <i>tenable</i>, from <i>tenir</i>.","f":"intenable, indéfendable","t":"« Intenable ».","h":["Not tenable. An untenable position.","Untenable: can’t defend."],"s":[]},{"w":"unviable","p":"adj.","m":"Not capable of working successfully.","e":"<i>un-</i> + viable.","f":"non viable","t":"Un-viable = can’t live (vie) on its own: an unviable business model needs constant cash.","h":["Not viable. An unviable plan.","Unviable: not workable."],"s":[]}]},{"name":"Advanced V","slug":"advanced-v","series":"Advanced","words":[{"w":"anachronism","p":"n.","m":"Something out of its proper time.","e":"Greek <i>anakhronismos</i>: <i>ana</i> (against) + <i>khronos</i> (time).","f":"anachronisme","t":"Same as « anachronisme »: a wristwatch in a Roman film.","h":["A- + chronos: out of time. A knight with a phone.","Anachronism: wrong era."],"s":[]},{"w":"antic","p":"adj. / n.","m":"Grotesque or bizarre; (pl.) foolish behaviour.","e":"Italian <i>antico</i> (ancient), used of grotesque Roman decorations.","f":"loufoque; pitreries","t":"Antics = « pitreries ».","h":["Antic: grotesque. The clown’s antics.","Antic: silly behaviour."],"s":[]},{"w":"apothegm","p":"n.","m":"A concise saying or maxim.","e":"Greek <i>apophthegma</i>, from <i>apophthengesthai</i> (to speak out).","f":"apophtegme, maxime","t":"Same as « apophtegme ».","h":["Apo + phthengesthai: speak out. A pithy apothegm.","Apothegm: short maxim."],"s":["aphorism","dictum","epigram","maxim"]},{"w":"appurtenant","p":"adj.","m":"Belonging; pertinent.","e":"Anglo-French <i>apurtenant</i>, from Latin <i>pertinere</i>.","f":"rattaché à, afférent","t":"« Appartenant ».","h":["Ad + pertinere: pertain to. Rights appurtenant to land.","Appurtenant: attached."],"s":[]},{"w":"arrogate","p":"v.","m":"To take without justification.","e":"Latin <i>arrogare</i> (to claim for oneself).","f":"s’arroger","t":"« S’arroger un droit ».","h":["Ad + rogare: claim. Arrogate power.","Arrogate: seize unjustly."],"s":["appropriate"]},{"w":"artifice","p":"n.","m":"Clever trickery.","e":"Latin <i>artificium</i> (craft), from <i>ars</i> + <i>facere</i>.","f":"artifice, ruse","t":"Same as « artifice ».","h":["Ars + facere: made by art. Win by artifice.","Artifice: cunning."],"s":["cunning","gambit","guile","ploy","stratagem","subterfuge"]},{"w":"atavism","p":"n.","m":"Reversion to something ancestral.","e":"Latin <i>atavus</i> (great-great-great-grandfather).","f":"atavisme","t":"Same as « atavisme ».","h":["Atavus: ancestor. An atavism from the cave.","Atavism: throwback."],"s":[]},{"w":"baleful","p":"adj.","m":"Threatening harm; menacing.","e":"Old English <i>bealu</i> (evil) + <i>-ful</i>.","f":"menaçant, funeste","t":"Bale = evil: a baleful glare that wishes you harm. « Menaçant ».","h":["Bale: evil. A baleful look.","Baleful: menacing."],"s":["fell","malevolent","malign","ominous","portentous","vindictive"]},{"w":"bemoan","p":"v.","m":"To express discontent about.","e":"<i>be-</i> + moan.","f":"se lamenter sur, déplorer","t":"Be + moan: moaning about something, « se lamenter sur ».","h":["Be + moan. Bemoan the loss.","Bemoan: lament."],"s":["lament"]},{"w":"besotted","p":"adj.","m":"Strongly infatuated.","e":"<i>be-</i> + sot (fool, Old French <i>sot</i>).","f":"entiché, fou de","t":"Made a « sot » by love.","h":["Be + sot: fool. Besotted with her.","Besotted: infatuated."],"s":["enamored"]},{"w":"bristle","p":"v.","m":"To react angrily; to be thickly covered.","e":"Old English <i>byrst</i> (bristle).","f":"se hérisser","t":"Hair standing up: bristling at criticism.","h":["Bristle: stiff hair. Bristle at the insult.","Bristle: take offence."],"s":["bridle"]},{"w":"broadside","p":"n.","m":"A fierce verbal attack.","e":"Naval term: firing all guns on one side of a ship.","f":"attaque en règle, bordée","t":"A warship firing every cannon on one side at once: a broadside against the government.","h":["Ship’s broad side. A broadside in print.","Broadside: harsh attack."],"s":["diatribe","harangue","polemic","screed","tirade"]},{"w":"brook","p":"v.","m":"To tolerate (usually negative: brook no dissent).","e":"Old English <i>brūcan</i> (to use, enjoy).","f":"tolérer, souffrir","x":"2nd meaning","t":"To brook = to tolerate; she brooks no dissent. Not the stream!","h":["Old English brucan: use. Brook no delay.","Brook: put up with."],"s":["abide","countenance","sanction"]},{"w":"browbeat","p":"v.","m":"To intimidate.","e":"<i>brow</i> + <i>beat</i>: bearing down with a frown.","f":"intimider, rudoyer","t":"Brow + beat: intimidating someone with a heavy frown, « rudoyer ».","h":["Brow + beat. Browbeat a witness.","Browbeat: bully."],"s":["badger","cow","hector"]},{"w":"chagrin","p":"n.","m":"Annoyance or humiliation.","e":"French <i>chagrin</i> (sorrow).","f":"dépit, contrariété","x":"Faux ami","t":"English chagrin = vexation at failing, more « dépit » than sadness.","h":["Chagrin: rough leather rubbing. His chagrin at losing.","Chagrin: vexed shame."],"s":["vexation"]},{"w":"chimera","p":"n.","m":"An illusion or fabrication.","e":"Greek <i>khimaira</i>, a fire-breathing monster (lion, goat, serpent).","f":"chimère","t":"Same as « chimère ».","h":["Chimera: fire-breathing monster. Chasing a chimera.","Chimera: pipe dream."],"s":["delusion"]},{"w":"debonair","p":"adj.","m":"Confident, stylish and charming (of a man).","e":"Old French <i>de bon aire</i> (of good disposition).","f":"élégant, charmant","t":"« De bon air ».","h":["De bon aire: of good air. A debonair host.","Debonair: suave."],"s":["cosmopolitan","raffish","rakish","sophisticated","urbane","winsome"]},{"w":"deign","p":"v.","m":"To do something one considers beneath one.","e":"Old French <i>deignier</i>, Latin <i>dignari</i>.","f":"daigner","t":"Same as « daigner ».","h":["Dignari: think worthy. She didn’t deign to reply.","Deign: condescend."],"s":[]},{"w":"disingenuous","p":"adj.","m":"Not candid; pretending to know less.","e":"<i>dis-</i> + ingenuous.","f":"de mauvaise foi, hypocrite","t":"Dis + ingenuous (ingénu): fake innocence, « de mauvaise foi ».","h":["Dis + ingenuous: not frank. A disingenuous reply.","Disingenuous: falsely naive."],"s":["artful","duplicitous","perfidious","treacherous"]},{"w":"doleful","p":"adj.","m":"Expressing sorrow.","e":"Old French <i>doel</i> (grief), Latin <i>dolere</i>.","f":"dolent, plaintif","t":"« Douleur ».","h":["Dolor: pain. A doleful sigh.","Doleful: mournful."],"s":["dolorous","lachrymose","lugubrious","melancholy","plaintive","wistful","woeful"]},{"w":"effervescent","p":"adj.","m":"Vivacious and enthusiastic.","e":"Latin <i>effervescere</i> (to boil up).","f":"pétillant","t":"Bubbling like champagne: an effervescent personality.","h":["Ex + fervere: boil up. Effervescent laughter.","Effervescent: bubbly."],"s":["buoyant","ebullient","effusive","scintillating","vivacious"]},{"w":"embryonic","p":"adj.","m":"In a rudimentary stage.","e":"Greek <i>embryon</i>.","f":"embryonnaire","t":"Same as « embryonnaire ».","h":["Embryo: unborn. An embryonic plan.","Embryonic: just starting."],"s":["fledgling","inchoate","incipient","nascent","rudimentary"]},{"w":"empiricism","p":"n.","m":"The theory that knowledge comes from experience.","e":"Greek <i>empeiria</i> (experience).","f":"empirisme","t":"Same as « empirisme ».","h":["Empeiria: experience. Empiricism trusts observation.","Empiricism: knowledge from senses."],"s":[]},{"w":"epigram","p":"n.","m":"A short, witty saying.","e":"Greek <i>epigramma</i> (inscription).","f":"épigramme","t":"Same as « épigramme ».","h":["Epi + gramma: inscription. A neat epigram.","Epigram: witty line."],"s":["aphorism","apothegm","dictum","maxim","quip"]},{"w":"ersatz","p":"adj.","m":"Artificial and inferior substitute.","e":"German <i>Ersatz</i> (replacement), used for wartime substitutes like acorn coffee.","f":"ersatz, de substitution","t":"Same as « ersatz ».","h":["German: replacement. Ersatz coffee.","Ersatz: fake substitute."],"s":["bogus","counterfeit","factitious","phony","sham","spurious"]},{"w":"exemplar","p":"n.","m":"A model or pattern.","e":"Latin <i>exemplum</i>.","f":"modèle, exemple","t":"« Exemplaire ».","h":["Exemplum: sample. An exemplar of virtue.","Exemplar: ideal model."],"s":["archetype","epitome","paragon"]},{"w":"gambit","p":"n.","m":"An opening move to gain an advantage.","e":"Italian <i>gambetto</i> (tripping up), chess opening sacrificing a pawn.","f":"stratagème, manœuvre","t":"In chess, a gambit sacrifices a pawn to gain position: an opening move with a plan.","h":["Chess opening sacrifice. A bold gambit.","Gambit: calculated opening move."],"s":["artifice","ploy","stratagem"]},{"w":"hoary","p":"adj.","m":"Grey with age; old and trite.","e":"Old English <i>hār</i> (grey).","f":"chenu; éculé","t":"Hoar = grey-white (hoarfrost = « givre »): a hoary joke is old and grey.","h":["Hoar: grey. A hoary joke.","Hoary: ancient, stale."],"s":["anachronistic","antiquated","archaic","banal","hackneyed","obsolete","trite"]},{"w":"inanity","p":"n.","m":"Silliness, emptiness.","e":"Latin <i>inanis</i> (empty).","f":"inanité, ineptie","t":"« Inanité ».","h":["Inanis: empty. The inanity of chat.","Inanity: emptiness."],"s":[]},{"w":"inchoate","p":"adj.","m":"Just begun; not fully formed.","e":"Latin <i>inchoare</i> (to begin).","f":"embryonnaire, informe","t":"Inchoate ideas = « balbutiantes ».","h":["Incohare: begin. Inchoate fears.","Inchoate: unformed."],"s":["embryonic","fledgling","incipient","nascent","rudimentary"]},{"w":"ineffable","p":"adj.","m":"Too great to be expressed in words.","e":"Latin <i>ineffabilis</i>: <i>in-</i> + <i>effari</i> (to speak out).","f":"ineffable","t":"Same as « ineffable ».","h":["In + effari: not utter. Ineffable joy.","Ineffable: inexpressible."],"s":[]},{"w":"languish","p":"v.","m":"To grow weak; suffer neglect.","e":"Old French <i>languir</i>.","f":"languir, dépérir","t":"Same as « languir ».","h":["Languere: be weak. Languish in jail.","Languish: wither."],"s":["flag","pine"]},{"w":"meteoric","p":"adj.","m":"Very rapid (of success).","e":"Greek <i>meteōros</i> (lofty).","f":"fulgurant","t":"Like a meteor streaking across the sky: a meteoric rise is fast and spectacular.","h":["Meteor streaking. A meteoric rise.","Meteoric: swift and dazzling."],"s":[]},{"w":"nettlesome","p":"adj.","m":"Causing annoyance.","e":"From <i>nettle</i>, the stinging plant.","f":"irritant, agaçant","t":"Stinging like nettles (« orties »): a nettlesome problem.","h":["Nettle: stinging plant. A nettlesome issue.","Nettlesome: irritating."],"s":["irksome"]},{"w":"objurgate","p":"v.","m":"To rebuke severely.","e":"Latin <i>obiurgare</i> (to scold).","f":"réprimander, admonester","t":"Ob + iurgare (to quarrel): scolding someone harshly.","h":["Ob + jurgare: scold. Objurgate the boy.","Objurgate: berate."],"s":["admonish","berate","castigate","chastise","lambaste","rebuke","reproach","upbraid"]},{"w":"paragon","p":"n.","m":"A model of excellence.","e":"Italian <i>paragone</i> (touchstone).","f":"parangon, modèle","t":"« Parangon de vertu ».","h":["Para + akone: touchstone. A paragon of virtue.","Paragon: perfect example."],"s":["apotheosis","archetype","epitome","exemplar"]},{"w":"percipient","p":"adj.","m":"Perceptive.","e":"Latin <i>percipere</i> (to perceive).","f":"perspicace","t":"Percipient ≈ perceptive: someone who perceives what others miss. « Perspicace ».","h":["Per + capere: grasp fully. A percipient critic.","Percipient: sharp-eyed."],"s":["astute","canny","penetrating","perspicacious","sagacious","shrewd"]},{"w":"philistine","p":"n.","m":"A person hostile to culture and the arts.","e":"From the Philistines of the Bible; German students’ slang for townspeople.","f":"béotien, philistin","t":"« Béotien ».","h":["Biblical foes of Israel. A philistine ignores art.","Philistine: anti-culture."],"s":[]},{"w":"phlegmatic","p":"adj.","m":"Calm, unemotional.","e":"Greek <i>phlegmatikos</i>, from phlegm, the humour of calm.","f":"flegmatique","t":"Same as « flegmatique ».","h":["Phlegm humour: sluggish. A phlegmatic response.","Phlegmatic: unexcitable."],"s":["placid","stoic","stolid","unflappable"]},{"w":"pith","p":"n.","m":"The essence; forcefulness.","e":"Old English <i>pitha</i> (core).","f":"essence, substance","t":"The pith is the core of a plant: the pith of an argument is its essence.","h":["Pith: plant core. The pith of the matter.","Pith: essence."],"s":[]},{"w":"rapprochement","p":"n.","m":"Re-establishment of harmonious relations.","e":"French <i>rapprochement</i>.","f":"rapprochement","t":"Straight from French « rapprochement »: two countries drawing closer again.","h":["Re + approcher: bring near. A rapprochement of rivals.","Rapprochement: renewed friendship."],"s":["detente"]},{"w":"recrudesce","p":"v.","m":"To break out again after a dormant period.","e":"Latin <i>recrudescere</i> (to become raw again): <i>crudus</i> (raw).","f":"connaître une recrudescence","t":"« Recrudescence ».","h":["Re + crudus: raw again. Fever recrudesces.","Recrudesce: flare up again."],"s":[]},{"w":"reprisal","p":"n.","m":"An act of retaliation.","e":"Old French <i>reprisaille</i>.","f":"représailles","t":"« Représailles ».","h":["Reprendre: take back. A reprisal attack.","Reprisal: payback."],"s":[]},{"w":"solicitude","p":"n.","m":"Care or concern.","e":"Latin <i>sollicitudo</i>.","f":"sollicitude","t":"Same as « sollicitude ».","h":["Sollicitus: anxious. Solicitude for the sick.","Solicitude: caring concern."],"s":[]},{"w":"squelch","p":"v.","m":"To suppress forcefully.","e":"Imitative of a squishing sound.","f":"étouffer, écraser","t":"Squelch = the sound of a boot stamping on mud: crushing a rumour or protest flat.","h":["Squelch: mud sound. Squelch the rumour.","Squelch: crush."],"s":["curb","hamper","nullify","quash","rescind","stultify","suppress"]},{"w":"truculence","p":"n.","m":"Aggressive defiance.","e":"Latin <i>truculentus</i>, from <i>trux</i> (savage).","f":"agressivité","x":"Faux ami","t":"English truculence = aggressive defiance; French truculence = colourfulness.","h":["Trux: fierce. His truculence at meetings.","Truculence: hostile attitude."],"s":[]},{"w":"unprepossessing","p":"adj.","m":"Not attractive or appealing.","e":"<i>un-</i> + prepossess (to impress favourably).","f":"peu engageant","t":"Prepossessing = making a good first impression. Unprepossessing = « peu engageant ».","h":["Not prepossessing. An unprepossessing house.","Unprepossessing: plain."],"s":[]},{"w":"unstinting","p":"adj.","m":"Given without restraint.","e":"<i>un-</i> + stint.","f":"généreux, sans réserve","t":"Stint = to hold back. Unstinting praise holds nothing back.","h":["Not stinting. Unstinting support.","Unstinting: lavish."],"s":["lavish","munificent"]},{"w":"untrammeled","p":"adj.","m":"Not restricted.","e":"<i>un-</i> + trammel (a net), Old French <i>tramail</i>.","f":"sans entraves","t":"A trammel was a net (« tramail »). Untrammeled = not caught in any net: free.","h":["Not trammeled: unhampered. Untrammeled freedom.","Untrammeled: unrestricted."],"s":["unfettered"]},{"w":"vitriol","p":"n.","m":"Cruel and bitter criticism.","e":"Medieval Latin <i>vitriolum</i> (sulphuric acid).","f":"vitriol, venin","t":"Vitriol is sulphuric acid: « une critique au vitriol » burns.","h":["Vitreolus: glassy; sulphuric acid. Spit vitriol.","Vitriol: bitter venom."],"s":["acrimony","asperity","diatribe","invective","tirade"]}]},{"name":"Advanced VI","slug":"advanced-vi","series":"Advanced","words":[{"w":"abjure","p":"v.","m":"To solemnly renounce.","e":"Latin <i>abiurare</i> (to deny on oath): <i>ab</i> + <i>iurare</i> (to swear).","f":"abjurer, renier","t":"Same as « abjurer »: swearing away.","h":["Ab + jurare: swear off. Abjure violence.","Abjure: renounce."],"s":["forgo","recant","relinquish","renounce","retract"]},{"w":"afford","p":"v.","m":"To provide or offer.","e":"Old English <i>geforthian</i> (to further, accomplish).","f":"offrir, fournir","x":"2nd meaning","t":"The view affords a panorama = « offre ».","h":["Ad + forth: bring forth. Trees afford shade.","Afford: provide."],"s":["render","yield"]},{"w":"aplomb","p":"n.","m":"Self-confidence in a difficult situation.","e":"French <i>aplomb</i> (perpendicularity), from <i>à plomb</i> (plumb line).","f":"aplomb, assurance","t":"Straight from French.","h":["A plomb: plumb-straight. Handled it with aplomb.","Aplomb: poise."],"s":["equanimity","poise","sangfroid"]},{"w":"appropriate","p":"v.","m":"To take for one’s own use, often without permission.","e":"Late Latin <i>appropriare</i>, from <i>proprius</i> (own).","f":"s’approprier","x":"2nd meaning","t":"« S’approprier », not “suitable”.","h":["Ad + proprius: make own. Appropriate funds.","Appropriate (verb): take."],"s":["arrogate"]},{"w":"assiduously","p":"adv.","m":"With great care and perseverance.","e":"Latin <i>assiduus</i> (constant), from <i>assidere</i> (to sit by).","f":"assidûment","t":"Sitting at your desk: « assidu ».","h":["Assidere: sit by. Study assiduously.","Assiduously: diligently."],"s":[]},{"w":"autocratic","p":"adj.","m":"Taking no account of others; tyrannical.","e":"Greek <i>autokratēs</i> (ruling by oneself).","f":"autocratique, autoritaire","t":"Auto + kratos (power): power held by one person alone. « Autocratique ».","h":["Auto + kratos: self rule. An autocratic boss.","Autocratic: dictatorial."],"s":["despotic","dictatorial","imperious"]},{"w":"bridle","p":"v.","m":"To show resentment; to restrain.","e":"Old English <i>brīdel</i>; a horse throwing back its head against the bridle.","f":"se cabrer, se rebiffer; brider","x":"2nd meaning","t":"A horse rearing against its bridle (« bride »).","h":["Bridle: horse strap. Bridle at orders.","Bridle: bristle with resentment."],"s":["begrudge","bristle","check","curb","curtail","inhibit","resent","suppress"]},{"w":"bromide","p":"n.","m":"A trite, unoriginal remark.","e":"Potassium bromide was used as a sedative; dull remarks were as soothing.","f":"banalité, platitude","t":"Bromide was a sedative: a bromide is a remark so dull it puts you to sleep.","h":["Bromide: sedative. A tired bromide.","Bromide: cliché."],"s":["banality","platitude"]},{"w":"callow","p":"adj.","m":"Inexperienced and immature.","e":"Old English <i>calu</i> (bald): a featherless young bird.","f":"inexpérimenté, blanc-bec","t":"Callow once meant bald: a featherless chick, young and inexperienced.","h":["Calu: bald. A callow youth.","Callow: green."],"s":["fledgling","jejune","nascent","neophyte","tyro"]},{"w":"complaisant","p":"adj.","m":"Willing to please others.","e":"French <i>complaisant</i>.","f":"complaisant","t":"Same as French complaisant. Not complacent.","h":["Complaire: please. A complaisant host.","Complaisant: agreeable."],"s":["amenable","compliant","docile","obliging","pliant","tractable"]},{"w":"complicit","p":"adj.","m":"Involved with others in wrongdoing.","e":"From complicity, French <i>complicité</i>.","f":"complice","t":"« Complice ».","h":["Com + plicare: folded together. Complicit in fraud.","Complicit: party to wrongdoing."],"s":[]},{"w":"conflagration","p":"n.","m":"A large, destructive fire; a conflict.","e":"Latin <i>conflagrare</i> (to burn up).","f":"incendie, conflagration","t":"« Conflagration ».","h":["Con + flagrare: burn. The city conflagration.","Conflagration: huge fire."],"s":[]},{"w":"conflate","p":"v.","m":"To combine two things into one (often wrongly).","e":"Latin <i>conflare</i> (to blow together, fuse).","f":"amalgamer, confondre","t":"« Faire l’amalgame ».","h":["Con + flare: blow together. Conflate two ideas.","Conflate: merge wrongly."],"s":["amalgamate","coalesce"]},{"w":"coterminous","p":"adj.","m":"Having the same boundaries or extent.","e":"Latin <i>conterminus</i>: <i>com-</i> + <i>terminus</i>.","f":"limitrophe, coextensif","t":"Co + terminus: two things ending at the same boundary, « limitrophe ».","h":["Co + terminus. Coterminous borders.","Coterminous: same limits."],"s":["commensurate"]},{"w":"desiccated","p":"adj.","m":"Dried out; lacking vitality.","e":"Latin <i>desiccare</i>.","f":"desséché","t":"« Desséché ».","h":["De + siccus: dry. Desiccated fruit.","Desiccated: bone dry."],"s":["wizened"]},{"w":"desideratum","p":"n.","m":"Something needed or wanted.","e":"Latin <i>desideratum</i> (thing desired).","f":"desiderata","t":"« Desiderata ».","h":["Desiderare: long for. A key desideratum.","Desideratum: something wanted."],"s":[]},{"w":"discursive","p":"adj.","m":"Digressing from subject to subject.","e":"Medieval Latin <i>discursivus</i>, from <i>discurrere</i> (to run about).","f":"décousu, digressif","t":"Running about from topic to topic (discourir): a discursive essay.","h":["Dis + currere: run about. A discursive talk.","Discursive: rambling."],"s":["desultory","diffuse","fitful","haphazard","prolix","sporadic","verbose"]},{"w":"dolorous","p":"adj.","m":"Feeling great sorrow.","e":"Latin <i>dolor</i> (pain).","f":"douloureux","t":"« Douleur ».","h":["Dolor: pain. A dolorous cry.","Dolorous: sorrowful."],"s":["doleful","lachrymose","lugubrious","plaintive","woeful"]},{"w":"doughty","p":"adj.","m":"Brave and persistent.","e":"Old English <i>dohtig</i> (able, worthy).","f":"vaillant","t":"Doughty sounds sturdy: a doughty old fighter who never gives up, « vaillant ».","h":["Dugan: be strong. A doughty fighter.","Doughty: valiant."],"s":["audacious","intrepid","plucky","stalwart"]},{"w":"elegiac","p":"adj.","m":"Mournful; relating to an elegy.","e":"Greek <i>elegeia</i> (lament).","f":"élégiaque","t":"Same as « élégiaque ».","h":["Elegy: lament poem. An elegiac tone.","Elegiac: mournful."],"s":["elegy","plaintive"]},{"w":"enormity","p":"n.","m":"The great wickedness of something; (loosely) great size.","e":"Latin <i>enormitas</i> (irregularity): <i>e</i> + <i>norma</i> (rule).","f":"atrocité, monstruosité","x":"2nd meaning","t":"Out of the norm: the enormity of the crime.","h":["E + norma: outside the norm. The enormity of the crime.","Enormity: monstrousness."],"s":[]},{"w":"ethereal","p":"adj.","m":"Extremely delicate and light.","e":"Greek <i>aithēr</i> (upper air).","f":"éthéré","t":"Same as « éthéré ».","h":["Aether: upper air. Ethereal beauty.","Ethereal: airy."],"s":["diaphanous","gossamer"]},{"w":"facile","p":"adj.","m":"Superficial; too simple.","e":"Latin <i>facilis</i> (easy).","f":"simpliste, superficiel (≠ facile)","x":"Faux ami","t":"In English it’s a criticism: too easy, shallow.","h":["Facilis: easy. A facile answer.","Facile: too easy."],"s":["cursory","glib","perfunctory","superficial","voluble"]},{"w":"fecund","p":"adj.","m":"Fertile; productive.","e":"Latin <i>fecundus</i>.","f":"fécond","t":"Same as « fécond ».","h":["Fecundus: fruitful. A fecund mind.","Fecund: fertile."],"s":["fruitful","lucrative","prolific"]},{"w":"gumption","p":"n.","m":"Shrewd resourcefulness; initiative.","e":"Scots (18th c.), origin unknown.","f":"jugeote, cran","t":"Gumption = common sense + guts: the initiative to just get it done.","h":["Scots: common sense. Show some gumption.","Gumption: initiative."],"s":[]},{"w":"hauteur","p":"n.","m":"Haughtiness.","e":"French <i>hauteur</i> (height).","f":"hauteur, morgue","t":"Straight from French « hauteur »: looking down from on high.","h":["Haut: high. Spoke with hauteur.","Hauteur: arrogance."],"s":["disdain"]},{"w":"impervious","p":"adj.","m":"Unable to be affected; impenetrable.","e":"Latin <i>impervius</i>: <i>in-</i> + <i>pervius</i> (passable).","f":"imperméable, insensible","t":"Impervious = nothing gets through, like a waterproof jacket: impervious to criticism.","h":["In + per + via: no way through. Impervious to pleas.","Impervious: unaffected."],"s":["callous","impenetrable","impermeable","inscrutable","opaque"]},{"w":"impugn","p":"v.","m":"To dispute the truth or honesty of.","e":"Latin <i>impugnare</i> (to attack).","f":"contester, attaquer","t":"Pugnare = fight: « impugner ».","h":["In + pugnare: fight against. Impugn his motives.","Impugn: challenge."],"s":["assail","gainsay"]},{"w":"inequity","p":"n.","m":"Lack of fairness.","e":"<i>in-</i> + equity.","f":"iniquité, injustice","t":"In + equity: « iniquité », not inequality of numbers but unfairness.","h":["In + equity. Social inequity.","Inequity: unfairness."],"s":[]},{"w":"internecine","p":"adj.","m":"Destructive to both sides within a group.","e":"Latin <i>internecinus</i> (deadly), from <i>necare</i> (to kill).","f":"fratricide","t":"« Une lutte fratricide ».","h":["Inter + necare: kill each other. Internecine feuds.","Internecine: mutually ruinous."],"s":[]},{"w":"inviolable","p":"adj.","m":"Never to be broken or dishonoured.","e":"Latin <i>inviolabilis</i>.","f":"inviolable","t":"Same as « inviolable ».","h":["In + violare. Inviolable oath.","Inviolable: sacred."],"s":["impenetrable","impregnable","inalienable","intrinsic","inviolate","irrefutable","sacrosanct","unassailable"]},{"w":"malingerer","p":"n.","m":"Someone who fakes illness to avoid work.","e":"French <i>malingre</i> (sickly).","f":"tire-au-flanc, simulateur","t":"« Malingre »: pretending to be sickly.","h":["Mal + malingre: sickly. A malingerer skips work.","Malingerer: fake invalid."],"s":[]},{"w":"mendicant","p":"n. / adj.","m":"A beggar; begging.","e":"Latin <i>mendicare</i> (to beg).","f":"mendiant","t":"« Mendiant », ordres mendiants.","h":["Mendicus: beggar. A mendicant friar.","Mendicant: begging."],"s":[]},{"w":"noisome","p":"adj.","m":"Offensive, disgusting (often smell).","e":"Middle English <i>noy</i> (annoyance) + <i>-some</i>.","f":"nauséabond, fétide","t":"Not noisy! Smelly.","h":["Noy: harm. A noisome stench.","Noisome: foul."],"s":["malodorous","noxious"]},{"w":"obtuse","p":"adj.","m":"Slow to understand.","e":"Latin <i>obtusus</i> (blunted).","f":"obtus","t":"Same as « obtus ».","h":["Obtusus: blunted. Too obtuse to see it.","Obtuse: dim."],"s":[]},{"w":"palatable","p":"adj.","m":"Acceptable; pleasant to taste.","e":"From palate, Latin <i>palatum</i>.","f":"acceptable, agréable","t":"Pleasing to the palate (palais): a palatable compromise.","h":["Palate: taste. A palatable compromise.","Palatable: acceptable."],"s":["passable"]},{"w":"panegyric","p":"n.","m":"A public speech of high praise.","e":"Greek <i>panēgyrikos</i> (for a public assembly).","f":"panégyrique","t":"Same as « panégyrique ».","h":["Pan + agora: assembly speech. A panegyric to him.","Panegyric: lavish praise."],"s":["accolade","encomium","eulogy","euphoria","rhapsody"]},{"w":"pellucid","p":"adj.","m":"Translucently clear; easy to understand.","e":"Latin <i>pellucidus</i>: <i>per</i> + <i>lucidus</i>.","f":"limpide, transparent","t":"Per + lucidus: light passes straight through it: pellucid water, pellucid prose.","h":["Per + lucere: shine through. Pellucid prose.","Pellucid: crystal clear."],"s":["coherent","intelligible","limpid","lucid"]},{"w":"pontificate","p":"v.","m":"To express opinions pompously.","e":"From pontiff, Latin <i>pontifex</i> (bridge-maker, high priest).","f":"pontifier","t":"« Pontifier ».","h":["Pontifex: priest. Stop pontificating.","Pontificate: preach pompously."],"s":["expound"]},{"w":"proscribe","p":"v.","m":"To forbid.","e":"Latin <i>proscribere</i> (to publish as outlawed).","f":"proscrire","t":"Same as « proscrire ». Prescribe = order.","h":["Pro + scribere: write publicly as banned. Proscribe drugs.","Proscribe: ban."],"s":[]},{"w":"proselytize","p":"v.","m":"To try to convert.","e":"Greek <i>prosēlytos</i> (newcomer, convert).","f":"faire du prosélytisme","t":"« Prosélytisme ».","h":["Proselytos: convert. Proselytize door to door.","Proselytize: convert."],"s":[]},{"w":"self-effacing","p":"adj.","m":"Modest.","e":"self + efface, French <i>effacer</i>.","f":"effacé, modeste","t":"« S’effacer »: erasing yourself to let others shine.","h":["Efface: rub out. A self-effacing hero.","Self-effacing: modest."],"s":["diffident","modest","reticent","retiring"]},{"w":"solicitous","p":"adj.","m":"Showing interest or concern.","e":"Latin <i>sollicitus</i> (anxious).","f":"plein de sollicitude, attentionné","t":"« Sollicitude ».","h":["Sollicitus: anxious. Solicitous host.","Solicitous: caring."],"s":[]},{"w":"stultify","p":"v.","m":"To cause to lose enthusiasm through routine.","e":"Late Latin <i>stultificare</i>, from <i>stultus</i> (foolish).","f":"abrutir, étouffer","t":"Stultus = stupid: a stultifying job makes you numb and dull.","h":["Stultus: foolish. Routine stultifies.","Stultify: dull the mind."],"s":["hamper","quash","squelch","suppress"]},{"w":"transmute","p":"v.","m":"To change in form or nature.","e":"Latin <i>transmutare</i>.","f":"transmuer","t":"Trans + mutare: the alchemist transmuting lead into gold.","h":["Trans + mutare: change across. Transmute lead to gold.","Transmute: convert."],"s":["morph"]},{"w":"turgid","p":"adj.","m":"Pompous, swollen (style).","e":"Latin <i>turgidus</i> (swollen).","f":"ampoulé, boursouflé","t":"Turgid = swollen: turgid prose is bloated with big words.","h":["Turgere: swell. Turgid prose.","Turgid: bloated."],"s":["bombastic","grandiloquent","tumid"]},{"w":"tyro","p":"n.","m":"A beginner, novice.","e":"Latin <i>tiro</i> (recruit).","f":"novice, débutant","t":"Tiro = a Roman recruit: a tyro is a beginner. « Novice ».","h":["Tiro: recruit. A tyro in chess.","Tyro: novice."],"s":["callow","dilettante","fledgling","nascent","neophyte"]},{"w":"unassailable","p":"adj.","m":"Unable to be attacked or questioned.","e":"<i>un-</i> + assail.","f":"inattaquable","t":"« Inattaquable ».","h":["Not assailable. An unassailable lead.","Unassailable: impregnable."],"s":["impenetrable","impregnable","inalienable","incontrovertible","intrinsic","inviolable","inviolate","ironclad","irrefutable","sacrosanct"]},{"w":"unimpeachable","p":"adj.","m":"Beyond reproach.","e":"<i>un-</i> + impeach (to accuse), Old French <i>empechier</i>.","f":"irréprochable","t":"Impeach = accuse (as with a president). Unimpeachable = beyond accusation: « irréprochable ».","h":["Not impeachable. Unimpeachable integrity.","Unimpeachable: blameless."],"s":["impeccable"]},{"w":"vaunted","p":"adj.","m":"Praised or boasted about.","e":"Old French <i>vanter</i>.","f":"vanté","t":"Same as « vanté ».","h":["Vanter: boast. Vaunted skills.","Vaunted: boasted of."],"s":[]}]},{"name":"Advanced VII","slug":"advanced-vii","series":"Advanced","words":[{"w":"abrogate","p":"v.","m":"To repeal or abolish a law.","e":"Latin <i>abrogare</i>: <i>ab</i> + <i>rogare</i> (to propose a law).","f":"abroger","t":"Same as « abroger ».","h":["Ab + rogare: ask away. Abrogate a treaty.","Abrogate: repeal."],"s":["countermand","nullify","quash","rescind"]},{"w":"adjudicate","p":"v.","m":"To make a formal judgment.","e":"Latin <i>adiudicare</i>, from <i>iudex</i> (judge).","f":"juger, arbitrer","t":"Ad + iudex (juge): the referee who adjudicates a dispute and hands down the decision.","h":["Ad + judicare. Adjudicate the dispute.","Adjudicate: rule on."],"s":[]},{"w":"bastardization","p":"n.","m":"Corruption of something to a worse form.","e":"From bastard, Old French <i>bastard</i>.","f":"abâtardissement, dénaturation","t":"« Abâtardir ».","h":["Bastard: impure. A bastardization of the recipe.","Bastardization: debasement."],"s":[]},{"w":"bereft","p":"adj.","m":"Deprived of; sad from loss.","e":"Old English <i>berēafian</i> (to rob).","f":"privé de, dépourvu","t":"Bereft = robbed (same root as bereaved): bereft of hope.","h":["Reave: rob. Bereft of ideas.","Bereft: stripped."],"s":["abject","forlorn","wanting"]},{"w":"canard","p":"n.","m":"An unfounded rumour.","e":"French <i>canard</i> (duck; hoax), from <i>vendre un canard à moitié</i> (to half-sell a duck, i.e. cheat).","f":"canard, bobard","t":"« Le Canard enchaîné ».","h":["Canard: duck; hoax. Spread a canard.","Canard: false rumour."],"s":[]},{"w":"capitulate","p":"v.","m":"To surrender.","e":"Medieval Latin <i>capitulare</i> (to draw up terms under headings).","f":"capituler","t":"Same as « capituler ».","h":["Capitulum: chapter heading; terms. Capitulate at dawn.","Capitulate: give in."],"s":["acquiesce","cede","comply","concede","relent","yield"]},{"w":"cataclysm","p":"n.","m":"A violent upheaval.","e":"Greek <i>kataklysmos</i> (deluge).","f":"cataclysme","t":"Same as « cataclysme ».","h":["Kata + kluzein: wash down. A cataclysm struck.","Cataclysm: disaster."],"s":[]},{"w":"chauvinism","p":"n.","m":"Excessive or prejudiced support for one’s group.","e":"French <i>chauvinisme</i>, from Nicolas Chauvin.","f":"chauvinisme","t":"Nicolas Chauvin, the fanatically loyal (possibly legendary) Napoleonic soldier.","h":["Chauvin the soldier. National chauvinism.","Chauvinism: biased loyalty."],"s":["jingoism"]},{"w":"concomitant","p":"adj.","m":"Naturally accompanying.","e":"Latin <i>concomitari</i> (to accompany), from <i>comes</i> (companion).","f":"concomitant","t":"Same as « concomitant ».","h":["Con + comitari: go along. Concomitant risks.","Concomitant: accompanying."],"s":["incidental","peripheral","tangential"]},{"w":"countermand","p":"v.","m":"To revoke an order.","e":"Old French <i>contremander</i>.","f":"annuler, révoquer","t":"Counter + mandate: cancelling an order you gave, « contre-ordre ».","h":["Counter + mandare. Countermand the order.","Countermand: cancel an order."],"s":["abrogate","negate","neutralize","nullify","quash","rescind"]},{"w":"demonstrative","p":"adj.","m":"Openly showing feelings.","e":"Latin <i>demonstrare</i>.","f":"démonstratif, expansif","t":"« Démonstratif ».","h":["Demonstrate feelings. A demonstrative child.","Demonstrative: openly affectionate."],"s":["effusive","expansive","forthcoming","profuse"]},{"w":"despot","p":"n.","m":"A tyrant.","e":"Greek <i>despotēs</i> (master).","f":"despote","t":"Same as « despote ».","h":["Despotes: master. A cruel despot.","Despot: tyrant."],"s":[]},{"w":"diminutive","p":"adj.","m":"Extremely small.","e":"Latin <i>diminutivus</i>.","f":"minuscule","t":"Diminutive = diminished, tiny: think of the diminutive -ette in « fillette », « maisonnette ».","h":["Diminuere: lessen. A diminutive figure.","Diminutive: tiny."],"s":["minute"]},{"w":"dissemble","p":"v.","m":"To conceal one’s true motives.","e":"Latin <i>dissimulare</i>.","f":"dissimuler","t":"« Dissimuler ».","h":["Dis + simulare: hide. Dissemble his anger.","Dissemble: feign."],"s":["cloak","feign","sham"]},{"w":"dissipate","p":"v.","m":"To disperse; to squander.","e":"Latin <i>dissipare</i>.","f":"dissiper, gaspiller","t":"Same as « dissiper ».","h":["Dissipare: scatter. The fog dissipated.","Dissipate: fade, squander."],"s":["diffuse","disperse","disseminate","lavish","propagate","squander"]},{"w":"dissolution","p":"n.","m":"Closing down; debauchery.","e":"Latin <i>dissolutio</i>.","f":"dissolution; débauche","t":"« Dissolution ».","h":["Dis + solvere: loosen. Dissolution of parliament.","Dissolution: breakup."],"s":[]},{"w":"ebullient","p":"adj.","m":"Cheerful and full of energy.","e":"Latin <i>ebullire</i> (to boil over).","f":"exubérant, débordant d’enthousiasme","t":"Bubbling over (ébullition).","h":["E + bullire: boil. An ebullient greeting.","Ebullient: bubbling."],"s":["buoyant","effervescent","effusive","sanguine","vivacious"]},{"w":"enamored","p":"adj.","m":"Filled with love for.","e":"Old French <i>enamourer</i>.","f":"épris, amoureux","t":"« Énamouré ».","h":["En + amor. Enamored of her voice.","Enamored: in love."],"s":["besotted"]},{"w":"eponym","p":"n.","m":"A person after whom something is named.","e":"Greek <i>epōnymos</i> (named after).","f":"éponyme","t":"Eponym = the name-giver: Galvani for galvanize, Mesmer for mesmerize.","h":["Epi + onyma: name upon. Newton is an eponym.","Eponym: name-giver."],"s":[]},{"w":"estimable","p":"adj.","m":"Worthy of great respect.","e":"Latin <i>aestimabilis</i>.","f":"estimable","t":"Same as « estimable ».","h":["Aestimare: value. An estimable colleague.","Estimable: admirable."],"s":["commendable","creditable","laudable","meritorious"]},{"w":"evanescent","p":"adj.","m":"Quickly fading.","e":"Latin <i>evanescere</i> (to vanish).","f":"évanescent","t":"Same as « évanescent ».","h":["E + vanescere: vanish. Evanescent glow.","Evanescent: fleeting."],"s":["ephemeral","momentary","transient","transitory"]},{"w":"exiguity","p":"n.","m":"Scantiness.","e":"Latin <i>exiguitas</i>.","f":"exiguïté","t":"Your 26 m²: « l’exiguïté ».","h":["Exiguus: scanty. Exiguity of funds.","Exiguity: smallness."],"s":[]},{"w":"exorbitant","p":"adj.","m":"Unreasonably high (price).","e":"Latin <i>exorbitare</i> (to go out of the track).","f":"exorbitant","t":"Ex + orbita = out of its orbit: an exorbitant price is off the charts.","h":["Ex + orbita: out of the track. Exorbitant fees.","Exorbitant: extortionate."],"s":["extravagant","flamboyant","ostentatious","outlandish","unconscionable","unscrupulous"]},{"w":"extrapolate","p":"v.","m":"To extend known trends to unknown situations.","e":"<i>extra</i> + (inter)polate.","f":"extrapoler","t":"Same as « extrapoler ».","h":["Extra + interpolate. Extrapolate the trend.","Extrapolate: project."],"s":[]},{"w":"flag","p":"v.","m":"To become tired or weaker.","e":"Perhaps from obsolete <i>flag</i> (drooping).","f":"faiblir, fléchir","x":"2nd meaning","t":"To flag = to droop like a flag without wind: energy flags at 3 p.m.","h":["Flag droops. Spirits flag.","Flag: tire."],"s":["demur","falter","languish","pine","vacillate"]},{"w":"graft","p":"n.","m":"Corruption; bribery.","e":"Probably from <i>graft</i> (digging), US slang for dishonest gain.","f":"corruption, pots-de-vin","x":"2nd meaning","t":"Political graft = « pots-de-vin ».","h":["Graft: shady gain. Political graft.","Graft: bribery."],"s":["venality"]},{"w":"halcyon","p":"adj.","m":"Idyllically happy and peaceful (past).","e":"Greek <i>alkyōn</i> (kingfisher), said to calm the sea while nesting.","f":"paisible, heureux","t":"The halcyon (kingfisher) was said to calm the seas: halcyon days = peaceful, happy times.","h":["Halcyon: calm bird. Halcyon days.","Halcyon: peaceful."],"s":["placid","serene","tranquil"]},{"w":"hoodwink","p":"v.","m":"To deceive.","e":"<i>hood</i> + <i>wink</i> (close the eyes): blindfolding.","f":"duper, berner","t":"Hood over someone’s eyes: blindfolded and tricked, « berner ».","h":["Hood over eyes. Hoodwinked by a con.","Hoodwink: deceive."],"s":["beguile","bilk","dupe","fleece","mulct","swindle"]},{"w":"ineluctable","p":"adj.","m":"Unable to be avoided.","e":"Latin <i>ineluctabilis</i>: <i>in-</i> + <i>eluctari</i> (to struggle out).","f":"inéluctable","t":"Same as « inéluctable ».","h":["In + eluctari: can’t struggle out. Ineluctable fate.","Ineluctable: inescapable."],"s":["inexorable"]},{"w":"infelicitous","p":"adj.","m":"Unfortunate; inappropriate.","e":"<i>in-</i> + felicitous, Latin <i>felix</i>.","f":"malheureux, malvenu","t":"Felix = happy (félicité). An infelicitous remark is an unhappy choice of words: « malvenu ».","h":["In + felix. An infelicitous phrase.","Infelicitous: ill-chosen."],"s":[]},{"w":"lachrymose","p":"adj.","m":"Tearful; given to weeping.","e":"Latin <i>lacrima</i> (tear).","f":"larmoyant","t":"« Larme ».","h":["Lacrima: tear. A lachrymose film.","Lachrymose: weepy."],"s":["doleful","dolorous","lugubrious","maudlin","mawkish","plaintive","sentimental","woeful"]},{"w":"loath","p":"adj.","m":"Reluctant.","e":"Old English <i>lāth</i> (hateful).","f":"peu enclin à, réticent","t":"Loath (adjective) = reluctant: « peu enclin à ». Loathe (verb) = to hate.","h":["Lath: hateful. Loath to leave.","Loath: unwilling."],"s":["chary"]},{"w":"misattribute","p":"v.","m":"To wrongly attribute.","e":"<i>mis-</i> + attribute.","f":"attribuer à tort","t":"Mis + attribute: the famous quote you hear at every conference that the person never actually said.","h":["Mis + attribute. Misattributed quote.","Misattribute: credit wrongly."],"s":[]},{"w":"modicum","p":"n.","m":"A small quantity.","e":"Latin <i>modicus</i> (moderate).","f":"minimum, brin","t":"« Modique ».","h":["Modus: measure. A modicum of respect.","Modicum: a little."],"s":["scintilla","smattering"]},{"w":"oblique","p":"adj.","m":"Indirect.","e":"Latin <i>obliquus</i> (slanting).","f":"indirect, oblique","t":"Same as « oblique ».","h":["Obliquus: slanting. An oblique remark.","Oblique: indirect."],"s":["allusive","circumstantial","devious","tortuous"]},{"w":"obtain","p":"v.","m":"To be prevalent or in effect.","e":"Latin <i>obtinere</i> (to hold).","f":"prévaloir, être en vigueur","x":"2nd meaning","t":"Obtain (intransitive) = to be in force: the rules that obtain here = « en vigueur ».","h":["Ob + tenere: hold. The rules that obtain.","Obtain (law): prevail."],"s":["prevail"]},{"w":"officious","p":"adj.","m":"Assertive of authority in an annoying way.","e":"Latin <i>officiosus</i> (dutiful).","f":"trop zélé, importun (≠ officieux)","x":"Faux ami","t":"Not « officieux » (unofficial)!","h":["Officium: duty. An officious clerk.","Officious: meddlesome."],"s":[]},{"w":"palaver","p":"n.","m":"Prolonged, idle discussion; fuss.","e":"Portuguese <i>palavra</i> (word).","f":"palabres","t":"« Palabres ».","h":["Parabola: speech. Enough palaver.","Palaver: idle talk."],"s":["prattle"]},{"w":"panacea","p":"n.","m":"A cure-all.","e":"Greek <i>panakeia</i>: <i>pan</i> + <i>akos</i> (cure).","f":"panacée","t":"Same as « panacée ».","h":["Pan + akos: all cure. No panacea exists.","Panacea: cure-all."],"s":[]},{"w":"pillory","p":"v.","m":"To attack or ridicule publicly.","e":"Old French <i>pilori</i>, a wooden frame for public punishment.","f":"clouer au pilori","t":"« Clouer au pilori ».","h":["Pillory: wooden stocks. Pilloried in the press.","Pillory: ridicule publicly."],"s":["castigate","lampoon","stigmatize"]},{"w":"promulgate","p":"v.","m":"To make widely known; to put a law into effect.","e":"Latin <i>promulgare</i>.","f":"promulguer","t":"Same as « promulguer ».","h":["Promulgare: publish. Promulgate a law.","Promulgate: proclaim."],"s":["diffuse","disseminate","propagate"]},{"w":"raillery","p":"n.","m":"Good-humoured teasing.","e":"French <i>raillerie</i>.","f":"raillerie","t":"Same as « raillerie ».","h":["Railler: tease. Friendly raillery.","Raillery: banter."],"s":[]},{"w":"row","p":"n.","m":"A noisy quarrel (rhymes with cow).","e":"18th-century slang, origin uncertain.","f":"dispute, querelle","x":"2nd meaning","t":"A row (rhymes with cow) is a noisy quarrel: « une engueulade ».","h":["Row rhymes cow. A family row.","Row: loud quarrel."],"s":[]},{"w":"sardonic","p":"adj.","m":"Grimly mocking.","e":"Greek <i>sardonios</i>; a Sardinian plant was said to make you grimace and die.","f":"sardonique","t":"« Rire sardonique ».","h":["Sardinian plant: grin. A sardonic smile.","Sardonic: bitterly mocking."],"s":["caustic","contemptuous","derisive","satirical","snide","supercilious"]},{"w":"simulacrum","p":"n.","m":"An imitation or representation.","e":"Latin <i>simulacrum</i> (likeness).","f":"simulacre","t":"« Simulacre ».","h":["Simulare: imitate. A simulacrum of democracy.","Simulacrum: hollow copy."],"s":["effigy","semblance"]},{"w":"splenetic","p":"adj.","m":"Bad-tempered.","e":"Latin <i>spleneticus</i>; the spleen was the seat of melancholy and anger.","f":"atrabilaire, irritable","t":"The spleen was the seat of bad temper: Baudelaire’s « spleen », but angry.","h":["Spleen: temper organ. A splenetic outburst.","Splenetic: irritable."],"s":["bilious","choleric","irascible","peevish","petulant","sullen","surly"]},{"w":"surfeit","p":"n.","m":"An excess.","e":"Old French <i>surfait</i>.","f":"surabondance, excès","t":"« Surfait ».","h":["Sur + faire: overdo. A surfeit of cake.","Surfeit: glut."],"s":["glut","plethora","profusion"]},{"w":"trenchant","p":"adj.","m":"Vigorous and incisive.","e":"Old French <i>trenchant</i> (cutting).","f":"tranchant, incisif","t":"Same as « tranchant ».","h":["Trancher: cut. Trenchant criticism.","Trenchant: incisive."],"s":["acerbic","caustic","cogent","compelling","incisive","keen","mordant","penetrating","perspicacious","scathing","telling"]},{"w":"verisimilitude","p":"n.","m":"The appearance of being true.","e":"Latin <i>verisimilitudo</i>: <i>verus</i> + <i>similis</i>.","f":"vraisemblance","t":"« Vraisemblance ».","h":["Verus + similis: truth-like. Verisimilitude in fiction.","Verisimilitude: lifelike quality."],"s":["semblance"]},{"w":"veritable","p":"adj.","m":"Real, genuine (for emphasis).","e":"French <i>véritable</i>.","f":"véritable","t":"Straight from French.","h":["Verus: true. A veritable feast.","Veritable: genuine."],"s":[]}]},{"name":"Advanced VIII","slug":"advanced-viii","series":"Advanced","words":[{"w":"abeyance","p":"n.","m":"Temporary suspension.","e":"Old French <i>abeance</i> (expectation), from <i>baer</i> (to gape).","f":"suspens","t":"« En suspens »: held in abeyance.","h":["Old French: gaping wait. Plans in abeyance.","Abeyance: on hold."],"s":[]},{"w":"abscission","p":"n.","m":"The act of cutting off.","e":"Latin <i>abscindere</i> (to cut off).","f":"abscission, ablation","t":"Ab + scindere (scinder): cutting off, like a leaf detaching from its branch in autumn.","h":["Ab + scindere: cut off. Leaf abscission.","Abscission: cutting off."],"s":[]},{"w":"attenuated","p":"adj.","m":"Weakened; thin.","e":"Latin <i>attenuare</i>.","f":"atténué","t":"« Atténué ».","h":["Ad + tenuis: thin. Attenuated signal.","Attenuated: weakened."],"s":[]},{"w":"august","p":"adj.","m":"Respected and impressive.","e":"Latin <i>augustus</i> (venerable), title of the first emperor.","f":"auguste","t":"August = majestic, like the Emperor Augustus: an august institution.","h":["Augustus: venerable. An august body.","August: majestic."],"s":["eminent","illustrious"]},{"w":"captious","p":"adj.","m":"Fault-finding.","e":"Latin <i>captiosus</i> (deceptive).","f":"pointilleux","t":"Captious = trying to capture you on a technicality, « pointilleux ».","h":["Capere: seize. Captious critic.","Captious: nitpicking."],"s":["carping","fastidious","finicky","meticulous","pedantic","punctilious"]},{"w":"contumacious","p":"adj.","m":"Stubbornly disobedient.","e":"Latin <i>contumax</i> (insolent).","f":"rebelle, insoumis","t":"« Contumace ».","h":["Contumax: stubborn. A contumacious witness.","Contumacious: defiant."],"s":["intractable","obdurate","obstinate","recalcitrant","refractory","unruly"]},{"w":"descry","p":"v.","m":"To catch sight of.","e":"Old French <i>descrier</i> (to proclaim).","f":"apercevoir","t":"Descry = « discerner » from far away: the sailor descrying land on the horizon.","h":["Descrier: proclaim. Descry land.","Descry: spot."],"s":["discern"]},{"w":"dichotomy","p":"n.","m":"A division into two contrasting things.","e":"Greek <i>dikhotomia</i> (cutting in two).","f":"dichotomie","t":"Same as « dichotomie ».","h":["Dicha + temnein: cut in two. Work-life dichotomy.","Dichotomy: sharp split."],"s":["schism"]},{"w":"droll","p":"adj.","m":"Curious or unusual in a way that provokes amusement.","e":"French <i>drôle</i>.","f":"drôle, cocasse","t":"Straight from « drôle ».","h":["Drôle: odd. A droll remark.","Droll: quaintly funny."],"s":["capricious","facetious","fanciful","jocular","jocund","jovial","quirky","whimsical"]},{"w":"effigy","p":"n.","m":"A sculpture or model of a person.","e":"Latin <i>effigies</i>.","f":"effigie","t":"An effigy is a figure of a person, often burned in protest: « brûlé en effigie ».","h":["Effigies: likeness. Burned in effigy.","Effigy: dummy image."],"s":["semblance","simulacrum"]},{"w":"elegy","p":"n.","m":"A mournful poem.","e":"Greek <i>elegeia</i>.","f":"élégie","t":"« Élégie ».","h":["Elegos: lament. An elegy for him.","Elegy: sad poem."],"s":["dirge","elegiac","lament","plaintive"]},{"w":"encomium","p":"n.","m":"A speech of high praise.","e":"Greek <i>enkōmion</i> (eulogy).","f":"éloge, panégyrique","t":"An encomium is a whole speech of « éloges »: think of the eulogy at a retirement dinner, but for someone still alive.","h":["Enkomion: praise. A glowing encomium.","Encomium: tribute."],"s":["accolade","eulogy","panegyric"]},{"w":"equanimity","p":"n.","m":"Calmness under stress.","e":"Latin <i>aequanimitas</i>: <i>aequus</i> + <i>animus</i>.","f":"équanimité, sérénité","t":"Aequus + animus = an even mind: staying calm when the deck breaks at 2 a.m.","h":["Aequus + animus. Face it with equanimity.","Equanimity: composure."],"s":["aplomb","poise","sangfroid"]},{"w":"exculpate","p":"v.","m":"To clear from blame.","e":"Latin <i>ex</i> + <i>culpa</i>.","f":"disculper","t":"Ex + culpa (mea culpa): exculpate = taking the culpa away, « disculper ».","h":["Ex + culpa. Exculpate the accused.","Exculpate: absolve."],"s":["exonerate","vindicate"]},{"w":"exigent","p":"adj.","m":"Pressing; demanding.","e":"Latin <i>exigere</i>.","f":"urgent, exigeant","t":"« Exigence ».","h":["Exigere: demand. Exigent needs.","Exigent: urgent."],"s":["exacting","imperative","onerous","stringent"]},{"w":"expiate","p":"v.","m":"To atone for.","e":"Latin <i>expiare</i>.","f":"expier","t":"Same as « expier ».","h":["Ex + piare: appease. Expiate his guilt.","Expiate: atone."],"s":[]},{"w":"extraneous","p":"adj.","m":"Irrelevant.","e":"Latin <i>extraneus</i> (external).","f":"étranger, superflu","t":"Extraneous = « étranger » to the topic: extraneous slides in the appendix.","h":["Extra: outside. Extraneous detail.","Extraneous: off-topic."],"s":["immaterial","impertinent","inconsequential","negligible","redundant","superfluous","tangential","trivial"]},{"w":"fulminate","p":"v.","m":"To express vehement protest.","e":"Latin <i>fulminare</i> (to strike with lightning).","f":"fulminer","t":"Same as « fulminer ».","h":["Fulmen: lightning. Fulminate against waste.","Fulminate: rant."],"s":["denounce"]},{"w":"hapless","p":"adj.","m":"Unfortunate.","e":"<i>hap</i> (luck) + <i>-less</i>.","f":"infortuné","t":"Hap = luck (as in happen, perhaps). Hapless = without luck: the hapless tourist who loses his passport twice.","h":["Hap: luck. A hapless victim.","Hapless: unlucky."],"s":[]},{"w":"incipient","p":"adj.","m":"In an initial stage.","e":"Latin <i>incipere</i> (to begin).","f":"naissant","t":"Incipit = the first words of a text. Incipient = just starting: an incipient cold, an incipient crisis.","h":["In + capere: start. Incipient decay.","Incipient: beginning."],"s":["embryonic","fledgling","inchoate","nascent","rudimentary"]},{"w":"inculcate","p":"v.","m":"To instil by persistent instruction.","e":"Latin <i>inculcare</i> (to tread in, press with the heel).","f":"inculquer","t":"« Inculquer ».","h":["In + calcare: tread in. Inculcate values.","Inculcate: drill in."],"s":[]},{"w":"indefatigable","p":"adj.","m":"Tireless.","e":"Latin <i>indefatigabilis</i>.","f":"infatigable","t":"« Infatigable ».","h":["In + de + fatigare. Indefatigable worker.","Indefatigable: untiring."],"s":["assiduous","diligent","dogged","industrious","sedulous"]},{"w":"ingrained","p":"adj.","m":"Firmly established.","e":"<i>in</i> + grain.","f":"enraciné, ancré","t":"Dye that has soaked into the grain of the wood can’t be scrubbed off: ingrained habits.","h":["In the grain. Ingrained habits.","Ingrained: deep-rooted."],"s":["entrenched","indelible","inveterate"]},{"w":"insouciant","p":"adj.","m":"Casually unconcerned.","e":"French <i>insouciant</i>.","f":"insouciant","t":"Straight from French.","h":["In + soucier: not worry. Insouciant air.","Insouciant: carefree."],"s":["blithe","nonchalant"]},{"w":"intrinsic","p":"adj.","m":"Essential, belonging naturally.","e":"Latin <i>intrinsecus</i> (inwardly).","f":"intrinsèque","t":"Same as « intrinsèque ».","h":["Intrinsecus: inwardly. Intrinsic worth.","Intrinsic: inherent."],"s":["inalienable","inborn","inherent","inviolable","sacrosanct","unassailable"]},{"w":"jettison","p":"v.","m":"To throw away; abandon.","e":"Old French <i>getaison</i> (throwing).","f":"larguer, abandonner","t":"« Jeter » overboard.","h":["Jeter: throw. Jettison cargo.","Jettison: ditch."],"s":["forsake","relinquish","renounce"]},{"w":"makeshift","p":"adj.","m":"Temporary and improvised.","e":"<i>make</i> + <i>shift</i> (to manage).","f":"de fortune","t":"« Un abri de fortune ».","h":["Make + shift. A makeshift bed.","Makeshift: improvised."],"s":[]},{"w":"mendacious","p":"adj.","m":"Untruthful.","e":"Latin <i>mendax</i>.","f":"mensonger","t":"Mendacious sounds like « mensonger », and means exactly that: a mendacious report is full of lies.","h":["Mendax: lying. A mendacious claim.","Mendacious: lying."],"s":[]},{"w":"milieu","p":"n.","m":"Social environment.","e":"French <i>milieu</i>.","f":"milieu","t":"Straight from French.","h":["Mi + lieu: middle place. Her social milieu.","Milieu: setting."],"s":[]},{"w":"obfuscate","p":"v.","m":"To make unclear.","e":"Latin <i>obfuscare</i> (to darken), from <i>fuscus</i> (dark).","f":"obscurcir, embrouiller","t":"Fuscus = dark (as in « offusquer », which once meant to darken). Obfuscate = cloud the issue on purpose.","h":["Ob + fuscare: darken. Obfuscate the facts.","Obfuscate: muddy."],"s":["obscure"]},{"w":"obviate","p":"v.","m":"To remove a need or difficulty.","e":"Latin <i>obviare</i> (to meet in the way).","f":"éviter, rendre superflu","t":"« Obvier à ».","h":["Ob + via: meet in the way. Obviate the need.","Obviate: make needless."],"s":["avert","forestall","preclude","preempt"]},{"w":"outstrip","p":"v.","m":"To surpass.","e":"<i>out</i> + <i>strip</i> (to move fast).","f":"dépasser","t":"Out + strip (to move fast): running so fast you leave the others behind.","h":["Out + strip. Outstrip rivals.","Outstrip: leave behind."],"s":["eclipse","transcend"]},{"w":"palliate","p":"v.","m":"To alleviate without curing.","e":"Latin <i>palliare</i> (to cloak).","f":"pallier","t":"« Soins palliatifs ».","h":["Pallium: cloak. Palliate the pain.","Palliate: ease, not cure."],"s":["alleviate","assuage","mitigate","temper"]},{"w":"pedant","p":"n.","m":"Someone overly concerned with rules.","e":"Italian <i>pedante</i>.","f":"pédant","t":"« Pédant ».","h":["Paidagogos: teacher. A pedant corrects grammar.","Pedant: stickler."],"s":[]},{"w":"penury","p":"n.","m":"Extreme poverty.","e":"Latin <i>penuria</i>.","f":"pénurie, misère","t":"« Pénurie ».","h":["Penuria: want. Live in penury.","Penury: destitution."],"s":[]},{"w":"perfidious","p":"adj.","m":"Deceitful, untrustworthy.","e":"Latin <i>perfidia</i>.","f":"perfide","t":"La perfide Albion.","h":["Per + fides: through faith breaking. A perfidious ally.","Perfidious: treacherous."],"s":["disingenuous","duplicitous","treacherous"]},{"w":"politic","p":"adj.","m":"Wise and prudent.","e":"Greek <i>politikos</i>.","f":"avisé, judicieux","x":"2nd meaning","t":"Politic = wise in a political way: it would be politic to stay quiet.","h":["Politikos. The politic reply.","Politic: shrewd."],"s":["astute","canny","circumspect","discreet","expedient","judicious","opportunistic","pragmatic","prudent","sagacious","shrewd","wary"]},{"w":"prattle","p":"v.","m":"To talk foolishly.","e":"Low German <i>pratelen</i>.","f":"babiller, jacasser","t":"Prattle = childish chatter, « babiller »: a toddler prattling on about dinosaurs.","h":["Prate: chatter. Children prattle.","Prattle: babble."],"s":["maunder","palaver","ramble"]},{"w":"prescient","p":"adj.","m":"Having foreknowledge.","e":"Latin <i>praescire</i>.","f":"prescient, clairvoyant","t":"Pre + scire (savoir): knowing before. A prescient analyst saw the crash coming.","h":["Pre + scire. Prescient warnings.","Prescient: foreseeing."],"s":["portentous","prophetic","visionary"]},{"w":"proclivity","p":"n.","m":"A tendency.","e":"Latin <i>proclivis</i> (sloping).","f":"penchant, propension","t":"Clivus = slope: a proclivity is a natural slope your behaviour slides down.","h":["Pro + clivus: slope. A proclivity for risk.","Proclivity: leaning."],"s":["penchant","predilection","propensity"]},{"w":"propagate","p":"v.","m":"To spread.","e":"Latin <i>propagare</i>.","f":"propager","t":"Same as « propager ».","h":["Propago: shoot. Propagate rumours.","Propagate: spread."],"s":["diffuse","disperse","disseminate","dissipate","promulgate"]},{"w":"prurient","p":"adj.","m":"Having excessive interest in sexual matters.","e":"Latin <i>prurire</i> (to itch).","f":"lubrique, malsain","t":"Itching: « prurit ».","h":["Prurire: itch. Prurient curiosity.","Prurient: lewdly curious."],"s":["bawdy","lascivious","salacious"]},{"w":"recalcitrant","p":"adj.","m":"Stubbornly uncooperative.","e":"Latin <i>recalcitrare</i> (to kick back), from <i>calx</i> (heel).","f":"récalcitrant","t":"Same as « récalcitrant ».","h":["Re + calcitrare: kick back. A recalcitrant mule.","Recalcitrant: defiant."],"s":["contumacious","fractious","intractable","obdurate","obstinate","obstreperous","refractory","unruly"]},{"w":"salacious","p":"adj.","m":"Having undue interest in sex.","e":"Latin <i>salax</i> (lustful).","f":"salace","t":"Same as « salace ».","h":["Salire: leap. Salacious gossip.","Salacious: lewd."],"s":["bawdy","lascivious","prurient","ribald"]},{"w":"scintilla","p":"n.","m":"A tiny trace.","e":"Latin <i>scintilla</i> (spark).","f":"once, soupçon","t":"Scintilla = spark (scintiller): not a scintilla of evidence = not one spark.","h":["Spark. Not a scintilla of doubt.","Scintilla: trace."],"s":["modicum"]},{"w":"stratagem","p":"n.","m":"A plan to deceive.","e":"Greek <i>stratēgēma</i>.","f":"stratagème","t":"Same as « stratagème ».","h":["Strategos: general. A clever stratagem.","Stratagem: ruse."],"s":["artifice","gambit","ploy"]},{"w":"supplicate","p":"v.","m":"To beg humbly.","e":"Latin <i>supplicare</i>.","f":"supplier","t":"« Supplier ».","h":["Sub + plicare: fold under. Supplicate for mercy.","Supplicate: beg."],"s":["beg","entreat","implore","importune"]},{"w":"tumid","p":"adj.","m":"Swollen; pompous.","e":"Latin <i>tumidus</i>.","f":"enflé, boursouflé","t":"« Tuméfié ».","h":["Tumere: swell. Tumid ego.","Tumid: swollen."],"s":["bombastic","grandiloquent","turgid"]},{"w":"unfeigned","p":"adj.","m":"Genuine, sincere.","e":"<i>un-</i> + feign (Old French <i>feindre</i>).","f":"sincère, non feint","t":"Feign = « feindre ». Unfeigned = not faked: unfeigned joy, genuine and spontaneous.","h":["Not feigned. Unfeigned delight.","Unfeigned: sincere."],"s":["candid","forthright","frank"]},{"w":"voluble","p":"adj.","m":"Talking fluently and at length.","e":"Latin <i>volubilis</i>.","f":"volubile","t":"Same as « volubile ».","h":["Volvere: roll. A voluble guest.","Voluble: talkative."],"s":["effusive","facile","garrulous","glib","loquacious","prolix","tedious","verbose"]}]},{"name":"Advanced IX","slug":"advanced-ix","series":"Advanced","words":[{"w":"abstemious","p":"adj.","m":"Indulging only very moderately.","e":"Latin <i>abstemius</i>: <i>abs</i> + <i>temetum</i> (strong drink).","f":"sobre, frugal","t":"Abs + temetum (strong drink): staying away from wine. « Sobre ».","h":["Abs + temetum: wine-free. An abstemious diet.","Abstemious: restrained."],"s":["ascetic","austere","economical","frugal","parsimonious","provident","spartan","thrifty"]},{"w":"adventitious","p":"adj.","m":"Happening by chance; external.","e":"Latin <i>adventicius</i> (coming from outside).","f":"fortuit, accessoire","t":"Ad + venire: something that arrives from outside, by chance. « Fortuit ».","h":["Ad + venire: arrives. Adventitious luck.","Adventitious: accidental."],"s":["fortuitous","incidental","providential","serendipitous"]},{"w":"affectation","p":"n.","m":"Behaviour designed to impress.","e":"Latin <i>affectatio</i>.","f":"affectation","t":"Same as « affectation ».","h":["Affectare: aim at. Affectation of accent.","Affectation: put-on show."],"s":["posturing"]},{"w":"aggrandize","p":"v.","m":"To increase power or status.","e":"French <i>agrandir</i>.","f":"agrandir, accroître","t":"Aggrandize = « agrandir » your own power or image: a self-aggrandizing CEO memoir.","h":["Ad + grandis: make grand. Aggrandize himself.","Aggrandize: inflate status."],"s":["embellish"]},{"w":"amalgamate","p":"v.","m":"To combine.","e":"From amalgam.","f":"fusionner","t":"Amalgamate = « fusionner », from amalgam: two companies amalgamated into one group.","h":["Amalgam: mixed metal. Firms amalgamate.","Amalgamate: merge."],"s":["coalesce","conflate"]},{"w":"assiduous","p":"adj.","m":"Showing great care and perseverance.","e":"Latin <i>assiduus</i>.","f":"assidu","t":"Same as « assidu ».","h":["Assidere: sit by. An assiduous student.","Assiduous: diligent."],"s":["diligent","indefatigable","industrious","meticulous","painstaking","scrupulous","sedulous","thorough"]},{"w":"bilk","p":"v.","m":"To cheat out of money.","e":"Perhaps from <i>balk</i>, a cribbage term.","f":"escroquer","t":"Bilk = cheat someone of money owed: the Ponzi scheme that bilked thousands of investors.","h":["Bilk: cheat at cards. Bilked of savings.","Bilk: swindle."],"s":["fleece","hoodwink","mulct","swindle"]},{"w":"blithe","p":"adj.","m":"Casually indifferent; carefree.","e":"Old English <i>blīthe</i> (joyous).","f":"insouciant, joyeux","t":"Blithe = carefree to the point of not caring: blithely ignoring warnings.","h":["Blithe: cheerful. Blithe spirit.","Blithe: carefree."],"s":["insouciant","nonchalant"]},{"w":"cadge","p":"v.","m":"To ask for something without paying.","e":"Origin uncertain (17th c.).","f":"taxer, quémander","t":"Picture a student cadging a cigarette, a coffee and a lift home, never paying for any of them: « taxer ».","h":["Cadge: peddle. Cadge a lift.","Cadge: scrounge."],"s":["beg"]},{"w":"cogitate","p":"v.","m":"To think deeply.","e":"Latin <i>cogitare</i>.","f":"cogiter","t":"Cogitare, as in Descartes’ cogito: « cogiter », thinking hard.","h":["Co + agitare: turn over. Cogitate on it.","Cogitate: ponder."],"s":["contemplate","deliberate","reflect","ruminate"]},{"w":"desultory","p":"adj.","m":"Lacking purpose or enthusiasm.","e":"Latin <i>desultorius</i> (of a circus rider leaping from horse to horse).","f":"décousu, sans conviction","t":"A desultor was a circus rider jumping from horse to horse: desultory = aimless, jumping around.","h":["Desultor: vaulting rider. Desultory chat.","Desultory: random."],"s":["cursory","diffuse","discursive","fitful","haphazard","indiscriminate","perfunctory","slapdash","sporadic","superficial","token"]},{"w":"diaphanous","p":"adj.","m":"Light, delicate and translucent.","e":"Greek <i>diaphanēs</i> (see-through).","f":"diaphane","t":"Same as « diaphane ».","h":["Dia + phainein: show through. Diaphanous silk.","Diaphanous: sheer."],"s":["ethereal","gossamer"]},{"w":"dissonance","p":"n.","m":"Lack of harmony.","e":"Latin <i>dissonantia</i>.","f":"dissonance","t":"Dis + sonare: sounds that clash. Cognitive dissonance = ideas that clash.","h":["Dis + sonare. Cognitive dissonance.","Dissonance: clash."],"s":["cacophony","clamor","discord"]},{"w":"distend","p":"v.","m":"To swell outward.","e":"Latin <i>distendere</i>.","f":"distendre","t":"Dis + tendre: stretched out in every direction, like a stomach distended after Christmas dinner.","h":["Dis + tendere: stretch apart. Distended belly.","Distend: bloat."],"s":[]},{"w":"emollient","p":"adj.","m":"Soothing; calming.","e":"Latin <i>emollire</i> (to soften).","f":"émollient, apaisant","t":"Emollient creams soften (mollis = mou) your skin; an emollient tone softens an angry client.","h":["Mollis: soft. An emollient reply.","Emollient: soothing."],"s":[]},{"w":"empirical","p":"adj.","m":"Based on observation.","e":"Greek <i>empeirikos</i>.","f":"empirique","t":"Same as « empirique ».","h":["Empeiria: experience. Empirical evidence.","Empirical: observed."],"s":[]},{"w":"execrable","p":"adj.","m":"Extremely bad.","e":"Latin <i>exsecrabilis</i>.","f":"exécrable","t":"Same as « exécrable ».","h":["Ex + sacrare: curse. Execrable food.","Execrable: dreadful."],"s":["abject","abysmal","odious","repugnant","woeful"]},{"w":"expedient","p":"adj.","m":"Convenient but possibly improper.","e":"Latin <i>expedire</i>.","f":"opportun, commode","t":"« Un expédient ».","h":["Expedire: free the feet. An expedient fix.","Expedient: convenient."],"s":["canny","discreet","exploitative","judicious","opportunistic","politic","pragmatic","prudent","shrewd","unscrupulous"]},{"w":"fatuous","p":"adj.","m":"Silly and pointless.","e":"Latin <i>fatuus</i> (foolish).","f":"sot, inepte","t":"« Fat » in old French meant conceited fool.","h":["Fatuus: foolish. A fatuous grin.","Fatuous: idiotic."],"s":["frivolous","puerile","vacuous"]},{"w":"forestall","p":"v.","m":"To prevent by acting ahead.","e":"Old English <i>foresteall</i> (ambush).","f":"devancer, prévenir","t":"Fore + stall: getting in front of a problem to block it, « prendre les devants ».","h":["Fore + stall: ambush. Forestall a crisis.","Forestall: pre-empt."],"s":["avert","deter","hinder","inhibit","obviate","preclude","preempt","supersede"]},{"w":"frenetic","p":"adj.","m":"Fast and energetic in an uncontrolled way.","e":"Greek <i>phrenitikos</i> (delirious).","f":"frénétique","t":"Same as « frénétique ».","h":["Phrenitis: frenzy. Frenetic pace.","Frenetic: frantic."],"s":[]},{"w":"gambol","p":"v.","m":"To run or jump playfully.","e":"Italian <i>gambata</i> (a kick), <i>gamba</i> (leg).","f":"gambader","t":"« Gambader ».","h":["Gamba: leg. Lambs gambol.","Gambol: frolic."],"s":[]},{"w":"gustatory","p":"adj.","m":"Concerned with taste.","e":"Latin <i>gustare</i>.","f":"gustatif","t":"« Gustatif ».","h":["Gustare: taste. Gustatory delight.","Gustatory: of taste."],"s":[]},{"w":"imminent","p":"adj.","m":"About to happen.","e":"Latin <i>imminere</i>.","f":"imminent","t":"Same as « imminent ».","h":["In + minere: overhang. Imminent storm.","Imminent: impending."],"s":["forthcoming","impending"]},{"w":"imperturbable","p":"adj.","m":"Unable to be upset.","e":"Latin <i>imperturbabilis</i>.","f":"imperturbable","t":"Same as « imperturbable ».","h":["Not perturbable. Imperturbable calm.","Imperturbable: unflappable."],"s":["placid","serene","unflappable"]},{"w":"inefficacious","p":"adj.","m":"Not producing the desired effect.","e":"<i>in-</i> + efficacious.","f":"inefficace","t":"« Inefficace ».","h":["Not efficacious. An inefficacious remedy.","Inefficacious: useless."],"s":["futile"]},{"w":"insuperable","p":"adj.","m":"Impossible to overcome.","e":"Latin <i>insuperabilis</i>.","f":"insurmontable","t":"« Insurmontable ».","h":["In + superare: not surmountable. An insuperable obstacle.","Insuperable: unbeatable."],"s":[]},{"w":"inveigle","p":"v.","m":"To persuade by flattery.","e":"French <i>aveugler</i> (to blind).","f":"enjôler","t":"From French « aveugler »: blinding someone with flattery to get them to agree.","h":["Aveugle: blind. Inveigle him into it.","Inveigle: coax by guile."],"s":["cajole","entice","wheedle"]},{"w":"legerdemain","p":"n.","m":"Skilful trickery; sleight of hand.","e":"French <i>léger de main</i>.","f":"tour de passe-passe","t":"« Léger de main ».","h":["Léger de main: light of hand. Legerdemain with cards.","Legerdemain: sleight of hand."],"s":["chicanery","skullduggery","subterfuge"]},{"w":"machination","p":"n.","m":"A plot.","e":"Latin <i>machinatio</i>.","f":"machination","t":"Same as « machination ».","h":["Machina. Political machinations.","Machination: scheme."],"s":["collusion","intrigue","ploy"]},{"w":"malediction","p":"n.","m":"A curse.","e":"Latin <i>maledictio</i>.","f":"malédiction","t":"Same as « malédiction ».","h":["Male + dicere: speak ill. Hurl a malediction.","Malediction: curse."],"s":["anathema"]},{"w":"malinger","p":"v.","m":"To fake illness to avoid work.","e":"French <i>malingre</i>.","f":"tirer au flanc","t":"« Malingre ».","h":["Malingre: sickly. Malinger to skip class.","Malinger: feign illness."],"s":["evade","feign","shirk"]},{"w":"modish","p":"adj.","m":"Fashionable.","e":"From mode, French <i>mode</i>.","f":"à la mode","t":"« À la mode ».","h":["Mode. A modish haircut.","Modish: trendy."],"s":[]},{"w":"occlude","p":"v.","m":"To block.","e":"Latin <i>occludere</i>.","f":"obstruer","t":"Ob + claudere (clore): an occluded artery is closed off. Same root as preclude and exclude.","h":["Ob + claudere: close. Occluded artery.","Occlude: block."],"s":[]},{"w":"pallid","p":"adj.","m":"Pale; lacking intensity.","e":"Latin <i>pallidus</i>.","f":"pâle, blafard","t":"Pallid = « pâle » (and « blafard »): a pallid face, or pallid, lifeless prose.","h":["Pallere: be pale. A pallid face.","Pallid: wan."],"s":["cadaverous"]},{"w":"pastiche","p":"n.","m":"An imitation of another style.","e":"French <i>pastiche</i>, Italian <i>pasticcio</i> (pie).","f":"pastiche","t":"Same as « pastiche ».","h":["Pasticcio: pie mix. A Mozart pastiche.","Pastiche: stylistic mimicry."],"s":["hodgepodge"]},{"w":"providential","p":"adj.","m":"Occurring at a favourable time; lucky.","e":"Latin <i>providentia</i>.","f":"providentiel","t":"« Providentiel ».","h":["Providentia: foresight. A providential rescue.","Providential: luckily timed."],"s":["adventitious","auspicious","fortuitous","propitious","serendipitous"]},{"w":"quiescent","p":"adj.","m":"Inactive, dormant.","e":"Latin <i>quiescere</i> (to rest).","f":"latent, en sommeil","t":"Quiescent = quiet, like a volcano « en sommeil » that could wake up any time.","h":["Quies: rest. A quiescent volcano.","Quiescent: dormant."],"s":["dormant","fallow","inert"]},{"w":"recalcitrance","p":"n.","m":"Stubborn resistance.","e":"Latin <i>recalcitrare</i> (to kick back).","f":"résistance, refus d’obéir","t":"Re + calx (heel): kicking back with your heels like a mule. « Récalcitrant ».","h":["Re + calx: heel. Recalcitrance of staff.","Recalcitrance: obstinate resistance."],"s":[]},{"w":"recrudescent","p":"adj.","m":"Breaking out again.","e":"Latin <i>recrudescere</i>.","f":"en recrudescence","t":"« Recrudescence ».","h":["Re + crudus. Recrudescent flu.","Recrudescent: flaring again."],"s":[]},{"w":"requite","p":"v.","m":"To repay.","e":"<i>re-</i> + quite (quit).","f":"rendre, payer de retour","t":"Requite = repay. Unrequited love is love that is never paid back.","h":["Re + quit: pay back. Requited love.","Requite: repay."],"s":["retaliate"]},{"w":"ruminate","p":"v.","m":"To think deeply.","e":"Latin <i>ruminare</i> (to chew the cud).","f":"ruminer","t":"Same as « ruminer ».","h":["Ruminare: chew cud. Ruminate on a choice.","Ruminate: mull over."],"s":["cogitate","contemplate","deliberate","reflect"]},{"w":"salubrious","p":"adj.","m":"Health-giving; pleasant.","e":"Latin <i>salubris</i>.","f":"salubre","t":"Same as « salubre ».","h":["Salus: health. A salubrious climate.","Salubrious: healthy."],"s":["salutary"]},{"w":"slake","p":"v.","m":"To quench (thirst).","e":"Old English <i>slacian</i> (to slacken).","f":"étancher","t":"Slake ≈ slacken: your thirst slackens when you drink. « Étancher sa soif ».","h":["Slack: lessen. Slake thirst.","Slake: quench."],"s":["assuage"]},{"w":"transgression","p":"n.","m":"Act that goes against a law.","e":"Latin <i>transgressio</i>.","f":"transgression","t":"Same as « transgression ».","h":["Trans + gradi: step across. A minor transgression.","Transgression: violation."],"s":[]},{"w":"trifling","p":"adj.","m":"Unimportant, trivial.","e":"Old French <i>trufle</i> (mockery).","f":"insignifiant","t":"A trifle is also an English dessert of leftovers: a trifling sum is a crumb, not worth worrying about.","h":["Trifle: bit. A trifling sum.","Trifling: petty."],"s":["flippant","frivolous","immaterial","inconsequential","negligible","paltry","picayune","trivial"]},{"w":"vagary","p":"n.","m":"An unpredictable change.","e":"Latin <i>vagari</i> (to wander).","f":"caprice, aléa","t":"« Les aléas ».","h":["Vagari: wander. Vagaries of weather.","Vagary: whim."],"s":[]},{"w":"vitiate","p":"v.","m":"To spoil or impair.","e":"Latin <i>vitiare</i>, from <i>vitium</i> (fault).","f":"vicier","t":"« Vicier ».","h":["Vitium: fault. Vitiated by bias.","Vitiate: spoil."],"s":["adulterate","compromise","debase","degrade","demean","impair","undermine"]},{"w":"welter","p":"n.","m":"A large disorderly mass.","e":"Middle Dutch <i>welteren</i> (to roll).","f":"fatras, fouillis","t":"Welter = something rolling around in a heap: a welter of data with no structure, « un fatras ».","h":["Welter: roll. A welter of rules.","Welter: jumble."],"s":["hodgepodge"]},{"w":"wizened","p":"adj.","m":"Shrivelled with age.","e":"Old English <i>wisnian</i> (to wither).","f":"ratatiné, desséché","t":"Wizened = withered and wrinkled, like an old apple. Nothing to do with wise.","h":["Wisnian: wither. A wizened face.","Wizened: shrivelled."],"s":["desiccated"]}]},{"name":"GregMat I","slug":"gregmat-i","series":"GregMat","words":[{"w":"abound","p":"v.","m":"To exist in large numbers or amounts.","e":"Latin <i>abundare</i> (to overflow): <i>ab-</i> + <i>unda</i> (wave).","f":"abonder","t":"Same as « abonder »: waves (unda) overflowing.","h":["Ab + unda: wave overflow. Fish abound here.","Abound: be plentiful."],"s":["proliferate"]},{"w":"accentuate","p":"v.","m":"To make more noticeable; to emphasize.","e":"Latin <i>accentus</i> (accent, tone): <i>ad-</i> + <i>cantus</i> (song).","f":"accentuer, souligner","t":"Same as « accentuer ».","h":["Accent. Accentuate the positive.","Accentuate: highlight."],"s":["underscore"]},{"w":"aloof","p":"adj.","m":"Not friendly; distant and cool.","e":"From Dutch sailing term <i>a</i> + <i>luff</i>: keeping the ship to windward, away from the lee shore.","f":"distant, froid, réservé","t":"Keeping your boat away from everyone else. An aloof manager stays apart.","h":["A + loof: windward. Stay aloof.","Aloof: remote."],"s":["apathetic","indifferent","nonchalant","remote"]},{"w":"anachronistic","p":"adj.","m":"Belonging to a period other than the one in which it exists.","e":"Greek <i>anachronismos</i>: <i>ana-</i> (against) + <i>khronos</i> (time).","f":"anachronique","t":"Against time: a smartphone in a Molière play is an « anachronisme ».","h":["Out of time. An anachronistic custom.","Anachronistic: out of date."],"s":["antiquated","archaic","hoary","obsolete"]},{"w":"cacophonous","p":"adj.","m":"Harsh-sounding; a mix of loud, unpleasant sounds.","e":"Greek <i>kakophōnia</i>: <i>kakos</i> (bad) + <i>phōnē</i> (sound).","f":"cacophonique","t":"Kakos (caca!) + phone: bad sound. The cacophony of a Paris traffic jam.","h":["Kakos + phone: bad sound. A cacophonous street.","Cacophonous: noisy."],"s":["discordant"]},{"w":"canonize","p":"v.","m":"To declare a person officially a saint; to regard as great.","e":"Medieval Latin <i>canonizare</i>, from <i>canon</i> (rule, list), Greek <i>kanōn</i>.","f":"canoniser","t":"Same as « canoniser »: added to the list of saints.","h":["Canon: rule. Canonized as a saint.","Canonize: sanctify."],"s":["deify"]},{"w":"chauvinistic","p":"adj.","m":"Excessively or aggressively patriotic; prejudiced in favour of one's own group.","e":"French <i>chauvin</i>, from Nicolas Chauvin, a legendary Napoleonic soldier of fanatical loyalty.","f":"chauvin","t":"A French word! Chauvin, the fanatical soldier of Napoleon. Same as « chauvin ».","h":["Chauvin the soldier. Chauvinistic pride.","Chauvinistic: jingoistic."],"s":["insular","xenophobic"]},{"w":"cherish","p":"v.","m":"To protect and care for lovingly; to hold dear.","e":"Old French <i>cherir</i>, from <i>cher</i> (dear), Latin <i>carus</i>.","f":"chérir","t":"Same as « chérir »: mon cher.","h":["Cher: dear. Cherish memories.","Cherish: treasure."],"s":[]},{"w":"clamorous","p":"adj.","m":"Making a loud and confused noise.","e":"Latin <i>clamare</i> (to cry out).","f":"bruyant, tapageur","t":"A clamour (clameur): a clamorous crowd shouts together.","h":["Clamor: shout. A clamorous mob.","Clamorous: loud."],"s":["boisterous","obstreperous","unruly","vehement","vociferous"]},{"w":"clangor","p":"n.","m":"A continuous loud banging or ringing noise.","e":"Latin <i>clangor</i> (sound of a trumpet), imitative of the sound.","f":"fracas, vacarme","t":"Hear the clang of metal: « clangor » is a loud ringing din. Cousin of « clameur ».","h":["Clangere: ring. The clangor of bells.","Clangor: clanging din."],"s":["clamor"]},{"w":"comity","p":"n.","m":"Courteous and considerate behaviour; mutual respect between states.","e":"Latin <i>comitas</i> (courtesy), from <i>comis</i> (friendly).","f":"courtoisie, bienveillance","t":"From « comité »? No: comity = friendly civility. « Comity of nations »: states respecting each other’s laws.","h":["Comis: courteous. Comity among nations.","Comity: civility."],"s":[]},{"w":"compelling","p":"adj.","m":"Evoking interest or admiration in a powerfully irresistible way; convincing.","e":"Latin <i>compellere</i> (to drive together): <i>com-</i> + <i>pellere</i> (to drive).","f":"convaincant, irrésistible","t":"A compelling argument drives you to agree (compel = contraindre).","h":["Com + pellere: drive. A compelling case.","Compelling: gripping."],"s":["cogent","incisive","telling","trenchant"]},{"w":"congenial","p":"adj.","m":"Pleasant because of shared qualities or interests.","e":"Latin <i>con-</i> (together) + <i>genialis</i> (of one's guiding spirit, <i>genius</i>).","f":"sympathique, agréable","x":"Look-alike","t":"Not « congénital ». Congenial = « sympathique »: a congenial colleague is easy company.","h":["Con + genius: same spirit. A congenial group.","Congenial: pleasantly compatible."],"s":["affable","amiable","amicable","convivial","cordial","genial","jovial"]},{"w":"conjectural","p":"adj.","m":"Based on guesswork rather than proof.","e":"Latin <i>coniectura</i> (inference), from <i>conicere</i> (to throw together).","f":"conjectural, hypothétique","t":"Same as « conjecture » (une conjecture): a guess.","h":["Con + jacere: throw together. Conjectural theory.","Conjectural: guessed."],"s":[]},{"w":"contend","p":"v.","m":"To struggle to overcome; to assert.","e":"Latin <i>contendere</i> (to stretch, strive): <i>con-</i> + <i>tendere</i> (to stretch).","f":"lutter; soutenir, prétendre","x":"2nd meaning","t":"Two meanings: compete (contender) and claim. « Il soutient que… » = he contends that…","h":["Con + tendere: strain against. Contend for the title.","Contend: compete or assert."],"s":["aver","maintain","vie"]},{"w":"conventional","p":"adj.","m":"Based on what is generally done; traditional.","e":"Latin <i>conventio</i> (agreement), from <i>convenire</i> (to come together).","f":"conventionnel, classique","t":"Same as « conventionnel »: following the usual agreement.","h":["Con + venire: come together. Conventional wisdom.","Conventional: customary."],"s":["hidebound","orthodox"]},{"w":"covet","p":"v.","m":"To desire what belongs to someone else.","e":"Old French <i>coveitier</i>, from Latin <i>cupiditas</i> (desire).","f":"convoiter","t":"Same as « convoiter ».","h":["Cupere: desire. Covet her car.","Covet: crave."],"s":[]},{"w":"cursory","p":"adj.","m":"Hasty and not thorough.","e":"Latin <i>cursorius</i> (of running), from <i>currere</i> (to run).","f":"superficiel, rapide","t":"Same root as « cursus » and « courir »: you run through it without stopping.","h":["Currere: run. A cursory glance.","Cursory: hasty."],"s":["desultory","facile","glib","perfunctory","slapdash","superficial","token"]},{"w":"daunting","p":"adj.","m":"Seeming difficult to deal with; intimidating.","e":"Old French <i>danter</i>, from Latin <i>domitare</i> (to tame), <i>domare</i>.","f":"intimidant, décourageant","t":"Danter = dompter: a task so big it tames you. A daunting pile of work.","h":["Domitare: tame. A daunting task.","Daunting: intimidating."],"s":[]},{"w":"decadent","p":"adj.","m":"In a state of moral or cultural decline; luxuriously self-indulgent.","e":"French <i>décadent</i>, Latin <i>de-</i> + <i>cadere</i> (to fall).","f":"décadent","t":"Same as « décadent »: Rome in decline. A decadent chocolate cake.","h":["De + cadere: fall. A decadent dessert.","Decadent: indulgent."],"s":["libertine","self-indulgent"]},{"w":"deft","p":"adj.","m":"Neatly skilful and quick in movement.","e":"Middle English <i>defte</i>, variant of <i>daft</i> (gentle, fitting). Germanic.","f":"habile, adroit","t":"Think « déft »: dexterous fingers. A deft pickpocket, a deft negotiator.","h":["Deft: neat. Deft hands.","Deft: nimble."],"s":["adept","adroit","dexterous","nimble","proficient"]},{"w":"deify","p":"v.","m":"To treat as a god; to worship.","e":"Latin <i>deificare</i>: <i>deus</i> (god) + <i>facere</i> (to make).","f":"déifier, diviniser","t":"Same as « déifier »: make (fier) into a deus.","h":["Deus + facere. They deified the king.","Deify: make a god of."],"s":["canonize","exalt","venerate"]},{"w":"discernible","p":"adj.","m":"Able to be seen or noticed.","e":"Latin <i>discernere</i> (to separate): <i>dis-</i> + <i>cernere</i> (to sift).","f":"discernable, perceptible","t":"Same root as « discerner »: you can tell it apart.","h":["Dis + cernere: separate out. Barely discernible.","Discernible: noticeable."],"s":["appreciable"]},{"w":"dogged","p":"adj.","m":"Persistent and determined.","e":"From <i>dog</i>: with the stubborn grip of a dog. Germanic.","f":"tenace, obstiné","t":"Dogged like a dog on a bone: dogged determination = « une ténacité de bouledogue ».","h":["Dog gripping a bone. Dogged pursuit.","Dogged: tenacious."],"s":["adamant","headstrong","indefatigable","obdurate","obstinate","pertinacious","resolute","staunch","steadfast","tenacious"]},{"w":"enigmatic","p":"adj.","m":"Mysterious and difficult to understand.","e":"Greek <i>ainigma</i> (riddle).","f":"énigmatique","t":"Same as « énigmatique »: the Mona Lisa’s smile.","h":["Ainigma: riddle. An enigmatic smile.","Enigmatic: puzzling."],"s":["arcane","cryptic","impenetrable","inscrutable","obscure"]},{"w":"entitled","p":"adj.","m":"Believing oneself inherently deserving of privileges; having a right to.","e":"From <i>entitle</i>, Old French <i>entiteler</i>, Latin <i>titulus</i> (title).","f":"qui se croit tout permis; ayant droit","x":"2nd meaning","t":"Two senses: having a right (entitled to a refund) or arrogant (an entitled brat).","h":["Title. Entitled to a refund; an entitled brat.","Entitled: owed, or presumptuous."],"s":[]},{"w":"estranged","p":"adj.","m":"No longer close or affectionate; alienated.","e":"Old French <i>estranger</i>, from Latin <i>extraneus</i> (foreign).","f":"séparé, brouillé, éloigné","t":"Made « étranger » to someone: an estranged husband is a stranger now.","h":["Extraneus: outsider. Estranged from family.","Estranged: alienated."],"s":["disaffected","divorced","jaundiced"]},{"w":"explicable","p":"adj.","m":"Able to be explained.","e":"Latin <i>explicare</i> (to unfold, explain): <i>ex-</i> + <i>plicare</i> (to fold).","f":"explicable","t":"Same as « explicable ». Opposite: inexplicable.","h":["Ex + plicare: unfold. An explicable result.","Explicable: explainable."],"s":["intelligible"]},{"w":"extravagant","p":"adj.","m":"Lacking restraint in spending or in behaviour.","e":"Medieval Latin <i>extravagari</i> (to wander outside): <i>extra</i> + <i>vagari</i>.","f":"extravagant, dépensier","t":"Same as « extravagant »: wandering outside the limits.","h":["Extra + vagari: wander beyond. Extravagant gifts.","Extravagant: excessive."],"s":["exorbitant","flamboyant","improvident","lavish","munificent","ostentatious","outlandish","prodigal","profligate","profuse","spendthrift"]},{"w":"fanciful","p":"adj.","m":"Overly imaginative and unrealistic.","e":"From <i>fancy</i>, shortened from <i>fantasy</i>, Greek <i>phantasia</i>.","f":"fantaisiste, imaginaire","t":"Fancy = fantaisie. A fanciful plan lives only in the imagination.","h":["Fancy: imagination. A fanciful tale.","Fanciful: whimsical."],"s":["capricious","droll","quirky","visionary","whimsical"]},{"w":"feasible","p":"adj.","m":"Possible and practical to do.","e":"Old French <i>faisable</i>, from <i>faire</i> (to do), Latin <i>facere</i>.","f":"faisable, réalisable","t":"Feasible = « faisable ». A feasibility study is an étude de faisabilité.","h":["Faire: do. A feasible plan.","Feasible: doable."],"s":["viable"]},{"w":"flamboyant","p":"adj.","m":"Tending to attract attention because of exuberance or confidence.","e":"French <i>flamboyant</i> (flaming), from <i>flamber</i>.","f":"flamboyant, extravagant","t":"Straight from French: flaming. Le style gothique flamboyant.","h":["Flamme. A flamboyant coat.","Flamboyant: showy."],"s":["baroque","exorbitant","extravagant","florid","ornate","ostentatious","outlandish","pretentious"]},{"w":"incendiary","p":"adj.","m":"Designed to start fires; tending to stir up conflict.","e":"Latin <i>incendiarius</i>, from <i>incendium</i> (fire), <i>incendere</i> (to set on fire).","f":"incendiaire","t":"Same as « incendiaire »: an incendiary remark sets the room on fire.","h":["In + candere: set aflame. Incendiary speech.","Incendiary: inflammatory."],"s":["firebrand","inflammatory","provocative"]},{"w":"incredulous","p":"adj.","m":"Unwilling or unable to believe something.","e":"Latin <i>incredulus</i>: <i>in-</i> (not) + <i>credere</i> (to believe).","f":"incrédule","t":"Same as « incrédule ».","h":["In + credere: not believe. An incredulous stare.","Incredulous: doubting."],"s":["dubious"]},{"w":"indiscriminate","p":"adj.","m":"Done at random or without careful judgement.","e":"<i>in-</i> (not) + Latin <i>discriminare</i> (to distinguish).","f":"sans discernement, aveugle","t":"Not « discrimé »: no distinguishing. Indiscriminate bombing hits everything.","h":["Not discriminating. Indiscriminate attacks.","Indiscriminate: random."],"s":["desultory","haphazard","slapdash"]},{"w":"invasive","p":"adj.","m":"Tending to intrude; spreading harmfully.","e":"Latin <i>invadere</i> (to go in): <i>in-</i> + <i>vadere</i> (to go).","f":"invasif, envahissant","t":"Same as « invasif »: invasive species, invasive surgery.","h":["In + vadere: go into. Invasive weeds.","Invasive: encroaching."],"s":["pervasive"]},{"w":"invigorate","p":"v.","m":"To give strength or energy to.","e":"Latin <i>in-</i> + <i>vigor</i> (strength), from <i>vigere</i> (to be lively).","f":"revigorer, donner de la vigueur","t":"In + vigueur: put vigour into someone. An invigorating morning run.","h":["In + vigor. An invigorating swim.","Invigorate: energize."],"s":[]},{"w":"irreverent","p":"adj.","m":"Showing a lack of respect for people or things usually taken seriously.","e":"Latin <i>irreverens</i>: <i>in-</i> (not) + <i>reverens</i> (respectful).","f":"irrévérencieux","t":"Same as « irrévérencieux »: no révérence.","h":["Not reverent. Irreverent jokes.","Irreverent: disrespectful."],"s":["cavalier","flippant","frivolous","glib","impertinent","impudent"]},{"w":"lax","p":"adj.","m":"Not strict or careful enough.","e":"Latin <i>laxus</i> (loose).","f":"relâché, laxiste","t":"Same as « laxiste »: loose rules, lax security.","h":["Laxus: loose. Lax rules.","Lax: slack."],"s":["derelict","negligent","remiss"]},{"w":"loathe","p":"v.","m":"To feel intense dislike or disgust for.","e":"Old English <i>lāthian</i> (to be hateful), from <i>lāth</i> (hostile). Germanic.","f":"détester, avoir en horreur","t":"Loathe, hate. Not to be confused with « loath » (reluctant, no e).","h":["Lath: hate. I loathe mornings.","Loathe: detest."],"s":["abhor","execrate"]},{"w":"malign","p":"v.","m":"To speak harmful untruths about; (adj.) evil in nature.","e":"Latin <i>malignus</i> (ill-natured): <i>malus</i> (bad) + <i>gignere</i> (to beget).","f":"calomnier, dénigrer; malin","t":"Same as « malin » (as in tumeur maligne): malign = speak ill of.","h":["Male + genus: ill-born. Malign gossip.","Malign: slander."],"s":["baleful","belittle","besmirch","defame","denigrate","deprecate","disparage","malevolent","slander","vilify","vindictive","vituperate"]},{"w":"marginalize","p":"v.","m":"To treat as insignificant or peripheral.","e":"Latin <i>margo</i> (edge).","f":"marginaliser","t":"Same as « marginaliser »: push to the margin of the page.","h":["Margin. Marginalize critics.","Marginalize: sideline."],"s":["disenfranchise","ostracize","relegate"]},{"w":"misanthropic","p":"adj.","m":"Disliking other people and avoiding society.","e":"Greek <i>misanthrōpos</i>: <i>misein</i> (to hate) + <i>anthrōpos</i> (human).","f":"misanthrope","t":"Molière’s « Le Misanthrope »: a man who hates mankind.","h":["Miso + anthropos: hates mankind. A misanthropic hermit.","Misanthropic: people-hating."],"s":[]},{"w":"misnomer","p":"n.","m":"A wrong or inaccurate name or term.","e":"Old French <i>mesnommer</i> (to misname): <i>mes-</i> (wrongly) + <i>nommer</i> (to name).","f":"terme impropre, erreur de nom","t":"Mis + nom: a wrong name. « Un abus de langage ».","h":["Mis + nomen: wrong name. Peanut is a misnomer.","Misnomer: wrong label."],"s":[]},{"w":"momentary","p":"adj.","m":"Lasting for a very short time.","e":"Latin <i>momentarius</i>, from <i>momentum</i> (movement, moment).","f":"momentané, passager","t":"Same as « momentané ».","h":["Momentum. A momentary pause.","Momentary: brief."],"s":["ephemeral","evanescent","transient","transitory"]},{"w":"negligent","p":"adj.","m":"Failing to take proper care.","e":"Latin <i>negligens</i>, from <i>neglegere</i> (to disregard): <i>nec</i> + <i>legere</i>.","f":"négligent","t":"Same as « négligent ».","h":["Neg + legere: not pick up. Negligent driver.","Negligent: careless."],"s":["derelict","lax","remiss"]},{"w":"nullify","p":"v.","m":"To make legally void; to cancel out the effect of.","e":"Latin <i>nullus</i> (none) + <i>facere</i> (to make).","f":"annuler, rendre nul","t":"Make nul: « rendre nul et non avenu ».","h":["Nullus: none. Nullify the contract.","Nullify: void."],"s":["abrogate","countermand","negate","neutralize","quash","rescind","squelch","suppress"]},{"w":"obsolete","p":"adj.","m":"No longer produced or used; out of date.","e":"Latin <i>obsolescere</i> (to fall into disuse).","f":"obsolète, désuet","t":"Same as « obsolète ».","h":["Obsolescere: wear out. Obsolete phones.","Obsolete: outdated."],"s":["anachronistic","antiquated","archaic","hoary"]},{"w":"omnipresent","p":"adj.","m":"Present everywhere at the same time.","e":"Latin <i>omni-</i> (all) + <i>praesens</i> (present).","f":"omniprésent","t":"Same as « omniprésent ».","h":["Omni + present. An omnipresent camera.","Omnipresent: everywhere."],"s":["pervasive","rampant","ubiquitous","universal"]},{"w":"oust","p":"v.","m":"To drive out or expel from a position.","e":"Anglo-French <i>ouster</i>, Old French <i>oster</i> (to remove), Latin <i>obstare</i> (to stand in the way).","f":"évincer, chasser","t":"French « ôter »: to remove. A CEO ousted by the board.","h":["Obstare: stand in the way. Oust the chairman.","Oust: expel."],"s":["banish","depose","ostracize","supersede","supplant"]},{"w":"palpable","p":"adj.","m":"So intense it seems almost touchable; easily perceived.","e":"Latin <i>palpabilis</i>, from <i>palpare</i> (to touch gently).","f":"palpable, tangible","t":"Same as « palpable »: you could touch it. Palpable tension.","h":["Palpare: touch. Palpable tension.","Palpable: tangible."],"s":["manifest","overt","patent","tangible"]},{"w":"paradigmatic","p":"adj.","m":"Serving as a typical example or model.","e":"Greek <i>paradeigma</i> (pattern, example): <i>para-</i> (beside) + <i>deiknynai</i> (to show).","f":"paradigmatique, exemplaire","t":"From « paradigme »: the perfect pattern. A paradigmatic case.","h":["Paradeigma: pattern. A paradigmatic case.","Paradigmatic: typical model."],"s":[]},{"w":"pertinacious","p":"adj.","m":"Holding firmly to an opinion or course of action; stubborn.","e":"Latin <i>pertinax</i> (very tenacious): <i>per-</i> (very) + <i>tenax</i> (holding).","f":"tenace, entêté, opiniâtre","t":"Per + tenace: very tenacious. Not « pertinent ».","h":["Per + tenax: very holding. A pertinacious critic.","Pertinacious: stubborn."],"s":["dogged","headstrong","obdurate","obstinate","refractory","resolute","tenacious","unruly","willful"]},{"w":"polarize","p":"v.","m":"To divide into two sharply contrasting groups.","e":"French <i>polariser</i>, from Latin <i>polus</i> (pole), Greek <i>polos</i>.","f":"polariser","t":"Same as « polariser »: a polarizing debate splits into two poles.","h":["Pole. A polarizing issue.","Polarize: split into extremes."],"s":[]},{"w":"polemical","p":"adj.","m":"Relating to strongly critical or controversial argument.","e":"Greek <i>polemikos</i> (of war), from <i>polemos</i> (war).","f":"polémique","t":"Same as « polémique »: a war of words.","h":["Polemos: war. A polemical essay.","Polemical: argumentative."],"s":["contentious"]},{"w":"profundity","p":"n.","m":"Great depth of insight or knowledge.","e":"Latin <i>profunditas</i>, from <i>profundus</i> (deep): <i>pro-</i> + <i>fundus</i> (bottom).","f":"profondeur","t":"Profondeur: a deep thought, with a deep bottom (fundus).","h":["Pro + fundus: deep. Profundity of thought.","Profundity: depth."],"s":[]},{"w":"prophetic","p":"adj.","m":"Accurately predicting what will happen.","e":"Greek <i>prophētēs</i> (one who speaks before): <i>pro-</i> + <i>phēmi</i> (to speak).","f":"prophétique","t":"Same as « prophétique ».","h":["Pro + phemi: speak forth. Prophetic warning.","Prophetic: foretelling."],"s":["portentous","prescient","visionary"]},{"w":"remedial","p":"adj.","m":"Intended to correct or improve something deficient.","e":"Latin <i>remedium</i> (cure): <i>re-</i> + <i>mederi</i> (to heal).","f":"de rattrapage, correctif","t":"A remedy: remedial classes are « cours de rattrapage ».","h":["Remedy. Remedial lessons.","Remedial: corrective."],"s":[]},{"w":"skullduggery","p":"n.","m":"Underhand or unscrupulous behaviour.","e":"17th-century Scottish <i>sculduddery</i> (obscene behaviour), origin unknown.","f":"magouilles, manœuvres louches","t":"A skull and dagger! Shady skullduggery in the boardroom = « des magouilles ».","h":["Scots sculduddery. Political skullduggery.","Skullduggery: shady dealing."],"s":["chicanery","legerdemain","subterfuge"]},{"w":"stern","p":"adj.","m":"Serious and strict, especially in manner.","e":"Old English <i>styrne</i> (severe). Germanic.","f":"sévère, austère","x":"2nd meaning","t":"A stern teacher is strict. (Also the back of a ship: another meaning.)","h":["Stearn: firm. A stern look.","Stern: strict."],"s":["austere","dour"]},{"w":"stigmatize","p":"v.","m":"To describe or regard as worthy of disgrace.","e":"Greek <i>stigma</i> (mark, brand burned on the skin).","f":"stigmatiser","t":"Same as « stigmatiser »: to brand someone.","h":["Stigma: brand mark. Stigmatize addicts.","Stigmatize: shame."],"s":["castigate","censure","decry","denounce","excoriate","lampoon","pillory","vilify"]},{"w":"subjective","p":"adj.","m":"Based on personal feelings rather than facts.","e":"Latin <i>subjectivus</i>, from <i>subjectus</i> (placed under).","f":"subjectif","t":"Same as « subjectif »: opinion, not fact.","h":["Subject’s view. Subjective taste.","Subjective: personal."],"s":[]},{"w":"subvert","p":"v.","m":"To undermine the power of an established system.","e":"Latin <i>subvertere</i> (to overturn): <i>sub-</i> + <i>vertere</i> (to turn).","f":"subvertir, renverser","t":"Same as « subversif »: turn it upside down from below.","h":["Sub + vertere: turn from beneath. Subvert authority.","Subvert: undermine."],"s":["undermine"]},{"w":"tranquil","p":"adj.","m":"Free from disturbance; calm.","e":"Latin <i>tranquillus</i> (calm, still).","f":"tranquille","t":"Same as « tranquille ».","h":["Trans + quies: beyond disturbance. A tranquil lake.","Tranquil: peaceful."],"s":["halcyon","placid","serene"]},{"w":"trivial","p":"adj.","m":"Of little value or importance.","e":"Latin <i>trivialis</i> (of the crossroads, common): <i>tri-</i> (three) + <i>via</i> (road).","f":"insignifiant, banal","x":"Faux ami","t":"French « trivial » means vulgar. English trivial = unimportant: « sans importance ».","h":["Trivium: crossroads, commonplace. Trivial details.","Trivial: petty."],"s":["extraneous","flippant","frivolous","immaterial","inconsequential","negligible","paltry","picayune","trifling","venial"]},{"w":"utterly","p":"adv.","m":"Completely and absolutely.","e":"From <i>utter</i> (outer, extreme), Old English <i>ūtera</i>, from <i>ūt</i> (out). Germanic.","f":"complètement, tout à fait","t":"To the outermost limit: utterly ridiculous = tout à fait ridicule.","h":["Outer-most. Utterly lost.","Utterly: totally."],"s":[]},{"w":"vapid","p":"adj.","m":"Offering nothing that is stimulating or challenging; dull.","e":"Latin <i>vapidus</i> (flat, flavourless, like wine that has lost its spirit).","f":"insipide, fade","t":"Flat like a wine gone off: « fade ». A vapid conversation.","h":["Vapidus: flat. Vapid chat.","Vapid: bland."],"s":["anodyne","insipid","jejune","naive","puerile"]},{"w":"venal","p":"adj.","m":"Willing to do dishonest things for money; corrupt.","e":"Latin <i>venalis</i> (for sale), from <i>venum</i> (sale).","f":"vénal, corrompu","t":"Same as « vénal »: someone whose loyalty is for sale.","h":["Venum: sale. A venal judge.","Venal: bribable."],"s":["avaricious","mercenary","unscrupulous"]},{"w":"weary","p":"adj.","m":"Tired; also, cautious about something because of past experience.","e":"Old English <i>wērig</i> (tired). Germanic.","f":"las, fatigué","x":"Look-alike","t":"Not « wary » (prudent). Weary = las: weary of the job market.","h":["Weary: tired. Weary traveller.","Weary: worn out."],"s":[]}]},{"name":"GregMat II","slug":"gregmat-ii","series":"GregMat","words":[{"w":"acquiesce","p":"v.","m":"To accept something reluctantly but without protest.","e":"Latin <i>acquiescere</i> (to rest): <i>ad-</i> + <i>quies</i> (rest).","f":"acquiescer, consentir","t":"Same as « acquiescer »: you rest your objections.","h":["Ad + quiescere: rest. Acquiesce in silence.","Acquiesce: comply."],"s":["adhere","capitulate","comply"]},{"w":"acrimonious","p":"adj.","m":"Angry and bitter.","e":"Latin <i>acrimonia</i>, from <i>acer</i> (sharp).","f":"acrimonieux, acerbe","t":"Same as « acrimonieux »: sharp (acre) words.","h":["Acer: sharp. An acrimonious split.","Acrimonious: bitter."],"s":["virulent","vitriolic"]},{"w":"adroit","p":"adj.","m":"Clever or skilful, especially in handling difficult situations.","e":"French <i>à droit</i> (rightly), from <i>droit</i> (right).","f":"adroit","t":"Same as « adroit » — even the opposite is French: « maladroit » = inept.","h":["A droit: to the right. Adroit move.","Adroit: skilful."],"s":["adept","deft","dexterous","nimble","proficient"]},{"w":"affinity","p":"n.","m":"A natural liking or attraction; similarity.","e":"Latin <i>affinitas</i> (relationship by marriage), from <i>affinis</i> (bordering).","f":"affinité","t":"Same as « affinité »: « avoir des affinités ».","h":["Ad + finis: bordering. An affinity for music.","Affinity: natural bond."],"s":[]},{"w":"altruistic","p":"adj.","m":"Showing selfless concern for others.","e":"French <i>altruisme</i>, from Latin <i>alter</i> (other).","f":"altruiste","t":"Same as « altruiste ».","h":["Alter: other. Altruistic donor.","Altruistic: selfless."],"s":[]},{"w":"amend","p":"v.","m":"To make minor changes to improve; to correct.","e":"Latin <i>emendare</i> (to free from fault), <i>e-</i> + <i>menda</i> (fault).","f":"amender, modifier","t":"Same as « amender »: un amendement to a law. Not « emend » (to correct a text).","h":["Emendare: fix. Amend the clause.","Amend: improve."],"s":["ameliorate","redress"]},{"w":"antithesis","p":"n.","m":"A direct opposite; a contrast of ideas.","e":"Greek <i>antithesis</i>: <i>anti-</i> (against) + <i>tithenai</i> (to place).","f":"antithèse, contraire","t":"Same as « antithèse »: placed against.","h":["Anti + tithenai: set against. Antithesis of peace.","Antithesis: exact opposite."],"s":[]},{"w":"baroque","p":"adj.","m":"Highly ornate and extravagant.","e":"French <i>baroque</i>, from Portuguese <i>barroco</i> (irregular pearl).","f":"baroque","t":"Same as « baroque »: complex and over-decorated.","h":["Barroco: odd pearl. Baroque excess.","Baroque: ornate."],"s":["elaborate","flamboyant","florid","ornate"]},{"w":"befuddled","p":"adj.","m":"Unable to think clearly; confused.","e":"From <i>be-</i> + <i>fuddle</i> (to confuse, probably drink-related), origin unclear.","f":"embrouillé, déboussolé","t":"Fuddled brain, as if drunk: « l'esprit brouillé ».","h":["Be + fuddle. Befuddled by the maths.","Befuddled: muddled."],"s":["flummoxed","flustered","nonplussed"]},{"w":"beneficent","p":"adj.","m":"Doing good; generous.","e":"Latin <i>beneficus</i>: <i>bene</i> (well) + <i>facere</i> (to do).","f":"bienfaisant","t":"Bene + facere = « bienfaisant ».","h":["Bene + facere. A beneficent donor.","Beneficent: kindly giving."],"s":["benevolent","benign","munificent"]},{"w":"boisterous","p":"adj.","m":"Noisy, energetic and cheerful.","e":"Middle English <i>boistous</i> (rough, coarse), origin unknown.","f":"bruyant, turbulent","t":"Not « boisson ». A boisterous party is rowdy.","h":["Boistous: rough. A boisterous crowd.","Boisterous: rowdy."],"s":["clamorous","obstreperous","turbulent","unruly","vociferous"]},{"w":"canny","p":"adj.","m":"Shrewd, especially in money matters.","e":"From Scots <i>can</i> (to know), Old English <i>cunnan</i>.","f":"astucieux, avisé","t":"Knows how to: a canny investor. Cousin of « cunning ».","h":["Can: know. A canny buyer.","Canny: shrewd."],"s":["artful","astute","discreet","expedient","frugal","judicious","percipient","perspicacious","politic","provident","prudent","sagacious","savvy","shrewd","thrifty"]},{"w":"clandestine","p":"adj.","m":"Kept secret, especially because illicit.","e":"Latin <i>clandestinus</i>, from <i>clam</i> (secretly).","f":"clandestin","t":"Same as « clandestin ».","h":["Clam: secretly. A clandestine meeting.","Clandestine: hidden."],"s":["covert","furtive","surreptitious","ulterior"]},{"w":"compromise","p":"v.","m":"To weaken or damage; to settle by mutual concession.","e":"Latin <i>compromissum</i> (mutual promise): <i>com-</i> + <i>promittere</i>.","f":"compromettre; faire un compromis","x":"2nd meaning","t":"Two uses: reach a compromise, OR « compromettre » (compromise safety = endanger it).","h":["Com + promittere. Compromise safety.","Compromise: weaken or settle."],"s":["impair","jeopardize","undermine","vitiate"]},{"w":"cordial","p":"adj.","m":"Warm and friendly.","e":"Medieval Latin <i>cordialis</i>, from Latin <i>cor, cordis</i> (heart).","f":"cordial, chaleureux","t":"Same as « cordial »: from the heart (cœur).","h":["Cor: heart. A cordial welcome.","Cordial: warm."],"s":["affable","amiable","amicable","congenial","convivial","genial","jovial"]},{"w":"countenance","p":"v.","m":"To tolerate or approve; (n.) the face.","e":"Old French <i>contenance</i> (bearing), Latin <i>continere</i> (to hold together).","f":"tolérer, approuver; contenance, visage","x":"2nd meaning","t":"Contenance. As a verb: « ne pas cautionner ». I will not countenance such behaviour.","h":["Contenance: bearing. Countenance no lies.","Countenance: tolerate."],"s":["abide","brook","condone","sanction"]},{"w":"credible","p":"adj.","m":"Able to be believed; convincing.","e":"Latin <i>credibilis</i>, from <i>credere</i> (to believe).","f":"crédible","t":"Same as « crédible ».","h":["Credere: believe. A credible witness.","Credible: believable."],"s":["plausible","specious","tenable"]},{"w":"debilitating","p":"adj.","m":"Making someone weak and infirm.","e":"Latin <i>debilitare</i>, from <i>debilis</i> (weak).","f":"débilitant, affaiblissant","t":"From « débile » (weak), not stupid: a debilitating illness drains strength.","h":["Debilis: weak. Debilitating flu.","Debilitating: sapping."],"s":[]},{"w":"diffuse","p":"adj.","m":"Spread over a wide area; not concise. (v. diffuse = to spread)","e":"Latin <i>diffundere</i>: <i>dis-</i> + <i>fundere</i> (to pour).","f":"diffus, prolixe","t":"Same as « diffus »: a diffuse writing style never gets to the point.","h":["Dis + fundere: pour apart. Diffuse prose.","Diffuse: spread out, wordy."],"s":["desultory","discursive","disperse","disseminate","dissipate","prolix","promulgate","propagate","verbose"]},{"w":"distressed","p":"adj.","m":"Suffering anxiety or pain; (of goods) sold at a low price; (of furniture) aged on purpose.","e":"Old French <i>destresse</i>, Latin <i>districtus</i> (restrained).","f":"affligé, en détresse","x":"2nd meaning","t":"Détresse. But distressed jeans are artificially worn.","h":["Distress. Distressed denim.","Distressed: upset or worn."],"s":[]},{"w":"documentary","p":"adj.","m":"Consisting of documents; based on factual evidence.","e":"Latin <i>documentum</i> (lesson, proof), from <i>docere</i> (to teach).","f":"documentaire, sur documents","t":"Documentary evidence = « preuves documentaires ».","h":["Document. Documentary proof.","Documentary: based on records."],"s":[]},{"w":"dwindling","p":"adj.","m":"Diminishing gradually.","e":"From <i>dwindle</i>, Old English <i>dwīnan</i> (to shrink). Germanic.","f":"qui diminue, décroissant","t":"Dwindling supplies are slowly vanishing: « s'amenuiser ».","h":["Dwine: fade. Dwindling stock.","Dwindling: shrinking."],"s":[]},{"w":"eclipse","p":"v.","m":"To obscure or surpass in importance.","e":"Greek <i>ekleipsis</i>: <i>ek-</i> + <i>leipein</i> (to leave).","f":"éclipser","t":"Same as « éclipser »: a star outshines the others.","h":["Ekleipsis: abandonment. Eclipse his rivals.","Eclipse: outshine."],"s":["obscure","outstrip","transcend"]},{"w":"edify","p":"v.","m":"To instruct or improve morally or intellectually.","e":"Latin <i>aedificare</i> (to build): <i>aedes</i> (building) + <i>facere</i>.","f":"édifier, instruire","t":"Same as « édifier »: build up the mind, like building an édifice.","h":["Aedificare: build. Edify the young.","Edify: uplift mentally."],"s":[]},{"w":"encyclopedic","p":"adj.","m":"Comprehensive in scope.","e":"Greek <i>enkyklios paideia</i> (general education).","f":"encyclopédique","t":"Same as « encyclopédique »: knowing everything.","h":["Enkyklios paideia: full education. Encyclopedic knowledge.","Encyclopedic: all-embracing."],"s":["all-ecompassing","exhaustive","thorough"]},{"w":"exasperated","p":"adj.","m":"Intensely irritated.","e":"Latin <i>exasperare</i>: <i>ex-</i> + <i>asper</i> (rough).","f":"exaspéré","t":"Same as « exaspéré ».","h":["Ex + asper: rough. Exasperated sigh.","Exasperated: fed up."],"s":[]},{"w":"exhaustive","p":"adj.","m":"Examining or including all elements; thorough.","e":"Latin <i>exhaurire</i> (to drain out).","f":"exhaustif","t":"Same as « exhaustif »: leave nothing out. Not « exhausting ».","h":["Ex + haurire: drain. An exhaustive search.","Exhaustive: complete."],"s":["all-ecompassing","arrant","encyclopedic","meticulous","painstaking","thorough","thoroughgoing"]},{"w":"exhilarating","p":"adj.","m":"Making one feel very happy, animated or elated.","e":"Latin <i>exhilarare</i>: <i>ex-</i> + <i>hilaris</i> (cheerful).","f":"grisant, euphorisant","t":"Hilarious inside: hilaris. An exhilarating rollercoaster.","h":["Ex + hilaris: cheer. Exhilarating ride.","Exhilarating: thrilling."],"s":["heady","potent"]},{"w":"expedite","p":"v.","m":"To make an action or process happen sooner or be accomplished more quickly.","e":"Latin <i>expedire</i> (to free the feet): <i>ex-</i> + <i>pes, pedis</i> (foot).","f":"accélérer, expédier","t":"Free the feet and go: « expédier » une affaire. Opposite of impede.","h":["Ex + pes: free the foot. Expedite delivery.","Expedite: speed up."],"s":["dispatch","facilitate"]},{"w":"feeble","p":"adj.","m":"Lacking physical strength; weak.","e":"Old French <i>feble</i>, Latin <i>flebilis</i> (lamentable).","f":"faible, débile","t":"Feeble = « faible » (feble → faible).","h":["Flebilis: tearful. A feeble excuse.","Feeble: weak."],"s":["anemic"]},{"w":"feign","p":"v.","m":"To pretend to be affected by (a feeling or state).","e":"Old French <i>feindre</i>, Latin <i>fingere</i> (to shape, invent).","f":"feindre, simuler","t":"Same as « feindre ».","h":["Fingere: shape. Feign illness.","Feign: pretend."],"s":["dissemble","malinger","sham","shirk"]},{"w":"felicitous","p":"adj.","m":"Well chosen or apt; pleasing.","e":"Latin <i>felicitas</i> (happiness), from <i>felix</i> (happy).","f":"heureux, bien choisi","t":"Une formule heureuse: a felicitous phrase fits perfectly. Cousin of « félicité ».","h":["Felix: happy. A felicitous phrase.","Felicitous: apt."],"s":["apposite","apropos","apt","germane","pertinent"]},{"w":"fervor","p":"n.","m":"Intense and passionate feeling.","e":"Latin <i>fervor</i> (boiling heat), from <i>fervere</i> (to boil).","f":"ferveur","t":"Same as « ferveur ».","h":["Fervere: boil. Religious fervor.","Fervor: passion."],"s":["zeal"]},{"w":"forbear","p":"v.","m":"To refrain from; to hold back.","e":"Old English <i>forberan</i>: <i>for-</i> (away) + <i>beran</i> (to bear).","f":"s'abstenir de, se retenir","x":"Look-alike","t":"Bear back your anger. Not to be confused with « forebear » (ancestor).","h":["For + bear. Forbear from comment.","Forbear: hold back."],"s":["abstain","forgo"]},{"w":"fungible","p":"adj.","m":"Replaceable by another identical item; interchangeable.","e":"Medieval Latin <i>fungibilis</i>, from <i>fungi vice</i> (to perform in place of).","f":"fongible, interchangeable","t":"Fongible: a euro is fungible, a painting is not.","h":["Fungi: perform. Fungible goods.","Fungible: swappable."],"s":["interchangeable"]},{"w":"illusory","p":"adj.","m":"Based on illusion; not real.","e":"Latin <i>illusorius</i>, from <i>illudere</i> (to mock).","f":"illusoire","t":"Same as « illusoire ».","h":["Illudere: mock. An illusory gain.","Illusory: not real."],"s":["specious"]},{"w":"indispensable","p":"adj.","m":"Absolutely necessary.","e":"<i>in-</i> + <i>dispensable</i>, Latin <i>dispensare</i> (to weigh out).","f":"indispensable","t":"Same as « indispensable ».","h":["Not dispensable. An indispensable tool.","Indispensable: essential."],"s":["imperative"]},{"w":"interchangeable","p":"adj.","m":"Able to be exchanged with each other.","e":"<i>inter-</i> + <i>change</i>, Old French <i>changier</i>.","f":"interchangeable","t":"Same as « interchangeable ».","h":["Inter + change. Interchangeable parts.","Interchangeable: swappable."],"s":["fungible"]},{"w":"lucrative","p":"adj.","m":"Producing a great deal of profit.","e":"Latin <i>lucrativus</i>, from <i>lucrum</i> (gain).","f":"lucratif","t":"Same as « lucratif ».","h":["Lucrum: gain. A lucrative deal.","Lucrative: profitable."],"s":["fecund","fruitful","prolific"]},{"w":"mercenary","p":"adj.","m":"Motivated primarily by money.","e":"Latin <i>mercenarius</i> (hired), from <i>merces</i> (wages).","f":"mercenaire, intéressé","t":"Same as « mercenaire »: acting only for the pay.","h":["Merces: wages. A mercenary motive.","Mercenary: money-driven."],"s":["avaricious","unscrupulous","venal"]},{"w":"metaphorical","p":"adj.","m":"Used in a figurative sense, not literal.","e":"Greek <i>metaphora</i>: <i>meta-</i> (across) + <i>pherein</i> (to carry).","f":"métaphorique","t":"Same as « métaphorique ».","h":["Meta + pherein: carry across. Metaphorical sense.","Metaphorical: figurative."],"s":["allegorical","figurative"]},{"w":"mimic","p":"v.","m":"To imitate, especially to ridicule.","e":"Greek <i>mimos</i> (imitator).","f":"imiter, singer","t":"Mimic = « mime »: act like someone else.","h":["Mimos: actor. Mimic a voice.","Mimic: copy."],"s":["emulate"]},{"w":"numinous","p":"adj.","m":"Having a strong religious or spiritual quality; awe-inspiring.","e":"Latin <i>numen</i> (divine power).","f":"numineux, sacré","t":"Numen = divinity. Sensing a god in a cathedral.","h":["Numen: divine will. A numinous hush.","Numinous: spiritual awe."],"s":[]},{"w":"obeisance","p":"n.","m":"Deferential respect; a gesture of submission.","e":"Old French <i>obeissance</i>, from <i>obeir</i> (to obey).","f":"révérence, soumission","t":"Obéissance + « révérence »: a deep bow.","h":["Obeir: obey. Bow in obeisance.","Obeisance: homage."],"s":["deference"]},{"w":"partial","p":"adj.","m":"Existing only in part; biased, or fond of something.","e":"Medieval Latin <i>partialis</i>, from <i>pars</i> (part).","f":"partiel; partial, favorable à","x":"2nd meaning","t":"Three senses: incomplete (partiel), biased (partial), and « partial to » = fond of.","h":["Pars: part. Partial to cake; a partial judge.","Partial: incomplete or biased."],"s":["partisan"]},{"w":"pensive","p":"adj.","m":"Engaged in deep or serious thought.","e":"Old French <i>pensif</i>, from <i>penser</i> (to think).","f":"pensif, songeur","t":"Same as « pensif ».","h":["Pensare: weigh. A pensive mood.","Pensive: thoughtful."],"s":["melancholy","wistful"]},{"w":"perilous","p":"adj.","m":"Full of danger or risk.","e":"Latin <i>periculosus</i>, from <i>periculum</i> (danger).","f":"périlleux","t":"Same as « périlleux ».","h":["Periculum: danger. A perilous climb.","Perilous: risky."],"s":["precarious"]},{"w":"peripheral","p":"adj.","m":"Of secondary importance; on the edge.","e":"Greek <i>peripheria</i>: <i>peri-</i> (around) + <i>pherein</i> (to carry).","f":"périphérique, secondaire","t":"Périphérique (le boulevard!) = the ring around the middle.","h":["Peri + pherein: carry around. Peripheral vision.","Peripheral: marginal."],"s":["concomitant","incidental","tangential"]},{"w":"portend","p":"v.","m":"To be an omen or warning of.","e":"Latin <i>portendere</i> (to point out, foretell): <i>por-</i> + <i>tendere</i>.","f":"présager, annoncer","t":"Same family as « portent » (a bad sign): dark clouds portend a storm.","h":["Pro + tendere: stretch ahead. Clouds portend rain.","Portend: foreshadow."],"s":["forebode","prefigure","presage"]},{"w":"provocative","p":"adj.","m":"Causing a strong reaction, especially anger or arousal.","e":"Latin <i>provocativus</i>, from <i>provocare</i> (to call forth).","f":"provocant, provocateur","t":"Same as « provocant ».","h":["Pro + vocare: call forth. A provocative remark.","Provocative: stirring."],"s":["incendiary","inflammatory"]},{"w":"quirky","p":"adj.","m":"Characterized by peculiar or unconventional traits.","e":"From <i>quirk</i> (odd twist), origin uncertain.","f":"excentrique, original","t":"A quirk is a petite manie: a quirky sense of humour.","h":["Quirk: oddity. Quirky humour.","Quirky: offbeat."],"s":["capricious","droll","eccentric","fanciful","idiosyncratic","outlandish","peculiar","whimsical"]},{"w":"rapacious","p":"adj.","m":"Aggressively greedy or grasping.","e":"Latin <i>rapax</i>, from <i>rapere</i> (to seize).","f":"rapace, avide","t":"Same as « rapace »: a bird of prey. Rapacious landlords seize everything.","h":["Rapere: seize. Rapacious greed.","Rapacious: predatory."],"s":["acquisitive","avaricious","ravenous","voracious"]},{"w":"rational","p":"adj.","m":"Based on reason or logic.","e":"Latin <i>rationalis</i>, from <i>ratio</i> (reckoning, reason).","f":"rationnel","t":"Same as « rationnel ».","h":["Ratio: reason. A rational choice.","Rational: logical."],"s":["lucid","sound"]},{"w":"relish","p":"v.","m":"To enjoy greatly.","e":"Old French <i>relais</i> (something left behind, a savour), from <i>relaisser</i>.","f":"savourer, se délecter de","t":"Relish a meal = savourer. (Also n.: a condiment.)","h":["Reles: aftertaste. Relish the challenge.","Relish: savour."],"s":["gloat","savor"]},{"w":"renounce","p":"v.","m":"To formally give up or reject.","e":"Latin <i>renuntiare</i> (to announce against): <i>re-</i> + <i>nuntiare</i>.","f":"renoncer à","t":"Same as « renoncer ».","h":["Re + nuntiare. Renounce the throne.","Renounce: give up."],"s":["abjure","cede","forgo","forsake","jettison","recant","relinquish","repudiate","retract","spurn"]},{"w":"salutary","p":"adj.","m":"Beneficial, especially when unpleasant.","e":"Latin <i>salutaris</i>, from <i>salus</i> (health).","f":"salutaire","t":"Same as « salutaire »: a salutary lesson.","h":["Salus: health. A salutary shock.","Salutary: good for you."],"s":["salubrious"]},{"w":"satirical","p":"adj.","m":"Using irony or mockery to expose folly.","e":"Latin <i>satira</i> (a medley, mixed dish).","f":"satirique","t":"Same as « satirique »: Charlie Hebdo.","h":["Satura: medley. A satirical show.","Satirical: mocking."],"s":["sardonic"]},{"w":"scathing","p":"adj.","m":"Witheringly scornful; severely critical.","e":"Old Norse <i>skaða</i> (to harm). Germanic.","f":"cinglant, acerbe","t":"A scathing review leaves scars: « cinglant ».","h":["Scathe: harm. A scathing review.","Scathing: harshly critical."],"s":["acerbic","astringent","caustic","mordant","trenchant","virulent","vitriolic"]},{"w":"sever","p":"v.","m":"To cut off; to end a connection.","e":"Old French <i>sevrer</i> (to separate), Latin <i>separare</i>.","f":"couper, rompre; sevrer","t":"Related to « sevrer » and « séparer »: sever ties.","h":["Separare. Sever the rope.","Sever: cut off."],"s":[]},{"w":"sham","p":"n.","m":"Something fake presented as genuine.","e":"17th-century slang, perhaps a variant of <i>shame</i>.","f":"imposture, faux-semblant","t":"A sham marriage: a « mariage blanc ». A fake.","h":["Sham: trick. A sham trial.","Sham: fake."],"s":["bogus","caricature","charlatan","counterfeit","dissemble","ersatz","fallacious","feign","phony","specious","spurious","travesty"]},{"w":"skirt","p":"v.","m":"To avoid dealing with; to go around the edge of.","e":"Old Norse <i>skyrta</i> (shirt). Germanic.","f":"contourner, éluder","t":"The skirt is the edge of the garment: you go around the edge. Skirt the issue = contourner.","h":["Skirt: edge. Skirt the issue.","Skirt: avoid."],"s":["circumvent","elude","evade"]},{"w":"sluggish","p":"adj.","m":"Slow-moving; lacking energy.","e":"From <i>slug</i>, Scandinavian <i>slugga</i> (to be slow).","f":"lent, apathique","t":"Like a slug (limace): a sluggish economy.","h":["Slug. Sluggish sales.","Sluggish: slow."],"s":["apathetic","dilatory","indolent","inert","languid","lethargic","passive"]},{"w":"somnolent","p":"adj.","m":"Sleepy; inducing drowsiness.","e":"Latin <i>somnolentus</i>, from <i>somnus</i> (sleep).","f":"somnolent","t":"Same as « somnolent »: somnus = sleep.","h":["Somnus: sleep. A somnolent afternoon.","Somnolent: drowsy."],"s":["soporific"]},{"w":"stoic","p":"adj.","m":"Enduring pain or hardship without showing feelings.","e":"Greek <i>Stoikos</i>, from <i>stoa</i> (porch where Zeno taught).","f":"stoïque","t":"Same as « stoïque ».","h":["Stoa: porch of the philosophers. Stoic in grief.","Stoic: uncomplaining."],"s":["phlegmatic","placid","stolid","unflappable"]},{"w":"subtle","p":"adj.","m":"So delicate as to be difficult to analyze; clever and indirect.","e":"Latin <i>subtilis</i> (finely woven): <i>sub-</i> + <i>tela</i> (web).","f":"subtil, délicat","t":"Same as « subtil »: finely woven.","h":["Sub + tela: fine thread. A subtle hint.","Subtle: delicate."],"s":["elusive","evasive","insidious","muted","pernicious","treacherous","understated"]},{"w":"superficial","p":"adj.","m":"Existing only on the surface; lacking depth.","e":"Latin <i>superficies</i>: <i>super-</i> + <i>facies</i> (face).","f":"superficiel","t":"Same as « superficiel ».","h":["Super + facies: face. Superficial wound.","Superficial: shallow."],"s":["cursory","desultory","facile","glib","perfunctory","slapdash","token"]},{"w":"tenable","p":"adj.","m":"Able to be defended against attack or objection.","e":"Old French <i>tenir</i> (to hold), Latin <i>tenere</i>.","f":"défendable, soutenable","t":"Tenable = « tenable »: a position you can hold. Untenable = indéfendable.","h":["Tenere: hold. A tenable theory.","Tenable: defensible."],"s":["credible","plausible","sound","viable"]},{"w":"turbulent","p":"adj.","m":"Characterized by conflict, disorder or confusion.","e":"Latin <i>turbulentus</i>, from <i>turba</i> (crowd, disorder).","f":"turbulent, agité","t":"Same as « turbulent ».","h":["Turba: crowd. Turbulent times.","Turbulent: stormy."],"s":["boisterous","obstreperous","tempestuous","unruly","volatile"]},{"w":"wane","p":"v.","m":"To decrease gradually in size, strength or power.","e":"Old English <i>wanian</i> (to lessen). Germanic.","f":"décliner, décroître","t":"The moon wanes (« décroît »). Opposite: wax.","h":["Wanian: lessen. The moon wanes.","Wane: dwindle."],"s":["abate","subside"]}]},{"name":"GregMat III","slug":"gregmat-iii","series":"GregMat","words":[{"w":"abet","p":"v.","m":"To encourage or assist, typically in wrongdoing.","e":"Old French <i>abeter</i> (to bait, incite).","f":"encourager, soutenir (un délit)","t":"Aid and abet = « être complice ».","h":["A + betan: bait on. Abet a crime.","Abet: assist wrongdoing."],"s":[]},{"w":"accessible","p":"adj.","m":"Able to be reached or understood.","e":"Latin <i>accessibilis</i>, from <i>accedere</i> (to approach).","f":"accessible","t":"Same as « accessible ».","h":["Ad + cedere: approach. Accessible prose.","Accessible: reachable."],"s":[]},{"w":"acclaim","p":"v.","m":"To praise enthusiastically and publicly.","e":"Latin <i>acclamare</i>: <i>ad-</i> + <i>clamare</i> (to shout).","f":"acclamer, saluer","t":"Same as « acclamer ».","h":["Ad + clamare: shout to. Critical acclaim.","Acclaim: applaud."],"s":["exalt","extol","hail","laud","lionize"]},{"w":"acquisitive","p":"adj.","m":"Excessively interested in acquiring money or material things.","e":"Latin <i>acquirere</i> (to get).","f":"cupide, avide de possession","t":"Same as « acquisitif »: always wanting to buy more.","h":["Acquirere: gain. An acquisitive tycoon.","Acquisitive: greedy for gain."],"s":["avaricious","rapacious"]},{"w":"alienate","p":"v.","m":"To make someone feel isolated or estranged.","e":"Latin <i>alienare</i>, from <i>alienus</i> (of another).","f":"aliéner, s'aliéner","t":"Same as « aliéner »: s'aliéner ses collègues.","h":["Alienus: other. Alienate allies.","Alienate: estrange."],"s":["antagonize"]},{"w":"animus","p":"n.","m":"Hostility or ill feeling; a motivating spirit.","e":"Latin <i>animus</i> (mind, spirit, anger).","f":"animosité, hostilité","t":"Cousin of « animosité »: feeling of hostility. Animus toward a rival.","h":["Animus: spirit. Animus toward rivals.","Animus: ill will."],"s":["animosity","antipathy","enmity"]},{"w":"apologist","p":"n.","m":"A person who offers a formal defence of a controversial idea or institution.","e":"Greek <i>apologia</i> (a speech in defence): <i>apo-</i> + <i>logos</i>.","f":"apologiste, défenseur","x":"Look-alike","t":"Not someone who says sorry! A defender: « un apologiste » of a regime.","h":["Apologia: defence speech. A regime’s apologist.","Apologist: defender."],"s":["advocate","champion","proponent"]},{"w":"apropos","p":"adj.","m":"Very appropriate to a particular situation.","e":"French <i>à propos</i> (to the purpose).","f":"à propos, pertinent","t":"Straight from French « à propos ».","h":["À propos. An apropos comment.","Apropos: fitting."],"s":["apposite","apt","felicitous","germane","pertinent"]},{"w":"apt","p":"adj.","m":"Appropriate or suitable; having a tendency to.","e":"Latin <i>aptus</i> (fitted).","f":"approprié; enclin à","x":"2nd meaning","t":"Apte = suitable. Also apt to (+ verb) = tends to.","h":["Aptus: fitted. An apt reply.","Apt: suitable."],"s":["apposite","apropos","felicitous","germane","inclined","pertinent"]},{"w":"ascertain","p":"v.","m":"To find out for certain.","e":"Old French <i>acertener</i>, from <i>certain</i>.","f":"s'assurer de, établir","t":"A + certain: make certain. « S'assurer ».","h":["Ad + certain. Ascertain the facts.","Ascertain: verify."],"s":[]},{"w":"assertive","p":"adj.","m":"Having or showing a confident and forceful personality.","e":"Latin <i>asserere</i> (to claim): <i>ad-</i> + <i>serere</i> (to join).","f":"affirmé, assuré","t":"« Assertif ». Cousin of « assertion ».","h":["Asserere: claim. An assertive manner.","Assertive: forceful."],"s":[]},{"w":"astringent","p":"adj.","m":"Sharp or severe in manner or style; causing tissues to contract.","e":"Latin <i>astringere</i> (to bind tight): <i>ad-</i> + <i>stringere</i>.","f":"astringent, âpre, mordant","t":"Same as « astringent »: tightens the skin; astringent wit is dry and cutting.","h":["Ad + stringere: bind. Astringent wit.","Astringent: sharp, tightening."],"s":["acerbic","caustic","mordant","scathing","vitriolic"]},{"w":"aversion","p":"n.","m":"A strong dislike.","e":"Latin <i>aversio</i>, from <i>avertere</i> (to turn away).","f":"aversion, répugnance","t":"Same as « aversion ».","h":["A + vertere: turn away. An aversion to heights.","Aversion: strong dislike."],"s":["antipathy"]},{"w":"bogus","p":"adj.","m":"Not genuine; fake.","e":"19th-century American slang, origin uncertain.","f":"faux, bidon","t":"« Bidon »: a bogus claim.","h":["Bogus: fake coin. A bogus claim.","Bogus: sham."],"s":["counterfeit","ersatz","fallacious","phony","sham","specious","spurious"]},{"w":"cataclysmic","p":"adj.","m":"Relating to a violent upheaval or disaster.","e":"Greek <i>kataklysmos</i> (flood): <i>kata-</i> + <i>klyzein</i> (to wash).","f":"cataclysmique, catastrophique","t":"Same as « cataclysme »: a flood.","h":["Kata + kluzein. A cataclysmic flood.","Cataclysmic: disastrous."],"s":["calamitous","catastrophic"]},{"w":"cloak","p":"v.","m":"To cover or hide.","e":"Old French <i>cloque</i> (bell-shaped cape), Latin <i>clocca</i> (bell).","f":"dissimuler, masquer","t":"Cloche: a cloak hangs like a bell. Cloaked in secrecy.","h":["Cloak covers. Cloaked in secrecy.","Cloak: conceal."],"s":["belie","dissemble"]},{"w":"collaborate","p":"v.","m":"To work jointly on an activity.","e":"Latin <i>collaborare</i>: <i>com-</i> + <i>laborare</i> (to work).","f":"collaborer","t":"Same as « collaborer ».","h":["Com + laborare. Collaborate on a paper.","Collaborate: work together."],"s":[]},{"w":"competent","p":"adj.","m":"Having the necessary ability or skill.","e":"Latin <i>competere</i> (to be suitable).","f":"compétent","t":"Same as « compétent ».","h":["Com + petere: strive together. A competent nurse.","Competent: capable."],"s":["adept","proficient"]},{"w":"comply","p":"v.","m":"To act in accordance with a wish or command.","e":"Latin <i>complere</i> (to fulfil), via Italian <i>complire</i>.","f":"se conformer à, obtempérer","t":"Comply with rules = « se conformer ».","h":["Complere: fulfil. Comply with the rules.","Comply: obey."],"s":["abide","acquiesce","adhere","capitulate"]},{"w":"consensus","p":"n.","m":"General agreement.","e":"Latin <i>consensus</i>, from <i>consentire</i> (to feel together).","f":"consensus","t":"Same as « consensus ».","h":["Con + sentire: feel together. Reach consensus.","Consensus: general accord."],"s":[]},{"w":"contempt","p":"n.","m":"The feeling that something is worthless.","e":"Latin <i>contemptus</i>, from <i>contemnere</i> (to despise).","f":"mépris","t":"Same as « contempt » root (contemptible). « Mépris ».","h":["Contemnere: despise. Look with contempt.","Contempt: scorn."],"s":["disdain","opprobrium","scorn","spurn"]},{"w":"correlate","p":"v.","m":"To have a mutual relationship or connection.","e":"Latin <i>com-</i> + <i>relatus</i> (related).","f":"être corrélé, mettre en corrélation","t":"Same as « corréler ».","h":["Co + relate. Variables correlate.","Correlate: be linked."],"s":[]},{"w":"curtail","p":"v.","m":"To reduce in extent or quantity; to cut short.","e":"Old French <i>courtault</i> (docked), from <i>court</i> (short).","f":"réduire, écourter","t":"« Court »: make it short. Curtail spending.","h":["Curtus: short. Curtail the visit.","Curtail: cut short."],"s":["bridle","check","curb","inhibit","retrench","suppress","truncate"]},{"w":"dictate","p":"v.","m":"To lay down authoritatively; to say aloud for writing down.","e":"Latin <i>dictare</i> (to say often), from <i>dicere</i> (to say).","f":"dicter, imposer","t":"Same as « dicter »: dictate terms = imposer ses conditions.","h":["Dictare: say often. Dictate terms.","Dictate: impose, or speak aloud."],"s":["prescribe"]},{"w":"distort","p":"v.","m":"To pull out of shape; to misrepresent.","e":"Latin <i>distorquere</i>: <i>dis-</i> + <i>torquere</i> (to twist).","f":"déformer, fausser","t":"Same as « distordre / distorsion ».","h":["Dis + torquere: twist. Distort facts.","Distort: warp."],"s":[]},{"w":"divergent","p":"adj.","m":"Tending to be different or develop in different directions.","e":"Latin <i>divergere</i>: <i>dis-</i> + <i>vergere</i> (to incline).","f":"divergent","t":"Same as « divergent ».","h":["Di + vergere: turn apart. Divergent views.","Divergent: differing."],"s":["disparate","heterogeneous"]},{"w":"divorced","p":"adj.","m":"Separated from; no longer connected (to).","e":"Latin <i>divortium</i>, from <i>divertere</i> (to turn aside).","f":"divorcé; coupé de, détaché de","x":"2nd meaning","t":"Figuratively: divorced from reality = « coupé de la réalité ».","h":["Divortium: separation. Divorced from reality.","Divorced: cut off."],"s":["disaffected","estranged"]},{"w":"elated","p":"adj.","m":"Extremely happy and excited.","e":"Latin <i>elatus</i> (lifted up), from <i>efferre</i>.","f":"enthousiaste, ravi","t":"Lifted up by joy: « exalté ».","h":["E + latus: carried up. Elated by the news.","Elated: overjoyed."],"s":["beatific","euphoric","jubilant"]},{"w":"elitist","p":"adj.","m":"Believing a select group deserves influence or privilege.","e":"French <i>élite</i>, from Latin <i>eligere</i> (to choose out).","f":"élitiste","t":"Same as « élitiste ».","h":["Élite. An elitist club.","Elitist: favouring the few."],"s":["rarefied"]},{"w":"enchant","p":"v.","m":"To fill with great delight; to put under a spell.","e":"Latin <i>incantare</i> (to sing a spell over): <i>in-</i> + <i>cantare</i>.","f":"enchanter","t":"Same as « enchanter »: sing a spell.","h":["En + cantare: sing into. Enchanted forest.","Enchant: bewitch."],"s":["beguile","enthrall","mesmerize","subjugate"]},{"w":"evade","p":"v.","m":"To escape or avoid, especially by cleverness or trickery.","e":"Latin <i>evadere</i> (to go out): <i>e-</i> + <i>vadere</i> (to go).","f":"éluder, échapper à","t":"Cousin of « s'évader » (escape). Evade taxes = fraude fiscale.","h":["E + vadere: go out. Evade the question.","Evade: dodge."],"s":["circumvent","elude","equivocate","hedge","malinger","prevaricate","shirk","skirt"]},{"w":"exotic","p":"adj.","m":"Originating in a distant foreign country; striking.","e":"Greek <i>exōtikos</i> (from outside), <i>exō</i>.","f":"exotique","t":"Same as « exotique ».","h":["Exo: outside. An exotic fruit.","Exotic: foreign, striking."],"s":["eccentric","outlandish","peculiar"]},{"w":"exploitative","p":"adj.","m":"Making use of a situation or person unfairly for one's own advantage.","e":"French <i>exploiter</i>, Latin <i>explicare</i> (to unfold).","f":"abusif, d'exploitation","t":"Cognate « exploiter » in the negative sense (exploiter des travailleurs).","h":["Exploit. Exploitative wages.","Exploitative: unfairly using."],"s":["expedient","opportunistic","unscrupulous"]},{"w":"fester","p":"v.","m":"To become worse or more intense, especially through neglect.","e":"Old French <i>festre</i> (ulcer), Latin <i>fistula</i> (ulcer).","f":"suppurer, s'envenimer","t":"« S'envenimer »: a festering wound or dispute.","h":["Fester: ulcer. Resentment festers.","Fester: rot."],"s":["gall","irk","rankle"]},{"w":"flummoxed","p":"adj.","m":"Perplexed; bewildered.","e":"19th-century English slang, origin unknown.","f":"déconcerté, perplexe","t":"Sounds like a mess: a flummoxed student staring at a trick question.","h":["Slang flummox. Flummoxed by the riddle.","Flummoxed: baffled."],"s":["befuddled","nonplussed"]},{"w":"foreseeable","p":"adj.","m":"Able to be anticipated.","e":"<i>fore-</i> (before) + <i>see</i> + <i>-able</i>. Germanic.","f":"prévisible","t":"See before: « prévisible ». In the foreseeable future = dans un avenir prévisible.","h":["Fore + see. In the foreseeable future.","Foreseeable: predictable."],"s":[]},{"w":"forsake","p":"v.","m":"To abandon; to give up.","e":"Old English <i>forsacan</i>: <i>for-</i> + <i>sacan</i> (to contend). Germanic.","f":"abandonner, délaisser","t":"For + sake: renounce. Forsaken = délaissé.","h":["For + sacan: renounce. Forsake friends.","Forsake: abandon."],"s":["jettison","relinquish","renounce"]},{"w":"fruitful","p":"adj.","m":"Producing good results; productive.","e":"<i>fruit</i> (Latin <i>fructus</i>) + <i>-ful</i>.","f":"fructueux, productif","t":"« Fructueux »: a fruitful meeting bears fruit.","h":["Fruit-full. Fruitful talks.","Fruitful: productive."],"s":["fecund","lucrative","prolific"]},{"w":"gratify","p":"v.","m":"To give pleasure or satisfaction to.","e":"Latin <i>gratificari</i>, from <i>gratus</i> (pleasing).","f":"satisfaire, gratifier","t":"Same as « gratifier »: gratify a desire.","h":["Gratus: pleasing. Gratify a whim.","Gratify: satisfy."],"s":[]},{"w":"heed","p":"v.","m":"To pay attention to.","e":"Old English <i>hēdan</i>. Germanic.","f":"tenir compte de, écouter","t":"Heed a warning = tenir compte d'un avertissement.","h":["Hedan: take care. Heed advice.","Heed: pay attention."],"s":[]},{"w":"hinder","p":"v.","m":"To create difficulties for; to delay.","e":"Old English <i>hindrian</i> (to hold back). Germanic.","f":"entraver, gêner","t":"Stands behind you (hind): holds you back.","h":["Hind: behind. Hinder progress.","Hinder: obstruct."],"s":["curb","deter","encumber","foil","forestall","frustrate","hamper","hobble","impede","inhibit","preclude","stymie","thwart"]},{"w":"impair","p":"v.","m":"To weaken or damage, especially a faculty.","e":"Old French <i>empeirer</i>, Latin <i>pejorare</i> (to make worse).","f":"affaiblir, altérer","t":"Cousin of « empirer » and « pire »: make worse. Impaired vision.","h":["In + pejor: worse. Impair hearing.","Impair: damage."],"s":["compromise","debase","jeopardize","undermine","vitiate"]},{"w":"improvise","p":"v.","m":"To create and perform spontaneously, without preparation.","e":"Latin <i>improvisus</i> (unforeseen): <i>in-</i> + <i>pro-</i> + <i>videre</i>.","f":"improviser","t":"Same as « improviser ».","h":["In + provisus: unforeseen. Improvise a speech.","Improvise: make up."],"s":["extemporize"]},{"w":"inborn","p":"adj.","m":"Existing from birth; natural.","e":"<i>in-</i> + <i>born</i>. Germanic.","f":"inné","t":"Born in: « inné », not learned.","h":["In + born. Inborn talent.","Inborn: innate."],"s":["inherent","intrinsic"]},{"w":"inclined","p":"adj.","m":"Having a tendency; willing.","e":"Latin <i>inclinare</i>: <i>in-</i> + <i>clinare</i> (to lean).","f":"enclin, porté à","t":"Same as « incliné »: leaning toward.","h":["In + clinare: lean. Inclined to agree.","Inclined: disposed."],"s":["apt"]},{"w":"inhibit","p":"v.","m":"To hinder, restrain or prevent.","e":"Latin <i>inhibere</i> (to hold in).","f":"inhiber, entraver","t":"Same as « inhiber ».","h":["In + habere: hold in. Inhibit growth.","Inhibit: restrain."],"s":["bridle","check","curb","curtail","deter","encumber","forestall","hamper","hinder","hobble","impede","stanch","stem","stymie","suppress"]},{"w":"miserly","p":"adj.","m":"Unwilling to spend; ungenerously small.","e":"Latin <i>miser</i> (wretched).","f":"avare, mesquin","t":"Not « misérable »! A miser: Harpagon in L'Avare.","h":["Miser: wretch. A miserly landlord.","Miserly: stingy."],"s":["avaricious","destitute","frugal","impecunious","indigent","parsimonious","penurious"]},{"w":"monotonous","p":"adj.","m":"Dull, tedious and repetitious.","e":"Greek <i>monotonos</i>: <i>mono-</i> (one) + <i>tonos</i> (tone).","f":"monotone","t":"Mono + tone: one tone. Same as « monotone ».","h":["Mono + tonos. A monotonous drone.","Monotonous: dull."],"s":["humdrum","irksome","mundane","prosaic","tedious"]},{"w":"peculiar","p":"adj.","m":"Strange or odd; characteristic of one.","e":"Latin <i>peculiaris</i> (of private property), from <i>pecu</i> (cattle).","f":"bizarre, particulier","t":"Cattle = private wealth: something belonging to you alone. « Particulier ». Peculiar to = propre à.","h":["Peculium: private cattle. A peculiar smell.","Peculiar: odd."],"s":["eccentric","exotic","idiosyncratic","outlandish","quirky"]},{"w":"pliant","p":"adj.","m":"Easily bent; easily influenced.","e":"Old French <i>plier</i> (to fold), Latin <i>plicare</i>.","f":"souple, docile","t":"Plier: foldable. A pliant mind obeys.","h":["Plier: bend. A pliant branch.","Pliant: flexible."],"s":["amenable","complaisant","compliant","docile","malleable","obliging","plastic","supple","tractable"]},{"w":"polymath","p":"n.","m":"A person of wide knowledge or learning.","e":"Greek <i>polymathēs</i>: <i>poly-</i> (many) + <i>manthanein</i> (to learn).","f":"polymathe, esprit universel","t":"Poly (many) + math (learning): Leonardo da Vinci.","h":["Poly + manthanein: much learning. A polymath scientist.","Polymath: many-field expert."],"s":["erudite"]},{"w":"premeditate","p":"v.","m":"To think out or plan beforehand.","e":"Latin <i>praemeditari</i>: <i>prae-</i> + <i>meditari</i>.","f":"préméditer","t":"Same as « préméditer ».","h":["Pre + meditari. Premeditated crime.","Premeditate: plan ahead."],"s":["contrive"]},{"w":"refine","p":"v.","m":"To remove impurities; to improve by small changes.","e":"<i>re-</i> + <i>fine</i>, French <i>raffiner</i>.","f":"raffiner, affiner","t":"Same as « raffiner / affiner ».","h":["Re + fine. Refine the draft.","Refine: polish."],"s":["distill","rarefy"]},{"w":"relinquish","p":"v.","m":"To voluntarily cease to keep or claim.","e":"Latin <i>relinquere</i> (to leave behind).","f":"abandonner, renoncer à","t":"Cousin of « relique »: what is left behind. Relinquish power.","h":["Re + linquere: leave behind. Relinquish control.","Relinquish: let go."],"s":["abjure","cede","concede","divest","forgo","forsake","jettison","renounce","repudiate","yield"]},{"w":"sensational","p":"adj.","m":"Causing great public interest; of outstanding quality.","e":"Latin <i>sensatio</i>, from <i>sensus</i> (feeling).","f":"sensationnel; à sensation","t":"Same as « sensationnel »: sensational journalism = journalisme à sensation.","h":["Sense. A sensational scoop.","Sensational: shocking or superb."],"s":["remarkable"]},{"w":"skittish","p":"adj.","m":"Nervous or excitable; easily scared.","e":"Middle English, probably Scandinavian <i>skyt-</i> (to shoot).","f":"nerveux, ombrageux, craintif","t":"A skittish horse jumps at shadows: « ombrageux ».","h":["Skit: dart. A skittish colt.","Skittish: jumpy."],"s":["fractious","restive","timorous"]},{"w":"sophisticated","p":"adj.","m":"Developed to a high degree of complexity; worldly and refined.","e":"Medieval Latin <i>sophisticare</i> (to adulterate), Greek <i>sophistēs</i>.","f":"sophistiqué, raffiné","t":"Same as « sophistiqué ».","h":["Sophia: wisdom. A sophisticated device.","Sophisticated: complex, refined."],"s":["cosmopolitan","debonair","genteel","universal","urbane"]},{"w":"sound","p":"adj.","m":"In good condition; based on valid reasoning.","e":"Old English <i>gesund</i> (healthy). Germanic.","f":"sain, solide, valable","x":"2nd meaning","t":"« Sain »: a sound argument, sound judgement. Safe and sound.","h":["Sund: healthy. A sound plan.","Sound: solid."],"s":["lucid","plausible","profound","rational","robust","tenable","viable"]},{"w":"strife","p":"n.","m":"Angry or bitter disagreement over fundamental issues.","e":"Old French <i>estrif</i> (quarrel).","f":"conflit, discorde","t":"Cousin of « s'efforcer » via 'strive'. Conflict.","h":["Estrif: contest. Civil strife.","Strife: conflict."],"s":["acrimony","contention","discord"]},{"w":"subservient","p":"adj.","m":"Prepared to obey others unquestioningly.","e":"Latin <i>subservire</i>: <i>sub-</i> + <i>servire</i> (to serve).","f":"servile, soumis","t":"Sub + serve: serving from below. « Servile ».","h":["Sub + servire. A subservient aide.","Subservient: servile."],"s":["deferential","obsequious"]},{"w":"synoptic","p":"adj.","m":"Taking a comprehensive view; giving a general summary.","e":"Greek <i>synoptikos</i>: <i>syn-</i> (together) + <i>opsis</i> (view).","f":"synoptique","t":"Same as « synoptique »: seen together.","h":["Syn + opsis: seen together. A synoptic view.","Synoptic: overview."],"s":[]},{"w":"tantalizing","p":"adj.","m":"Teasing with something desirable but out of reach.","e":"From <i>Tantalus</i>, Greek myth: punished with water and fruit just out of reach.","f":"tentant, aguichant","t":"Tantale in French! Le supplice de Tantale: see it, can't have it.","h":["Tantalus: out of reach. A tantalizing hint.","Tantalizing: teasing."],"s":[]},{"w":"tepid","p":"adj.","m":"Slightly warm; lacking enthusiasm.","e":"Latin <i>tepidus</i>, from <i>tepere</i> (to be warm).","f":"tiède","t":"Same as « tiède »: a tepid reception.","h":["Tepere: be warm. A tepid response.","Tepid: lukewarm."],"s":["apathetic"]},{"w":"thorough","p":"adj.","m":"Complete with regard to every detail.","e":"Old English <i>thuruh</i>, a form of <i>through</i>. Germanic.","f":"minutieux, approfondi","t":"Through-and-through: « minutieux ».","h":["Through. A thorough check.","Thorough: complete."],"s":["all-ecompassing","assiduous","encyclopedic","exhaustive","fastidious","meticulous","painstaking","punctilious","scrupulous","thoroughgoing"]},{"w":"understated","p":"adj.","m":"Presented in a subtle, restrained way.","e":"<i>under-</i> + <i>state</i>. Germanic.","f":"discret, sobre","t":"Stated under: « sobre ». An understated elegance.","h":["Under + state. Understated chic.","Understated: restrained."],"s":["elusive","muted","subdued","subtle"]},{"w":"versatile","p":"adj.","m":"Able to adapt to many functions.","e":"Latin <i>versatilis</i>, from <i>versare</i> (to turn).","f":"polyvalent, souple","x":"Faux ami","t":"« Versatile » in French means fickle (changeable). English: flexible, many-skilled.","h":["Vertere: turn. A versatile actor.","Versatile: adaptable."],"s":["multifaceted","protean","resourceful"]},{"w":"vexation","p":"n.","m":"The state of being annoyed or worried.","e":"Latin <i>vexatio</i>, from <i>vexare</i> (to harass).","f":"contrariété, irritation","t":"Same as « vexation » (but milder than in French).","h":["Vexare: shake. Vexation at the delay.","Vexation: annoyance."],"s":["chagrin"]},{"w":"visionary","p":"adj.","m":"Thinking about the future with imagination.","e":"Latin <i>visio</i> (sight), from <i>videre</i>.","f":"visionnaire","t":"Same as « visionnaire ».","h":["Vision. A visionary founder.","Visionary: forward-looking."],"s":["fanciful","prescient","prophetic","quixotic","whimsical"]},{"w":"wayward","p":"adj.","m":"Difficult to control because of unpredictable behaviour.","e":"Middle English, short for <i>awayward</i> (turned away).","f":"capricieux, rebelle","t":"Turned away from the way: a wayward teenager.","h":["Away-ward. A wayward child.","Wayward: wilful."],"s":["capricious","erratic","fickle","fitful","gratuitous","headstrong","mercurial","refractory","wanton","willful"]}]},{"name":"GregMat IV","slug":"gregmat-iv","series":"GregMat","words":[{"w":"abject","p":"adj.","m":"Extremely bad; showing hopelessness or humiliation.","e":"Latin <i>abjectus</i> (cast away): <i>ab-</i> + <i>jacere</i>.","f":"abject, misérable","t":"Same as « abject ». Abject poverty.","h":["Ab + jacere: thrown down. Abject poverty.","Abject: wretched."],"s":["abysmal","bereft","execrable","forlorn"]},{"w":"abreast","p":"adv.","m":"Up to date with; side by side.","e":"<i>a-</i> + <i>breast</i>. Germanic.","f":"au courant de; de front","t":"Keep abreast of the news = rester au courant.","h":["A + breast: side by side. Stay abreast of news.","Abreast: up to date."],"s":[]},{"w":"acolyte","p":"n.","m":"An assistant or follower.","e":"Greek <i>akolouthos</i> (follower), via Latin <i>acolythus</i>.","f":"acolyte","t":"Same as « acolyte » (in English with a mild negative tone).","h":["Akolouthos: follower. The star’s acolytes.","Acolyte: attendant."],"s":["disciple"]},{"w":"amicable","p":"adj.","m":"Characterized by friendliness; without ill feeling.","e":"Latin <i>amicabilis</i>, from <i>amicus</i> (friend).","f":"amical, à l'amiable","t":"« Amical ». An amicable divorce = divorce à l'amiable.","h":["Amicus: friend. An amicable split.","Amicable: friendly."],"s":["affable","amiable","congenial","cordial","genial"]},{"w":"anoint","p":"v.","m":"To smear with oil, as a rite; to choose officially.","e":"Latin <i>inungere</i> (to smear on).","f":"oindre; désigner","t":"Same as « oindre ». An heir anointed as successor.","h":["In + ungere: smear. Anoint a successor.","Anoint: consecrate, choose."],"s":[]},{"w":"arresting","p":"adj.","m":"Striking; capturing the attention.","e":"Old French <i>arester</i> (to stop), Latin <i>arrestare</i>.","f":"saisissant, frappant","t":"It stops you in your tracks: an arresting photograph.","h":["Arrest: stop. An arresting image.","Arresting: eye-catching."],"s":[]},{"w":"barrage","p":"n.","m":"A concentrated outpouring (of questions, criticism); heavy artillery fire.","e":"French <i>barrage</i> (barrier), from <i>barrer</i>.","f":"avalanche, déluge; tir de barrage","t":"Un barrage: like a dam bursting. A barrage of questions.","h":["Barrage: barrier fire. A barrage of questions.","Barrage: heavy volley."],"s":[]},{"w":"coercion","p":"n.","m":"Persuasion by force or threats.","e":"Latin <i>coercere</i> (to restrain).","f":"coercition, contrainte","t":"Same as « coercition ».","h":["Coercere: restrain. Signed under coercion.","Coercion: forced pressure."],"s":["constraint","duress"]},{"w":"coin","p":"v.","m":"To invent a new word or phrase.","e":"Old French <i>coing</i> (wedge, stamp for minting money).","f":"inventer (un mot), forger","x":"Look-alike","t":"Not « coin » (corner)! Coin a term = forger. Money is struck with a coin die.","h":["Coin a phrase.","Coin: invent a word."],"s":["contrive","fabricate"]},{"w":"cunning","p":"adj.","m":"Skilled in deceit; clever in achieving one's ends.","e":"Old English <i>cunnan</i> (to know). Germanic.","f":"rusé, malin","t":"Fox-like: « rusé ».","h":["Can: know. Fox-like cunning.","Cunning: sly."],"s":["artful","artifice","crafty","devious","guile","ingenious","shrewd","wily"]},{"w":"dawdle","p":"v.","m":"To waste time; to move slowly.","e":"17th-century English, possibly related to <i>daddle</i> (to walk unsteadily).","f":"traîner, lambiner","t":"Don't dawdle: « ne traîne pas ».","h":["Dawdle: waste time. Don’t dawdle.","Dawdle: dillydally."],"s":[]},{"w":"decipher","p":"v.","m":"To succeed in understanding or reading something unclear.","e":"<i>de-</i> + <i>cipher</i> (Arabic <i>ṣifr</i>, zero/code).","f":"déchiffrer","t":"Same as « déchiffrer ».","h":["De + cipher. Decipher the code.","Decipher: decode."],"s":["construe","unravel"]},{"w":"deflect","p":"v.","m":"To cause to change direction; to turn aside.","e":"Latin <i>deflectere</i>: <i>de-</i> + <i>flectere</i> (to bend).","f":"dévier, détourner","t":"Same as « défléchir / déflexion ». Deflect criticism = détourner.","h":["De + flectere: bend away. Deflect blame.","Deflect: turn aside."],"s":["avert"]},{"w":"delusion","p":"n.","m":"A false belief held despite contrary evidence.","e":"Latin <i>deludere</i> (to mock): <i>de-</i> + <i>ludere</i> (to play).","f":"illusion, délire","t":"« Délire ». Delusions of grandeur = folie des grandeurs.","h":["De + ludere: play false. A delusion of grandeur.","Delusion: false belief."],"s":["chimera"]},{"w":"digression","p":"n.","m":"A temporary departure from the main subject.","e":"Latin <i>digredi</i> (to step aside).","f":"digression","t":"Same as « digression ».","h":["Di + gradi: step aside. A digression on cats.","Digression: tangent."],"s":[]},{"w":"discomfit","p":"v.","m":"To make uneasy or confused.","e":"Old French <i>desconfit</i> (defeated), Latin <i>deficere</i>.","f":"décontenancer, déconcerter","t":"Related to « déconfit »: defeated and embarrassed. Discomfit ≠ discomfort.","h":["Dis + confire: undo. Discomfited by the question.","Discomfit: unsettle."],"s":["confound","flummox"]},{"w":"discount","p":"v.","m":"To regard as unlikely or unworthy of consideration; to reduce the price of.","e":"Old French <i>desconter</i>: <i>des-</i> + <i>conter</i> (to count).","f":"ne pas tenir compte de; escompter","x":"2nd meaning","t":"Discount a rumour = ignore it. Beyond price cuts: « ne pas tenir compte ».","h":["Dis + count. Discount the rumour.","Discount: disregard or reduce."],"s":[]},{"w":"dispense","p":"v.","m":"To distribute; (dispense with) to do without.","e":"Latin <i>dispensare</i> (to weigh out).","f":"distribuer; se passer de","x":"2nd meaning","t":"Dispense with formalities = se passer des formalités. Dispenser = distributeur.","h":["Dis + pensare: weigh out. Dispense with rules.","Dispense: give out, forgo."],"s":["forgo"]},{"w":"dissident","p":"n.","m":"One who opposes official policy.","e":"Latin <i>dissidere</i> (to sit apart): <i>dis-</i> + <i>sedere</i>.","f":"dissident","t":"Same as « dissident »: sits apart.","h":["Dis + sedere: sit apart. A jailed dissident.","Dissident: dissenter."],"s":["apostate","heretic","heterodox"]},{"w":"distill","p":"v.","m":"To purify a liquid; to extract the essential meaning of.","e":"Latin <i>destillare</i> (to drip down): <i>de-</i> + <i>stilla</i> (drop).","f":"distiller; extraire l'essentiel","t":"Same as « distiller »: drops. Distill a report into key points.","h":["De + stillare: drip. Distill the essence.","Distill: boil down."],"s":["refine"]},{"w":"duplicitous","p":"adj.","m":"Deceitful; double-dealing.","e":"Latin <i>duplicitas</i>, from <i>duplex</i> (twofold).","f":"fourbe, hypocrite","t":"Duplex = two-faced. Duplicité in French has the same sense.","h":["Duplex: double. A duplicitous spy.","Duplicitous: two-faced."],"s":["artful","disingenuous","perfidious","treacherous"]},{"w":"economy","p":"n.","m":"Careful management of resources; thrift.","e":"Greek <i>oikonomia</i>: <i>oikos</i> (house) + <i>nomos</i> (management).","f":"économie, parcimonie","x":"2nd meaning","t":"Beyond GDP: economy of words = brièveté, économie de moyens.","h":["Oikos + nomos: household rule. Economy of words.","Economy: thrift."],"s":[]},{"w":"elementary","p":"adj.","m":"Relating to the basic, simplest parts.","e":"Latin <i>elementarius</i>, from <i>elementum</i>.","f":"élémentaire","t":"Same as « élémentaire »: « Élémentaire, mon cher Watson ».","h":["Element. Elementary school.","Elementary: basic."],"s":["rudimentary","vestigial"]},{"w":"euphoric","p":"adj.","m":"Characterized by intense excitement and happiness.","e":"Greek <i>euphoria</i>: <i>eu-</i> (well) + <i>pherein</i> (to bear).","f":"euphorique","t":"Same as « euphorique ».","h":["Eu + pherein: well-carried. Euphoric crowd.","Euphoric: elated."],"s":["beatific","elated","jubilant"]},{"w":"fabricate","p":"v.","m":"To invent (something false); to make or manufacture.","e":"Latin <i>fabricare</i>, from <i>fabrica</i> (workshop).","f":"fabriquer; inventer","x":"2nd meaning","t":"Fabriquer. A fabricated story is invented from scratch.","h":["Fabrica: workshop. Fabricate an alibi.","Fabricate: make up."],"s":["coin","contrive"]},{"w":"fallible","p":"adj.","m":"Capable of making mistakes.","e":"Latin <i>fallere</i> (to deceive).","f":"faillible","t":"Same as « faillible »: capable of faillir.","h":["Fallere: deceive. Fallible humans.","Fallible: error-prone."],"s":["errant"]},{"w":"falter","p":"v.","m":"To start to lose strength; to speak hesitatingly.","e":"Middle English, possibly Scandinavian.","f":"faiblir, vaciller, hésiter","t":"Falter = vaciller. His voice faltered.","h":["Falter: stumble. His voice faltered.","Falter: waver."],"s":["demur","flag","vacillate"]},{"w":"fervent","p":"adj.","m":"Having or displaying passionate intensity.","e":"Latin <i>fervere</i> (to boil).","f":"fervent","t":"Same as « fervent ».","h":["Fervere: boil. A fervent fan.","Fervent: ardent."],"s":["ardent","avid","fervid","keen","vehement","zealous"]},{"w":"fortitude","p":"n.","m":"Courage in pain or adversity.","e":"Latin <i>fortitudo</i>, from <i>fortis</i> (strong).","f":"courage, force d'âme","t":"Same family as « fort ».","h":["Fortis: strong. Face it with fortitude.","Fortitude: grit."],"s":["valor"]},{"w":"gawky","p":"adj.","m":"Nervously awkward and ungainly.","e":"17th-century English, from <i>gawk</i> (a fool), possibly Scandinavian.","f":"dégingandé, gauche","t":"Tall, gauche and clumsy: « dégingandé ».","h":["Gawk: clumsy. A gawky teen.","Gawky: awkward."],"s":["gauche","inept","maladroit"]},{"w":"glum","p":"adj.","m":"Looking or feeling dejected.","e":"Probably from <i>gloom</i>. Germanic.","f":"morose, abattu","t":"Gloomy: « avoir le moral dans les chaussettes ».","h":["Glum: sullen. A glum face.","Glum: gloomy."],"s":["crestfallen","disheartened","dour","forlorn","morose","saturnine","sullen","surly","taciturn"]},{"w":"harbinger","p":"n.","m":"A person or thing that announces the approach of something.","e":"Old French <i>herberger</i> (to lodge), an advance officer arranging lodging.","f":"signe avant-coureur, précurseur","t":"Originally the scout who finds you a bed (auberge). Swallows are a harbinger of spring.","h":["Harbour finder. A harbinger of spring.","Harbinger: forerunner."],"s":["precursor"]},{"w":"heterodox","p":"adj.","m":"Not conforming to accepted standards or beliefs.","e":"Greek <i>heterodoxos</i>: <i>heteros</i> (other) + <i>doxa</i> (opinion).","f":"hétérodoxe","t":"Same as « hétérodoxe »; opposite: orthodox.","h":["Hetero + doxa: other opinion. Heterodox views.","Heterodox: unorthodox."],"s":["apostate","dissident","heretic"]},{"w":"inform","p":"v.","m":"(inform on/against) To betray; (inform) to give shape or character to.","e":"Latin <i>informare</i> (to shape, give form).","f":"dénoncer; informer; imprégner","x":"2nd meaning","t":"inform on someone = « dénoncer ». Also: a decision informed by data.","h":["In + formare: give shape. Informed by data; inform on a thief.","Inform: shape, or betray."],"s":["apprise"]},{"w":"irksome","p":"adj.","m":"Irritating; tedious.","e":"Middle English <i>irken</i> (to tire).","f":"agaçant, pénible","t":"It irks me: « ça m'agace ». An irksome chore.","h":["Irk: weary. An irksome chore.","Irksome: annoying."],"s":["humdrum","monotonous","nettlesome","tedious"]},{"w":"largesse","p":"n.","m":"Generosity in bestowing gifts or money.","e":"Old French <i>largesse</i>, from <i>large</i> (generous).","f":"largesse, générosité","t":"Same as « largesse ».","h":["Large: generous. The donor’s largesse.","Largesse: generosity."],"s":["largess"]},{"w":"liability","p":"n.","m":"A person or thing that causes problems; legal responsibility; a debt.","e":"From <i>liable</i>, French <i>lier</i> (to bind), Latin <i>ligare</i>.","f":"handicap, passif; responsabilité","x":"2nd meaning","t":"Opposite of an asset. Un handicap / « passif ». Product liability = responsabilité du fait des produits.","h":["Liable. A liability to the team.","Liability: burden."],"s":[]},{"w":"libertine","p":"n.","m":"A person who behaves without moral restraint.","e":"Latin <i>libertinus</i> (freedman), from <i>liber</i> (free).","f":"libertin","t":"Same as « libertin »: Dom Juan.","h":["Liber: free. A libertine lifestyle.","Libertine: dissolute person."],"s":["decadent","profligate","reprobate","self-indulgent"]},{"w":"manacle","p":"n.","m":"A metal chain for the hands; (v.) to restrain.","e":"Latin <i>manicula</i> (little hand), from <i>manus</i>.","f":"menotte, entrave","t":"Latin manus (hand): « menotte ».","h":["Manus: hand. Manacled wrists.","Manacle: handcuff."],"s":[]},{"w":"manifest","p":"adj.","m":"Clear and obvious; (v.) to display.","e":"Latin <i>manifestus</i> (caught in the act, plain).","f":"manifeste, évident","t":"Same as « manifeste ». Manifest destiny.","h":["Manus + festus: hand-struck, plain. Manifest error.","Manifest: obvious."],"s":["conspicuous","overt","palpable","patent","tangible"]},{"w":"meritorious","p":"adj.","m":"Deserving reward or praise.","e":"Latin <i>meritorius</i>, from <i>merere</i> (to earn).","f":"méritoire","t":"Same as « méritoire ».","h":["Meritus: earned. Meritorious service.","Meritorious: praiseworthy."],"s":["commendable","creditable","estimable","laudable"]},{"w":"minute","p":"adj.","m":"Extremely small; very precise (pronounced my-NYOOT).","e":"Latin <i>minutus</i> (made small).","f":"minuscule, minutieux","x":"2nd meaning","t":"Not the time unit: mi-NUTE = tiny, « minutieux ». Minute details.","h":["Minutus: tiny. Minute detail (my-NYOOT).","Minute: extremely small."],"s":["diminutive"]},{"w":"modest","p":"adj.","m":"Unassuming; moderate or limited in size.","e":"Latin <i>modestus</i> (moderate), from <i>modus</i> (measure).","f":"modeste","t":"Same as « modeste »: a modest salary is of limited size.","h":["Modus: measure. A modest income.","Modest: humble or small."],"s":["coy","demure","diffident","reticent","retiring","self-effacing"]},{"w":"mutiny","p":"n.","m":"An open rebellion against authority, especially by sailors.","e":"Old French <i>mutin</i> (rebellious), Latin <i>movere</i> (to move).","f":"mutinerie","t":"Same as « mutinerie ».","h":["Movere: move. The crew’s mutiny.","Mutiny: revolt."],"s":[]},{"w":"noble","p":"adj.","m":"Having fine personal qualities or high social rank.","e":"Latin <i>nobilis</i> (well known, of high birth).","f":"noble","t":"Same as « noble ».","h":["Nobilis: known. A noble cause.","Noble: honourable."],"s":["benevolent","magnanimous"]},{"w":"noxious","p":"adj.","m":"Harmful, poisonous or very unpleasant.","e":"Latin <i>noxius</i>, from <i>noxa</i> (harm).","f":"nocif, nuisible","t":"Same family as « nocif ». Noxious fumes.","h":["Nocere: harm. Noxious fumes.","Noxious: toxic."],"s":["deleterious","detrimental","inimical","insidious","malodorous","noisome","pernicious"]},{"w":"perseverance","p":"n.","m":"Persistence in doing something despite difficulty.","e":"Latin <i>perseverare</i>: <i>per-</i> + <i>severus</i> (strict).","f":"persévérance","t":"Same as « persévérance ».","h":["Per + severus: very strict. Perseverance pays.","Perseverance: persistence."],"s":["resolve"]},{"w":"predicament","p":"n.","m":"A difficult, unpleasant situation.","e":"Late Latin <i>praedicamentum</i> (category), from <i>praedicare</i>.","f":"situation difficile, dilemme","t":"« Prédicament » is not French. Think « pétrin »: in a predicament.","h":["Praedicamentum: category, fix. In a predicament.","Predicament: tight spot."],"s":["imbroglio","quandary"]},{"w":"prime","p":"adj.","m":"Of first importance; main.","e":"Latin <i>primus</i> (first).","f":"principal, premier","t":"Prime minister: « Premier ministre ».","h":["Primus: first. Of prime importance.","Prime: chief."],"s":["acme","cardinal","heyday","zenith"]},{"w":"proficient","p":"adj.","m":"Competent or skilled.","e":"Latin <i>proficere</i> (to make progress): <i>pro-</i> + <i>facere</i>.","f":"compétent, doué","t":"Pro + facere: progress as a pro. Proficient in French.","h":["Pro + facere. Proficient in French.","Proficient: skilled."],"s":["adept","adroit","competent","deft","dexterous"]},{"w":"prolix","p":"adj.","m":"Using too many words; tediously lengthy.","e":"Latin <i>prolixus</i> (extended).","f":"prolixe, verbeux","t":"Same as « prolixe »: a verbose essay.","h":["Pro + liquere: flow forth. A prolix report.","Prolix: wordy."],"s":["diffuse","discursive","effusive","garrulous","loquacious","tedious","verbose","voluble"]},{"w":"prowess","p":"n.","m":"Skill or expertise; bravery in battle.","e":"Old French <i>proesce</i>, from <i>prou</i> (valiant).","f":"prouesse, talent","t":"Same as « prouesse ».","h":["Prou: valiant. Athletic prowess.","Prowess: skill."],"s":["valor"]},{"w":"radical","p":"adj.","m":"Fundamental; far-reaching; extreme.","e":"Latin <i>radicalis</i>, from <i>radix</i> (root).","f":"radical, fondamental","t":"Same as « radical »: from the root. Radical reform.","h":["Radix: root. Radical change.","Radical: fundamental."],"s":[]},{"w":"render","p":"v.","m":"To cause to be or become; to provide or give.","e":"Old French <i>rendre</i>, Latin <i>reddere</i>.","f":"rendre, rendre (un jugement)","t":"Same as « rendre »: render someone speechless.","h":["Rendre: give back. Render aid.","Render: make or provide."],"s":["afford","yield"]},{"w":"repertoire","p":"n.","m":"The stock of skills or pieces a person is prepared to perform.","e":"Latin <i>repertorium</i> (inventory).","f":"répertoire","t":"Same as « répertoire ».","h":["Re + parere: find again. A wide repertoire.","Repertoire: stock of pieces."],"s":[]},{"w":"resilient","p":"adj.","m":"Able to recover quickly; flexible.","e":"Latin <i>resilire</i> (to leap back): <i>re-</i> + <i>salire</i>.","f":"résilient, qui a du ressort","t":"Same as « résilient »: bounces back.","h":["Re + salire: leap back. A resilient child.","Resilient: bouncing back."],"s":["buoyant"]},{"w":"resolute","p":"adj.","m":"Admirably purposeful and determined.","e":"Latin <i>resolutus</i> (loosened, settled), from <i>resolvere</i>.","f":"résolu, déterminé","t":"Same as « résolu ».","h":["Re + solvere: settle. Resolute leader.","Resolute: determined."],"s":["adamant","dogged","obdurate","obstinate","pertinacious","robust","stalwart","staunch","steadfast","tenacious"]},{"w":"schism","p":"n.","m":"A split between strongly opposed groups.","e":"Greek <i>skhisma</i> (cleft), from <i>skhizein</i> (to split).","f":"schisme","t":"Same as « schisme »: schizo = split.","h":["Schisma: split. A church schism.","Schism: division."],"s":["dichotomy"]},{"w":"scorn","p":"n.","m":"Contempt or disdain.","e":"Old French <i>escarn</i>, Germanic origin.","f":"mépris, dédain","t":"Cousin of « escarnir »: to treat with scorn. « Mépriser » = to scorn.","h":["Scorn: mockery. Scorn his offer.","Scorn: disdain."],"s":["contempt","contravene","disdain","flout","opprobrium","snub","spurn"]},{"w":"slander","p":"n.","m":"The making of a false spoken statement damaging to a person's reputation.","e":"Old French <i>esclandre</i>, Latin <i>scandalum</i> (scandal).","f":"calomnie, diffamation","t":"« Esclandre »: scandal → slander.","h":["Scandalum. Slander ruins names.","Slander: spoken defamation."],"s":["aspersion","besmirch","calumny","defame","denigrate","disparage","malign","vilify","vituperate"]},{"w":"stinting","p":"adj.","m":"Restricting an allowance; frugal.","e":"Old English <i>styntan</i> (to blunt). Germanic.","f":"parcimonieux, chiche","t":"Not stinging! Stinting = skimping. Opposite of lavish: « sans lésiner » = unstinting.","h":["Stint: limit. Stinting with praise.","Stinting: skimpy."],"s":["economical","frugal","scant"]},{"w":"subordinate","p":"adj.","m":"Lower in rank or importance.","e":"Latin <i>sub-</i> + <i>ordinare</i> (to order).","f":"subordonné","t":"Same as « subordonné ».","h":["Sub + ordo. A subordinate clause.","Subordinate: lower rank."],"s":[]},{"w":"supple","p":"adj.","m":"Bending and moving easily and gracefully.","e":"Old French <i>souple</i>, Latin <i>supplex</i> (bending).","f":"souple","t":"« Souple » → supple.","h":["Supplex: bending. A supple body.","Supple: flexible."],"s":["compliant","malleable","pliant"]},{"w":"temper","p":"v.","m":"To moderate or mitigate; (n.) disposition or anger.","e":"Latin <i>temperare</i> (to mix in due proportion).","f":"tempérer, modérer","x":"2nd meaning","t":"Same as « tempérer ». Temper enthusiasm with caution. Also a bad temper.","h":["Temperare: mix right. Temper your zeal.","Temper: moderate."],"s":["alleviate","assuage","mitigate","mollify","palliate","qualify"]},{"w":"temporal","p":"adj.","m":"Relating to time; worldly, not spiritual.","e":"Latin <i>temporalis</i>, from <i>tempus</i> (time).","f":"temporel","t":"Same as « temporel »: temporal power opposes spiritual power.","h":["Tempus: time. Temporal power.","Temporal: of time or the world."],"s":["mundane"]},{"w":"tentative","p":"adj.","m":"Not certain or fixed; hesitant.","e":"Latin <i>tentare</i> (to try).","f":"provisoire, hésitant","x":"Faux ami","t":"Not « tentative » (an attempt, a try). Tentative plans = provisoire, sous réserve.","h":["Tentare: try. A tentative plan.","Tentative: provisional."],"s":["irresolute","provisional"]},{"w":"universal","p":"adj.","m":"Applicable to all cases; relating to everyone.","e":"Latin <i>universalis</i>, from <i>universus</i> (whole).","f":"universel","t":"Same as « universel ».","h":["Unus + vertere: turned into one. Universal truth.","Universal: for all."],"s":["catholic","cosmopolitan","eclectic","omnipresent","pervasive","rampant","sophisticated","ubiquitous","urbane"]},{"w":"valor","p":"n.","m":"Great courage in the face of danger.","e":"Latin <i>valor</i>, from <i>valere</i> (to be strong).","f":"bravoure, vaillance","t":"Same as « valeur » (in the old sense). « Valeureux ».","h":["Valere: be strong. Valor in battle.","Valor: bravery."],"s":["fortitude","prowess"]},{"w":"woeful","p":"adj.","m":"Very sad; deplorably bad.","e":"<i>woe</i> (Old English <i>wā</i>) + <i>-ful</i>.","f":"lamentable, déplorable","t":"Full of woe (malheur). Woeful performance = pitoyable.","h":["Woe-full. A woeful tale.","Woeful: dreadful."],"s":["abysmal","doleful","dolorous","execrable","lachrymose","lugubrious","melancholy","odious","plaintive"]}]},{"name":"GregMat V","slug":"gregmat-v","series":"GregMat","words":[{"w":"adept","p":"adj.","m":"Very skilled; proficient.","e":"Latin <i>adeptus</i> (having attained).","f":"expert, habile","x":"Faux ami","t":"« Adepte » = follower. English: an adept = someone skilled at something.","h":["Adeptus: attained. An adept chess player.","Adept: skilled."],"s":["adroit","competent","deft","dexterous","nimble","proficient","virtuoso"]},{"w":"adverse","p":"adj.","m":"Harmful or unfavourable.","e":"Latin <i>adversus</i> (turned against).","f":"défavorable, néfaste","x":"Look-alike","t":"Not « adverse » (opponent). Adverse effects, adverse weather = conditions défavorables. Not 'averse'.","h":["Ad + vertere: turned against. Adverse weather.","Adverse: unfavourable."],"s":["inimical","ominous","unpropitious","unseemly","untoward"]},{"w":"allusive","p":"adj.","m":"Making indirect reference to something.","e":"Latin <i>alludere</i> (to play with): <i>ad-</i> + <i>ludere</i>.","f":"allusif","t":"Same as « allusif / allusion ».","h":["Alludere: play with. An allusive poem.","Allusive: hinting."],"s":["oblique"]},{"w":"archetype","p":"n.","m":"A very typical example; an original model.","e":"Greek <i>arkhetypon</i>: <i>arkhe-</i> (first) + <i>typos</i> (model).","f":"archétype","t":"Same as « archétype ».","h":["Arche + typos: first mould. The archetype of a hero.","Archetype: prototype."],"s":["epitome","exemplar","paragon"]},{"w":"ardent","p":"adj.","m":"Enthusiastic or passionate.","e":"Latin <i>ardere</i> (to burn).","f":"ardent","t":"Same as « ardent ».","h":["Ardere: burn. An ardent fan.","Ardent: fiery."],"s":["avid","fervent","fervid","keen","vehement","zealous"]},{"w":"astute","p":"adj.","m":"Having the ability to assess situations accurately; shrewd.","e":"Latin <i>astutus</i>, from <i>astus</i> (cunning).","f":"astucieux, perspicace","t":"Cousin of « astucieux »: an astute investor.","h":["Astus: cunning. An astute observer.","Astute: shrewd."],"s":["artful","avid","canny","discreet","incisive","judicious","keen","penetrating","percipient","perspicacious","politic","prudent","sagacious","savvy","shrewd"]},{"w":"axiomatic","p":"adj.","m":"Self-evident or unquestionable.","e":"Greek <i>axiōma</i> (that which is thought worthy).","f":"axiomatique, évident","t":"Same as « axiome »: no proof needed.","h":["Axioma: worthy thing. Axiomatic truth.","Axiomatic: self-evident."],"s":["incontrovertible","irrefutable"]},{"w":"benevolent","p":"adj.","m":"Well meaning and kindly.","e":"Latin <i>bene</i> (well) + <i>velle</i> (to wish).","f":"bienveillant","t":"Bene + volent = « bienveillant »: wishing well.","h":["Bene + volens: wishing well. A benevolent king.","Benevolent: kind."],"s":["beneficent","benign","magnanimous","noble"]},{"w":"berate","p":"v.","m":"To scold or criticize angrily.","e":"<i>be-</i> + <i>rate</i> (to scold), perhaps Scandinavian.","f":"réprimander sévèrement, rabrouer","t":"Be-rate: dressing someone down. Not related to « rate » (tax).","h":["Be + rate: scold. Berate staff.","Berate: scold."],"s":["admonish","castigate","censure","chastise","excoriate","lambast","lambaste","objurgate","rebuke","reproach","upbraid","vilify","vituperate"]},{"w":"brittle","p":"adj.","m":"Hard but easily broken or snapped; (of a person or mood) fragile and easily upset.","e":"Middle English <i>britel</i>, from Old English <i>brēotan</i> (to break).","f":"cassant, fragile","t":"« Cassant »: brittle bones, a brittle voice. Not « bridle » (to restrain, see Advanced VI).","h":["Think « cassant ». Brittle bones snap.","Brittle: easily broken."],"s":[]},{"w":"buoyant","p":"adj.","m":"Able to float; cheerful and optimistic.","e":"Spanish <i>boyante</i>, from <i>boya</i> (buoy).","f":"flottant; optimiste, allègre","x":"2nd meaning","t":"Une bouée floats: buoyant mood. Also a buoyant market is rising.","h":["Buoy floats. Buoyant mood.","Buoyant: floating, upbeat."],"s":["ebullient","effervescent","resilient","sanguine","vivacious"]},{"w":"cease","p":"v.","m":"To come or bring to an end.","e":"Old French <i>cesser</i>, Latin <i>cessare</i>.","f":"cesser","t":"Same as « cesser ».","h":["Cessare. Cease fire.","Cease: stop."],"s":[]},{"w":"commence","p":"v.","m":"To begin.","e":"Old French <i>comencier</i>, Latin <i>cum-</i> + <i>initiare</i>.","f":"commencer","t":"Same as « commencer ».","h":["Cum + initiare. Commence at nine.","Commence: begin."],"s":["start"]},{"w":"conclusive","p":"adj.","m":"Decisive; ending all doubt.","e":"Latin <i>concludere</i> (to close).","f":"concluant, probant","t":"Un résultat concluant.","h":["Conclude. Conclusive evidence.","Conclusive: settling."],"s":["irrefutable","unequivocal"]},{"w":"condone","p":"v.","m":"To accept or allow behaviour that is wrong.","e":"Latin <i>condonare</i> (to give away): <i>con-</i> + <i>donare</i>.","f":"cautionner, excuser, fermer les yeux sur","x":"Look-alike","t":"Donner: you give it a pass. Not 'approve': condone = tolerate wrong.","h":["Con + donare: give. Condone cheating.","Condone: overlook."],"s":["countenance"]},{"w":"congeal","p":"v.","m":"To become solid or semi-solid, especially by cooling or clotting.","e":"Latin <i>congelare</i> (to freeze together): <i>com-</i> + <i>gelare</i> (to freeze).","f":"se figer, se coaguler","t":"Same family as « congeler » and « gel ». Congealed fat, congealed blood.","h":["Com + gelare: freeze together. Congealed fat.","Congeal: set solid."],"s":[]},{"w":"conspire","p":"v.","m":"To make secret plans jointly for an unlawful act.","e":"Latin <i>conspirare</i> (to breathe together).","f":"conspirer, comploter","t":"Same as « conspirer »: breathe together.","h":["Con + spirare: breathe together. Conspire to rob.","Conspire: plot."],"s":["collude","connive","intrigue","machinate"]},{"w":"contravene","p":"v.","m":"To violate a law or rule.","e":"Latin <i>contravenire</i> (to come against): <i>contra</i> + <i>venire</i>.","f":"enfreindre, contrevenir à","t":"Same as « contrevenir »: contravene a law.","h":["Contra + venire: come against. Contravene a law.","Contravene: breach."],"s":["flout","scorn"]},{"w":"convalescent","p":"adj.","m":"Recovering from illness.","e":"Latin <i>convalescere</i> (to grow strong).","f":"convalescent","t":"Same as « convalescent ».","h":["Con + valere: grow strong. A convalescent patient.","Convalescent: recovering."],"s":[]},{"w":"corporeal","p":"adj.","m":"Relating to a person's body; tangible.","e":"Latin <i>corporeus</i>, from <i>corpus</i> (body).","f":"corporel","t":"Same as « corporel ».","h":["Corpus: body. Corporeal form.","Corporeal: bodily."],"s":["tangible"]},{"w":"curb","p":"v.","m":"To restrain or keep in check.","e":"Old French <i>courber</i> (to bend), Latin <i>curvus</i>.","f":"freiner, juguler","t":"Same family as « courber »: a curb on a horse is a strap. Curb inflation.","h":["Curb strap on a horse. Curb spending.","Curb: restrain."],"s":["bridle","check","constraint","curtail","deterrent","hamper","hinder","impede","impediment","inhibit","quash","squelch","stanch","stem","suppress","truncate"]},{"w":"denounce","p":"v.","m":"To publicly declare to be wrong or evil.","e":"Latin <i>denuntiare</i> (to announce).","f":"dénoncer","t":"Same as « dénoncer ».","h":["De + nuntiare. Denounce the regime.","Denounce: condemn."],"s":["castigate","censure","decry","denigrate","disparage","excoriate","fulminate","stigmatize","vilify"]},{"w":"despotic","p":"adj.","m":"Exercising absolute power in a cruel way.","e":"Greek <i>despotēs</i> (master).","f":"despotique","t":"Same as « despotique ».","h":["Despot. A despotic ruler.","Despotic: tyrannical."],"s":["autocratic","dictatorial","imperious"]},{"w":"deviate","p":"v.","m":"To depart from an established course.","e":"Latin <i>deviare</i>: <i>de-</i> + <i>via</i> (road).","f":"dévier, s'écarter","t":"Same as « dévier »: off the road.","h":["De + via: off the road. Deviate from plan.","Deviate: stray."],"s":["diverge"]},{"w":"disentangle","p":"v.","m":"To free from entanglement; to untangle.","e":"<i>dis-</i> + <i>entangle</i>.","f":"démêler","t":"« Démêler ». Disentangle fact from fiction.","h":["Dis + entangle. Disentangle the wires.","Disentangle: untie."],"s":["resolve","unravel"]},{"w":"doctrinaire","p":"adj.","m":"Seeking to impose a doctrine without regard to practical considerations.","e":"French <i>doctrinaire</i>, from <i>doctrine</i>.","f":"doctrinaire, dogmatique","t":"Same as « doctrinaire ».","h":["Doctrine. A doctrinaire leader.","Doctrinaire: rigidly dogmatic."],"s":["dictatorial","dogmatic","hidebound"]},{"w":"effusive","p":"adj.","m":"Expressing feelings, especially gratitude or praise, in a gushing, unrestrained way.","e":"Latin <i>effundere</i> (to pour out): <i>ex-</i> + <i>fundere</i> (to pour).","f":"expansif, démonstratif, exubérant","t":"Same family as « effusion » (« effusions de joie »): feelings pour out. Effusive praise.","h":["Ex + fundere: pour out. An effusive welcome.","Effusive: gushing."],"s":["demonstrative","ebullient","effervescent","expansive","forthcoming","garrulous","loquacious","profuse","prolix","verbose","voluble"]},{"w":"escalate","p":"v.","m":"To increase rapidly; to become more intense.","e":"From <i>escalator</i>, Latin <i>scala</i> (ladder).","f":"s'intensifier, monter en puissance","t":"Escalier: step up. A conflict escalates = « s'envenime ».","h":["Scala: ladder. Tensions escalate.","Escalate: intensify."],"s":["amplify","augment"]},{"w":"evoke","p":"v.","m":"To bring a feeling or memory to mind.","e":"Latin <i>evocare</i> (to call out): <i>e-</i> + <i>vocare</i>.","f":"évoquer","t":"Same as « évoquer ».","h":["E + vocare: call out. Evoke memories.","Evoke: summon."],"s":["elicit"]},{"w":"exorcise","p":"v.","m":"To drive out an evil spirit; to get rid of a painful memory.","e":"Greek <i>exorkizein</i> (to bind by oath).","f":"exorciser","t":"Same as « exorciser ».","h":["Ex + horkos: out by oath. Exorcise a ghost.","Exorcise: expel."],"s":["banish"]},{"w":"figurative","p":"adj.","m":"Departing from literal meaning; metaphorical.","e":"Latin <i>figurativus</i>, from <i>figura</i> (shape).","f":"figuré","t":"Au sens figuré. Opposite: literal.","h":["Figure of speech. Figurative sense.","Figurative: not literal."],"s":["allegorical","metaphorical"]},{"w":"finicky","p":"adj.","m":"Fussy about details; hard to please.","e":"From <i>finical</i>, probably from <i>fine</i>.","f":"tatillon, pointilleux, difficile","t":"Finicky about food: « difficile »; about details: « tatillon ».","h":["Fine. Finicky eater.","Finicky: fussy."],"s":["captious","carping","fastidious","meticulous","pedantic","punctilious"]},{"w":"flustered","p":"adj.","m":"Agitated and confused.","e":"Scandinavian origin (cf. Icelandic <i>flaustr</i>, hurry).","f":"troublé, déboussolé","t":"A flustered speaker loses the thread: « décontenancé ».","h":["Flustra. Flustered by questions.","Flustered: rattled."],"s":["befuddled"]},{"w":"foil","p":"v.","m":"To prevent from succeeding.","e":"Old French <i>fouler</i> (to trample), Latin <i>fullo</i> (fuller).","f":"déjouer, faire échouer","t":"Foil a plot = déjouer un complot. (Also n.: a contrasting character.)","h":["Foil: leaf; thwart. Foil the plot.","Foil: thwart."],"s":["balk","check","circumvent","frustrate","hinder","preclude","stymie","thwart"]},{"w":"frailty","p":"n.","m":"Weakness; vulnerability.","e":"Old French <i>fraileté</i>, Latin <i>fragilis</i> (breakable).","f":"fragilité, faiblesse","t":"Frail = « frêle » = fragile.","h":["Frail. Human frailty.","Frailty: fragility."],"s":["foible","idiosyncrasy","peccadillo"]},{"w":"fret","p":"v.","m":"To be constantly or visibly anxious.","e":"Old English <i>fretan</i> (to devour). Germanic.","f":"se tracasser, s'inquiéter","t":"Worry eats at you. Don't fret = ne t'en fais pas.","h":["Fretan: devour. Don’t fret.","Fret: worry."],"s":[]},{"w":"gingerly","p":"adv./adj.","m":"In a careful or cautious manner, to avoid harm or damage.","e":"Probably Old French <i>gensor</i> (more delicate), from <i>gent</i> (graceful, well-born). Nothing to do with ginger.","f":"avec précaution, délicatement","t":"Not from « gingembre ». Think « gentil »: handle it gently. Lift the lid gingerly.","h":["Gentle, not ginger. Lift it gingerly.","Gingerly: with great care."],"s":[]},{"w":"grievance","p":"n.","m":"A real or imagined cause for complaint.","e":"Old French <i>grever</i> (to burden), Latin <i>gravare</i>.","f":"doléance, grief","t":"« Grief » (also in French legal speak): a heavy burden. Cousin of « grave ».","h":["Gravis: heavy. Air a grievance.","Grievance: complaint."],"s":[]},{"w":"headstrong","p":"adj.","m":"Wilful and obstinate.","e":"<i>head</i> + <i>strong</i>. Germanic.","f":"têtu, entêté","t":"Strong in the head: « têtu ».","h":["Head + strong. A headstrong child.","Headstrong: wilful."],"s":["adamant","capricious","deliberate","dogged","intransigent","obdurate","obstinate","pertinacious","refractory","tenacious","unruly","wayward","willful"]},{"w":"idiosyncratic","p":"adj.","m":"Peculiar or individual to one person.","e":"Greek <i>idiosunkrasia</i>: <i>idios</i> (own) + <i>sunkrasis</i> (mixture).","f":"idiosyncrasique, particulier","t":"Same as « idiosyncrasie »: your own mix.","h":["Idios + synkrasis: own mixture. An idiosyncratic style.","Idiosyncratic: one’s own quirky."],"s":["eccentric","outlandish","peculiar","quirky"]},{"w":"incidental","p":"adj.","m":"Happening as a minor accompaniment; secondary.","e":"Latin <i>incidens</i> (falling upon).","f":"accessoire, secondaire","t":"Related to « incident ». Incidental expenses = frais accessoires.","h":["Incidens: happening upon. Incidental costs.","Incidental: minor."],"s":["adventitious","concomitant","fortuitous","peripheral","tangential"]},{"w":"intertwined","p":"adj.","m":"Twisted together; closely connected.","e":"<i>inter-</i> + <i>twine</i>. Germanic.","f":"entrelacé, étroitement lié","t":"Entrelacés.","h":["Inter + twine. Intertwined fates.","Intertwined: interlaced."],"s":[]},{"w":"ire","p":"n.","m":"Anger.","e":"Latin <i>ira</i> (anger).","f":"colère, courroux","t":"Cousin of « irascible »: ira = anger.","h":["Ira: anger. Provoke ire.","Ire: wrath."],"s":[]},{"w":"ironclad","p":"adj.","m":"Impossible to break or change.","e":"<i>iron</i> + <i>clad</i> (clothed). Germanic.","f":"inattaquable, en béton","t":"Clad in iron: an ironclad contract is airtight. « Blindé ».","h":["Iron + clad. An ironclad contract.","Ironclad: unbreakable."],"s":["unassailable"]},{"w":"jeopardize","p":"v.","m":"To put at risk of harm or failure.","e":"Old French <i>jeu parti</i> (divided game, even chances).","f":"mettre en danger, compromettre","t":"« Jeu parti »: a gamble with even odds. Jeopardy = péril.","h":["Jeu parti: divided game. Jeopardize the deal.","Jeopardize: endanger."],"s":["compromise","impair","undermine"]},{"w":"lull","p":"v.","m":"To calm or send to sleep; (n.) a pause.","e":"Imitative of lullaby sounds (<i>lulla</i>).","f":"bercer, apaiser; accalmie","t":"Lullaby: lull a baby; a lull in the storm = « accalmie ».","h":["Lullaby. Lulled to sleep; a lull in the storm.","Lull: soothe or pause."],"s":["pacify","respite"]},{"w":"neutralize","p":"v.","m":"To render ineffective by countering.","e":"French <i>neutraliser</i>, Latin <i>neuter</i> (neither).","f":"neutraliser","t":"Same as « neutraliser ».","h":["Neuter: neither. Neutralize the threat.","Neutralize: cancel out."],"s":["countermand","negate","nullify"]},{"w":"oblivious","p":"adj.","m":"Not aware of or concerned about what is happening around.","e":"Latin <i>obliviosus</i>, from <i>oblivio</i> (forgetfulness).","f":"inconscient de, indifférent","t":"Same family as « oubli / oblivion ».","h":["Oblivisci: forget. Oblivious to danger.","Oblivious: unaware."],"s":[]},{"w":"perpetrate","p":"v.","m":"To carry out a harmful or illegal act.","e":"Latin <i>perpetrare</i> (to accomplish).","f":"perpétrer, commettre","t":"Same as « perpétrer ». The perpetrator = auteur du crime.","h":["Per + patrare: accomplish. Perpetrate fraud.","Perpetrate: commit."],"s":[]},{"w":"plaintive","p":"adj.","m":"Sounding sad and mournful.","e":"Old French <i>plaintif</i>, from <i>plaindre</i>.","f":"plaintif","t":"Same as « plaintif ».","h":["Plangere: lament. A plaintive cry.","Plaintive: sorrowful."],"s":["carping","doleful","dolorous","elegiac","elegy","lachrymose","lugubrious","melancholy","petulant","querulous","wistful","woeful"]},{"w":"poise","p":"n.","m":"Graceful, self-assured balance in manner.","e":"Old French <i>peser</i> (to weigh), Latin <i>pensare</i>.","f":"aplomb, assurance","t":"Poids → balance: « avoir de l'aplomb ».","h":["Pensum: weight. Poise under pressure.","Poise: composure."],"s":["aplomb","equanimity","sangfroid"]},{"w":"pomposity","p":"n.","m":"Self-importance; ostentatious speech.","e":"Latin <i>pomposus</i>, from <i>pompa</i> (procession).","f":"emphase, grandiloquence","t":"Same as « pompeux / pompe ». Pompous.","h":["Pompa: procession. His pomposity.","Pomposity: self-importance."],"s":["rhetoric"]},{"w":"pretentious","p":"adj.","m":"Attempting to impress by affecting greater importance than is possessed.","e":"Latin <i>praetendere</i> (to put forward).","f":"prétentieux","t":"Same as « prétentieux ».","h":["Pretend. A pretentious menu.","Pretentious: showy."],"s":["bombastic","flamboyant","grandiloquent","ostentatious"]},{"w":"profound","p":"adj.","m":"Very great or intense; having great depth.","e":"Latin <i>profundus</i> (deep): <i>pro-</i> + <i>fundus</i> (bottom).","f":"profond","t":"Same as « profond ».","h":["Pro + fundus: deep. A profound insight.","Profound: deep."],"s":["abstruse","robust","sound"]},{"w":"proxy","p":"n.","m":"The authority to represent someone else; a stand-in.","e":"Contraction of <i>procuracy</i>, Latin <i>procurare</i> (to take care of).","f":"procuration, mandataire","t":"Proxy = « procuration ». Use as a proxy for.","h":["Procuracy. Vote by proxy.","Proxy: stand-in."],"s":["surrogate"]},{"w":"ramification","p":"n.","m":"A consequence of an action; a branching out.","e":"Latin <i>ramus</i> (branch).","f":"ramification, conséquence","t":"Same as « ramification »: ramus = branch. Ramifications are consequences that branch out.","h":["Ramus: branch. Ramifications of the law.","Ramification: offshoot."],"s":["corollary","repercussion"]},{"w":"recourse","p":"n.","m":"A source of help in a difficult situation; resort.","e":"Latin <i>recursus</i> (a running back): <i>re-</i> + <i>currere</i>.","f":"recours","t":"Same as « recours »: avoir recours à. Without recourse = sans recours.","h":["Re + cursus: run back. No recourse but court.","Recourse: resort."],"s":[]},{"w":"regress","p":"v.","m":"To return to a former, less developed state.","e":"Latin <i>regredi</i> (to step back): <i>re-</i> + <i>gradi</i>.","f":"régresser, rétrograder","t":"Opposite of progress: « régresser ».","h":["Re + gradi: step back. Regress to childhood.","Regress: revert."],"s":[]},{"w":"reiterate","p":"v.","m":"To say again for emphasis.","e":"Latin <i>reiterare</i>: <i>re-</i> + <i>iterum</i> (again).","f":"réitérer","t":"Same as « réitérer ».","h":["Re + iterum: again. Reiterate the point.","Reiterate: repeat."],"s":["recapitulate"]},{"w":"relent","p":"v.","m":"To yield after initially refusing.","e":"Latin <i>re-</i> + <i>lentus</i> (slow, soft).","f":"fléchir, se radoucir","t":"Cousin of « ralentir ». Soften your stance: « céder ».","h":["Re + lentus: slow. He finally relented.","Relent: soften."],"s":["capitulate","cede","concede","yield"]},{"w":"repercussion","p":"n.","m":"An unintended consequence.","e":"Latin <i>repercussio</i> (rebound): <i>re-</i> + <i>percutere</i> (to strike).","f":"répercussion, conséquence","t":"Same as « répercussion ». Usually plural: repercussions.","h":["Re + percutere: strike back. Serious repercussions.","Repercussion: consequence."],"s":["ramification"]},{"w":"replenish","p":"v.","m":"To fill up again.","e":"Old French <i>replenir</i>, Latin <i>plenus</i> (full).","f":"réapprovisionner, remplir à nouveau","t":"Re + plein: fill again. Cousin of « plénitude ».","h":["Re + plenus. Replenish stock.","Replenish: refill."],"s":[]},{"w":"rigor","p":"n.","m":"The quality of being extremely thorough and strict.","e":"Latin <i>rigor</i> (stiffness).","f":"rigueur","t":"Same as « rigueur ».","h":["Rigere: be stiff. Academic rigor.","Rigor: strictness."],"s":[]},{"w":"sparse","p":"adj.","m":"Thinly dispersed or scattered.","e":"Latin <i>sparsus</i> (scattered), from <i>spargere</i>.","f":"clairsemé, épars","t":"Same as « épars »: sparse vegetation.","h":["Spargere: scatter. Sparse hair.","Sparse: thin."],"s":["paltry","scant"]},{"w":"surmount","p":"v.","m":"To overcome (a difficulty); to be on top of.","e":"Old French <i>surmonter</i>: <i>sur-</i> + <i>monter</i>.","f":"surmonter","t":"Same as « surmonter ».","h":["Sur + monter. Surmount obstacles.","Surmount: overcome."],"s":["vanquish"]},{"w":"suspect","p":"adj.","m":"Open to doubt; possibly dishonest.","e":"Latin <i>suspectus</i>, from <i>suspicere</i> (to look up at).","f":"suspect, douteux","t":"Same as « suspect ».","h":["Sub + specere: look under. A suspect alibi.","Suspect (adj.): doubtful."],"s":["dubious"]},{"w":"tedious","p":"adj.","m":"Too long, slow or dull.","e":"Latin <i>taedium</i> (weariness).","f":"fastidieux, ennuyeux","t":"Same as « fastidieux »; not « tédieux ».","h":["Taedium: weariness. A tedious lecture.","Tedious: boring."],"s":["banal","garrulous","humdrum","irksome","laborious","loquacious","monotonous","mundane","pedestrian","plodding","prolix","prosaic","verbose","voluble"]},{"w":"teeming","p":"adj.","m":"Full of, swarming with (people, animals, or things); crowded and busy.","e":"From <i>teem</i>, Old English <i>tīeman</i> (to give birth, produce offspring), related to <i>team</i> (offspring). A different <i>teem</i>, from Old Norse <i>tœma</i>, means to pour out (rain teeming down).","f":"grouillant, fourmillant","t":"« Grouiller de » or « fourmiller de »: a town teeming with tourists. Born in numbers, so swarming.","h":["Think « grouillant ». A town teeming with tourists.","Teeming: swarming, packed."],"s":[]},{"w":"transcend","p":"v.","m":"To go beyond the range or limits of.","e":"Latin <i>transcendere</i> (to climb over).","f":"transcender, dépasser","t":"Same as « transcender ».","h":["Trans + scandere: climb across. Transcend limits.","Transcend: surpass."],"s":["eclipse","outstrip"]},{"w":"treatise","p":"n.","m":"A formal written work dealing systematically with a subject.","e":"Old French <i>tretiz</i>, from Latin <i>tractare</i> (to handle).","f":"traité","t":"« Un traité » de philosophie.","h":["Tractare: handle. A treatise on law.","Treatise: formal study."],"s":[]},{"w":"vigilant","p":"adj.","m":"Keeping careful watch for danger.","e":"Latin <i>vigilare</i> (to stay awake).","f":"vigilant","t":"Same as « vigilant ».","h":["Vigil: wake. Stay vigilant.","Vigilant: watchful."],"s":["chary","circumspect","leery","wary"]},{"w":"vitality","p":"n.","m":"The state of being strong and active.","e":"Latin <i>vita</i> (life).","f":"vitalité","t":"Same as « vitalité ».","h":["Vita: life. Full of vitality.","Vitality: energy."],"s":["panache","verve"]},{"w":"vivacious","p":"adj.","m":"Attractively lively and animated.","e":"Latin <i>vivax</i> (lively), from <i>vivere</i> (to live).","f":"vif, plein d'entrain","t":"Same family as « vivace / vivacité ».","h":["Vivere: live. A vivacious host.","Vivacious: lively."],"s":["buoyant","ebullient","effervescent","scintillating"]},{"w":"yield","p":"v.","m":"To produce; to give way.","e":"Old English <i>gieldan</i> (to pay). Germanic.","f":"produire, rapporter; céder","x":"2nd meaning","t":"Rendement (n.). Yield to pressure = céder. Yield returns = rapporter.","h":["Gieldan: pay. Yield to pressure; crops yield.","Yield: give way or produce."],"s":["afford","capitulate","cede","concede","relent","relinquish","render"]}]},{"name":"GregMat VI","slug":"gregmat-vi","series":"GregMat","words":[{"w":"abide","p":"v.","m":"To tolerate; to accept or follow (rules).","e":"Old English <i>ābīdan</i> (to wait). Germanic.","f":"supporter, tolérer; respecter","x":"2nd meaning","t":"Can't abide = ne supporte pas. Abide by the rules = respecter.","h":["Abidan: wait. Can’t abide noise; abide by rules.","Abide: tolerate or obey."],"s":["adhere","brook","comply","countenance","sanction"]},{"w":"abstract","p":"adj.","m":"Existing in thought rather than as a concrete thing.","e":"Latin <i>abstractus</i> (drawn away): <i>abs-</i> + <i>trahere</i>.","f":"abstrait","t":"Same as « abstrait ».","h":["Abs + trahere: drawn away. Abstract idea.","Abstract: not concrete."],"s":[]},{"w":"affront","p":"n.","m":"An action that causes offence.","e":"Old French <i>afronter</i> (to slap in the face), Latin <i>ad frontem</i>.","f":"affront, offense","t":"Same as « affront »: a slap in the front/face.","h":["Ad + frons: to the face. A public affront.","Affront: insult."],"s":["slight","snub"]},{"w":"aghast","p":"adj.","m":"Filled with horror or shock.","e":"Middle English <i>agasten</i> (to terrify), related to <i>ghost</i>.","f":"consterné, horrifié","t":"As if you've seen a ghost: « sidéré ».","h":["A + gast: terrify. Aghast at the news.","Aghast: horrified."],"s":[]},{"w":"agitate","p":"v.","m":"To disturb or excite; to campaign.","e":"Latin <i>agitare</i> (to drive), from <i>agere</i>.","f":"agiter; faire campagne","t":"Same as « agiter ».","h":["Agere: drive. Agitate for reform.","Agitate: stir up."],"s":["foment","incite","perturb"]},{"w":"antagonize","p":"v.","m":"To provoke hostility in someone.","e":"Greek <i>antagōnizesthai</i>: <i>anti-</i> + <i>agōnizesthai</i> (to struggle).","f":"s'aliéner, provoquer l'hostilité de","t":"Cousin of « antagoniste ». Don't antagonize the client.","h":["Anti + agon: contest. Don’t antagonize him.","Antagonize: provoke."],"s":["alienate"]},{"w":"apprise","p":"v.","m":"To inform or tell someone of something.","e":"French <i>apprendre</i> (to learn, to teach), past participle <i>appris</i>.","f":"informer, mettre au courant","x":"Look-alike","t":"Not « apprécier »! Apprise = « mettre au courant ». Apprise him of the facts.","h":["Apprendre: learn; inform. Apprise me of changes.","Apprise: notify."],"s":["inform"]},{"w":"aspersion","p":"n.","m":"An attack on someone's reputation (usually: cast aspersions).","e":"Latin <i>aspergere</i> (to sprinkle).","f":"calomnie, insinuation","t":"Sprinkle mud on someone's name: cast aspersions on.","h":["Aspergere: sprinkle. Cast aspersions.","Aspersion: slur."],"s":["calumny","slander"]},{"w":"barren","p":"adj.","m":"Too poor to produce much or any vegetation; unproductive.","e":"Old French <i>baraigne</i> (sterile, of land or women).","f":"stérile, aride","t":"Think « bréhaigne » (old: sterile). Barren desert = désert aride.","h":["Baraigne: sterile. Barren land.","Barren: lifeless."],"s":[]},{"w":"bawdy","p":"adj.","m":"Humorously indecent.","e":"From <i>bawd</i> (brothel keeper), Old French <i>baud</i> (merry).","f":"grivois, salé","t":"Rabelais! A bawdy tale = histoire grivoise.","h":["Bawd: brothel keeper. Bawdy humour.","Bawdy: raunchy."],"s":["lascivious","prurient","ribald","salacious"]},{"w":"beguile","p":"v.","m":"To charm or enchant; to deceive.","e":"<i>be-</i> + Old French <i>guile</i> (deceit).","f":"séduire, charmer; tromper","x":"2nd meaning","t":"Guile: ruse. Beguiled by a smile = séduit. Also beguile into = tromper.","h":["Be + guile. Beguiled by charm.","Beguile: charm or trick."],"s":["dupe","enchant","enthrall","entice","hoodwink","mesmerize"]},{"w":"bravado","p":"n.","m":"A bold manner intended to impress; false courage.","e":"Spanish <i>bravada</i>, from <i>bravo</i>.","f":"bravade, fanfaronnade","t":"Same as « bravade ».","h":["Bravo. Mere bravado.","Bravado: swagger."],"s":["posturing"]},{"w":"burnish","p":"v.","m":"To polish by rubbing.","e":"Old French <i>burnir</i> (to make brown, polish), from <i>brun</i>.","f":"polir, brunir","t":"« Brunir »: to polish metal until it shines. Burnish an image.","h":["Brunir: brown, polish. Burnish silver.","Burnish: buff."],"s":[]},{"w":"cajole","p":"v.","m":"To persuade by sustained coaxing or flattery.","e":"French <i>cajoler</i> (to chatter like a jay), from <i>gaiole</i> (cage).","f":"cajoler, enjôler","t":"Same as « cajoler »: coax with sweet words.","h":["Cajoler: coax. Cajole her into it.","Cajole: wheedle."],"s":["entice","inveigle","wheedle"]},{"w":"callous","p":"adj.","m":"Showing insensitive disregard for others.","e":"Latin <i>callosus</i> (thick-skinned), from <i>callum</i> (hard skin).","f":"insensible, cruel","t":"Un cal(lus) on the heart: thick skin.","h":["Callus: hard skin. Callous remark.","Callous: heartless."],"s":["impenetrable","impermeable","impervious"]},{"w":"collude","p":"v.","m":"To cooperate secretly for illegal ends.","e":"Latin <i>colludere</i> (to play together).","f":"être de connivence, s'entendre","t":"Same as « collusion ».","h":["Con + ludere: play together. Firms collude.","Collude: conspire."],"s":["connive","conspire","intrigue","machinate"]},{"w":"commiserate","p":"v.","m":"To express sympathy or pity.","e":"Latin <i>commiserari</i>: <i>com-</i> + <i>miser</i> (wretched).","f":"compatir, plaindre","t":"Commisérer. Share someone's misery.","h":["Con + miserari. Commiserate over a loss.","Commiserate: sympathize."],"s":[]},{"w":"contretemps","p":"n.","m":"An unexpected and awkward occurrence.","e":"French <i>contretemps</i> (against the time).","f":"contretemps","t":"Straight from French « contretemps ».","h":["Contre + temps. An awkward contretemps.","Contretemps: mishap."],"s":[]},{"w":"conviction","p":"n.","m":"A firmly held belief; a formal declaration of guilt.","e":"Latin <i>convictio</i>, from <i>convincere</i> (to overcome).","f":"conviction; condamnation","x":"2nd meaning","t":"« Conviction » = belief. Also a criminal conviction = condamnation.","h":["Convincere: prove guilty. Strong conviction.","Conviction: firm belief or guilty verdict."],"s":[]},{"w":"coy","p":"adj.","m":"Making a pretence of shyness; reluctant to give details.","e":"Old French <i>coi</i> (quiet), Latin <i>quietus</i>.","f":"faussement timide, évasif","t":"« Coi » (se tenir coi). Coy about the salary = évasif.","h":["Quietus: still. Coy smile.","Coy: bashful."],"s":["demure","diffident","modest","retiring"]},{"w":"croon","p":"v.","m":"To sing softly in a low voice.","e":"Middle Dutch <i>kronen</i> (to lament).","f":"fredonner, chanter doucement","t":"Frank Sinatra, the crooner.","h":["Croon: lament. Crooning ballads.","Croon: sing softly."],"s":[]},{"w":"deportment","p":"n.","m":"Behaviour or manners; bearing.","e":"French <i>déportement</i>, Latin <i>deportare</i>.","f":"maintien, tenue","t":"Not « déportation »! Deportment = bearing, comportement.","h":["Deporter: behave. Graceful deportment.","Deportment: bearing."],"s":[]},{"w":"depose","p":"v.","m":"To remove from office; to testify under oath.","e":"Old French <i>deposer</i>, <i>de-</i> + <i>poser</i>.","f":"destituer; déposer","t":"Same as « déposer »: put down the ruler.","h":["De + ponere: put down. Depose the king.","Depose: oust."],"s":["oust","supplant"]},{"w":"deprecate","p":"v.","m":"To express disapproval of; to belittle (self-deprecating).","e":"Latin <i>deprecari</i> (to pray against).","f":"désapprouver, minimiser","x":"Look-alike","t":"Not depreciate (lose value). Self-deprecating humour belittles oneself: « autodérision ».","h":["De + precari: pray away. Self-deprecating.","Deprecate: belittle."],"s":["belittle","decry","defame","demean","denigrate","disparage","malign","vilify"]},{"w":"detente","p":"n.","m":"The easing of strained relations.","e":"French <i>détente</i> (relaxation).","f":"détente","t":"Straight from French « détente ».","h":["Détendre: relax. Cold War détente.","Detente: eased tension."],"s":["rapprochement"]},{"w":"dirge","p":"n.","m":"A lament for the dead; a mournful song.","e":"Latin <i>dirige</i> (direct!), the first word of the Office of the Dead.","f":"chant funèbre, complainte","t":"Latin dirige (“guide”): opening of a funeral prayer. A dirge = funeral song.","h":["Dirige: guide us, funeral chant. A slow dirge.","Dirge: funeral song."],"s":["elegy","lament"]},{"w":"disdain","p":"n.","m":"The feeling that someone is unworthy of respect.","e":"Old French <i>desdeignier</i>, Latin <i>dedignari</i> (to reject as unworthy).","f":"dédain","t":"Same as « dédain ».","h":["Dis + dignari: deem unworthy. Look with disdain.","Disdain: scorn."],"s":["contempt","hauteur","opprobrium","scorn","snub","spurn"]},{"w":"disperse","p":"v.","m":"To go in different directions.","e":"Latin <i>dispergere</i>: <i>dis-</i> + <i>spargere</i> (to scatter).","f":"disperser, se disperser","t":"Same as « disperser ».","h":["Dis + spargere. The crowd dispersed.","Disperse: scatter."],"s":["diffuse","disseminate","dissipate","propagate","squander"]},{"w":"dowdy","p":"adj.","m":"Unfashionable and drab.","e":"Middle English <i>doude</i> (slut/drab woman), origin unknown.","f":"sans élégance, mal fagoté","t":"Dull dress: « mal fagoté ».","h":["Dowd: slut; drab. A dowdy coat.","Dowdy: frumpy."],"s":[]},{"w":"echelon","p":"n.","m":"A level or rank in an organization.","e":"French <i>échelon</i> (rung of a ladder), from <i>échelle</i>.","f":"échelon, niveau","t":"Same as « échelon »: upper echelons of management.","h":["Échelle: ladder. The upper echelon.","Echelon: rank."],"s":[]},{"w":"ennui","p":"n.","m":"Listlessness arising from boredom.","e":"French <i>ennui</i>, Latin <i>in odio</i> (in hatred).","f":"ennui, lassitude","t":"Straight from French: « l'ennui » (stronger in English).","h":["Ennui: boredom. Weary ennui.","Ennui: listless boredom."],"s":["lassitude","torpor"]},{"w":"expatiate","p":"v.","m":"To speak or write at length on a subject.","e":"Latin <i>exspatiari</i> (to wander): <i>ex-</i> + <i>spatium</i>.","f":"s'étendre sur, développer longuement","x":"Look-alike","t":"Not « expatriate » (live abroad). Expatiate = « s'étendre » on a subject.","h":["Ex + spatiari: roam. Expatiate on theory.","Expatiate: elaborate."],"s":["elaborate","elucidate","embellish","expound"]},{"w":"extemporize","p":"v.","m":"To speak or perform without preparation.","e":"Latin <i>ex tempore</i> (out of the moment).","f":"improviser","t":"Ex tempore: out of the moment.","h":["Ex + tempore: out of time. Extemporize a toast.","Extemporize: ad-lib."],"s":["improvise"]},{"w":"fallow","p":"adj.","m":"(Of land) ploughed but left unplanted; inactive.","e":"Old English <i>fealh</i> (ploughed land).","f":"en jachère, inactif","t":"Jachère. A fallow period for the mind.","h":["Falwe: pale ploughed. Fallow field.","Fallow: unplanted."],"s":["dormant","quiescent"]},{"w":"feint","p":"n.","m":"A deceptive movement intended to distract.","e":"Old French <i>feinte</i>, from <i>feindre</i>.","f":"feinte","t":"Same as « feinte » in boxing and fencing.","h":["Feindre: pretend. A boxer’s feint.","Feint: fake move."],"s":[]},{"w":"flagrant","p":"adj.","m":"Conspicuously offensive; blatant.","e":"Latin <i>flagrare</i> (to blaze).","f":"flagrant","t":"« Flagrant délit »: caught in the act.","h":["Flagrare: blaze. A flagrant foul.","Flagrant: glaring."],"s":["blatant","brazen","egregious"]},{"w":"fraught","p":"adj.","m":"Filled with (something undesirable); causing anxiety.","e":"Middle Dutch <i>vracht</i> (freight). Germanic.","f":"chargé de, tendu","t":"Freight: loaded with. A fraught meeting is « chargé de tension ».","h":["Freight: loaded. Fraught with danger.","Fraught: laden, tense."],"s":["replete"]},{"w":"fulcrum","p":"n.","m":"The point on which a lever rests; the pivot of an activity.","e":"Latin <i>fulcrum</i> (bedpost), from <i>fulcire</i> (to support).","f":"point d'appui, pivot","t":"Archimède: the pivot of a lever.","h":["Fulcire: prop up. The fulcrum of the lever.","Fulcrum: pivot point."],"s":[]},{"w":"gratuitous","p":"adj.","m":"Uncalled for; lacking good reason.","e":"Latin <i>gratuitus</i> (free).","f":"gratuit, injustifié","x":"2nd meaning","t":"Not 'free of charge' here: gratuit = for no reason. Gratuitous violence = violence gratuite, injustifiée.","h":["Gratuitus: free. Gratuitous violence.","Gratuitous: unwarranted."],"s":["wanton","wayward","willful"]},{"w":"heady","p":"adj.","m":"Intoxicating; exhilarating.","e":"From <i>head</i>. Germanic.","f":"grisant, enivrant","t":"Goes to your head: « grisant ». Heady perfume, heady days.","h":["Head. A heady perfume.","Heady: intoxicating."],"s":["exhilarating","potent"]},{"w":"hysterical","p":"adj.","m":"Exhibiting wildly uncontrolled emotion; extremely funny.","e":"Greek <i>hystera</i> (womb), from old medical theory.","f":"hystérique; à mourir de rire","x":"2nd meaning","t":"Hysterical laughter = fou rire. A hysterical comedy is hilarious.","h":["Hystera: womb; wild. Hysterical laughter.","Hysterical: frantic or hilarious."],"s":[]},{"w":"intrigue","p":"v.","m":"To arouse curiosity; to plot secretly.","e":"French <i>intriguer</i>, Latin <i>intricare</i> (to entangle).","f":"intriguer, comploter","t":"Same as « intriguer ».","h":["Intricare: entangle. Court intrigue.","Intrigue: fascinate or plot."],"s":["collude","collusion","connive","conspire","machinate","machination","ploy"]},{"w":"jocund","p":"adj.","m":"Cheerful and lighthearted.","e":"Latin <i>jocundus</i>, variant of <i>jucundus</i> (pleasant).","f":"jovial, enjoué","t":"Jocund = jovial; same joke (jocus) root as « jouer ».","h":["Jocus: joke. A jocund mood.","Jocund: merry."],"s":["convivial","droll","facetious","jocular","jovial"]},{"w":"lambaste","p":"v.","m":"To criticize harshly.","e":"<i>lam</i> (to beat) + <i>baste</i> (to thrash). Germanic.","f":"éreinter, fustiger","t":"Beat + beat: verbally. « Éreinter » a film.","h":["Lam + baste: beat. Lambaste the film.","Lambaste: slam."],"s":["admonish","berate","castigate","chastise","excoriate","lambast","objurgate","rebuke","reproach","upbraid"]},{"w":"nimble","p":"adj.","m":"Quick and light in movement.","e":"Old English <i>nǣmel</i> (quick to grasp). Germanic.","f":"agile, leste","t":"Nimble fingers: « agile ».","h":["Niman: take. Nimble fingers.","Nimble: agile."],"s":["adept","adroit","deft","dexterous"]},{"w":"nominal","p":"adj.","m":"Existing in name only; very small (of a fee).","e":"Latin <i>nominalis</i>, from <i>nomen</i> (name).","f":"nominal, symbolique","x":"2nd meaning","t":"For a nominal fee = une somme symbolique. Nominal leader: leader in name only.","h":["Nomen: name. A nominal fee.","Nominal: token."],"s":["perfunctory","token"]},{"w":"odious","p":"adj.","m":"Extremely unpleasant; repulsive.","e":"Latin <i>odiosus</i>, from <i>odium</i> (hatred).","f":"odieux","t":"Same as « odieux ».","h":["Odium: hatred. An odious crime.","Odious: hateful."],"s":["abysmal","execrable","invidious","repugnant","woeful"]},{"w":"ominous","p":"adj.","m":"Giving the impression that something bad will happen.","e":"Latin <i>ominosus</i>, from <i>omen</i>.","f":"menaçant, de mauvais augure","t":"An omen: « de mauvais augure ».","h":["Omen. An ominous silence.","Ominous: threatening."],"s":["adverse","baleful","portentous","unpropitious"]},{"w":"outlandish","p":"adj.","m":"Looking or sounding bizarre or unfamiliar.","e":"Old English <i>ūtlendisc</i> (foreign): <i>ūt</i> + <i>land</i>. Germanic.","f":"extravagant, bizarre","t":"From outside the land: weird.","h":["Out of the land. Outlandish costume.","Outlandish: bizarre."],"s":["eccentric","exorbitant","exotic","extravagant","flamboyant","idiosyncratic","ostentatious","peculiar","quirky"]},{"w":"peccadillo","p":"n.","m":"A small, minor sin or fault.","e":"Spanish <i>pecadillo</i>, diminutive of <i>pecado</i> (sin), Latin <i>peccare</i>.","f":"peccadille, faute vénielle","t":"Same as « peccadille »: a little pécher.","h":["Peccare: sin. A mere peccadillo.","Peccadillo: petty fault."],"s":["foible","frailty","idiosyncrasy"]},{"w":"quarantine","p":"n.","m":"A period of isolation to prevent the spread of disease.","e":"Italian <i>quaranta giorni</i> (forty days).","f":"quarantaine","t":"Same as « quarantaine »: forty days (quarante).","h":["Quaranta: forty days. Quarantine the sick.","Quarantine: isolation."],"s":[]},{"w":"quash","p":"v.","m":"To reject as invalid; to put an end to.","e":"Old French <i>quasser</i> (to annul), Latin <i>quassare</i>.","f":"annuler, étouffer, réprimer","t":"Casser! Quash a verdict = casser un jugement; quash a rebellion.","h":["Quassare: shatter. Quash the verdict.","Quash: annul."],"s":["abrogate","countermand","curb","hamper","negate","nullify","rescind","squelch","stultify","suppress"]},{"w":"quibble","p":"v.","m":"To argue about trivial matters.","e":"Probably from Latin <i>quibus</i> (to whom), legal jargon pun.","f":"chicaner, ergoter","t":"Quibble = ergoter. Don't quibble over details.","h":["Quib: petty point. Quibble over pennies.","Quibble: nitpick."],"s":["equivocate","hedge","prevaricate"]},{"w":"ravage","p":"v.","m":"To cause severe damage to.","e":"Old French <i>ravir</i> (to seize).","f":"ravager, dévaster","t":"Same as « ravager ».","h":["Ravir: seize. Floods ravage towns.","Ravage: devastate."],"s":["decimation"]},{"w":"remuneration","p":"n.","m":"Payment for work done.","e":"Latin <i>remunerari</i> (to reward).","f":"rémunération","t":"Same as « rémunération ».","h":["Re + munus: gift back. Fair remuneration.","Remuneration: pay."],"s":["stipend"]},{"w":"repugnant","p":"adj.","m":"Extremely distasteful; unacceptable.","e":"Latin <i>repugnare</i> (to fight against).","f":"répugnant, repoussant","t":"Same as « répugnant ».","h":["Re + pugnare: fight back. Repugnant smell.","Repugnant: revolting."],"s":["execrable","odious"]},{"w":"sadistic","p":"adj.","m":"Deriving pleasure from inflicting pain.","e":"From the Marquis de <i>Sade</i>.","f":"sadique","t":"Same as « sadique » — named for the French marquis.","h":["Marquis de Sade. Sadistic glee.","Sadistic: pleasure in pain."],"s":[]},{"w":"shrill","p":"adj.","m":"High-pitched and piercing.","e":"Middle English <i>shrille</i>, imitative.","f":"strident, perçant","t":"Hear the shriek: « strident ».","h":["Shrill: piercing. A shrill whistle.","Shrill: high and harsh."],"s":[]},{"w":"slovenly","p":"adj.","m":"Untidy and dirty; careless.","e":"Possibly Flemish <i>sloef</i> (dirty).","f":"négligé, débraillé","t":"Un « souillon ». A slovenly appearance.","h":["Sloven: untidy. Slovenly dress.","Slovenly: messy."],"s":[]},{"w":"soliloquy","p":"n.","m":"An act of speaking one's thoughts aloud when alone.","e":"Latin <i>solus</i> (alone) + <i>loqui</i> (to speak).","f":"monologue, soliloque","t":"Hamlet’s « To be or not to be ».","h":["Solus + loqui: speak alone. Hamlet’s soliloquy.","Soliloquy: speech to self."],"s":[]},{"w":"sophistry","p":"n.","m":"The use of clever but misleading arguments.","e":"Greek <i>sophistēs</i> (a clever person).","f":"sophisme, argutie","t":"Same as « sophisme »: clever but misleading.","h":["Sophistes: clever one. Pure sophistry.","Sophistry: slick false logic."],"s":[]},{"w":"swindle","p":"v.","m":"To use deception to deprive of money or possessions.","e":"German <i>schwindeln</i> (to be dizzy, to cheat).","f":"escroquer, arnaquer","t":"Swindler: « escroc ».","h":["Schwindeln: cheat. Swindle the elderly.","Swindle: defraud."],"s":["bilk","fleece","hoodwink","mulct"]},{"w":"tangible","p":"adj.","m":"Perceptible by touch; real and concrete.","e":"Latin <i>tangere</i> (to touch).","f":"tangible, palpable","t":"Same as « tangible ».","h":["Tangere: touch. Tangible results.","Tangible: concrete."],"s":["corporeal","manifest","palpable"]},{"w":"unalloyed","p":"adj.","m":"Complete; not mixed with anything.","e":"<i>un-</i> + <i>alloy</i> (metal mix), Old French <i>aloyer</i>.","f":"pur, sans mélange","t":"« Alliage »: no alloy. Unalloyed joy = joie pure.","h":["Not alloyed. Unalloyed joy.","Unalloyed: pure."],"s":[]},{"w":"undercut","p":"v.","m":"To weaken; to offer lower prices than a competitor.","e":"<i>under</i> + <i>cut</i>. Germanic.","f":"saper, mettre à mal; casser les prix","t":"Cut from beneath: it « sape » the argument.","h":["Under + cut. Undercut rivals.","Undercut: undermine."],"s":["undermine"]},{"w":"verve","p":"n.","m":"Vigour, spirit and style in writing or performance.","e":"French <i>verve</i> (enthusiasm).","f":"verve","t":"Same as « verve ».","h":["Verve: vigour. Played with verve.","Verve: zest."],"s":["panache","vitality"]},{"w":"wheedle","p":"v.","m":"To persuade by flattery or coaxing.","e":"Possibly German <i>wedeln</i> (to wag the tail, fawn).","f":"enjôler, cajoler","t":"A dog wagging its tail: wheedle a treat out of you.","h":["Wheedle: coax. Wheedle a treat.","Wheedle: coax by flattery."],"s":["cajole","entice","inveigle"]},{"w":"wily","p":"adj.","m":"Skilled at gaining an advantage by deceit.","e":"From <i>wile</i> (trick), Old French <i>guile</i>.","f":"rusé, malicieux","t":"Wile E. Coyote. « Rusé ».","h":["Wile: trick. A wily fox.","Wily: crafty."],"s":["artful","crafty","cunning","devious","ingenious","shrewd"]},{"w":"xenophobic","p":"adj.","m":"Having a fear or dislike of strangers or foreigners.","e":"Greek <i>xenos</i> (stranger) + <i>phobos</i> (fear).","f":"xénophobe","t":"Same as « xénophobe ».","h":["Xenos: stranger + phobos. Xenophobic rhetoric.","Xenophobic: foreigner-fearing."],"s":["chauvinistic","insular"]}]},{"name":"GregMat VII","slug":"gregmat-vii","series":"GregMat","words":[{"w":"abrasive","p":"adj.","m":"Harsh and rough in manner; capable of scraping.","e":"Latin <i>abradere</i> (to scrape away).","f":"abrasif, rugueux, cassant","t":"Same as « abrasif »: an abrasive personality grates.","h":["Ab + radere: scrape. An abrasive boss.","Abrasive: grating."],"s":[]},{"w":"allegorical","p":"adj.","m":"Having a hidden meaning, typically moral or political.","e":"Greek <i>allēgoria</i>: <i>allos</i> (other) + <i>agoreuein</i> (to speak).","f":"allégorique","t":"Same as « allégorique »: speaks of another thing.","h":["Allos + agoreuein: speak otherwise. An allegorical tale.","Allegorical: symbolic."],"s":["figurative","metaphorical"]},{"w":"allude","p":"v.","m":"To suggest or call attention to indirectly.","e":"Latin <i>alludere</i> (to play with).","f":"faire allusion à","t":"Same as « faire allusion ».","h":["Ad + ludere: play at. Allude to a scandal.","Allude: hint."],"s":["intimate"]},{"w":"amplify","p":"v.","m":"To increase in volume or effect.","e":"Latin <i>amplificare</i>, from <i>amplus</i> (large).","f":"amplifier","t":"Same as « amplifier ».","h":["Amplus: large. Amplify the sound.","Amplify: magnify."],"s":["augment","escalate"]},{"w":"auxiliary","p":"adj.","m":"Providing supplementary support.","e":"Latin <i>auxiliarius</i>, from <i>auxilium</i> (help).","f":"auxiliaire","t":"Same as « auxiliaire ».","h":["Auxilium: help. Auxiliary power.","Auxiliary: backup."],"s":[]},{"w":"brevity","p":"n.","m":"Concise and exact use of words.","e":"Latin <i>brevis</i> (short).","f":"brièveté","t":"Same as « brièveté ».","h":["Brevis: short. Brevity is wit.","Brevity: conciseness."],"s":[]},{"w":"caricature","p":"n.","m":"A grotesque exaggeration of a person's features.","e":"Italian <i>caricatura</i> (loading), from <i>caricare</i>.","f":"caricature","t":"Same as « caricature ».","h":["Caricare: load. A cruel caricature.","Caricature: exaggerated portrait."],"s":["deride","lampoon","satirize","sham","travesty"]},{"w":"catastrophic","p":"adj.","m":"Involving sudden great damage or suffering.","e":"Greek <i>katastrophē</i> (overturning).","f":"catastrophique","t":"Same as « catastrophique ».","h":["Kata + strephein: overturn. Catastrophic failure.","Catastrophic: calamitous."],"s":["calamitous","cataclysmic"]},{"w":"circumstantial","p":"adj.","m":"Pointing indirectly to a conclusion; based on circumstances.","e":"Latin <i>circumstare</i> (to stand around).","f":"circonstanciel; indirect","t":"Circumstantial evidence = preuves indirectes.","h":["Circum + stare. Circumstantial evidence.","Circumstantial: indirect."],"s":["oblique"]},{"w":"coddle","p":"v.","m":"To treat in an indulgent or overprotective way.","e":"Possibly from <i>caudle</i>, a warm drink for invalids; Latin <i>calidus</i> (warm).","f":"dorloter, chouchouter","t":"« Dorloter »: coddle a child.","h":["Caudle: warm drink for invalids. Coddle the kids.","Coddle: pamper."],"s":["cosset"]},{"w":"contemporary","p":"adj.","m":"Living or occurring at the same time; modern.","e":"Latin <i>con-</i> + <i>tempus</i> (time).","f":"contemporain; actuel","t":"Same as « contemporain ».","h":["Con + tempus. Contemporary art.","Contemporary: of the same time."],"s":[]},{"w":"counterfeit","p":"adj.","m":"Made in exact imitation to deceive; forged.","e":"Old French <i>contrefait</i>.","f":"contrefait, faux","t":"Same as « contrefaçon » / « contrefait »: counterfeit money = fausse monnaie.","h":["Contre + faire. Counterfeit cash.","Counterfeit: forged."],"s":["bogus","ersatz","fallacious","phony","sham","specious","spurious"]},{"w":"crescendo","p":"n.","m":"A gradual increase in loudness or intensity.","e":"Italian <i>crescendo</i>, from Latin <i>crescere</i> (to grow).","f":"crescendo","t":"Same as « crescendo ».","h":["Crescere: grow. A rising crescendo.","Crescendo: building volume."],"s":[]},{"w":"defame","p":"v.","m":"To damage the good reputation of.","e":"Latin <i>diffamare</i> (to spread evil report): <i>dis-</i> + <i>fama</i>.","f":"diffamer","t":"Same as « diffamer ».","h":["De + fama: undo repute. Defame a rival.","Defame: slander."],"s":["belittle","besmirch","debunk","denigrate","deprecate","discredit","disparage","malign","slander","vilify","vituperate"]},{"w":"depravity","p":"n.","m":"Moral corruption.","e":"Latin <i>depravare</i> (to make crooked).","f":"dépravation, perversion","t":"Same as « dépravation ».","h":["De + pravus: crooked. Sheer depravity.","Depravity: wickedness."],"s":["turpitude"]},{"w":"detract","p":"v.","m":"To diminish the value of.","e":"Latin <i>detrahere</i> (to draw away).","f":"enlever de la valeur, rabaisser","t":"Detractors drag you down. « Détracteur ».","h":["De + trahere: draw away. Detract from the glory.","Detract: diminish."],"s":["belittle"]},{"w":"devious","p":"adj.","m":"Showing a skilful use of underhand tactics; roundabout.","e":"Latin <i>devius</i> (off the road): <i>de-</i> + <i>via</i>.","f":"retors, tortueux","t":"Off the road: a « chemin détourné ».","h":["De + via: off the road. A devious plan.","Devious: sneaky."],"s":["artful","crafty","cunning","oblique","tortuous","wily"]},{"w":"disciple","p":"n.","m":"A follower of a teacher, leader or philosophy.","e":"Latin <i>discipulus</i> (learner), from <i>discere</i>.","f":"disciple","t":"Same as « disciple ».","h":["Discipulus: learner. A loyal disciple.","Disciple: follower."],"s":["acolyte"]},{"w":"dormant","p":"adj.","m":"Temporarily inactive; asleep.","e":"Latin <i>dormire</i> (to sleep).","f":"en sommeil, dormant","t":"Same as « dormant » (volcan dormant).","h":["Dormire: sleep. A dormant volcano.","Dormant: asleep."],"s":["fallow","inert","quiescent"]},{"w":"draconian","p":"adj.","m":"Excessively harsh and severe (of laws).","e":"From <i>Draco</i>, Athenian lawgiver (7th c. BC).","f":"draconien","t":"Same as « draconien ».","h":["Draco’s harsh laws. Draconian rules.","Draconian: brutally strict."],"s":["stringent"]},{"w":"encroach","p":"v.","m":"To intrude on a territory or right.","e":"Old French <i>encrochier</i> (to seize), from <i>croc</i> (hook).","f":"empiéter sur","t":"« Empiéter »: use a hook to grab. Encroach on one's rights.","h":["En + croc: hook. Encroach on land.","Encroach: intrude."],"s":[]},{"w":"endow","p":"v.","m":"To provide with a quality or a source of income.","e":"Old French <i>endouer</i>, Latin <i>dotare</i> (to give a dowry).","f":"doter","t":"Same as « doter »: un don, a dot. Endowed with talent = doté.","h":["En + dower. Endowed with talent.","Endow: bestow."],"s":[]},{"w":"entreat","p":"v.","m":"To ask earnestly or anxiously.","e":"Old French <i>entraiter</i> (to treat), from <i>traiter</i>.","f":"supplier, implorer","t":"« Supplier ». Entreat him to stay.","h":["En + treat. Entreat him to stay.","Entreat: beg."],"s":["beg","implore","importune","supplicate"]},{"w":"erstwhile","p":"adj.","m":"Former.","e":"Old English <i>ǣrest</i> (earliest) + <i>while</i>. Germanic.","f":"ancien, d'autrefois","t":"« Jadis »: his erstwhile friend.","h":["Erst: first + while. My erstwhile friend.","Erstwhile: former."],"s":["onetime"]},{"w":"extol","p":"v.","m":"To praise enthusiastically.","e":"Latin <i>extollere</i> (to raise up).","f":"louer, exalter","t":"Raise up with praise. Cousin of « exalter ».","h":["Ex + tollere: lift up. Extol virtues.","Extol: praise."],"s":["acclaim","exalt","hail","laud","lionize"]},{"w":"forebode","p":"v.","m":"To predict or have a presentiment of evil.","e":"<i>fore-</i> + <i>bode</i> (Old English <i>bodian</i>, announce). Germanic.","f":"présager, pressentir","t":"A bad omen: « pressentir » le pire. Foreboding.","h":["Fore + bode. Forebode disaster.","Forebode: portend evil."],"s":["portend","prefigure","presage"]},{"w":"fringe","p":"n.","m":"The outer edge; a minority group beyond the mainstream.","e":"Old French <i>frenge</i>, Latin <i>fimbria</i> (fibre, fringe).","f":"frange, marge","t":"« Frange »: the fringe of society = en marge.","h":["Fimbria: edge. Fringe groups.","Fringe: outer edge."],"s":[]},{"w":"gloat","p":"v.","m":"To dwell on one's own success or another's misfortune with smugness.","e":"Possibly Scandinavian <i>glotta</i> (to grin).","f":"jubiler, se réjouir mesquinement","t":"« Jubiler » méchamment. Don't gloat.","h":["Gloat: gaze. Gloat over a win.","Gloat: smug rejoicing."],"s":["relish"]},{"w":"harrowing","p":"adj.","m":"Acutely distressing.","e":"From <i>harrow</i> (a farm tool tearing up soil). Germanic.","f":"éprouvant, déchirant","t":"Like a rake tearing at the earth: « déchirant ».","h":["Harrow: rake. A harrowing ordeal.","Harrowing: agonizing."],"s":["excruciating"]},{"w":"ideologue","p":"n.","m":"An adherent of an ideology, especially a dogmatic one.","e":"French <i>idéologue</i>, from Greek <i>idea</i> + <i>-logos</i>.","f":"idéologue","t":"Same as « idéologue ».","h":["Idea + logos. A party ideologue.","Ideologue: dogmatist."],"s":[]},{"w":"immaculate","p":"adj.","m":"Perfectly clean, neat or tidy; free from flaws.","e":"Latin <i>immaculatus</i>: <i>in-</i> + <i>macula</i> (spot).","f":"immaculé, impeccable","t":"« L'Immaculée Conception »: no spot.","h":["In + macula: no spot. An immaculate kitchen.","Immaculate: spotless."],"s":["impeccable","inviolate","pristine"]},{"w":"impediment","p":"n.","m":"A hindrance or obstruction.","e":"Latin <i>impedimentum</i>, from <i>impedire</i> (to shackle the feet).","f":"obstacle, empêchement","t":"Feet bound (pes, pedis). Speech impediment = défaut d'élocution.","h":["In + pes: foot-bound. A speech impediment.","Impediment: obstacle."],"s":["check","curb","deterrent"]},{"w":"imperative","p":"adj.","m":"Of vital importance; compulsory.","e":"Latin <i>imperativus</i>, from <i>imperare</i> (to command).","f":"impératif, indispensable","t":"Same as « impératif ».","h":["Imperare: command. It is imperative.","Imperative: essential."],"s":["exacting","exigent","indispensable"]},{"w":"impulsive","p":"adj.","m":"Acting without forethought.","e":"Latin <i>impulsivus</i>, from <i>impellere</i> (to push).","f":"impulsif","t":"Same as « impulsif ».","h":["Impellere: drive on. Impulsive purchase.","Impulsive: rash."],"s":["capricious","foolhardy","impetuous","precipitate","rash"]},{"w":"indefinite","p":"adj.","m":"Lasting for an unspecified time; vague.","e":"Latin <i>indefinitus</i>: <i>in-</i> + <i>definire</i>.","f":"indéfini, indéterminé","t":"Same as « indéfini »: an indefinite strike (grève illimitée).","h":["Not definite. Indefinite delay.","Indefinite: unspecified."],"s":["indeterminate"]},{"w":"indictment","p":"n.","m":"A formal charge; a sign that something is bad.","e":"Anglo-French <i>enditement</i>, Latin <i>indictare</i>.","f":"mise en accusation; réquisitoire","x":"2nd meaning","t":"Figurative: a damning indictment of the system = un réquisitoire.","h":["In + dicere: declare. A damning indictment.","Indictment: charge."],"s":[]},{"w":"ingenious","p":"adj.","m":"Clever, original and inventive.","e":"Latin <i>ingeniosus</i>, from <i>ingenium</i> (talent).","f":"ingénieux","t":"Same as « ingénieux »; not ingenuous (naïve).","h":["Ingenium: talent. An ingenious device.","Ingenious: inventive."],"s":["artful","crafty","cunning","resourceful","shrewd","wily"]},{"w":"inquisitive","p":"adj.","m":"Curious, prying, asking too many questions.","e":"Latin <i>inquirere</i> (to seek into).","f":"curieux, indiscret","t":"« Inquisitif » is rare: use « curieux ».","h":["In + quaerere: seek. An inquisitive child.","Inquisitive: nosy."],"s":[]},{"w":"interminable","p":"adj.","m":"Endless (often tediously).","e":"Latin <i>interminabilis</i>: <i>in-</i> + <i>terminare</i>.","f":"interminable","t":"Same as « interminable ».","h":["Not terminable. An interminable talk.","Interminable: endless."],"s":["incessant"]},{"w":"intuitive","p":"adj.","m":"Using instinct rather than conscious reasoning.","e":"Latin <i>intueri</i> (to look at).","f":"intuitif","t":"Same as « intuitif ».","h":["Intueri: look at. Intuitive design.","Intuitive: instinctive."],"s":[]},{"w":"keen","p":"adj.","m":"Eager; sharp (of senses or edges).","e":"Old English <i>cēne</i> (bold, brave). Germanic.","f":"enthousiaste, vif, aiguisé","t":"Keen on = passionné par. Keen eyesight = vue perçante.","h":["Cene: bold. Keen eyes.","Keen: eager or sharp."],"s":["acerbic","ardent","astute","avid","fervent","fervid","incisive","penetrating","perspicacious","shrewd","trenchant","zealous"]},{"w":"latitude","p":"n.","m":"Scope for freedom of action or thought.","e":"Latin <i>latitudo</i>, from <i>latus</i> (wide).","f":"latitude, liberté d'action","t":"Same as « latitude »: a wide berth. Latitude to decide.","h":["Latus: wide. Freedom and latitude.","Latitude: leeway."],"s":["discretion"]},{"w":"mediate","p":"v.","m":"To intervene between disputing parties.","e":"Latin <i>mediare</i> (to be in the middle).","f":"servir de médiateur, arbitrer","t":"Same as « médiation ».","h":["Medius: middle. Mediate the dispute.","Mediate: arbitrate."],"s":[]},{"w":"multifaceted","p":"adj.","m":"Having many aspects.","e":"<i>multi-</i> (many) + <i>facet</i>, French <i>facette</i>.","f":"à multiples facettes, complexe","t":"« Multi-facettes ». A multifaceted issue.","h":["Multi + facet. A multifaceted problem.","Multifaceted: many-sided."],"s":["protean","resourceful","versatile"]},{"w":"omit","p":"v.","m":"To leave out or exclude.","e":"Latin <i>omittere</i> (to let go).","f":"omettre","t":"Same as « omettre ».","h":["Ob + mittere: let go. Omit the footnote.","Omit: leave out."],"s":[]},{"w":"omniscient","p":"adj.","m":"Knowing everything.","e":"Latin <i>omnis</i> (all) + <i>scire</i> (to know).","f":"omniscient","t":"Same as « omniscient ».","h":["Omni + scire. An omniscient narrator.","Omniscient: all-knowing."],"s":[]},{"w":"pacify","p":"v.","m":"To quell the anger of; to bring peace to.","e":"Latin <i>pacificare</i>: <i>pax</i> (peace) + <i>facere</i>.","f":"apaiser, pacifier","t":"Same as « pacifier ».","h":["Pax + facere. Pacify the baby.","Pacify: calm."],"s":["appease","assuage","conciliate","lull","mollify","placate","propitiate","reconcile"]},{"w":"paltry","p":"adj.","m":"Ridiculously small or unimportant.","e":"Dialect <i>palt</i> (rubbish), Low German <i>paltrig</i> (ragged).","f":"dérisoire, piètre","t":"A paltry sum = une somme dérisoire.","h":["Palt: rag. A paltry sum.","Paltry: trivial."],"s":["immaterial","inconsequential","negligible","picayune","scant","sparse","trifling","trivial"]},{"w":"prefigure","p":"v.","m":"To be an early indication of.","e":"Latin <i>praefigurare</i>: <i>prae-</i> + <i>figurare</i>.","f":"préfigurer","t":"Same as « préfigurer ».","h":["Pre + figure. Prefigure a trend.","Prefigure: foreshadow."],"s":["forebode","portend","presage"]},{"w":"presage","p":"v.","m":"To be a sign or warning of a future event.","e":"Latin <i>praesagium</i>, from <i>praesagire</i> (to perceive beforehand).","f":"présager, annoncer","t":"Same as « présage / présager ».","h":["Prae + sagire: sense before. Presage a storm.","Presage: foretell."],"s":["forebode","portend","prefigure"]},{"w":"prescribe","p":"v.","m":"To recommend with authority; to order a medicine.","e":"Latin <i>praescribere</i> (to write before).","f":"prescrire","t":"Same as « prescrire ».","h":["Pre + scribere: write before. Prescribe rest.","Prescribe: order."],"s":["dictate"]},{"w":"rampant","p":"adj.","m":"Flourishing or spreading unchecked.","e":"Old French <i>ramper</i> (to climb, rear up).","f":"endémique, déchaîné","t":"A lion rampant (heraldry) rears up. Rampant corruption spreads wildly.","h":["Ramper: climb. Rampant crime.","Rampant: unchecked."],"s":["endemic","indigenous","omnipresent","pervasive","ubiquitous","universal"]},{"w":"recluse","p":"n.","m":"A person who lives alone and avoids society.","e":"Latin <i>recludere</i> (to shut away).","f":"reclus, ermite","t":"Same as « reclus ».","h":["Re + claudere: shut away. A famous recluse.","Recluse: hermit."],"s":[]},{"w":"remarkable","p":"adj.","m":"Worthy of attention; extraordinary.","e":"French <i>remarquable</i>, from <i>remarquer</i>.","f":"remarquable","t":"Same as « remarquable ».","h":["Re + mark. A remarkable feat.","Remarkable: striking."],"s":["sensational"]},{"w":"remote","p":"adj.","m":"Far away; slight (of chances).","e":"Latin <i>remotus</i>, from <i>removere</i>.","f":"éloigné, lointain; faible","x":"2nd meaning","t":"Remote chance = faible chance. Distant too.","h":["Re + movere: moved away. A remote chance.","Remote: far or slim."],"s":["aloof","slight"]},{"w":"retaliate","p":"v.","m":"To make an attack in return for a similar attack.","e":"Latin <i>retaliare</i>, from <i>talio</i> (like for like).","f":"riposter, user de représailles","t":"« Loi du talion » (an eye for an eye): talio.","h":["Re + talio: like for like. Retaliate with tariffs.","Retaliate: strike back."],"s":["requite"]},{"w":"rhapsody","p":"n.","m":"An effusive expression of enthusiasm; a free musical work.","e":"Greek <i>rhapsōidia</i>: <i>rhaptein</i> (to stitch) + <i>ōidē</i> (song).","f":"rhapsodie","t":"Same as « rhapsodie »: Bohemian Rhapsody. Wax rhapsodic = s'extasier.","h":["Rhapsodia: stitched song. Rhapsody in Blue.","Rhapsody: gushing piece."],"s":["euphoria","panegyric"]},{"w":"serendipitous","p":"adj.","m":"Occurring by happy chance.","e":"Coined by Horace Walpole from <i>The Three Princes of Serendip</i> (Sri Lanka).","f":"dû à un heureux hasard","t":"« Heureux hasard ». Penicillin was serendipitous.","h":["Three Princes of Serendip. A serendipitous find.","Serendipitous: happily accidental."],"s":["adventitious","fortuitous","providential"]},{"w":"shirk","p":"v.","m":"To avoid or neglect (a duty).","e":"Probably German <i>Schurke</i> (scoundrel).","f":"se dérober à, éviter","t":"« Se défiler ». Shirk responsibility.","h":["Schurke: rogue. Shirk duty.","Shirk: dodge."],"s":["evade","feign","malinger"]},{"w":"sinuous","p":"adj.","m":"Having many curves and turns.","e":"Latin <i>sinuosus</i>, from <i>sinus</i> (curve).","f":"sinueux","t":"Same as « sinueux ».","h":["Sinus: curve. A sinuous river.","Sinuous: winding."],"s":["byzantine","convoluted","tortuous"]},{"w":"sober","p":"adj.","m":"Not drunk; serious and sensible.","e":"Latin <i>sobrius</i> (not drunk).","f":"sobre; sérieux","t":"Same as « sobre »: a sober assessment = réaliste.","h":["Sobrius: not drunk. A sober view.","Sober: sensible."],"s":["demure","staid"]},{"w":"stanch","p":"v.","m":"To stop or restrict a flow (especially of blood).","e":"Old French <i>estanchier</i> (to stop).","f":"étancher, arrêter","t":"Same as « étancher ». Stanch the bleeding.","h":["Estanchier: stop. Stanch the wound.","Stanch: stop flow."],"s":["check","curb","inhibit","staunch","stem"]},{"w":"stem from","p":"phr.","m":"To originate in or be caused by.","e":"Old English <i>stefn</i> (stem, trunk). Germanic.","f":"découler de, provenir de","t":"A plant's stem: where it all comes from. Stem from = « découler de ».","h":["Stem of a plant. Stems from fear.","Stem from: originate in."],"s":[]},{"w":"subdued","p":"adj.","m":"Quiet and rather reflective; reduced in intensity.","e":"Latin <i>subdere</i> (to place under).","f":"discret, atténué, réprimé","t":"Subdued light = lumière tamisée. A subdued crowd is quiet.","h":["Subdere: subdue. A subdued mood.","Subdued: muted."],"s":["muted","understated"]},{"w":"token","p":"adj.","m":"Done for the sake of appearances; symbolic.","e":"Old English <i>tācen</i> (sign). Germanic.","f":"symbolique, de pure forme","x":"2nd meaning","t":"A token gesture = un geste symbolique, « pour la forme ».","h":["Token: sign. A token gesture.","Token: symbolic."],"s":["cursory","desultory","nominal","perfunctory","superficial"]},{"w":"turbid","p":"adj.","m":"Cloudy, opaque or thick with suspended matter; confused.","e":"Latin <i>turbidus</i>, from <i>turba</i> (disturbance).","f":"trouble, boueux","t":"« Trouble » water: turbid. Turbid emotions.","h":["Turba: disturbance. Turbid water.","Turbid: muddy."],"s":["impenetrable","obscure","opaque"]},{"w":"ulterior","p":"adj.","m":"Existing beyond what is obvious; hidden (of motives).","e":"Latin <i>ulterior</i> (farther), from <i>ultra</i>.","f":"ultérieur; caché","x":"Faux ami","t":"« Ultérieur » = later in time. English ulterior = hidden: an ulterior motive = arrière-pensée.","h":["Ulterior: beyond. Ulterior motive.","Ulterior: hidden."],"s":["clandestine","covert","furtive","surreptitious"]},{"w":"unravel","p":"v.","m":"To undo twisted or knitted threads; to solve a mystery.","e":"<i>un-</i> + Dutch <i>ravelen</i> (to tangle).","f":"démêler, défaire, élucider","t":"Un-tangle: démêler. A plot unravels.","h":["Un + ravel. The plot unravels.","Unravel: come apart."],"s":["construe","decipher","disentangle","resolve"]},{"w":"withstand","p":"v.","m":"To remain undamaged or unaffected by.","e":"Old English <i>withstandan</i> (stand against). Germanic.","f":"résister à, supporter","t":"With = against: stand against. Withstand pressure = résister.","h":["With: against + stand. Withstand a siege.","Withstand: resist."],"s":["buck"]}]},{"name":"GregMat VIII","slug":"gregmat-viii","series":"GregMat","words":[{"w":"accord","p":"v.","m":"To give or grant; to be consistent with.","e":"Old French <i>acorder</i>, Latin <i>ad cor</i> (to the heart).","f":"accorder; concorder","t":"Same as « accorder / être en accord ».","h":["Ad + cor: heart to heart. Accord with facts.","Accord: grant or agree."],"s":["dovetail"]},{"w":"ad hoc","p":"adj.","m":"Created for a particular purpose only.","e":"Latin <i>ad hoc</i> (for this).","f":"ad hoc, improvisé","t":"Same as « ad hoc ».","h":["Latin: for this. An ad hoc panel.","Ad hoc: made for the purpose."],"s":[]},{"w":"all-ecompassing","p":"adj.","m":"Including everything; comprehensive. (Standard spelling: all-encompassing.)","e":"<i>all</i> + <i>encompass</i> (<i>en-</i> + <i>compass</i>, Latin <i>compassare</i>).","f":"global, exhaustif","x":"Spelling","t":"GregMat’s spelling has a typo: the correct form is all-encompassing. « Qui englobe tout ».","h":["All + encompass. An all-encompassing plan.","All-encompassing: total."],"s":["encyclopedic","exhaustive","thorough","thoroughgoing"]},{"w":"attribute","p":"v.","m":"To regard something as belonging to or caused by.","e":"Latin <i>attribuere</i> (to assign).","f":"attribuer","t":"Same as « attribuer ».","h":["Ad + tribuere: assign to. Attribute success to luck.","Attribute: ascribe."],"s":["ascribe","impute"]},{"w":"beholden","p":"adj.","m":"Owing thanks or having a duty to someone.","e":"Old English <i>behealdan</i> (to hold, observe); past participle of <i>behold</i>.","f":"redevable","t":"« Redevable » to someone. Beholden to donors.","h":["Be + hold. Beholden to donors.","Beholden: indebted."],"s":[]},{"w":"benchmark","p":"n.","m":"A standard against which things can be measured.","e":"From a surveyor’s <i>bench mark</i> cut in stone.","f":"référence, étalon","t":"Same in French business jargon: « un benchmark ».","h":["Bench mark: survey point. Set a benchmark.","Benchmark: standard."],"s":[]},{"w":"blighted","p":"adj.","m":"Spoiled or ruined; stricken by disease (plants).","e":"<i>blight</i> (plant disease), origin unknown.","f":"gâché, ravagé","t":"A blight: la rouille. Blighted hopes.","h":["Blight: plant disease. Blighted crops.","Blighted: ruined."],"s":[]},{"w":"calamitous","p":"adj.","m":"Causing great damage.","e":"Latin <i>calamitas</i> (disaster).","f":"désastreux, calamiteux","t":"Same as « calamiteux ».","h":["Calamitas: disaster. A calamitous year.","Calamitous: disastrous."],"s":["cataclysmic","catastrophic"]},{"w":"cluster","p":"n.","m":"A group of similar things close together.","e":"Old English <i>clyster</i>. Germanic.","f":"grappe, groupe","t":"Un « amas ». A cluster of stars.","h":["Cluster: clump. A star cluster.","Cluster: tight group."],"s":[]},{"w":"coherent","p":"adj.","m":"Logical and consistent; clear.","e":"Latin <i>cohaerere</i> (to stick together).","f":"cohérent","t":"Same as « cohérent ».","h":["Co + haerere: stick together. A coherent essay.","Coherent: logical."],"s":["articulate","cogent","intelligible","limpid","lucid","pellucid"]},{"w":"contemplate","p":"v.","m":"To think deeply; to consider as a possibility.","e":"Latin <i>contemplari</i> (to observe), <i>templum</i> (a space for observing).","f":"contempler; envisager","x":"2nd meaning","t":"« Contempler » a view, but also envisager: contemplate resigning.","h":["Templum: sacred space. Contemplate the view.","Contemplate: ponder."],"s":["cogitate","deliberate","reflect","ruminate"]},{"w":"content","p":"adj.","m":"In a state of peaceful happiness; satisfied. (Stress: conTENT.)","e":"Latin <i>contentus</i> (satisfied), from <i>continere</i>.","f":"content, satisfait","x":"2nd meaning","t":"Same as « content ». Two words: CONtent (the substance) vs conTENT (satisfied).","h":["Contentus: held together. Content with life.","Content: satisfied."],"s":[]},{"w":"crafty","p":"adj.","m":"Clever at achieving aims by deceit.","e":"Old English <i>cræftig</i>, from <i>cræft</i> (skill).","f":"rusé, astucieux","t":"Craft = skill, and slyness. A crafty fox.","h":["Craft: skill. A crafty ploy.","Crafty: sly."],"s":["artful","cunning","devious","ingenious","shrewd","wily"]},{"w":"dexterous","p":"adj.","m":"Showing skill with hands or mind.","e":"Latin <i>dexter</i> (right-handed, skilful).","f":"adroit, habile","t":"Dexter = right. Cousin of « dextérité ».","h":["Dexter: right-handed. Dexterous fingers.","Dexterous: deft."],"s":["adept","adroit","deft","nimble","proficient"]},{"w":"dictum","p":"n.","m":"A formal pronouncement; a short statement of principle.","e":"Latin <i>dictum</i> (something said).","f":"maxime, sentence","t":"Same as « dicton ». Dictum = a said thing.","h":["Dicere: say. A legal dictum.","Dictum: pronouncement."],"s":["aphorism","apothegm","epigram","maxim"]},{"w":"disconcerting","p":"adj.","m":"Causing unease or confusion.","e":"French <i>disconcerter</i>.","f":"déconcertant","t":"Same as « déconcertant ».","h":["Dis + concert. Disconcerting news.","Disconcerting: unsettling."],"s":[]},{"w":"dismantle","p":"v.","m":"To take apart; to abolish gradually.","e":"Old French <i>desmanteler</i> (to strip off a cloak).","f":"démanteler, démonter","t":"Same as « démanteler »: take off the mantle.","h":["Dis + mantle. Dismantle the engine.","Dismantle: take apart."],"s":[]},{"w":"dutiful","p":"adj.","m":"Conscientiously obedient.","e":"<i>duty</i> + <i>-ful</i>.","f":"respectueux, obéissant","t":"Full of duty (devoir): a dutiful son.","h":["Duty-full. A dutiful son.","Dutiful: obedient."],"s":["deferential","obsequious","reverent"]},{"w":"ensue","p":"v.","m":"To happen afterwards, as a result.","e":"Old French <i>ensuivre</i>: <i>en-</i> + <i>suivre</i> (to follow).","f":"s'ensuivre, résulter","t":"Same as « s'ensuivre ».","h":["In + sequi: follow. Chaos ensued.","Ensue: follow."],"s":[]},{"w":"facility","p":"n.","m":"A natural ease; a place or equipment for an activity.","e":"Latin <i>facilitas</i>, from <i>facilis</i> (easy).","f":"aisance, facilité; installation","x":"2nd meaning","t":"Facility for languages = facilité. But a research facility = une installation.","h":["Facilis: easy. A facility for maths; a new facility.","Facility: ease or site."],"s":[]},{"w":"fathom","p":"v.","m":"To understand after much thought.","e":"Old English <i>fæthm</i> (outstretched arms), a unit of depth.","f":"comprendre, sonder","t":"Sound the depth: « sonder ». I can’t fathom it.","h":["Faethm: outstretched arms, depth. Can’t fathom it.","Fathom: understand."],"s":[]},{"w":"fitful","p":"adj.","m":"Active only in short bursts; irregular.","e":"<i>fit</i> (a sudden attack), Old English <i>fitt</i> + <i>-ful</i>.","f":"intermittent, irrégulier","t":"Fits and starts: fitful sleep = sommeil agité.","h":["Fit: spasm. Fitful sleep.","Fitful: on and off."],"s":["capricious","desultory","discursive","erratic","fickle","haphazard","intermittent","mercurial","sporadic","wayward"]},{"w":"forgo","p":"v.","m":"To go without; to give up.","e":"Old English <i>forgān</i> (to pass over). Germanic.","f":"renoncer à, se passer de","x":"Look-alike","t":"Not « forego » (to precede). Forgo dessert = renoncer au dessert.","h":["For + go. Forgo dessert.","Forgo: do without."],"s":["abjure","abstain","avert","cede","dispense","eschew","forbear","relinquish","renounce"]},{"w":"frank","p":"adj.","m":"Open, honest and direct.","e":"Old French <i>franc</i> (free), from Frankish.","f":"franc","t":"Same as « franc »: Franc de port.","h":["Franc: free. A frank answer.","Frank: candid."],"s":["aboveboard","candid","forthright","unfeigned"]},{"w":"grumble","p":"v.","m":"To complain in a bad-tempered way.","e":"Dutch <i>grommelen</i>. Germanic.","f":"grogner, ronchonner","t":"Grommeler. Grumble about taxes.","h":["Grommeler. Grumble about work.","Grumble: mutter."],"s":[]},{"w":"hidebound","p":"adj.","m":"Unwilling to accept new ideas; rigidly conventional.","e":"<i>hide</i> (skin) + <i>bound</i>: cattle with tight skin.","f":"étroit d'esprit, borné","t":"Skin too tight: un esprit « borné ».","h":["Hide + bound. A hidebound bureaucracy.","Hidebound: narrow-minded."],"s":["blinkered","conventional","doctrinaire","dogmatic"]},{"w":"hypocrite","p":"n.","m":"A person who pretends to have virtues they do not possess.","e":"Greek <i>hypokritēs</i> (actor).","f":"hypocrite","t":"Same as « hypocrite »: an actor playing a role.","h":["Hypokrites: actor. A hypocrite preaches.","Hypocrite: pretender."],"s":["charlatan","phony"]},{"w":"impenetrable","p":"adj.","m":"Impossible to pass through or understand.","e":"Latin <i>impenetrabilis</i>.","f":"impénétrable","t":"Same as « impénétrable ».","h":["Not penetrable. Impenetrable fog.","Impenetrable: unfathomable."],"s":["callous","cryptic","enigmatic","impermeable","impervious","impregnable","inscrutable","inviolable","obscure","opaque","turbid","unassailable"]},{"w":"impolitic","p":"adj.","m":"Unwise; failing to take account of consequences.","e":"<i>im-</i> + <i>politic</i> (wise), Greek <i>politikos</i>.","f":"peu judicieux, malavisé","t":"Not rude: politic = prudent. An impolitic remark = une maladresse.","h":["Not politic. An impolitic joke.","Impolitic: unwise."],"s":["imprudent"]},{"w":"inalienable","p":"adj.","m":"Unable to be taken away from or given away.","e":"<i>in-</i> + <i>alien</i>, Latin <i>alienare</i>.","f":"inaliénable","t":"Same as « inaliénable »: les droits inaliénables.","h":["Not alienable. Inalienable rights.","Inalienable: can’t be removed."],"s":["intrinsic","inviolable","sacrosanct","unassailable"]},{"w":"incite","p":"v.","m":"To encourage or stir up (violence or hatred).","e":"Latin <i>incitare</i> (to urge on).","f":"inciter, provoquer","t":"Same as « inciter ».","h":["In + citare: stir. Incite a riot.","Incite: provoke."],"s":["agitate","exhort","foment","goad","induce"]},{"w":"induce","p":"v.","m":"To persuade; to bring about.","e":"Latin <i>inducere</i> (to lead in).","f":"inciter, provoquer, induire","t":"Same as « induire » (en erreur). Induce sleep = provoquer le sommeil.","h":["In + ducere: lead in. Induce labour.","Induce: bring about."],"s":["incite"]},{"w":"inept","p":"adj.","m":"Having no skill; clumsy.","e":"Latin <i>ineptus</i>: <i>in-</i> + <i>aptus</i> (suitable).","f":"inapte, incompétent","t":"Opposite of apt. An inept manager = « incapable ».","h":["In + aptus. An inept reply.","Inept: clumsy."],"s":["bumbling","feckless","gauche","gawky","improvident","maladroit"]},{"w":"infelicity","p":"n.","m":"An inappropriate remark or expression; unhappiness.","e":"Latin <i>infelicitas</i>: <i>in-</i> + <i>felix</i> (happy).","f":"impropriété, maladresse","t":"Opposite of felicity. An infelicity of style = formule malheureuse.","h":["In + felix. An infelicity of phrasing.","Infelicity: clumsy phrase."],"s":["gaffe","malapropism","solecism"]},{"w":"intelligible","p":"adj.","m":"Able to be understood.","e":"Latin <i>intelligibilis</i>, from <i>intellegere</i>.","f":"intelligible","t":"Same as « intelligible ».","h":["Inter + legere: choose between. Intelligible speech.","Intelligible: clear."],"s":["articulate","cogent","coherent","explicable","limpid","lucid","pellucid"]},{"w":"intermediary","p":"n.","m":"A person who acts as a link between parties.","e":"Latin <i>intermedius</i>.","f":"intermédiaire","t":"Same as « intermédiaire ».","h":["Inter + medius. Act as intermediary.","Intermediary: go-between."],"s":[]},{"w":"narcissism","p":"n.","m":"Excessive interest in oneself.","e":"Greek <i>Narkissos</i>, mythical youth in love with his reflection.","f":"narcissisme","t":"Same as « narcissisme ».","h":["Narcissus loved his reflection. Pure narcissism.","Narcissism: self-obsession."],"s":[]},{"w":"objurgation","p":"n.","m":"A harsh rebuke.","e":"Latin <i>objurgare</i> (to scold): <i>ob-</i> + <i>jurgare</i> (to quarrel).","f":"réprimande, objurgation","t":"Cousin of « objurguer » (rare in French). Think « injure »: a severe scolding.","h":["Ob + jurgare. Stern objurgation.","Objurgation: sharp rebuke."],"s":["rebuke"]},{"w":"onetime","p":"adj.","m":"Former.","e":"<i>one</i> + <i>time</i>. Germanic.","f":"ancien, d'autrefois","t":"A onetime champion = ancien champion.","h":["One + time. A onetime star.","Onetime: former."],"s":["erstwhile"]},{"w":"opportunistic","p":"adj.","m":"Exploiting circumstances for immediate advantage.","e":"Latin <i>opportunus</i> (favourable).","f":"opportuniste","t":"Same as « opportuniste ».","h":["Opportunity. Opportunistic hire.","Opportunistic: seizing chances."],"s":["expedient","exploitative","politic","pragmatic","unscrupulous"]},{"w":"passable","p":"adj.","m":"Acceptable but not outstanding; (of a road) able to be travelled.","e":"Old French <i>passer</i> (to pass).","f":"passable, acceptable","t":"Same as « passable » (just OK). A passable meal.","h":["Passer. A passable meal.","Passable: just okay."],"s":["palatable"]},{"w":"passive","p":"adj.","m":"Accepting what happens without active response.","e":"Latin <i>passivus</i>, from <i>pati</i> (to suffer).","f":"passif","t":"Same as « passif ».","h":["Pati: suffer. Passive resistance.","Passive: inactive."],"s":["docile","inert","lethargic","sluggish"]},{"w":"penetrating","p":"adj.","m":"Able to pass through; showing keen insight.","e":"Latin <i>penetrare</i>.","f":"pénétrant, perspicace","t":"Same as « pénétrant »: a penetrating question.","h":["Penetrare. A penetrating gaze.","Penetrating: piercing, insightful."],"s":["acerbic","astute","avid","incisive","keen","percipient","perspicacious","sagacious","shrewd","trenchant"]},{"w":"phony","p":"adj.","m":"Not genuine; fake.","e":"American slang, early 20th century, possibly from <i>fawney</i> (a gilt brass ring used in scams).","f":"faux, bidon","t":"Holden Caulfield: phoney. « Bidon ».","h":["Phoney: fake. A phony smile.","Phony: sham."],"s":["bogus","charlatan","counterfeit","ersatz","fallacious","hypocrite","sham","specious","spurious"]},{"w":"picturesque","p":"adj.","m":"Visually attractive, as in a painting.","e":"French <i>pittoresque</i>, Italian <i>pittoresco</i>.","f":"pittoresque","t":"Same as « pittoresque ».","h":["Pittoresco: like a picture. A picturesque village.","Picturesque: charming to see."],"s":[]},{"w":"plausible","p":"adj.","m":"Seeming reasonable or probable.","e":"Latin <i>plausibilis</i> (deserving applause).","f":"plausible, vraisemblable","t":"Same as « plausible ».","h":["Plaudere: applaud. A plausible story.","Plausible: believable."],"s":["credible","sound","specious","spurious","tenable","viable"]},{"w":"posturing","p":"n.","m":"Behaviour intended to impress or mislead.","e":"Latin <i>positura</i> (position).","f":"pose, affectation, grands airs","t":"Une « posture » (not neutral): political posturing = jeu de rôle.","h":["Posture. Political posturing.","Posturing: grandstanding."],"s":["affectation","bravado"]},{"w":"potent","p":"adj.","m":"Having great power or strong effect.","e":"Latin <i>potens</i>, from <i>posse</i> (to be able).","f":"puissant, efficace","t":"Same as « potentiel / puissant ». A potent drug.","h":["Posse: be able. A potent brew.","Potent: powerful."],"s":["efficacious","exhilarating","heady","puissant"]},{"w":"ramble","p":"v.","m":"To walk for pleasure; to talk at length confusedly.","e":"Middle Dutch <i>rammelen</i> (to roam in sexual excitement).","f":"flâner; divaguer","x":"2nd meaning","t":"A rambling speech = discours décousu. Walkers ramble too.","h":["Ramble: roam. A rambling speech.","Ramble: wander."],"s":["maunder","meander","prattle"]},{"w":"recapitulate","p":"v.","m":"To summarize and state again the main points.","e":"Latin <i>recapitulare</i>, from <i>capitulum</i> (little head, chapter).","f":"récapituler","t":"Same as « récapituler ».","h":["Re + capitulum: chapter again. Recapitulate the points.","Recapitulate: sum up."],"s":["reiterate"]},{"w":"redundant","p":"adj.","m":"Not needed; superfluous.","e":"Latin <i>redundare</i> (to overflow).","f":"redondant, superflu","t":"Same as « redondant »; also “laid off” in British English.","h":["Re + undare: overflow. A redundant clause.","Redundant: surplus."],"s":["extraneous","immaterial","impertinent","superfluous","tangential"]},{"w":"reflect","p":"v.","m":"To throw back light; to think carefully.","e":"Latin <i>reflectere</i> (to bend back).","f":"refléter; réfléchir","t":"Same as « réfléchir »: both meanings (mirror, thought).","h":["Re + flectere: bend back. Reflect on it.","Reflect: mirror or ponder."],"s":["cogitate","contemplate","deliberate","ruminate"]},{"w":"resent","p":"v.","m":"To feel bitter indignation at.","e":"French <i>ressentir</i> (to feel again).","f":"en vouloir à, ne pas supporter","x":"Faux ami","t":"Ressentir ≠ resent: English = bitter. « Il m'en veut » = he resents me.","h":["Re + sentir: feel again. Resent the delay.","Resent: begrudge."],"s":["begrudge","bridle"]},{"w":"residual","p":"adj.","m":"Remaining after the main part has gone.","e":"Latin <i>residuum</i>, from <i>residere</i> (to remain).","f":"résiduel","t":"Same as « résiduel ».","h":["Residuum: remainder. Residual heat.","Residual: leftover."],"s":["rudimentary","vestigial"]},{"w":"resourceful","p":"adj.","m":"Having the ability to find quick and clever ways to overcome difficulties.","e":"<i>resource</i> (French <i>ressource</i>) + <i>-ful</i>.","f":"ingénieux, débrouillard","t":"« Débrouillard ».","h":["Resource-full. A resourceful scout.","Resourceful: inventive."],"s":["ingenious","multifaceted","protean","shrewd","versatile"]},{"w":"retrench","p":"v.","m":"To reduce costs or spending.","e":"Old French <i>retrenchier</i> (to cut back).","f":"réduire ses dépenses, se restreindre","t":"Cut back: « retrancher ». Retrenchment = austérité.","h":["Re + trancher: cut back. Retrench spending.","Retrench: cut costs."],"s":["curtail"]},{"w":"sacrosanct","p":"adj.","m":"Too important to be changed.","e":"Latin <i>sacrosanctus</i>: <i>sacro</i> (by a sacred rite) + <i>sanctus</i> (made holy).","f":"sacro-saint","t":"Same as « sacro-saint ».","h":["Sacer + sanctus. A sacrosanct rule.","Sacrosanct: untouchable."],"s":["impregnable","inalienable","intrinsic","inviolable","inviolate","unassailable"]},{"w":"self-indulgent","p":"adj.","m":"Allowing oneself to enjoy pleasures or luxuries.","e":"<i>self</i> + Latin <i>indulgere</i> (to be kind).","f":"complaisant envers soi-même","t":"Indulgence: you pardon yourself everything. « Laxiste envers soi ».","h":["Indulge oneself. A self-indulgent binge.","Self-indulgent: pampering oneself."],"s":["decadent","libertine"]},{"w":"shrewd","p":"adj.","m":"Having sharp judgement, especially in business.","e":"Middle English <i>shrewe</i> (wicked person), later 'sharp'.","f":"astucieux, perspicace","t":"A shrewd negotiator = fin négociateur.","h":["Shrew: scold; sharp. A shrewd investor.","Shrewd: canny."],"s":["artful","astute","avid","canny","crafty","cunning","discreet","expedient","incisive","ingenious","judicious","keen","penetrating","percipient","perspicacious","politic","prudent","resourceful","sagacious","savvy","wily"]},{"w":"speculate","p":"v.","m":"To form a theory without firm evidence; to invest at risk.","e":"Latin <i>speculari</i> (to observe).","f":"spéculer, conjecturer","t":"Same as « spéculer ».","h":["Specula: watchtower. Speculate on causes.","Speculate: guess or gamble."],"s":["surmise"]},{"w":"suppress","p":"v.","m":"To forcibly put an end to; to prevent from being seen.","e":"Latin <i>supprimere</i>: <i>sub-</i> + <i>premere</i> (to press).","f":"réprimer, étouffer, supprimer","t":"Same as « supprimer / réprimer ».","h":["Sub + premere: press down. Suppress a yawn.","Suppress: stifle."],"s":["bridle","check","curb","curtail","hamper","inhibit","nullify","quash","rescind","squelch","stultify"]},{"w":"surrogate","p":"n.","m":"A substitute, especially a person acting for another.","e":"Latin <i>surrogare</i> (to substitute).","f":"substitut, remplaçant","t":"Same as « substitut »: surrogate mother = mère porteuse.","h":["Sub + rogare: ask in place. A surrogate parent.","Surrogate: substitute."],"s":["proxy","vicarious"]},{"w":"unadorned","p":"adj.","m":"Plain; without decoration.","e":"<i>un-</i> + Latin <i>adornare</i>.","f":"sans fard, dépouillé","t":"« Sans fard »: the unadorned truth.","h":["Not adorned. Unadorned truth.","Unadorned: plain."],"s":["austere"]},{"w":"valedictory","p":"adj.","m":"Serving as a farewell.","e":"Latin <i>vale dicere</i> (to say farewell).","f":"d'adieu","t":"Vale! Valedictorian gives the farewell speech.","h":["Vale dicere: say farewell. A valedictory speech.","Valedictory: parting."],"s":[]},{"w":"vestigial","p":"adj.","m":"Forming a remnant of something that once existed.","e":"Latin <i>vestigium</i> (footprint).","f":"vestigial, résiduel","t":"Same as « vestige »: a vestigial organ.","h":["Vestigium: footprint. Vestigial tail.","Vestigial: leftover trace."],"s":["elementary","residual","rudimentary"]},{"w":"warranted","p":"adj.","m":"Justified or necessary.","e":"Old French <i>warant</i>, Germanic. Cf. « garantir ».","f":"justifié, fondé","t":"Warrant ~ garantir: warranted = guaranteed to be justified.","h":["Warrant: guarantee. Warranted concern.","Warranted: justified."],"s":[]},{"w":"willful","p":"adj.","m":"Stubbornly determined; intentional.","e":"<i>will</i> + <i>-ful</i>. Germanic.","f":"entêté; délibéré","t":"Willful neglect = négligence volontaire; a willful child = têtu.","h":["Will-full. Willful neglect.","Willful: deliberate."],"s":["capricious","deliberate","gratuitous","headstrong","obstinate","pertinacious","refractory","unruly","wanton","wayward"]},{"w":"wistful","p":"adj.","m":"Having a feeling of vague longing.","e":"Probably from <i>wistly</i> (intently), influenced by <i>wishful</i>.","f":"mélancolique, nostalgique","t":"Wishful, melancholy: « nostalgique ».","h":["Wist: longing. A wistful smile.","Wistful: yearning."],"s":["doleful","melancholy","pensive","plaintive"]}]}];
